static void movem_long_postincrement_loads_registers_and_updates_base(void) {
    create_cpu();
    const uint8_t program[] = {
        0x41u, 0xf9u, 0x00u, 0x00u, 0x01u, 0x80u, /* LEA $180,A0 */
        0x4cu, 0xd8u, 0x02u, 0x03u}; /* MOVEM.L (A0)+,D0/D1/A1 */
    const uint32_t values[] = {
        UINT32_C(0x11223344), UINT32_C(0x55667788), UINT32_C(0x99aabbcc)};
    for (size_t i = 0u; i < 3u; ++i) {
        const uint32_t address = UINT32_C(0x180) + (uint32_t)i * UINT32_C(4);
        memory.rom[address] = (uint8_t)(values[i] >> 24);
        memory.rom[address + 1u] = (uint8_t)(values[i] >> 16);
        memory.rom[address + 2u] = (uint8_t)(values[i] >> 8);
        memory.rom[address + 3u] = (uint8_t)values[i];
    }
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(48));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(48u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(2u, result.instructions);
    owned_cpu_observation observation;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX32(values[0], observation.data_registers[0]);
    TEST_ASSERT_EQUAL_HEX32(values[1], observation.data_registers[1]);
    TEST_ASSERT_EQUAL_HEX32(values[2], observation.address_registers[1]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x18c), observation.address_registers[0]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x10a), observation.pc);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2700), observation.sr);

    const uint8_t base_register_in_mask[] = {
        0x41u, 0xf9u, 0x00u, 0x00u, 0x01u, 0x80u,
        0x4cu, 0xd8u, 0x01u, 0x01u}; /* MOVEM.L (A0)+,D0/A0 */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(
        base_register_in_mask, sizeof(base_register_in_mask)));
    result = owned_cpu_run(cpu, UINT64_C(40));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(40u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX32(values[0], observation.data_registers[0]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x188), observation.address_registers[0]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2700), observation.sr);

}

/* M68000 Family Programmer's Reference Manual MOVEM, pp. 4-127 to 4-130;
 * MC68000 User's Manual Rev. 9.1 Sections 6.3.9.1 and 6.3.10, Fig. 6-7, and
 * Table 8-14 printed p. 8-11 (address error: 50 clocks). */
static void movem_long_postincrement_odd_address_enters_address_error(void) {
    create_cpu();
    const uint8_t program[] = {0x4cu, 0xd9u, 0x00u, 0x03u}; /* (A1)+ -> D0/D1 */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    set_vector(12u, UINT32_C(0x140));
    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.address_registers[1] = UINT32_C(0x1e1);
    state.data_registers[0] = UINT32_C(0x11223344);
    state.data_registers[1] = UINT32_C(0x55667788);
    state.sr = UINT16_C(0x271f);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));

    const size_t reads_before = memory.reads;
    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(50));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(50u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(0u, result.instructions);
    TEST_ASSERT_EQUAL_UINT(reads_before + 4u, memory.reads); /* opcode, mask, vector */
    TEST_ASSERT_EQUAL_UINT(7u, memory.write_attempts); /* exception frame only */

    owned_cpu_observation observation;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_UINT8(3u, observation.last_exception_vector);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x140), observation.pc);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x1e1), observation.address_registers[1]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x11223344), observation.data_registers[0]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x55667788), observation.data_registers[1]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x1ff4), memory.write_addresses[4]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x0000), memory.write_values[4]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x1ff6), memory.write_addresses[5]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x01e1), memory.write_values[5]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x1ff2), memory.write_addresses[6]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x001d), memory.write_values[6]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x4cd9), memory.write_values[3]);
}

static void movea_long_postincrement_loads_address_register_in_12_cycles(void) {
    create_cpu();
    const uint8_t program[] = {
        0x41u, 0xf9u, 0x00u, 0x00u, 0x01u, 0x80u, /* LEA $180,A0 */
        0x22u, 0x58u}; /* MOVEA.L (A0)+,A1 */
    const uint32_t value = UINT32_C(0x89abcdef);
    memory.rom[0x180] = (uint8_t)(value >> 24);
    memory.rom[0x181] = (uint8_t)(value >> 16);
    memory.rom[0x182] = (uint8_t)(value >> 8);
    memory.rom[0x183] = (uint8_t)value;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    /* MC68000 UM Rev. 9.1 Table 8-10 (p. 8-8) LEA (xxx).L 12(3/0) plus
     * Table 8-3 (p. 8-3) MOVE.L (An)+,An 12(3/0): 24 clocks, 6 reads, 0 writes. */
    const size_t reads_before = memory.reads;
    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(24));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(24u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(2u, result.instructions);
    TEST_ASSERT_EQUAL_UINT(6u, memory.reads - reads_before);
    TEST_ASSERT_EQUAL_UINT(0u, memory.byte_reads);
    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
    owned_cpu_observation observation;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX32(value, observation.address_registers[1]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x184), observation.address_registers[0]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2700), observation.sr);

}

static void movea_long_address_register_to_address_register_uses_4_cycles(void) {
    create_cpu();
    const uint8_t program[] = {
        0x26, 0x4a, /* MOVEA.L A2,A3 */
        0x24, 0x4a}; /* MOVEA.L A2,A2 */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.address_registers[2] = UINT32_C(0x12345678);
    state.sr = UINT16_C(0x271f);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(4));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(4u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
    owned_cpu_observation observation;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x12345678), observation.address_registers[3]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x271f), observation.sr);
    result = owned_cpu_run(cpu, UINT64_C(4));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(4u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x12345678), observation.address_registers[2]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x271f), observation.sr);

    /* MOVE.L (An),Dn is covered by the shared memory-source family. */
}

/* Guest-observed encoding (05-11): MOVE.L An,(d16,An). The MOVEA.L An,An
 * decode mask once ignored the destination mode, so this store ran as a
 * register copy, overwrote the base register and desynchronized the PC. */
static void move_long_address_register_to_displacement_stores_in_16_cycles(void) {
    create_cpu();
    const uint8_t program[] = {
        0x2b, 0x4b, 0x00, 0x20,  /* MOVE.L A3,(32,A5) */
        0x2b, 0x4b, 0xff, 0xf0,  /* MOVE.L A3,(-16,A5) */
        0x2b, 0x4b, 0x00, 0x21}; /* MOVE.L A3,(33,A5): odd destination */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.address_registers[3] = UINT32_C(0x89abcdef);
    state.address_registers[5] = UINT32_C(0x1f0);
    state.sr = UINT16_C(0x271f); /* X N Z V C all set beforehand */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
    const size_t reads_before = memory.reads;
    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(16));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(16u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
    TEST_ASSERT_EQUAL_UINT(2u, memory.reads - reads_before);
    TEST_ASSERT_EQUAL_UINT(2u, memory.write_attempts);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x210), memory.write_addresses[0]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x89ab), memory.write_values[0]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x212), memory.write_addresses[1]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0xcdef), memory.write_values[1]);
    owned_cpu_observation observation;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x104), observation.pc);
    /* Source and base are unchanged (the defect clobbered the base). */
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x89abcdef), observation.address_registers[3]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x1f0), observation.address_registers[5]);
    /* N set from bit 31, Z/V/C cleared, X preserved. */
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2718), observation.sr);

    /* Negative displacement is sign extended; zero value sets Z and clears N. */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.address_registers[3] = 0u;
    state.sr = UINT16_C(0x2713); /* X set, V and C set, N and Z clear */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
    result = owned_cpu_run(cpu, UINT64_C(16));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(16u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT(4u, memory.write_attempts);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x1e0), memory.write_addresses[2]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x1e2), memory.write_addresses[3]);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2714), observation.sr);

    /* An odd destination enters the address-error path with no operand write.
     * The exception charge itself is not asserted here (see ORACLE.md
     * "Interrupt and exception entry table selection"). */
    set_vector(12u, UINT32_C(0x140));
    result = owned_cpu_run(cpu, UINT64_C(200));
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_UINT8(3u, observation.last_exception_vector);
    for (size_t index = 4u; index < memory.write_attempts && index < MAX_WRITES; ++index)
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x211), memory.write_addresses[index]);
}

/* Bounded no-input continuation after the BIOS entry predicate:
 * MOVE.L An,-(Am). The address register source is sampled before the
 * destination register is decremented. The pinned MAME generated 68000
 * handler writes the low word at destination+2 first, then the high word at
 * destination; final memory remains big-endian. */
static void move_long_address_register_to_predecrement_stores_in_12_cycles(void) {
    for (unsigned source_register = 0u; source_register < 8u; ++source_register) {
        for (unsigned destination_register = 0u; destination_register < 8u;
             ++destination_register) {
            memset(&memory, 0, sizeof(memory));
            create_cpu();
            const uint16_t opcode = (uint16_t)(UINT16_C(0x2108) |
                (uint16_t)(destination_register << 9) |
                (uint16_t)source_register);
            const uint8_t program[] = {
                (uint8_t)(opcode >> 8), (uint8_t)opcode};
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              reset_with_program(program, sizeof(program)));

            owned_cpu_state before;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_capture_state(cpu, &before));
            for (unsigned reg = 0u; reg < 8u; ++reg)
                before.address_registers[reg] =
                    UINT32_C(0x400) + (uint32_t)(reg * 0x20u);
            uint32_t source_value = UINT32_C(0x89abcdef) ^
                ((uint32_t)source_register * UINT32_C(0x01010101));
            if (source_register == 0u) source_value = 0u;
            if (source_register == 1u) source_value = UINT32_C(0x80000000);
            before.address_registers[source_register] = source_value;
            const uint32_t destination_before =
                UINT32_C(0x400) + (uint32_t)(destination_register * 0x20u);
            before.address_registers[destination_register] = destination_before;
            source_value = before.address_registers[source_register];
            before.sr = UINT16_C(0x271f);
            before.ssp = before.address_registers[7];
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_restore_state(cpu, &before));

            const size_t reads_before = memory.reads;
            const size_t writes_before = memory.write_attempts;
            const owned_cpu_run_result result =
                owned_cpu_run(cpu, UINT64_C(12));
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
            TEST_ASSERT_EQUAL_UINT64(UINT64_C(12), result.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
            TEST_ASSERT_EQUAL_UINT(reads_before + 1u, memory.reads);
            TEST_ASSERT_EQUAL_UINT(writes_before + 2u, memory.write_attempts);

            const uint32_t destination = destination_before - UINT32_C(4);
            TEST_ASSERT_EQUAL_HEX32(destination + UINT32_C(2),
                                    memory.write_addresses[writes_before]);
            TEST_ASSERT_EQUAL_HEX16((uint16_t)source_value,
                                    memory.write_values[writes_before]);
            TEST_ASSERT_EQUAL_HEX32(destination,
                                    memory.write_addresses[writes_before + 1u]);
            TEST_ASSERT_EQUAL_HEX16((uint16_t)(source_value >> 16),
                                    memory.write_values[writes_before + 1u]);

            owned_cpu_observation after;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_observe(cpu, &after));
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102), after.pc);
            for (unsigned reg = 0u; reg < 8u; ++reg) {
                const uint32_t expected = reg == destination_register
                    ? destination : before.address_registers[reg];
                TEST_ASSERT_EQUAL_HEX32(expected,
                                        after.address_registers[reg]);
            }
            uint16_t expected_sr = UINT16_C(0x2710);
            if (source_value == 0u)
                expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0004));
            if ((source_value & UINT32_C(0x80000000)) != 0u)
                expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0008));
            TEST_ASSERT_EQUAL_HEX16(expected_sr, after.sr);
            owned_cpu_destroy(cpu);
            cpu = NULL;
        }
    }
}

static void move_long_address_register_to_predecrement_odd_address_enters_address_error(void) {
    create_cpu();
    const uint8_t program[] = {0x21u, 0x08u}; /* MOVE.L A0,-(A0) */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      reset_with_program(program, sizeof(program)));
    set_vector(12u, UINT32_C(0x140));
    owned_cpu_state before;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_capture_state(cpu, &before));
    before.address_registers[0] = UINT32_C(0x201);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_restore_state(cpu, &before));

    const size_t writes_before = memory.write_attempts;
    const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(50));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(UINT64_C(50), result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(0u, result.instructions);
    owned_cpu_observation after;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
    TEST_ASSERT_EQUAL_UINT8(3u, after.last_exception_vector);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x140), after.pc);
    /* The pinned candidate evaluates -(A0) before detecting odd alignment. */
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x1fd), after.address_registers[0]);
    for (size_t write = writes_before; write < memory.write_attempts; ++write) {
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x1fd), memory.byte_write_addresses[write]);
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x1ff), memory.byte_write_addresses[write]);
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x1fd), memory.write_addresses[write]);
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x1ff), memory.write_addresses[write]);
    }
    tearDown();
}

/* Guest-observed encoding (05-27): MOVE.L Dn,(d16,An). The source data
 * register is written as two words; the displacement is signed and flags
 * follow MOVE semantics while X is preserved. */
static void move_long_data_register_to_displacement_stores_in_16_cycles(void) {
    create_cpu();
    const uint8_t program[] = {
        0x2b, 0x43, 0x00, 0x20,  /* MOVE.L D3,(32,A5) */
        0x2b, 0x43, 0xff, 0xf0,  /* MOVE.L D3,(-16,A5) */
        0x2b, 0x43, 0x00, 0x21}; /* MOVE.L D3,(33,A5): odd destination */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.data_registers[3] = UINT32_C(0x89abcdef);
    state.address_registers[5] = UINT32_C(0x1f0);
    state.sr = UINT16_C(0x271f); /* X N Z V C all set beforehand */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
    const size_t reads_before = memory.reads;
    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(16));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(16u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
    TEST_ASSERT_EQUAL_UINT(2u, memory.reads - reads_before);
    TEST_ASSERT_EQUAL_UINT(2u, memory.write_attempts);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x210), memory.write_addresses[0]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x89ab), memory.write_values[0]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x212), memory.write_addresses[1]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0xcdef), memory.write_values[1]);
    owned_cpu_observation observation;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x104), observation.pc);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x89abcdef), observation.data_registers[3]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x1f0), observation.address_registers[5]);
    /* N set from bit 31, Z/V/C cleared, X preserved. */
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2718), observation.sr);

    /* Negative displacement is sign extended; zero value sets Z and clears N. */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.data_registers[3] = 0u;
    state.sr = UINT16_C(0x2713); /* X set, V and C set, N and Z clear */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
    result = owned_cpu_run(cpu, UINT64_C(16));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(16u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT(4u, memory.write_attempts);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x1e0), memory.write_addresses[2]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x1e2), memory.write_addresses[3]);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2714), observation.sr);

    /* An odd destination enters the address-error path without a target write. */
    set_vector(12u, UINT32_C(0x140));
    result = owned_cpu_run(cpu, UINT64_C(200));
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_UINT8(3u, observation.last_exception_vector);
    for (size_t index = 4u; index < memory.write_attempts && index < MAX_WRITES; ++index)
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x211), memory.write_addresses[index]);
}

/* Guest-observed encoding (05-27): MOVE.L Dn,(d8,An,Xn). PRM section 2.2.7
 * p. 2-9 defines the signed byte displacement and brief index extension;
 * bits 10-8 are reserved on MC68000. PRM MOVE pp. 4-116 to 4-118 supplies
 * longword/flag semantics. User's Manual Rev. 9.1 Table 8-3 (p. 8-3):
 * Dn to indexed destination is 18(2/2). */
static void move_long_data_register_to_indexed_displacement_uses_18_cycles(void) {
    create_cpu();
    const uint8_t program[] = {
        0x2b, 0x83, 0x20, 0x08, /* MOVE.L D3,(8,A5,D2.W) */
        0x2b, 0x83, 0xc8, 0xfc, /* MOVE.L D3,(-4,A5,A4.L) */
        0x2b, 0x83, 0x20, 0x09  /* MOVE.L D3,(9,A5,D2.W): odd target */
    };
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    set_vector(12u, UINT32_C(0x140));
    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.data_registers[2] = UINT32_C(0x1234fff0); /* word index is -16 */
    state.data_registers[3] = UINT32_C(0x89abcdef);
    state.address_registers[4] = UINT32_C(0x20);   /* long address-register index */
    state.address_registers[5] = UINT32_C(0x200);
    state.sr = UINT16_C(0x271f); /* X N Z V C all set beforehand */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));

    size_t reads_before = memory.reads;
    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(18));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(18u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
    TEST_ASSERT_EQUAL_UINT(2u, memory.reads - reads_before);
    TEST_ASSERT_EQUAL_UINT(2u, memory.write_attempts);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x1f8), memory.write_addresses[0]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x89ab), memory.write_values[0]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x1fa), memory.write_addresses[1]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0xcdef), memory.write_values[1]);
    owned_cpu_observation observation;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x104), observation.pc);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x200), observation.address_registers[5]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x20), observation.address_registers[4]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x89abcdef), observation.data_registers[3]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2718), observation.sr);

    /* Long address-register index and signed negative byte displacement. */
    reads_before = memory.reads;
    result = owned_cpu_run(cpu, UINT64_C(18));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(18u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
    TEST_ASSERT_EQUAL_UINT(2u, memory.reads - reads_before);
    TEST_ASSERT_EQUAL_UINT(4u, memory.write_attempts);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x21c), memory.write_addresses[2]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x89ab), memory.write_values[2]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x21e), memory.write_addresses[3]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0xcdef), memory.write_values[3]);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x108), observation.pc);

    /* An odd indexed longword destination takes the address-error path and
     * does not write either word of the target operand. */
    const size_t writes_before_exception = memory.write_attempts;
    (void)owned_cpu_run(cpu, UINT64_C(200));
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_UINT8(3u, observation.last_exception_vector);
    for (size_t index = writes_before_exception;
         index < memory.write_attempts && index < MAX_WRITES; ++index) {
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x1f9), memory.write_addresses[index]);
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x1fb), memory.write_addresses[index]);
    }
}

static void move_long_data_register_to_indexed_displacement_neighbors_stay_unsupported(void) {
    static const struct {
        uint8_t program[4];
        const char *name;
    } neighbors[] = {
        {{0x2b, 0x83, 0x27, 0x08}, "MOVE.L D3,unsupported full extension"},
    };
    for (size_t index = 0u; index < sizeof(neighbors) / sizeof(neighbors[0]); ++index) {
        memset(&memory, 0, sizeof(memory));
        create_cpu();
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(neighbors[index].program, 4u));
        owned_cpu_state state;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
        state.data_registers[2] = UINT32_C(0x1234fff0);
        state.data_registers[3] = UINT32_C(0x89abcdef);
        state.address_registers[3] = UINT32_C(0x180);
        state.address_registers[5] = UINT32_C(0x200);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
        owned_cpu_observation before;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &before));
        owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(32));
        TEST_ASSERT_EQUAL_MESSAGE(OWNED_CPU_UNSUPPORTED_OPCODE, result.reason,
                                  neighbors[index].name);
        owned_cpu_observation after;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
        TEST_ASSERT_EQUAL_HEX32_MESSAGE(before.pc, after.pc, neighbors[index].name);
        TEST_ASSERT_EQUAL_HEX32_MESSAGE(UINT32_C(0x89abcdef), after.data_registers[3],
                                        neighbors[index].name);
        TEST_ASSERT_EQUAL_HEX32_MESSAGE(UINT32_C(0x180), after.address_registers[3],
                                        neighbors[index].name);
        TEST_ASSERT_EQUAL_HEX32_MESSAGE(UINT32_C(0x200), after.address_registers[5],
                                        neighbors[index].name);
        TEST_ASSERT_EQUAL_UINT_MESSAGE(0u, memory.write_attempts, neighbors[index].name);
        owned_cpu_destroy(cpu);
        cpu = NULL;
    }
}

/* Guest-observed encoding (05-27): MOVE.L (d16,An),(d16,An). Each
 * displacement is signed; the longword transfers as two big-endian words.
 * PRM MOVE, pp. 4-116 to 4-118: X is preserved, N/Z reflect the result, V/C
 * clear. User's Manual Rev. 9.1 Table 8-3 (printed p. 8-3): 28(5/2). */
static void move_long_displacement_to_displacement_uses_28_cycles(void) {
    create_cpu();
    const uint8_t program[] = {
        0x23, 0x68, 0x00, 0x20, 0xff, 0xf0, /* MOVE.L (32,A0),(-16,A1) */
        0x23, 0x68, 0x00, 0x24, 0x00, 0x10  /* MOVE.L (36,A0),(16,A1) */
    };
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    memory.rom[0x1a0] = 0x89u;
    memory.rom[0x1a1] = 0xabu;
    memory.rom[0x1a2] = 0xcdu;
    memory.rom[0x1a3] = 0xefu;
    memory.rom[0x1a4] = 0u;
    memory.rom[0x1a5] = 0u;
    memory.rom[0x1a6] = 0u;
    memory.rom[0x1a7] = 0u;
    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.address_registers[0] = UINT32_C(0x180);
    state.address_registers[1] = UINT32_C(0x220);
    state.sr = UINT16_C(0x271f); /* X N Z V C set before negative result */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));

    size_t reads_before = memory.reads;
    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(28));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(28u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
    TEST_ASSERT_EQUAL_UINT(5u, memory.reads - reads_before);
    TEST_ASSERT_EQUAL_UINT(2u, memory.write_attempts);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x210), memory.write_addresses[0]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x89ab), memory.write_values[0]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x212), memory.write_addresses[1]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0xcdef), memory.write_values[1]);
    owned_cpu_observation observation;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x106), observation.pc);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x180), observation.address_registers[0]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x220), observation.address_registers[1]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2718), observation.sr);

    /* A zero longword sets Z, clears N/V/C and still preserves X. */
    reads_before = memory.reads;
    result = owned_cpu_run(cpu, UINT64_C(28));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(28u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
    TEST_ASSERT_EQUAL_UINT(5u, memory.reads - reads_before);
    TEST_ASSERT_EQUAL_UINT(4u, memory.write_attempts);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x230), memory.write_addresses[2]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x0000), memory.write_values[2]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x232), memory.write_addresses[3]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x0000), memory.write_values[3]);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x10c), observation.pc);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2714), observation.sr);
}

/* Guest-observed encoding (05-27): MOVE.L (d16,An),(d8,An,Xn). The
 * destination uses the MC68000 brief index extension; bits 10-8 remain
 * reserved. PRM §2.2.7 p. 2-9 defines the signed displacements and index;
 * PRM MOVE pp. 4-116 to 4-118 defines flags and transfer behavior. User's
 * Manual Rev. 9.1 Table 8-3 (printed p. 8-3): (d16,An) to indexed is
 * 30(5/2). */
static void move_long_displacement_to_indexed_displacement_uses_30_cycles(void) {
    create_cpu();
    const uint8_t program[] = {
        0x21, 0xac, 0x00, 0x06, 0x20, 0x14, /* MOVE.L (6,A4),(20,A0,D2.W) */
        0x21, 0xac, 0xff, 0xf8, 0xc8, 0xfc  /* MOVE.L (-8,A4),(-4,A0,A4.L) */
    };
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    memory.rom[0x186] = 0x89u;
    memory.rom[0x187] = 0xabu;
    memory.rom[0x188] = 0xcdu;
    memory.rom[0x189] = 0xefu;
    memory.rom[0x178] = 0u;
    memory.rom[0x179] = 0u;
    memory.rom[0x17a] = 0u;
    memory.rom[0x17b] = 0u;
    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.data_registers[2] = UINT32_C(0x1234fff0); /* D2.W = -16 */
    state.address_registers[0] = UINT32_C(0x220);
    state.address_registers[4] = UINT32_C(0x180);
    state.sr = UINT16_C(0x271f); /* X N Z V C set before negative result */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));

    size_t reads_before = memory.reads;
    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(30));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(30u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
    TEST_ASSERT_EQUAL_UINT(5u, memory.reads - reads_before);
    TEST_ASSERT_EQUAL_UINT(2u, memory.write_attempts);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x224), memory.write_addresses[0]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x89ab), memory.write_values[0]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x226), memory.write_addresses[1]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0xcdef), memory.write_values[1]);
    owned_cpu_observation observation;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x106), observation.pc);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x220), observation.address_registers[0]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x180), observation.address_registers[4]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2718), observation.sr);

    reads_before = memory.reads;
    result = owned_cpu_run(cpu, UINT64_C(30));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(30u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
    TEST_ASSERT_EQUAL_UINT(5u, memory.reads - reads_before);
    TEST_ASSERT_EQUAL_UINT(4u, memory.write_attempts);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x39c), memory.write_addresses[2]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x0000), memory.write_values[2]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x39e), memory.write_addresses[3]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x0000), memory.write_values[3]);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x10c), observation.pc);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2714), observation.sr);
}

