static void move_long_address_indirect_alignment_errors_order_source_reads(void) {
    static const uint8_t program[] = {0x22u, 0x90u}; /* MOVE.L (A0),(A1) */
    for (unsigned test_case = 0u; test_case < 2u; ++test_case) {
        memset(&memory, 0, sizeof(memory));
        create_cpu();
        set_vector(12u, UINT32_C(0x140));
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          reset_with_program(program, sizeof(program)));
        owned_cpu_state before;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
        before.address_registers[0] = test_case == 0u
            ? UINT32_C(0x181) : UINT32_C(0x180);
        before.address_registers[1] = test_case == 0u
            ? UINT32_C(0x190) : UINT32_C(0x191);
        before.ssp = before.address_registers[7];
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));
        memory.rom[0x180u] = 0x12u;
        memory.rom[0x181u] = 0x34u;
        memory.rom[0x182u] = 0x56u;
        memory.rom[0x183u] = 0x78u;
        const size_t reads_before = memory.reads;
        const size_t writes_before = memory.write_attempts;
        const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(50));
        TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
        TEST_ASSERT_EQUAL_UINT64(50u, result.elapsed_cycles);
        owned_cpu_observation after;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
        TEST_ASSERT_EQUAL_UINT8(3u, after.last_exception_vector);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x140), after.pc);
        if (test_case == 0u) {
            for (size_t i = reads_before; i < memory.reads && i < ROM_SIZE; ++i) {
                TEST_ASSERT_NOT_EQUAL(UINT32_C(0x181), memory.read_addresses[i]);
                TEST_ASSERT_NOT_EQUAL(UINT32_C(0x183), memory.read_addresses[i]);
            }
        } else {
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x180),
                                    memory.read_addresses[reads_before + 1u]);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x182),
                                    memory.read_addresses[reads_before + 2u]);
        }
        for (size_t i = writes_before; i < memory.write_attempts && i < MAX_WRITES; ++i) {
            TEST_ASSERT_NOT_EQUAL(UINT32_C(0x191), memory.write_addresses[i]);
            TEST_ASSERT_NOT_EQUAL(UINT32_C(0x193), memory.write_addresses[i]);
        }
        TEST_ASSERT_EQUAL_HEX32(before.address_registers[0], after.address_registers[0]);
        TEST_ASSERT_EQUAL_HEX32(before.address_registers[1], after.address_registers[1]);
        owned_cpu_destroy(cpu);
        cpu = NULL;
    }
}

/* Guest-observed plan 05-03 continuation: MOVE.W (An)+,(d16,Am). UM Rev.
 * 9.1 Table 8-2 p. 8-2 gives 16(3/1). Pinned MAME differential evidence
 * resolves the source and commits its postincrement before the destination
 * base is used when both fields name the same register. */
static void move_word_postincrement_to_displacement_covers_all_register_pairs_in_16_cycles(void) {
    static const uint16_t values[] = {
        UINT16_C(0x0000), UINT16_C(0x8001),
        UINT16_C(0x7fff), UINT16_C(0x0001)};
    static const int16_t displacements[] = {-2, 0, 4};
    for (unsigned source_reg = 0u; source_reg < 8u; ++source_reg) {
        for (unsigned destination_reg = 0u; destination_reg < 8u;
             ++destination_reg) {
            memset(&memory, 0, sizeof(memory));
            create_cpu();
            const uint16_t opcode = (uint16_t)(UINT16_C(0x3158) |
                (uint16_t)(destination_reg << 9) | (uint16_t)source_reg);
            const int16_t displacement = displacements[
                (source_reg * 8u + destination_reg) %
                (sizeof(displacements) / sizeof(displacements[0]))];
            uint8_t program[4];
            size_t length = 0u;
            emit_word(program, &length, opcode);
            emit_word(program, &length, (uint16_t)displacement);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              reset_with_program(program, length));
            owned_cpu_state before;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_capture_state(cpu, &before));
            for (unsigned reg = 0u; reg < 8u; ++reg)
                before.address_registers[reg] =
                    UINT32_C(0x0180) + (uint32_t)reg * UINT32_C(0x10);
            before.ssp = before.address_registers[7];
            before.usp = UINT32_C(0x01e0);
            before.sr = UINT16_C(0x271f);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_restore_state(cpu, &before));

            const uint32_t source_address =
                before.address_registers[source_reg];
            const uint32_t destination_base =
                before.address_registers[destination_reg] +
                (source_reg == destination_reg ? UINT32_C(2) : UINT32_C(0));
            const uint32_t destination_address = destination_base +
                (uint32_t)(int32_t)displacement;
            const uint16_t value = values[(source_reg * 8u + destination_reg) %
                (sizeof(values) / sizeof(values[0]))];
            memory.rom[source_address] = (uint8_t)(value >> 8);
            memory.rom[source_address + 1u] = (uint8_t)value;
            const size_t reads_before = memory.reads;
            const size_t writes_before = memory.write_attempts;
            const owned_cpu_run_result result =
                owned_cpu_run(cpu, UINT64_C(16));
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
            TEST_ASSERT_EQUAL_UINT64(16u, result.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
            TEST_ASSERT_EQUAL_UINT(reads_before + 3u, memory.reads);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                                    memory.read_addresses[reads_before]);
            TEST_ASSERT_EQUAL_HEX32(source_address,
                                    memory.read_addresses[reads_before + 1u]);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102),
                                    memory.read_addresses[reads_before + 2u]);
            TEST_ASSERT_EQUAL_UINT(writes_before + 1u,
                                   memory.write_attempts);
            TEST_ASSERT_EQUAL_UINT(writes_before + 1u,
                                   memory.successful_writes);
            TEST_ASSERT_EQUAL_HEX32(destination_address,
                                    memory.write_addresses[writes_before]);
            TEST_ASSERT_EQUAL_HEX16(value,
                                    memory.write_values[writes_before]);

            owned_cpu_state after;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_capture_state(cpu, &after));
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x104), after.pc);
            uint16_t expected_sr = UINT16_C(0x2710);
            if (value == 0u) expected_sr |= UINT16_C(0x0004);
            if ((value & UINT16_C(0x8000)) != 0u)
                expected_sr |= UINT16_C(0x0008);
            TEST_ASSERT_EQUAL_HEX16(expected_sr, after.sr);
            for (unsigned reg = 0u; reg < 8u; ++reg) {
                const uint32_t expected_address =
                    before.address_registers[reg] +
                    (reg == source_reg ? UINT32_C(2) : UINT32_C(0));
                TEST_ASSERT_EQUAL_HEX32(expected_address,
                                        after.address_registers[reg]);
            }
            TEST_ASSERT_EQUAL_HEX32(after.address_registers[7], after.ssp);
            TEST_ASSERT_EQUAL_HEX32(before.usp, after.usp);
            owned_cpu_destroy(cpu);
            cpu = NULL;
        }
    }
}

static void move_word_postincrement_to_displacement_alignment_errors_preserve_effects(void) {
    static const uint8_t odd_source[] = {
        0x33u, 0x58u, 0x00u, 0x00u}; /* MOVE.W (A0)+,0(A1) */
    static const uint8_t odd_destination[] = {
        0x33u, 0x58u, 0x00u, 0x01u}; /* MOVE.W (A0)+,1(A1) */
    for (unsigned test_case = 0u; test_case < 2u; ++test_case) {
        memset(&memory, 0, sizeof(memory));
        create_cpu();
        set_vector(12u, UINT32_C(0x140));
        const uint8_t *program = test_case == 0u
            ? odd_source : odd_destination;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          reset_with_program(program, sizeof(odd_source)));
        owned_cpu_state before;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          owned_cpu_capture_state(cpu, &before));
        before.address_registers[0] = test_case == 0u
            ? UINT32_C(0x0181) : UINT32_C(0x0180);
        before.address_registers[1] = UINT32_C(0x01a0);
        before.ssp = before.address_registers[7];
        before.usp = UINT32_C(0x01e0);
        before.sr = UINT16_C(0x271f);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          owned_cpu_restore_state(cpu, &before));
        memory.rom[0x0180u] = 0x12u;
        memory.rom[0x0181u] = 0x34u;
        const size_t reads_before = memory.reads;
        const size_t writes_before = memory.write_attempts;
        const owned_cpu_run_result result =
            owned_cpu_run(cpu, UINT64_C(50));
        TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
        owned_cpu_observation after;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
        TEST_ASSERT_EQUAL_UINT8(3u, after.last_exception_vector);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x140), after.pc);
        if (test_case == 0u) {
            for (size_t i = reads_before; i < memory.reads && i < ROM_SIZE;
                 ++i)
                TEST_ASSERT_NOT_EQUAL(UINT32_C(0x0181),
                                      memory.read_addresses[i]);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0183),
                                    after.address_registers[0]);
        } else {
            unsigned source_reads = 0u;
            for (size_t i = reads_before; i < memory.reads && i < ROM_SIZE;
                 ++i)
                if (memory.read_addresses[i] == UINT32_C(0x0180))
                    ++source_reads;
            TEST_ASSERT_EQUAL_UINT(1u, source_reads);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0182),
                                    after.address_registers[0]);
        }
        for (size_t i = writes_before; i < memory.write_attempts &&
             i < MAX_WRITES; ++i)
            TEST_ASSERT_NOT_EQUAL(UINT32_C(0x01a1),
                                  memory.write_addresses[i]);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x01a0),
                                after.address_registers[1]);
        owned_cpu_destroy(cpu);
        cpu = NULL;
    }
}

