/* CMP.B/W/L memory sources use the documented data-alterable EAs. Start with
 * CMP.W d16(An),Dn, the selected guest's current fault, then cover the same
 * source-EA path for byte and long and all admitted forms. */
static void cmp_data_alterable_memory_sources_use_documented_timings(void) {
    static const struct {
        unsigned mode;
        unsigned absolute_register;
        unsigned extension_words;
    } forms[] = {
        {5u, 0u, 1u}, /* d16(An) */
        {2u, 0u, 0u}, /* (An) */
        {3u, 0u, 0u}, /* (An)+ */
        {4u, 0u, 0u}, /* -(An) */
        {6u, 0u, 1u}, /* brief d8(An,Xn) */
        {7u, 0u, 1u}, /* absolute short */
        {7u, 1u, 2u}, /* absolute long */
    };
    static const unsigned widths[] = {2u, 1u, 4u}; /* observed word first */
    static const uint64_t ea_cycles[2][7] = {
        {8u, 4u, 4u, 6u, 10u, 8u, 12u},
        {12u, 8u, 8u, 10u, 14u, 12u, 16u},
    };
    static const uint32_t samples[] = {
        UINT32_C(0x00000000), UINT32_C(0x00000001), UINT32_C(0x0000007f),
        UINT32_C(0x00000080), UINT32_C(0x00007fff), UINT32_C(0x00008000),
        UINT32_C(0xffff0001), UINT32_C(0x89abcdef),
    };
    const uint32_t even_target = UINT32_C(0x01e0);
    unsigned case_number = 0u;

    for (size_t width_index = 0u;
         width_index < sizeof(widths) / sizeof(widths[0]); ++width_index) {
        const unsigned width = widths[width_index];
        const unsigned base_cycles = width == 4u ? 6u : 4u;
        const unsigned long_ea_row = width == 4u ? 1u : 0u;
        const uint32_t mask = width == 1u ? UINT32_C(0xff) :
            width == 2u ? UINT32_C(0xffff) : UINT32_MAX;
        for (size_t form_index = 0u;
             form_index < sizeof(forms) / sizeof(forms[0]); ++form_index) {
            const unsigned register_count = forms[form_index].mode == 7u
                ? 1u : 8u;
            for (unsigned base_reg = 0u; base_reg < register_count; ++base_reg) {
                const unsigned ea_register = forms[form_index].mode == 7u
                    ? forms[form_index].absolute_register : base_reg;
                for (unsigned destination_reg = 0u; destination_reg < 8u;
                     ++destination_reg, ++case_number) {
                    memset(&memory, 0, sizeof(memory));
                    create_cpu();
                    const uint32_t target = width == 1u &&
                        forms[form_index].mode != 7u &&
                        ((case_number + form_index) & 1u) != 0u
                        ? even_target + UINT32_C(1) : even_target;
                    uint8_t program[8] = {0};
                    size_t length = 0u;
                    const uint16_t size_bits = width == 1u ? UINT16_C(0x0000) :
                        width == 2u ? UINT16_C(0x0040) : UINT16_C(0x0080);
                    const uint16_t opcode = (uint16_t)(UINT16_C(0xb000) |
                        size_bits |
                        (uint16_t)(destination_reg << 9) |
                        (uint16_t)(forms[form_index].mode << 3) |
                        (uint16_t)ea_register);
                    emit_word(program, &length, opcode);
                    if (forms[form_index].mode == 5u) {
                        emit_word(program, &length, UINT16_C(0x0020));
                    } else if (forms[form_index].mode == 6u) {
                        emit_word(program, &length, UINT16_C(0x1000)); /* D1.W */
                    } else if (forms[form_index].mode == 7u &&
                               forms[form_index].absolute_register == 0u) {
                        emit_word(program, &length, (uint16_t)target);
                    } else if (forms[form_index].mode == 7u) {
                        emit_word(program, &length, (uint16_t)(target >> 16));
                        emit_word(program, &length, (uint16_t)target);
                    }
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      reset_with_program(program, length));

                    owned_cpu_state before;
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      owned_cpu_capture_state(cpu, &before));
                    for (unsigned reg = 0u; reg < 8u; ++reg) {
                        before.address_registers[reg] =
                            UINT32_C(0x0300) + reg * UINT32_C(8);
                        before.data_registers[reg] = UINT32_C(0xa5a50000) |
                            (samples[(case_number + reg) %
                                (sizeof(samples) / sizeof(samples[0]))] & mask);
                    }
                    if (forms[form_index].mode < 7u) {
                        const uint32_t step = width == 1u && base_reg == 7u
                            ? 2u : width;
                        switch (forms[form_index].mode) {
                            case 2u:
                            case 3u:
                                before.address_registers[base_reg] = target;
                                break;
                            case 4u:
                                before.address_registers[base_reg] = target + step;
                                break;
                            case 5u:
                                before.address_registers[base_reg] =
                                    target - UINT32_C(0x20);
                                break;
                            case 6u:
                                before.address_registers[base_reg] =
                                    target - UINT32_C(2);
                                before.data_registers[1] = UINT32_C(2); /* D1.W */
                                break;
                            default:
                                TEST_FAIL_MESSAGE("unexpected CMP memory EA");
                        }
                    }
                    before.sr = (case_number & 1u) != 0u
                        ? UINT16_C(0x271f) : UINT16_C(0x2700);
                    before.ssp = before.address_registers[7];
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      owned_cpu_restore_state(cpu, &before));

                    const uint32_t source = samples[(case_number + 3u) %
                        (sizeof(samples) / sizeof(samples[0]))] & mask;
                    if (width == 1u) {
                        memory.rom[target] = (uint8_t)source;
                    } else if (width == 2u) {
                        memory.rom[target] = (uint8_t)(source >> 8);
                        memory.rom[target + 1u] = (uint8_t)source;
                    } else {
                        memory.rom[target] = (uint8_t)(source >> 24);
                        memory.rom[target + 1u] = (uint8_t)(source >> 16);
                        memory.rom[target + 2u] = (uint8_t)(source >> 8);
                        memory.rom[target + 3u] = (uint8_t)source;
                    }
                    const uint32_t destination =
                        before.data_registers[destination_reg] & mask;
                    const uint64_t cycles = base_cycles +
                        ea_cycles[long_ea_row][form_index];
                    const size_t word_reads_before = memory.reads;
                    const size_t byte_reads_before = memory.byte_reads;
                    const size_t ordered_reads_before = memory.ordered_read_count;
                    const size_t writes_before = memory.write_attempts;
                    const owned_cpu_run_result result = owned_cpu_run(cpu, cycles);
                    TEST_ASSERT_EQUAL_MESSAGE(OWNED_CPU_BUDGET, result.reason,
                        "CMP memory-source form must execute");
                    TEST_ASSERT_EQUAL_UINT64(cycles, result.elapsed_cycles);
                    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
                    const size_t operand_words = width == 4u ? 2u :
                        width == 2u ? 1u : 0u;
                    TEST_ASSERT_EQUAL_UINT(1u + forms[form_index].extension_words +
                        operand_words, memory.reads - word_reads_before);
                    TEST_ASSERT_EQUAL_UINT(width == 1u ? 1u : 0u,
                                           memory.byte_reads - byte_reads_before);
                    const size_t operand_accesses = width == 4u ? 2u : 1u;
                    const size_t ordered_count = 1u +
                        forms[form_index].extension_words + operand_accesses;
                    TEST_ASSERT_EQUAL_UINT(ordered_count,
                        memory.ordered_read_count - ordered_reads_before);
                    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                        memory.ordered_read_addresses[ordered_reads_before]);
                    TEST_ASSERT_EQUAL_HEX32(target,
                        memory.ordered_read_addresses[ordered_reads_before +
                            ordered_count - operand_accesses]);
                    TEST_ASSERT_EQUAL_UINT(width == 1u ? 1u : 2u,
                        memory.ordered_read_widths[ordered_reads_before +
                            ordered_count - operand_accesses]);
                    if (width == 4u) {
                        TEST_ASSERT_EQUAL_HEX32(target + UINT32_C(2),
                            memory.ordered_read_addresses[ordered_reads_before +
                                ordered_count - 1u]);
                    }
                    TEST_ASSERT_EQUAL_UINT(writes_before, memory.write_attempts);

                    owned_cpu_observation after;
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      owned_cpu_observe(cpu, &after));
                    const uint16_t expected_flags = width == 1u
                        ? expected_compare_byte_flags(before.sr,
                            (uint8_t)destination, (uint8_t)source)
                        : width == 2u
                            ? expected_compare_word_flags(before.sr,
                                (uint16_t)destination, (uint16_t)source)
                            : expected_compare_long_flags(before.sr,
                                destination, source);
                    TEST_ASSERT_EQUAL_HEX16(expected_flags, after.sr);
                    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102) +
                        forms[form_index].extension_words * UINT32_C(2), after.pc);
                    for (unsigned reg = 0u; reg < 8u; ++reg) {
                        uint32_t expected_address = before.address_registers[reg];
                        if (reg == base_reg && forms[form_index].mode == 3u)
                            expected_address += width == 1u && reg == 7u ? 2u : width;
                        if (reg == base_reg && forms[form_index].mode == 4u)
                            expected_address -= width == 1u && reg == 7u ? 2u : width;
                        TEST_ASSERT_EQUAL_HEX32(expected_address,
                                                after.address_registers[reg]);
                        TEST_ASSERT_EQUAL_HEX32(before.data_registers[reg],
                                                after.data_registers[reg]);
                    }
                    TEST_ASSERT_EQUAL_HEX32(after.address_registers[7], after.ssp);
                    owned_cpu_destroy(cpu);
                    cpu = NULL;
                }
            }
        }
    }
}

/* Guest-observed encoding (05-02): CMP.W (d8,An,Xn),Dn. */
static void cmp_word_address_index_to_data_register_covers_registers_and_index_sizes(void) {
    static const int8_t displacements[4] = {-128, -1, 0, 127};
    static const uint32_t indexes[8] = {
        UINT32_C(0x00000002), UINT32_C(0x0000fffc), UINT32_C(0x00010001),
        UINT32_C(0xffff0003), UINT32_C(0x7fff0000), UINT32_C(0x80000000),
        UINT32_C(0x1234007f), UINT32_C(0xffffff81)};
    static const uint16_t source_values[4] = {
        UINT16_C(0x8000), UINT16_C(0x0000), UINT16_C(0x7fff), UINT16_C(0x0001)};
    static const uint16_t destination_values[4] = {
        UINT16_C(0x7fff), UINT16_C(0x8000), UINT16_C(0x0000), UINT16_C(0x0001)};
    for (unsigned destination_reg = 0u; destination_reg < 8u; ++destination_reg) {
        for (unsigned base_reg = 0u; base_reg < 8u; ++base_reg) {
            for (unsigned index_reg = 0u; index_reg < 8u; ++index_reg) {
                for (unsigned index_is_address = 0u; index_is_address < 2u;
                     ++index_is_address) {
                    for (unsigned index_is_long = 0u; index_is_long < 2u;
                         ++index_is_long) {
                        if (index_is_address != 0u && index_reg == base_reg) continue;
                        memset(&memory, 0, sizeof(memory));
                        create_cpu();
                        uint8_t program[4];
                        size_t length = 0u;
                        const int8_t displacement = displacements[
                            (destination_reg + base_reg + index_reg +
                             index_is_address + index_is_long) % 4u];
                        emit_word(program, &length, (uint16_t)(
                            UINT16_C(0xb070) | (destination_reg << 9) | base_reg));
                        emit_word(program, &length, (uint16_t)(
                            (index_is_address != 0u ? UINT16_C(0x8000) : 0u) |
                            (index_reg << 12) |
                            (index_is_long != 0u ? UINT16_C(0x0800) : 0u) |
                            (uint8_t)displacement));
                        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                          reset_with_program(program, length));
                        owned_cpu_state state;
                        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                          owned_cpu_capture_state(cpu, &state));
                        for (unsigned i = 0u; i < 8u; ++i)
                            state.data_registers[i] = UINT32_C(0xa55a0000) |
                                destination_values[(i + base_reg) % 4u];
                        const uint32_t index_value = indexes[index_reg];
                        const uint32_t effective_index = index_is_long != 0u
                            ? index_value
                            : expected_sign_extend_word((uint16_t)index_value);
                        if (index_is_address != 0u)
                            state.address_registers[index_reg] = index_value;
                        else
                            state.data_registers[index_reg] = index_value;
                        const uint32_t target = UINT32_C(0x1e0);
                        state.address_registers[base_reg] = target -
                            (uint32_t)(int32_t)displacement - effective_index;
                        state.ssp = state.address_registers[7];
                        state.sr = (uint16_t)(UINT16_C(0x270f) |
                            (((destination_reg + index_reg) & 1u) != 0u
                                ? UINT16_C(0x0010) : 0u));
                        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                          owned_cpu_restore_state(cpu, &state));
                        const size_t reads_before = memory.reads;
                        const size_t writes_before = memory.write_attempts;
                        const uint16_t source = source_values[
                            (destination_reg + index_reg + base_reg) % 4u];
                        memory.rom[target] = (uint8_t)(source >> 8);
                        memory.rom[target + 1u] = (uint8_t)source;
                        const uint16_t destination =
                            (uint16_t)state.data_registers[destination_reg];

                        owned_cpu_run_result result =
                            owned_cpu_run(cpu, UINT64_C(14));
                        TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
                        TEST_ASSERT_EQUAL_UINT64(14u, result.elapsed_cycles);
                        TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
                        TEST_ASSERT_EQUAL_UINT(3u, memory.reads - reads_before);
                        TEST_ASSERT_EQUAL_HEX32(target,
                            memory.read_addresses[reads_before + 2u]);
                        TEST_ASSERT_EQUAL_UINT(writes_before,
                                               memory.write_attempts);
                        owned_cpu_observation observation;
                        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                          owned_cpu_observe(cpu, &observation));
                        TEST_ASSERT_EQUAL_HEX16(
                            expected_compare_word_flags(state.sr, destination, source),
                            observation.sr);
                        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x104), observation.pc);
                        for (unsigned i = 0u; i < 8u; ++i)
                            TEST_ASSERT_EQUAL_HEX32(state.data_registers[i],
                                                    observation.data_registers[i]);
                        for (unsigned i = 0u; i < 8u; ++i)
                            TEST_ASSERT_EQUAL_HEX32(state.address_registers[i],
                                                    observation.address_registers[i]);
                        owned_cpu_destroy(cpu);
                        cpu = NULL;
                    }
                }
            }
        }
    }
}

static void cmp_word_address_index_aliases_base_register_without_scaling(void) {
    for (unsigned reg = 0u; reg < 8u; ++reg) {
        for (unsigned destination_reg = 0u; destination_reg < 8u;
             ++destination_reg) {
            for (unsigned index_is_long = 0u; index_is_long < 2u;
                 ++index_is_long) {
                memset(&memory, 0, sizeof(memory));
                create_cpu();
                uint8_t program[4];
                size_t length = 0u;
                emit_word(program, &length, (uint16_t)(
                    UINT16_C(0xb070) | (destination_reg << 9) | reg));
                emit_word(program, &length, (uint16_t)(
                    UINT16_C(0x8000) | (reg << 12) |
                    (index_is_long != 0u ? UINT16_C(0x0800) : 0u) |
                    UINT16_C(0x00fc)));
                TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                  reset_with_program(program, length));
                owned_cpu_state state;
                TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                  owned_cpu_capture_state(cpu, &state));
                for (unsigned i = 0u; i < 8u; ++i)
                    state.data_registers[i] = UINT32_C(0x5aa50000) |
                        ((i & 1u) != 0u ? UINT32_C(0x8001) : UINT32_C(0x7fff));
                state.address_registers[reg] = UINT32_C(0x00f2);
                state.ssp = state.address_registers[7];
                state.sr = UINT16_C(0x271f);
                TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                  owned_cpu_restore_state(cpu, &state));
                const uint32_t target = UINT32_C(0x1e0);
                const size_t reads_before = memory.reads;
                memory.rom[target] = 0x80u;
                memory.rom[target + 1u] = 0x00u;
                const uint16_t destination =
                    (uint16_t)state.data_registers[destination_reg];
                const uint16_t source = UINT16_C(0x8000);
                owned_cpu_run_result result =
                    owned_cpu_run(cpu, UINT64_C(14));
                TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
                TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
                TEST_ASSERT_EQUAL_UINT(3u, memory.reads - reads_before);
                TEST_ASSERT_EQUAL_HEX32(target,
                    memory.read_addresses[reads_before + 2u]);
                owned_cpu_observation observation;
                TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                  owned_cpu_observe(cpu, &observation));
                TEST_ASSERT_EQUAL_HEX16(
                    expected_compare_word_flags(state.sr, destination, source),
                    observation.sr);
                owned_cpu_destroy(cpu);
                cpu = NULL;
            }
        }
    }
}

static void cmp_word_address_index_odd_address_takes_vector_three_before_operand_read(void) {
    const uint8_t program[] = {0xb0, 0x70, 0x18, 0x01};
    create_cpu();
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    set_vector(12u, UINT32_C(0x140));
    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.address_registers[0] = UINT32_C(0x1e0);
    state.data_registers[1] = 0u;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
    const size_t reads_before = memory.reads;
    const size_t writes_before = memory.write_attempts;
    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(50));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(50u, result.elapsed_cycles);
    owned_cpu_observation observation;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_UINT8(3u, observation.last_exception_vector);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x140), observation.pc);
    for (size_t i = reads_before; i < memory.reads && i < ROM_SIZE; ++i)
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x1e1), memory.read_addresses[i]);
    for (size_t i = writes_before; i < memory.write_attempts && i < MAX_WRITES; ++i)
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x1e1), memory.write_addresses[i]);
}

static void cmp_long_predecrement_odd_address_commits_before_vector_three(void) {
    const uint8_t program[] = {0xb0u, 0xa0u}; /* CMP.L -(A0),D0 */
    memset(&memory, 0, sizeof(memory));
    create_cpu();
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      reset_with_program(program, sizeof(program)));
    set_vector(12u, UINT32_C(0x140));
    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.address_registers[0] = UINT32_C(0x185);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
    const size_t reads_before = memory.reads;
    const size_t writes_before = memory.write_attempts;
    const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(50));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(50u, result.elapsed_cycles);

    owned_cpu_observation observation;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_UINT8(3u, observation.last_exception_vector);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x140), observation.pc);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x181), observation.address_registers[0]);
    for (size_t i = reads_before; i < memory.reads && i < ROM_SIZE; ++i) {
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x181), memory.read_addresses[i]);
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x183), memory.read_addresses[i]);
    }
    for (size_t i = writes_before;
         i < memory.write_attempts && i < MAX_WRITES; ++i) {
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x181), memory.write_addresses[i]);
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x183), memory.write_addresses[i]);
    }
    owned_cpu_destroy(cpu);
    cpu = NULL;
}

static void cmp_word_address_index_neighbors_stay_unsupported(void) {
    static const struct { uint8_t program[4]; const char *name; } neighbors[] = {
        {{0xb0, 0x30, 0x01, 0x00}, "CMP.B indexed reserved extension bits"},
        {{0xb0, 0xbb, 0x00, 0x00}, "CMP.L (d8,PC,Xn),Dn"},
        {{0xb0, 0x7b, 0x00, 0x00}, "CMP.W (d8,PC,Xn),Dn"},
    };
    for (size_t i = 0u; i < sizeof(neighbors) / sizeof(neighbors[0]); ++i) {
        memset(&memory, 0, sizeof(memory));
        create_cpu();
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          reset_with_program(neighbors[i].program, 4u));
        owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(32));
        TEST_ASSERT_EQUAL_MESSAGE(OWNED_CPU_UNSUPPORTED_OPCODE, result.reason,
                                  neighbors[i].name);
        TEST_ASSERT_EQUAL_UINT64_MESSAGE(0u, result.elapsed_cycles,
                                         neighbors[i].name);
        TEST_ASSERT_EQUAL_UINT64_MESSAGE(0u, result.instructions,
                                         neighbors[i].name);
        TEST_ASSERT_EQUAL_UINT_MESSAGE(0u, memory.write_attempts,
                                       neighbors[i].name);
        owned_cpu_destroy(cpu);
        cpu = NULL;
    }
}

/* Guest-observed (05-02 task 2): CMP.W (xxx).L,Dn. */
static void cmp_word_absolute_long_to_data_register_compares_all_destinations(void) {
    static const uint16_t destinations[5] = {
        UINT16_C(0x0000), UINT16_C(0x7fff), UINT16_C(0x8000),
        UINT16_C(0x0000), UINT16_C(0x7ffe)};
    static const uint16_t sources[5] = {
        UINT16_C(0x0000), UINT16_C(0xffff), UINT16_C(0x0001),
        UINT16_C(0x0001), UINT16_C(0x0001)};
    const uint32_t target = UINT32_C(0x1e0);

    for (unsigned destination_reg = 0u; destination_reg < 8u;
         ++destination_reg) {
        for (unsigned case_index = 0u; case_index < 5u; ++case_index) {
            memset(&memory, 0, sizeof(memory));
            create_cpu();
            uint8_t program[6];
            size_t length = 0u;
            emit_word(program, &length, (uint16_t)(UINT16_C(0xb079) |
                                                    (destination_reg << 9)));
            emit_word(program, &length, (uint16_t)(target >> 16));
            emit_word(program, &length, (uint16_t)target);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              reset_with_program(program, length));

            owned_cpu_state before;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_capture_state(cpu, &before));
            for (unsigned reg = 0u; reg < 8u; ++reg)
                before.data_registers[reg] = UINT32_C(0xa55a0000) | reg;
            before.data_registers[destination_reg] = UINT32_C(0xa55a0000) |
                destinations[case_index];
            before.sr = UINT16_C(0x271f);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_restore_state(cpu, &before));
            memory.rom[target] = (uint8_t)(sources[case_index] >> 8);
            memory.rom[target + 1u] = (uint8_t)sources[case_index];

            const size_t reads_before = memory.reads;
            const size_t writes_before = memory.write_attempts;
            owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(16));
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
            TEST_ASSERT_EQUAL_UINT64(16u, result.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
            TEST_ASSERT_EQUAL_UINT(4u, memory.reads - reads_before);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                                    memory.read_addresses[reads_before]);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102),
                                    memory.read_addresses[reads_before + 1u]);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x104),
                                    memory.read_addresses[reads_before + 2u]);
            TEST_ASSERT_EQUAL_HEX32(target,
                                    memory.read_addresses[reads_before + 3u]);
            TEST_ASSERT_EQUAL_UINT(writes_before, memory.write_attempts);

            owned_cpu_observation after;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_observe(cpu, &after));
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x106), after.pc);
            TEST_ASSERT_EQUAL_HEX16(expected_compare_word_flags(
                before.sr, destinations[case_index], sources[case_index]),
                after.sr);
            for (unsigned reg = 0u; reg < 8u; ++reg)
                TEST_ASSERT_EQUAL_HEX32(before.data_registers[reg],
                                        after.data_registers[reg]);
            for (unsigned reg = 0u; reg < 8u; ++reg)
                TEST_ASSERT_EQUAL_HEX32(before.address_registers[reg],
                                        after.address_registers[reg]);
            owned_cpu_destroy(cpu);
            cpu = NULL;
        }
    }
}

