/* Guest-observed encoding (05-02): TST.B (xxx).W. */
static void tst_byte_absolute_short_reads_and_sets_flags_in_12_cycles(void) {
    create_cpu();
    const uint8_t program[] = {
        0x4a, 0x38, 0x01, 0xe1, /* TST.B ($01e1).W: odd byte address */
        0x4a, 0x38, 0x01, 0xe2,
        0x4a, 0x38, 0x01, 0xe3};
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    memory.rom[0x1e1] = 0x80u;
    memory.rom[0x1e2] = 0x00u;
    memory.rom[0x1e3] = 0x01u;
    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.sr = UINT16_C(0x2713); /* X V C set beforehand */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
    const uint16_t expected_flags[] = {
        UINT16_C(0x2718), UINT16_C(0x2714), UINT16_C(0x2710)};
    const uint32_t expected_addresses[] = {
        UINT32_C(0x1e1), UINT32_C(0x1e2), UINT32_C(0x1e3)};
    owned_cpu_observation observation;
    for (size_t index = 0u; index < 3u; ++index) {
        const size_t reads_before = memory.reads;
        const size_t byte_reads_before = memory.byte_reads;
        const size_t writes_before = memory.write_attempts;
        owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(12));
        TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
        TEST_ASSERT_EQUAL_UINT64(12u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
        /* Opcode and extension words; the byte operand has its own counter. */
        TEST_ASSERT_EQUAL_UINT(2u, memory.reads - reads_before);
        TEST_ASSERT_EQUAL_UINT(1u, memory.byte_reads - byte_reads_before);
        TEST_ASSERT_EQUAL_HEX32(expected_addresses[index],
                                memory.byte_read_addresses[byte_reads_before]);
        TEST_ASSERT_EQUAL_UINT(writes_before, memory.write_attempts);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x104) + (uint32_t)(index * 4u),
                                observation.pc);
        TEST_ASSERT_EQUAL_HEX16(expected_flags[index], observation.sr);
    }
}

/* Guest-observed (05-02 task 2): NOT.B Dn complements only Dn[7:0]. */
static void not_byte_data_register_complements_all_registers(void) {
    static const uint8_t values[8] = {
        UINT8_C(0x00), UINT8_C(0xff), UINT8_C(0x80), UINT8_C(0x7f),
        UINT8_C(0x01), UINT8_C(0x55), UINT8_C(0xaa), UINT8_C(0xfe),
    };
    for (unsigned reg = 0u; reg < 8u; ++reg) {
        setUp();
        create_cpu();
        const uint8_t program[] = {0x46u, (uint8_t)reg};
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
        owned_cpu_state before;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
        for (unsigned i = 0u; i < 8u; ++i)
            before.data_registers[i] = UINT32_C(0x12340000) + i * UINT32_C(0x100);
        before.data_registers[reg] |= values[reg];
        before.sr = UINT16_C(0x271f);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));
        const uint8_t result_byte = (uint8_t)~values[reg];
        const size_t reads_before = memory.reads;
        const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(4));
        TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
        TEST_ASSERT_EQUAL_UINT64(4u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
        TEST_ASSERT_EQUAL_UINT(1u, memory.reads - reads_before);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100), memory.read_addresses[reads_before]);
        TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
        owned_cpu_state after;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &after));
        for (unsigned i = 0u; i < 8u; ++i) {
            const uint32_t expected = i == reg
                ? (before.data_registers[i] & UINT32_C(0xffffff00)) | result_byte
                : before.data_registers[i];
            TEST_ASSERT_EQUAL_HEX32(expected, after.data_registers[i]);
            TEST_ASSERT_EQUAL_HEX32(before.address_registers[i], after.address_registers[i]);
        }
        uint16_t expected_sr = UINT16_C(0x2710); /* preserve X; clear V/C */
        if (result_byte == 0u) expected_sr |= UINT16_C(0x0004);
        if ((result_byte & UINT8_C(0x80)) != 0u) expected_sr |= UINT16_C(0x0008);
        TEST_ASSERT_EQUAL_HEX16(expected_sr, after.sr);
        tearDown();
    }
}

static void not_non_data_alterable_neighbors_stay_unsupported(void) {
    static const uint16_t opcodes[] = {
        UINT16_C(0x4648), /* NOT.W A0: address-register direct is not data alterable */
        UINT16_C(0x467a), /* NOT.W (d16,PC) */
        UINT16_C(0x46bc), /* NOT.L #imm: immediate is mode 111, register 100 */
    };
    for (size_t i = 0u; i < sizeof(opcodes) / sizeof(opcodes[0]); ++i) {
        setUp();
        create_cpu();
        uint8_t program[2];
        size_t length = 0u;
        emit_word(program, &length, opcodes[i]);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, length));
        owned_cpu_state before;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
        const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(16));
        TEST_ASSERT_EQUAL_MESSAGE(OWNED_CPU_UNSUPPORTED_OPCODE, result.reason,
                                  i == 0u ? "NOT.W An" :
                                  i == 1u ? "NOT.W (d16,PC)" :
                                            "NOT.L immediate");
        TEST_ASSERT_EQUAL_UINT64(0u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(0u, result.instructions);
        TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
        owned_cpu_state after;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &after));
        TEST_ASSERT_EQUAL_HEX16(before.sr, after.sr);
        for (unsigned reg = 0u; reg < 8u; ++reg)
            TEST_ASSERT_EQUAL_HEX32(before.data_registers[reg], after.data_registers[reg]);
        tearDown();
    }
}

/* NOT has one operation across its byte/word/long data-alterable forms.
 * PRM §4 NOT, pp. 4-148 to 4-149, defines complement and N/Z with X
 * preserved and V/C cleared; UM Rev. 9.1 Table 8-6 p. 8-6 gives register
 * timings 4/4/6. */
static void not_data_register_widths_use_manual_timing_and_preserve_upper_bits(void) {
    static const unsigned widths[] = {1u, 2u, 4u};
    static const unsigned size_codes[] = {0u, 1u, 2u};
    static const uint64_t cycles[] = {4u, 4u, 6u};
    for (size_t size_index = 0u; size_index < 3u; ++size_index) {
        const unsigned width = widths[size_index];
        const uint32_t mask = width == 4u ? UINT32_MAX :
            (UINT32_C(1) << (width * 8u)) - UINT32_C(1);
        const uint32_t sign_bit = UINT32_C(1) << (width * 8u - 1u);
        for (unsigned reg = 0u; reg < 8u; ++reg) {
            setUp();
            create_cpu();
            uint8_t program[2];
            size_t length = 0u;
            emit_word(program, &length, (uint16_t)(UINT16_C(0x4600) |
                (uint16_t)(size_codes[size_index] << 6) | (uint16_t)reg));
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              reset_with_program(program, length));
            owned_cpu_state before;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_capture_state(cpu, &before));
            for (unsigned index = 0u; index < 8u; ++index)
                before.data_registers[index] = UINT32_C(0xa5c30000) +
                    (uint32_t)(index * UINT32_C(0x01010101));
            before.data_registers[reg] =
                (before.data_registers[reg] & ~mask) |
                (((uint32_t)reg * UINT32_C(0x13579bdf)) & mask);
            before.sr = UINT16_C(0x271f);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_restore_state(cpu, &before));

            const uint32_t operand = before.data_registers[reg] & mask;
            const uint32_t value = (~operand) & mask;
            uint16_t expected_sr = (uint16_t)(before.sr &
                                               (uint16_t)~UINT16_C(0x000f));
            if (value == 0u)
                expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0004));
            if ((value & sign_bit) != 0u)
                expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0008));
            const size_t reads_before = memory.reads;
            const owned_cpu_run_result run = owned_cpu_run(cpu, cycles[size_index]);
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, run.reason);
            TEST_ASSERT_EQUAL_UINT64(cycles[size_index], run.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, run.instructions);
            TEST_ASSERT_EQUAL_UINT(1u, memory.reads - reads_before);
            TEST_ASSERT_EQUAL_UINT(0u, memory.byte_reads);
            TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);

            owned_cpu_state after;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_capture_state(cpu, &after));
            TEST_ASSERT_EQUAL_HEX16(expected_sr, after.sr);
            for (unsigned index = 0u; index < 8u; ++index) {
                const uint32_t expected = index == reg
                    ? (before.data_registers[index] & ~mask) | value
                    : before.data_registers[index];
                TEST_ASSERT_EQUAL_HEX32(expected, after.data_registers[index]);
                TEST_ASSERT_EQUAL_HEX32(before.address_registers[index],
                                        after.address_registers[index]);
            }
            tearDown();
        }
    }
}

/* Table 8-6 single-operand bases (8 clocks for byte/word, 12 for long) add
 * Table 8-1's memory-EA timing. Cover all seven data-alterable memory EAs for
 * every width, including odd byte addresses and A7's two-byte byte step. */
static void not_memory_data_alterable_widths_use_table_timing_and_rmw(void) {
    static const unsigned widths[] = {1u, 2u, 4u};
    static const unsigned size_codes[] = {0u, 1u, 2u};
    static const uint64_t ea_cycles[7][3] = {
        {4u, 4u, 8u}, {4u, 4u, 8u}, {6u, 6u, 10u},
        {8u, 8u, 12u}, {10u, 10u, 14u}, {8u, 8u, 12u},
        {12u, 12u, 16u},
    };
    static const unsigned modes[] = {2u, 3u, 4u, 5u, 6u, 7u, 7u};

    for (size_t size_index = 0u; size_index < 3u; ++size_index) {
        const unsigned width = widths[size_index];
        const uint32_t mask = width == 4u ? UINT32_MAX :
            (UINT32_C(1) << (width * 8u)) - UINT32_C(1);
        const uint32_t sign_bit = UINT32_C(1) << (width * 8u - 1u);
        for (size_t ea_index = 0u; ea_index < 7u; ++ea_index) {
            const unsigned mode = modes[ea_index];
            const unsigned reg = mode == 7u ?
                (ea_index == 5u ? 0u : 1u) :
                (unsigned)((ea_index + size_index * 3u) & 7u);
            const unsigned extension_words = mode == 5u || mode == 6u ||
                (mode == 7u && reg == 0u) ? 1u :
                (mode == 7u && reg == 1u) ? 2u : 0u;
            const uint16_t opcode = (uint16_t)(UINT16_C(0x4600) |
                (uint16_t)(size_codes[size_index] << 6) |
                (uint16_t)(mode << 3) | (uint16_t)reg);
            uint8_t program[6];
            size_t program_length = 0u;
            emit_word(program, &program_length, opcode);
            if (mode == 5u)
                emit_word(program, &program_length, UINT16_C(2));
            else if (mode == 6u)
                emit_word(program, &program_length, UINT16_C(2));
            else if (mode == 7u && reg == 0u)
                emit_word(program, &program_length,
                          (uint16_t)(UINT16_C(0x01a0) |
                                     (width == 1u ? UINT16_C(1) : UINT16_C(0))));
            else if (mode == 7u && reg == 1u) {
                emit_word(program, &program_length, UINT16_C(0));
                emit_word(program, &program_length,
                          (uint16_t)(UINT16_C(0x01c0) |
                                     (width == 1u ? UINT16_C(1) : UINT16_C(0))));
            }

            setUp();
            create_cpu();
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              reset_with_program(program, program_length));
            owned_cpu_state before;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_capture_state(cpu, &before));
            for (unsigned index = 0u; index < 8u; ++index)
                before.address_registers[index] = UINT32_C(0x0120) +
                    (uint32_t)(index * UINT32_C(0x10)) +
                    (width == 1u ? UINT32_C(1) : UINT32_C(0));
            before.data_registers[0] = UINT32_C(4); /* D0.W brief index */
            before.ssp = before.address_registers[7];
            before.sr = UINT16_C(0x271f);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_restore_state(cpu, &before));

            const unsigned step = width == 1u && reg == 7u ? 2u : width;
            const uint32_t base = before.address_registers[reg];
            uint32_t address = 0u;
            if (mode == 2u || mode == 3u)
                address = base;
            else if (mode == 4u)
                address = base - (uint32_t)step;
            else if (mode == 5u)
                address = base + UINT32_C(2);
            else if (mode == 6u)
                address = base + UINT32_C(6);
            else if (mode == 7u && reg == 0u)
                address = UINT32_C(0x01a0) +
                    (width == 1u ? UINT32_C(1) : UINT32_C(0));
            else
                address = UINT32_C(0x01c0) +
                    (width == 1u ? UINT32_C(1) : UINT32_C(0));

            const uint32_t operand = ea_index == 0u ? mask :
                ((UINT32_C(0x13579bdf) + (uint32_t)(ea_index * 17u) +
                  (uint32_t)(size_index * 0x01010101u)) & mask);
            for (unsigned byte = 0u; byte < width; ++byte)
                memory.rom[address + byte] = (uint8_t)(operand >>
                    ((width - byte - 1u) * 8u));
            const uint32_t value = (~operand) & mask;
            uint16_t expected_sr = (uint16_t)(before.sr &
                                               (uint16_t)~UINT16_C(0x000f));
            if (value == 0u)
                expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0004));
            if ((value & sign_bit) != 0u)
                expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0008));
            const uint64_t total_cycles =
                (width == 4u ? UINT64_C(12) : UINT64_C(8)) +
                ea_cycles[ea_index][size_index];
            const size_t reads_before = memory.reads;
            const size_t ordered_reads_before = memory.ordered_read_count;
            const size_t byte_reads_before = memory.byte_reads;
            const unsigned writes_before = memory.write_attempts;
            const owned_cpu_run_result run = owned_cpu_run(cpu, total_cycles);
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, run.reason);
            TEST_ASSERT_EQUAL_UINT64(total_cycles, run.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, run.instructions);
            TEST_ASSERT_EQUAL_UINT(1u + extension_words +
                                  (width == 1u ? 0u : width / 2u),
                                  memory.reads - reads_before);
            TEST_ASSERT_EQUAL_UINT(width == 1u ? 1u : 0u,
                                   memory.byte_reads - byte_reads_before);
            TEST_ASSERT_EQUAL_UINT(width == 4u ? 2u : 1u,
                                   memory.write_attempts - writes_before);
            TEST_ASSERT_EQUAL_HEX32(address,
                memory.ordered_read_addresses[ordered_reads_before + 1u +
                                               extension_words]);
            if (width == 4u)
                TEST_ASSERT_EQUAL_HEX32(address + UINT32_C(2),
                    memory.ordered_read_addresses[ordered_reads_before +
                                                   extension_words + 2u]);
            if (width == 1u) {
                TEST_ASSERT_EQUAL_HEX32(address,
                                        memory.byte_write_addresses[writes_before]);
                TEST_ASSERT_EQUAL_HEX32(value,
                                        memory.byte_write_values[writes_before]);
            } else {
                TEST_ASSERT_EQUAL_HEX32(address,
                                        memory.write_addresses[writes_before]);
                TEST_ASSERT_EQUAL_HEX16((uint16_t)(value >>
                    (width == 4u ? 16u : 0u)),
                    memory.write_values[writes_before]);
                if (width == 4u) {
                    TEST_ASSERT_EQUAL_HEX32(address + UINT32_C(2),
                        memory.write_addresses[writes_before + 1u]);
                    TEST_ASSERT_EQUAL_HEX16((uint16_t)value,
                        memory.write_values[writes_before + 1u]);
                }
            }

            owned_cpu_state after;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_capture_state(cpu, &after));
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100) +
                                    (uint32_t)program_length, after.pc);
            TEST_ASSERT_EQUAL_HEX16(expected_sr, after.sr);
            for (unsigned index = 0u; index < 8u; ++index) {
                uint32_t expected = before.address_registers[index];
                if (index == reg && mode == 3u)
                    expected += (uint32_t)step;
                if (index == reg && mode == 4u)
                    expected -= (uint32_t)step;
                TEST_ASSERT_EQUAL_HEX32(expected,
                                        after.address_registers[index]);
            }
            tearDown();
        }
    }
}

static void not_memory_odd_word_and_long_faults_commit_auto_updates_before_vector_three(void) {
    static const struct {
        uint16_t opcode;
        unsigned address_register;
        uint32_t initial_address;
        uint32_t expected_address_register;
        uint32_t fault_address;
    } cases[] = {
        {UINT16_C(0x4660), 0u, UINT32_C(0x0183), UINT32_C(0x0181),
         UINT32_C(0x0181)}, /* NOT.W -(A0) */
        {UINT16_C(0x469a), 2u, UINT32_C(0x01e1), UINT32_C(0x01e5),
         UINT32_C(0x01e1)}, /* NOT.L (A2)+ */
    };

    for (size_t index = 0u; index < sizeof(cases) / sizeof(cases[0]); ++index) {
        setUp();
        create_cpu();
        uint8_t program[2];
        size_t length = 0u;
        emit_word(program, &length, cases[index].opcode);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, length));
        set_vector(12u, UINT32_C(0x140));
        owned_cpu_state before;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
        before.address_registers[cases[index].address_register] =
            cases[index].initial_address;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));

        const size_t reads_before = memory.reads;
        const size_t writes_before = memory.write_attempts;
        const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(50));
        TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
        TEST_ASSERT_EQUAL_UINT64(50u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(0u, result.instructions);
        owned_cpu_observation after;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
        TEST_ASSERT_EQUAL_UINT8(3u, after.last_exception_vector);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x140), after.pc);
        TEST_ASSERT_EQUAL_HEX32(cases[index].expected_address_register,
                                after.address_registers[
                                    cases[index].address_register]);
        for (size_t read = reads_before;
             read < memory.reads && read < ROM_SIZE; ++read)
            TEST_ASSERT_NOT_EQUAL(cases[index].fault_address,
                                  memory.read_addresses[read]);
        for (size_t write = writes_before;
             write < memory.write_attempts && write < MAX_WRITES; ++write)
            TEST_ASSERT_NOT_EQUAL(cases[index].fault_address,
                                  memory.write_addresses[write]);
        tearDown();
    }
}

/* Guest-observed encoding (05-02): TST.W (d16,An). */
static void tst_word_displacement_addressing_covers_all_address_registers(void) {
    static const uint16_t values[8] = {
        UINT16_C(0x8000), UINT16_C(0x0000), UINT16_C(0x0001), UINT16_C(0x7fff),
        UINT16_C(0xffff), UINT16_C(0x7fff), UINT16_C(0x8000), UINT16_C(0x0000)};
    uint8_t program[32];
    size_t length = 0u;
    for (unsigned reg = 0u; reg < 8u; ++reg) {
        emit_word(program, &length, (uint16_t)(UINT16_C(0x4a68) | reg));
        emit_word(program, &length, UINT16_C(0xfffc)); /* signed -4 */
    }
    create_cpu();
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, length));
    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    for (unsigned reg = 0u; reg < 8u; ++reg) {
        const uint32_t target = UINT32_C(0x1e0) + (uint32_t)(reg * 4u);
        state.address_registers[reg] = target + UINT32_C(4);
        memory.rom[target] = (uint8_t)(values[reg] >> 8);
        memory.rom[target + 1u] = (uint8_t)values[reg];
    }
    state.ssp = state.address_registers[7]; /* supervisor A7 bank stays coherent */
    state.sr = UINT16_C(0x271f); /* N/Z/V/C/X set before each TST */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));

    owned_cpu_observation observation;
    for (unsigned reg = 0u; reg < 8u; ++reg) {
        const size_t reads_before = memory.reads;
        const size_t writes_before = memory.write_attempts;
        owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(12));
        TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
        TEST_ASSERT_EQUAL_UINT64(12u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
        TEST_ASSERT_EQUAL_UINT(3u, memory.reads - reads_before);
        TEST_ASSERT_EQUAL_UINT(writes_before, memory.write_attempts);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x1e0) + (uint32_t)(reg * 4u),
                                memory.read_addresses[reads_before + 2u]);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x104) + (uint32_t)(reg * 4u),
                                observation.pc);
        uint16_t expected_flags = UINT16_C(0x2710); /* X preserved; V/C cleared */
        if (values[reg] == 0u) expected_flags |= UINT16_C(0x0004);
        if ((values[reg] & UINT16_C(0x8000)) != 0u)
            expected_flags |= UINT16_C(0x0008);
        TEST_ASSERT_EQUAL_HEX16(expected_flags, observation.sr);
        for (unsigned i = 0u; i < 8u; ++i)
            TEST_ASSERT_EQUAL_HEX32(state.address_registers[i],
                                    observation.address_registers[i]);
    }
}

static void tst_word_displacement_odd_address_takes_vector_three_without_operand_read(void) {
    const uint8_t program[] = {0x4a, 0x6c, 0x00, 0x01}; /* TST.W (1,A4) */
    create_cpu();
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    set_vector(12u, UINT32_C(0x140)); /* vector 3 table offset */
    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.address_registers[4] = UINT32_C(0x1e0);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));

    const size_t reads_before = memory.reads;
    const size_t writes_before = memory.write_attempts;
    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(50));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(50u, result.elapsed_cycles);
    owned_cpu_observation observation;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_UINT8(3u, observation.last_exception_vector);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x140), observation.pc);
    for (size_t index = reads_before; index < memory.reads && index < ROM_SIZE; ++index)
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x1e1), memory.read_addresses[index]);
    for (size_t index = writes_before; index < memory.write_attempts && index < MAX_WRITES;
         ++index)
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x1e1), memory.write_addresses[index]);
}

static void tst_word_displacement_neighbors_stay_unsupported(void) {
    static const struct { uint8_t program[6]; const char *name; } neighbors[] = {
        {{0x4a, 0xba, 0x00, 0x00, 0x00, 0x00}, "TST.L (d16,PC)"},
        {{0x4a, 0x7a, 0x00, 0x00, 0x00, 0x00}, "TST.W (d16,PC)"},
    };
    for (size_t index = 0u; index < sizeof(neighbors) / sizeof(neighbors[0]); ++index) {
        memset(&memory, 0, sizeof(memory));
        create_cpu();
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          reset_with_program(neighbors[index].program, 6u));
        owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(32));
        TEST_ASSERT_EQUAL_MESSAGE(OWNED_CPU_UNSUPPORTED_OPCODE, result.reason,
                                  neighbors[index].name);
        TEST_ASSERT_EQUAL_UINT_MESSAGE(0u, memory.write_attempts,
                                       neighbors[index].name);
        owned_cpu_destroy(cpu);
        cpu = NULL;
    }
}

/* Guest-observed TST.W (An). PRM section 4 TST, pp. 4-192 to 4-193,
 * requires N/Z from the word, V/C cleared and X preserved. UM Rev. 9.1
 * Table 8-6 (printed p. 8-6) gives 4(1/0); Table 8-1 (printed p. 8-2)
 * adds 4(1/0) for (An), totaling 8 clocks and two word reads, no writes. */
static void tst_word_address_indirect_register_variants_use_8_cycles(void) {
    static const uint16_t values[8] = {
        0x0000u, 0x8000u, 0x0001u, 0x7fffu,
        0xffffu, 0x0000u, 0x4000u, 0x8001u};
    for (unsigned reg = 0u; reg < 8u; ++reg) {
        memset(&memory, 0, sizeof(memory));
        create_cpu();
        const uint16_t opcode = (uint16_t)(UINT16_C(0x4a50) | reg);
        const uint8_t program[] = {(uint8_t)(opcode >> 8), (uint8_t)opcode};
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
        const uint32_t address = UINT32_C(0x180) + (uint32_t)reg * UINT32_C(2);
        memory.rom[address] = (uint8_t)(values[reg] >> 8);
        memory.rom[address + 1u] = (uint8_t)values[reg];
        owned_cpu_state state;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
        for (unsigned data_reg = 0u; data_reg < 8u; ++data_reg)
            state.data_registers[data_reg] = UINT32_C(0xa5c30000) | data_reg;
        state.address_registers[reg] = address;
        if (reg == 7u) state.ssp = address;
        state.sr = UINT16_C(0x271f); /* all condition bits set before TST */
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));

        const size_t reads_before = memory.reads;
        const size_t writes_before = memory.write_attempts;
        owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(8));
        TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
        TEST_ASSERT_EQUAL_UINT64(8u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
        TEST_ASSERT_EQUAL_UINT(2u, memory.reads - reads_before);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                                memory.read_addresses[reads_before]);
        TEST_ASSERT_EQUAL_HEX32(address,
                                memory.read_addresses[reads_before + 1u]);
        TEST_ASSERT_EQUAL_UINT(writes_before, memory.write_attempts);
        owned_cpu_observation observation;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102), observation.pc);
        uint16_t expected_sr = UINT16_C(0x2710); /* X preserved; V/C cleared */
        if (values[reg] == 0u) expected_sr |= UINT16_C(0x0004);
        if ((values[reg] & UINT16_C(0x8000)) != 0u)
            expected_sr |= UINT16_C(0x0008);
        TEST_ASSERT_EQUAL_HEX16(expected_sr, observation.sr);
        TEST_ASSERT_EQUAL_HEX32(address, observation.address_registers[reg]);
        for (unsigned data_reg = 0u; data_reg < 8u; ++data_reg)
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0xa5c30000) | data_reg,
                                    observation.data_registers[data_reg]);
        owned_cpu_destroy(cpu);
        cpu = NULL;
    }
}

/* Guest-observed TST.B (An). Byte operands may be odd; only N/Z are derived
 * from the byte, V/C clear and X is preserved. */
static void tst_byte_address_indirect_reads_all_bases_and_allows_odd_addresses(void) {
    static const uint8_t values[8] = {
        0x00u, 0x80u, 0x01u, 0xffu, 0x7fu, 0x81u, 0x00u, 0x55u};
    for (unsigned reg = 0u; reg < 8u; ++reg) {
        memset(&memory, 0, sizeof(memory));
        create_cpu();
        const uint16_t opcode = (uint16_t)(UINT16_C(0x4a10) | reg);
        const uint8_t program[] = {(uint8_t)(opcode >> 8), (uint8_t)opcode};
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
        const uint32_t address = UINT32_C(0x181) + (uint32_t)reg * UINT32_C(2);
        TEST_ASSERT_EQUAL_UINT(1u, address & 1u);
        memory.rom[address] = values[reg];
        owned_cpu_state before;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
        for (unsigned i = 0u; i < 8u; ++i) {
            before.data_registers[i] = UINT32_C(0xa5c30000) | i;
            before.address_registers[i] = UINT32_C(0x180) + i * UINT32_C(2);
        }
        before.address_registers[reg] = address;
        before.ssp = before.address_registers[7];
        before.sr = (uint16_t)(UINT16_C(0x270f) |
            ((reg & 1u) != 0u ? UINT16_C(0x0010) : UINT16_C(0x0000)));
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));

        const size_t reads_before = memory.reads;
        const size_t byte_reads_before = memory.byte_reads;
        const size_t writes_before = memory.write_attempts;
        const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(8));
        TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
        TEST_ASSERT_EQUAL_UINT64(8u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
        TEST_ASSERT_EQUAL_UINT(1u, memory.reads - reads_before);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100), memory.read_addresses[reads_before]);
        TEST_ASSERT_EQUAL_UINT(1u, memory.byte_reads - byte_reads_before);
        TEST_ASSERT_EQUAL_HEX32(address, memory.byte_read_addresses[byte_reads_before]);
        TEST_ASSERT_EQUAL_UINT(writes_before, memory.write_attempts);
        TEST_ASSERT_EQUAL_HEX8(values[reg], memory.rom[address]);

        owned_cpu_state after;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &after));
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102), after.pc);
        uint16_t expected_sr = (uint16_t)(before.sr & (uint16_t)~UINT16_C(0x000f));
        if (values[reg] == 0u) expected_sr |= UINT16_C(0x0004);
        if ((values[reg] & UINT8_C(0x80)) != 0u) expected_sr |= UINT16_C(0x0008);
        TEST_ASSERT_EQUAL_HEX16(expected_sr, after.sr);
        for (unsigned i = 0u; i < 8u; ++i) {
            TEST_ASSERT_EQUAL_HEX32(before.data_registers[i], after.data_registers[i]);
            TEST_ASSERT_EQUAL_HEX32(before.address_registers[i], after.address_registers[i]);
        }
        TEST_ASSERT_EQUAL_HEX32(before.ssp, after.ssp);
        owned_cpu_destroy(cpu);
        cpu = NULL;
    }
}

static void tst_word_address_indirect_odd_address_takes_vector_three_before_read(void) {
    const uint8_t program[] = {0x4au, 0x50u}; /* TST.W (A0) */
    memset(&memory, 0, sizeof(memory));
    create_cpu();
    set_vector(12u, UINT32_C(0x140)); /* vector 3 table offset */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.address_registers[0] = UINT32_C(0x181);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
    const size_t reads_before = memory.reads;
    const size_t writes_before = memory.write_attempts;
    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(50));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(50u, result.elapsed_cycles);
    owned_cpu_observation observation;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_UINT8(3u, observation.last_exception_vector);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x140), observation.pc);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x181), observation.address_registers[0]);
    for (size_t i = reads_before; i < memory.reads && i < ROM_SIZE; ++i)
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x181), memory.read_addresses[i]);
    for (size_t i = writes_before; i < memory.write_attempts && i < MAX_WRITES; ++i)
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x181), memory.write_addresses[i]);
}

