/* Guest-observed encoding (05-02): TST.B (d16,An). */
static void tst_byte_displacement_reads_all_address_registers_and_allows_odd_addresses(void) {
    static const int16_t displacements[8] = {-8, -3, 0, 5, -2, 1, 6, -1};
    static const uint8_t values[8] = {
        0x00u, 0x80u, 0xffu, 0x01u, 0x7fu, 0x81u, 0x00u, 0x55u};
    for (unsigned reg = 0u; reg < 8u; ++reg) {
        memset(&memory, 0, sizeof(memory));
        create_cpu();
        uint8_t program[4];
        size_t length = 0u;
        emit_word(program, &length,
                  (uint16_t)(UINT16_C(0x4a28) | reg));
        emit_word(program, &length, (uint16_t)displacements[reg]);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, length));
        owned_cpu_state before;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
        for (unsigned index = 0u; index < 8u; ++index) {
            before.data_registers[index] = UINT32_C(0x55aa0000) + index;
            before.address_registers[index] = UINT32_C(0x40) + index * UINT32_C(2);
        }
        const uint32_t base = UINT32_C(0x80) + (uint32_t)reg * UINT32_C(2);
        before.address_registers[reg] = base;
        before.ssp = before.address_registers[7];
        before.sr = (reg & 1u) != 0u ? UINT16_C(0x271f) : UINT16_C(0x2700);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));
        const uint32_t address =
            base + (uint32_t)(int32_t)displacements[reg];
        memory.rom[address] = values[reg];
        const size_t reads_before = memory.reads;
        const size_t byte_reads_before = memory.byte_reads;
        const size_t writes_before = memory.write_attempts;
        owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(12));
        TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
        TEST_ASSERT_EQUAL_UINT64(12u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
        TEST_ASSERT_EQUAL_UINT(2u, memory.reads - reads_before);
        TEST_ASSERT_EQUAL_UINT(byte_reads_before + 1u, memory.byte_reads);
        TEST_ASSERT_EQUAL_HEX32(address,
            memory.byte_read_addresses[byte_reads_before]);
        TEST_ASSERT_EQUAL_UINT(writes_before, memory.write_attempts);
        owned_cpu_state after;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &after));
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x104), after.pc);
        uint16_t expected_sr = (uint16_t)(before.sr & UINT16_C(0xfff0));
        if (values[reg] == 0u) expected_sr |= UINT16_C(0x0004);
        if ((values[reg] & UINT8_C(0x80)) != 0u)
            expected_sr |= UINT16_C(0x0008);
        TEST_ASSERT_EQUAL_HEX16(expected_sr, after.sr);
        for (unsigned index = 0u; index < 8u; ++index) {
            TEST_ASSERT_EQUAL_HEX32(before.data_registers[index],
                                    after.data_registers[index]);
            TEST_ASSERT_EQUAL_HEX32(before.address_registers[index],
                                    after.address_registers[index]);
        }
        owned_cpu_destroy(cpu);
        cpu = NULL;
    }
}

/* Guest-observed encoding (05-02): TST.W (d8,An,Xn). */
static void tst_word_address_index_covers_registers_and_index_sizes(void) {
    static const uint16_t values[8] = {
        UINT16_C(0x8000), UINT16_C(0x0000), UINT16_C(0x0001), UINT16_C(0x7fff),
        UINT16_C(0xffff), UINT16_C(0x8001), UINT16_C(0x55aa), UINT16_C(0x0000)};
    for (unsigned test_case = 0u; test_case < 16u; ++test_case) {
        memset(&memory, 0, sizeof(memory));
        create_cpu();
        const unsigned base_register = test_case & 7u;
        const unsigned index_is_address = test_case & 1u;
        const unsigned index_is_long = (test_case >> 1) & 1u;
        const unsigned index_register = index_is_address != 0u
            ? (base_register + 2u) & 7u : (test_case + 1u) & 7u;
        const int8_t displacement = (int8_t)((int)(test_case % 4u) * 2 - 4);
        uint8_t program[4];
        size_t length = 0u;
        emit_word(program, &length,
                  (uint16_t)(UINT16_C(0x4a70) | base_register));
        uint32_t index_value;
        if (index_is_long != 0u)
            index_value = test_case % 4u == 1u
                ? UINT32_C(0xfffffff8)
                : UINT32_C(0x20) + (uint32_t)test_case * UINT32_C(2);
        else
            index_value = test_case % 4u == 0u
                ? UINT32_C(0xfffffffc)
                : UINT32_C(0x20) + (uint32_t)test_case * UINT32_C(2);
        emit_word(program, &length, (uint16_t)(
            (index_is_address != 0u ? UINT16_C(0x8000) : 0u) |
            (index_register << 12) |
            (index_is_long != 0u ? UINT16_C(0x0800) : 0u) |
            (uint8_t)displacement));
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, length));
        owned_cpu_state before;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
        for (unsigned reg = 0u; reg < 8u; ++reg) {
            before.data_registers[reg] = UINT32_C(0x55aa0000) + reg;
            before.address_registers[reg] = UINT32_C(0x40) + reg * UINT32_C(2);
        }
        const uint32_t base = UINT32_C(0x80) +
            (uint32_t)test_case * UINT32_C(2);
        before.address_registers[base_register] = base;
        if (index_is_address != 0u)
            before.address_registers[index_register] = index_value;
        else
            before.data_registers[index_register] = index_value;
        before.ssp = before.address_registers[7];
        before.sr = (test_case & 1u) != 0u
            ? UINT16_C(0x271f) : UINT16_C(0x2700);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));
        const uint32_t address = base + index_value +
            (uint32_t)(int32_t)displacement;
        memory.rom[address] = (uint8_t)(values[test_case % 8u] >> 8);
        memory.rom[address + 1u] = (uint8_t)values[test_case % 8u];
        const size_t reads_before = memory.reads;
        const size_t writes_before = memory.write_attempts;
        owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(14));
        TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
        TEST_ASSERT_EQUAL_UINT64(14u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
        TEST_ASSERT_EQUAL_UINT(3u, memory.reads - reads_before);
        TEST_ASSERT_EQUAL_UINT(0u, memory.byte_reads);
        TEST_ASSERT_EQUAL_HEX32(address, memory.read_addresses[reads_before + 2u]);
        TEST_ASSERT_EQUAL_UINT(writes_before, memory.write_attempts);
        owned_cpu_state after;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &after));
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x104), after.pc);
        uint16_t expected_sr = (uint16_t)(before.sr & UINT16_C(0xfff0));
        if (values[test_case % 8u] == 0u) expected_sr |= UINT16_C(0x0004);
        if ((values[test_case % 8u] & UINT16_C(0x8000)) != 0u)
            expected_sr |= UINT16_C(0x0008);
        TEST_ASSERT_EQUAL_HEX16(expected_sr, after.sr);
        for (unsigned reg = 0u; reg < 8u; ++reg) {
            TEST_ASSERT_EQUAL_HEX32(before.data_registers[reg],
                                    after.data_registers[reg]);
            TEST_ASSERT_EQUAL_HEX32(before.address_registers[reg],
                                    after.address_registers[reg]);
        }
        owned_cpu_destroy(cpu);
        cpu = NULL;
    }
}

