        for (unsigned i = 0u; i < 8u; ++i)
            before.data_registers[i] = UINT32_C(0xa55a0000) |
                                       (uint32_t)(UINT16_C(0x1100) + i);
        before.data_registers[reg] = UINT32_C(0x5aa50000) |
                                     cases[reg].destination;
        before.sr = cases[reg].sr;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          owned_cpu_restore_state(cpu, &before));
