/* The remaining immediate rotate widths share the register-only ROL/ROR
 * contract. Rotates do not consume X; C receives the last bit rotated out,
 * X is preserved, V clears, N/Z follow the selected width, and count field
 * zero means eight. */
static void rotate_immediate_byte_word_and_long_forms_cover_boundaries(void) {
    static const struct {
        unsigned width;
        unsigned size_code;
        unsigned left;
    } forms[] = {
        {1u, 0u, 1u}, {2u, 1u, 1u}, {4u, 2u, 1u},
        {1u, 0u, 0u}, {2u, 1u, 0u}, {4u, 2u, 0u},
    };

    for (size_t form_index = 0u;
         form_index < sizeof(forms) / sizeof(forms[0]); ++form_index) {
        const unsigned width = forms[form_index].width;
        const unsigned bits = width * 8u;
        const uint32_t mask = width == 4u ? UINT32_MAX
            : (UINT32_C(1) << bits) - UINT32_C(1);
        const uint32_t sign = UINT32_C(1) << (bits - 1u);
        const uint32_t values[] = {sign | UINT32_C(1), sign >> 1u,
                                   UINT32_C(1), UINT32_C(0)};
        const uint16_t base = (uint16_t)(UINT16_C(0xe018) |
            (forms[form_index].left != 0u ? UINT16_C(0x0100) : 0u) |
            (uint16_t)(forms[form_index].size_code << 6));

        for (unsigned count = 1u; count <= 8u; ++count) {
            const unsigned count_field = count & 7u;
            const uint32_t carry_probe = forms[form_index].left != 0u
                ? UINT32_C(1) << (bits - count)
                : UINT32_C(1) << (count - 1u);
            for (unsigned reg = 0u; reg < 8u; ++reg) {
                for (size_t value_index = 0u;
                     value_index < sizeof(values) / sizeof(values[0]) + 1u;
                     ++value_index) {
                    for (unsigned extend = 0u; extend < 2u; ++extend) {
                        setUp();
                        create_cpu();
                        const uint16_t opcode = (uint16_t)(base |
                            (uint16_t)(count_field << 9) | (uint16_t)reg);
                        uint8_t program[2];
                        size_t length = 0u;
                        emit_word(program, &length, opcode);
                        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                            reset_with_program(program, length));

                        owned_cpu_state before;
                        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                            owned_cpu_capture_state(cpu, &before));
                        for (unsigned other = 0u; other < 8u; ++other)
                            before.data_registers[other] =
                                UINT32_C(0x5a5a0000) | (uint32_t)other;
                        const uint32_t input = value_index ==
                            sizeof(values) / sizeof(values[0])
                            ? carry_probe : values[value_index];
                        const uint32_t operand = input & mask;
                        before.data_registers[reg] =
                            (before.data_registers[reg] & ~mask) | operand;
                        before.sr = extend != 0u ? UINT16_C(0x271f)
                                                : UINT16_C(0x2700);
                        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                            owned_cpu_restore_state(cpu, &before));

                        const uint64_t cycles =
                            (width == 4u ? UINT64_C(8) : UINT64_C(6)) +
                            (uint64_t)(2u * count);
                        size_t reads_before = memory.reads;
                        if (count == 1u && reg == 0u && value_index == 0u &&
                            extend == 0u) {
                            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                owned_cpu_test_seed_counters(cpu, 0u, 0u,
                                    0u, 0u, UINT64_MAX - (cycles - 1u)));
                            const owned_cpu_run_result preflight =
                                owned_cpu_run(cpu, cycles);
                            TEST_ASSERT_EQUAL(OWNED_CPU_COUNTER_OVERFLOW,
                                preflight.reason);
                            TEST_ASSERT_EQUAL_UINT64(0u,
                                preflight.elapsed_cycles);
                            TEST_ASSERT_EQUAL_UINT64(0u,
                                preflight.instructions);
                            TEST_ASSERT_EQUAL_UINT(reads_before + 1u,
                                                  memory.reads);
                            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                owned_cpu_test_seed_counters(cpu, 0u, 0u,
                                    0u, 0u, 0u));
                            reads_before = memory.reads;
                        }
                        const owned_cpu_run_result result =
                            owned_cpu_run(cpu, cycles);
                        TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
                        TEST_ASSERT_EQUAL_UINT64(cycles, result.elapsed_cycles);
                        TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
                        TEST_ASSERT_EQUAL_UINT(reads_before + 1u, memory.reads);
                        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                            memory.read_addresses[reads_before]);
                        TEST_ASSERT_EQUAL_UINT(0u, memory.byte_reads);
                        TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);

                        const uint32_t rotated = forms[form_index].left != 0u
                            ? ((operand << count) |
                               (operand >> (bits - count))) & mask
                            : ((operand >> count) |
                               (operand << (bits - count))) & mask;
                        const unsigned carry = forms[form_index].left != 0u
                            ? (unsigned)((operand >> (bits - count)) & 1u)
                            : (unsigned)((operand >> (count - 1u)) & 1u);
                        uint16_t expected_sr = (uint16_t)(before.sr &
                            (uint16_t)~UINT16_C(0x000f));
                        if ((rotated & sign) != 0u)
                            expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0008));
                        if (rotated == 0u)
                            expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0004));
                        if (carry != 0u)
                            expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0001));

                        owned_cpu_observation after;
                        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                          owned_cpu_observe(cpu, &after));
                        for (unsigned other = 0u; other < 8u; ++other) {
                            const uint32_t expected = other == reg
                                ? (before.data_registers[other] & ~mask) | rotated
                                : before.data_registers[other];
                            TEST_ASSERT_EQUAL_HEX32(expected,
                                after.data_registers[other]);
                        }
                        TEST_ASSERT_EQUAL_HEX16(expected_sr, after.sr);
                        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102), after.pc);
                        tearDown();
                    }
                }
            }
        }
    }
}

/* Guest-observed ROL.L #1..8,Dn. MC68000 PRM ROL/ROR pp. 4-161 to 4-162
 * defines rotate-without-extend flags; UM Rev. 9.1 Table 8-7 p. 8-6 gives
 * long register timing 8+2n clocks. */
static void rol_long_immediate_count_rotates_in_8_plus_2n_cycles(void) {
    static const uint32_t operands[] = {
        UINT32_C(0x80000000), UINT32_C(0x40000000), UINT32_C(0x00000001),
        UINT32_C(0x00000000),
    };
    for (unsigned count = 1u; count <= 8u; ++count) {
        const unsigned count_field = count & 7u;
        for (unsigned reg = 0u; reg < 8u; ++reg) {
            for (size_t operand_index = 0u;
                 operand_index < sizeof(operands) / sizeof(operands[0]);
                 ++operand_index) {
                for (unsigned extend = 0u; extend < 2u; ++extend) {
                    setUp();
                    create_cpu();
                    const uint16_t opcode = (uint16_t)(UINT16_C(0xe198) |
                        (uint16_t)(count_field << 9) | (uint16_t)reg);
                    uint8_t program[2];
                    size_t length = 0u;
                    emit_word(program, &length, opcode);
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      reset_with_program(program, length));
                    owned_cpu_state before;
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      owned_cpu_capture_state(cpu, &before));
                    for (unsigned other = 0u; other < 8u; ++other)
                        before.data_registers[other] =
                            UINT32_C(0xa5a50000) | (uint32_t)other;
                    before.data_registers[reg] = operands[operand_index];
                    before.sr = extend != 0u ? UINT16_C(0x271f)
                                             : UINT16_C(0x270f);
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      owned_cpu_restore_state(cpu, &before));

                    const uint64_t cycles = UINT64_C(8) +
                                            (uint64_t)(2u * count);
                    const size_t reads_before = memory.reads;
                    const owned_cpu_run_result result =
                        owned_cpu_run(cpu, cycles);
                    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
                    TEST_ASSERT_EQUAL_UINT64(cycles, result.elapsed_cycles);
                    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
                    TEST_ASSERT_EQUAL_UINT(reads_before + 1u, memory.reads);
                    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                                            memory.read_addresses[reads_before]);
                    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
                    const uint32_t operand = operands[operand_index];
                    const uint32_t rotated = (operand << count) |
                                             (operand >> (32u - count));
                    const unsigned last_out =
                        (unsigned)((operand >> (32u - count)) & UINT32_C(1));
                    uint16_t expected_sr = (uint16_t)(before.sr &
                        (uint16_t)~(UINT16_C(0x0008) | UINT16_C(0x0004) |
                                    UINT16_C(0x0002) | UINT16_C(0x0001)));
                    if ((rotated & UINT32_C(0x80000000)) != 0u)
                        expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0008));
                    if (rotated == 0u)
                        expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0004));
                    if (last_out != 0u)
                        expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0001));
                    owned_cpu_observation after;
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      owned_cpu_observe(cpu, &after));
                    TEST_ASSERT_EQUAL_HEX16(expected_sr, after.sr);
                    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102), after.pc);
                    for (unsigned other = 0u; other < 8u; ++other) {
                        const uint32_t expected_data = other == reg
                            ? rotated : UINT32_C(0xa5a50000) | (uint32_t)other;
                        TEST_ASSERT_EQUAL_HEX32(expected_data,
                                                after.data_registers[other]);
                        TEST_ASSERT_EQUAL_HEX32(before.address_registers[other],
                                                after.address_registers[other]);
                    }
                    tearDown();
                }
            }
        }
    }
}

/* Guest-observed LSL.L immediate-count, register-destination form. The first
 * case is the selected guest's count-5 operation; the matrix covers all counts
 * 1..8, D0..D7, carry outcomes, X replacement, N/Z and the full long result. */
static void lsl_long_immediate_count_shifts_in_8_plus_2n_cycles(void) {
    static const uint32_t operands[] = {
        UINT32_C(0x88000010), UINT32_C(0x80000000), UINT32_C(0x40000001),
        UINT32_C(0x00000001), UINT32_C(0x01234567), UINT32_C(0x00000000),
    };
    const unsigned counts[] = {5u, 1u, 2u, 3u, 4u, 6u, 7u, 8u};
    for (size_t count_index = 0u;
         count_index < sizeof(counts) / sizeof(counts[0]); ++count_index) {
        const unsigned count = counts[count_index];
        for (unsigned register_index = 0u; register_index < 8u;
             ++register_index) {
            const unsigned reg = register_index == 0u
                ? 7u : register_index - 1u;
            for (size_t operand_index = 0u;
                 operand_index < sizeof(operands) / sizeof(operands[0]);
                 ++operand_index) {
                for (unsigned old_extend = 0u; old_extend < 2u; ++old_extend) {
                    setUp();
                    create_cpu();
                    const unsigned count_field = count & 7u;
                    const uint16_t opcode = (uint16_t)(UINT16_C(0xe188) |
                        (uint16_t)(count_field << 9) | (uint16_t)reg);
                    uint8_t program[2];
                    size_t length = 0u;
                    emit_word(program, &length, opcode);
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      reset_with_program(program, length));
                    owned_cpu_state before;
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      owned_cpu_capture_state(cpu, &before));
                    for (unsigned other = 0u; other < 8u; ++other)
                        before.data_registers[other] =
                            UINT32_C(0xa5a50000) | (uint32_t)other;
                    before.data_registers[reg] = operands[operand_index];
                    before.sr = old_extend != 0u ? UINT16_C(0x2710)
                                                 : UINT16_C(0x2700);
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      owned_cpu_restore_state(cpu, &before));

                    const uint64_t cycles = UINT64_C(8) +
                                            (uint64_t)(2u * count);
                    const size_t reads_before = memory.reads;
                    const owned_cpu_run_result result =
                        owned_cpu_run(cpu, cycles);
                    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
                    TEST_ASSERT_EQUAL_UINT64(cycles, result.elapsed_cycles);
                    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
                    TEST_ASSERT_EQUAL_UINT(reads_before + 1u, memory.reads);
                    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                                            memory.read_addresses[reads_before]);
                    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);

                    const uint32_t operand = operands[operand_index];
                    const uint32_t shifted = operand << count;
                    const unsigned last_out =
                        (unsigned)((operand >> (32u - count)) & UINT32_C(1));
                    uint16_t expected_sr = (uint16_t)(before.sr &
                        (uint16_t)~UINT16_C(0x001f));
                    if (last_out != 0u)
                        expected_sr = (uint16_t)(expected_sr |
                            UINT16_C(0x0011));
                    if ((shifted & UINT32_C(0x80000000)) != 0u)
                        expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0008));
                    if (shifted == 0u)
                        expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0004));

                    owned_cpu_observation after;
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      owned_cpu_observe(cpu, &after));
                    TEST_ASSERT_EQUAL_HEX16(expected_sr, after.sr);
                    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102), after.pc);
                    for (unsigned other = 0u; other < 8u; ++other) {
                        const uint32_t expected_data = other == reg
                            ? shifted : UINT32_C(0xa5a50000) | (uint32_t)other;
                        TEST_ASSERT_EQUAL_HEX32(expected_data,
                                                after.data_registers[other]);
                        TEST_ASSERT_EQUAL_HEX32(before.address_registers[other],
                                                after.address_registers[other]);
                    }
                    tearDown();
                }
            }
        }
    }
}

static void or_byte_odd_address_indirect_source_does_not_take_vector_three(void) {
    const uint8_t program[] = {UINT8_C(0x80), UINT8_C(0x10)}; /* OR.B (A0),D0 */
    create_cpu();
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    memory.rom[UINT32_C(0x181)] = UINT8_C(0x80);

    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.address_registers[0] = UINT32_C(0x181);
    state.data_registers[0] = UINT32_C(0x12340040);
    state.sr = UINT16_C(0x271f);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));

    const size_t byte_reads_before = memory.byte_reads;
    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(8));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(8u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
    TEST_ASSERT_EQUAL_UINT(byte_reads_before + 1u, memory.byte_reads);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x181),
                            memory.byte_read_addresses[byte_reads_before]);
    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);

    owned_cpu_observation observation;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x123400c0), observation.data_registers[0]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x181), observation.address_registers[0]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2718), observation.sr);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102), observation.pc);
    TEST_ASSERT_EQUAL_UINT8(0u, observation.last_exception_vector);
}

