static void divu_word_all_readable_ea_sources_resolve_before_destination_write(void) {
    static const struct {
        uint16_t ea;
        uint16_t extension[2];
        size_t extension_words;
        uint64_t ea_cycles;
        uint32_t address_register_zero;
        uint32_t expected_address_register_zero;
        uint32_t operand_address;
        unsigned immediate;
        const char *name;
    } cases[] = {
        {UINT16_C(0x0010), {0u, 0u}, 0u, 4u, 0x180u, 0x180u, 0x180u, 0u,
         "(An)"},
        {UINT16_C(0x0018), {0u, 0u}, 0u, 4u, 0x180u, 0x182u, 0x180u, 0u,
         "(An)+"},
        {UINT16_C(0x0020), {0u, 0u}, 0u, 6u, 0x182u, 0x180u, 0x180u, 0u,
         "-(An)"},
        {UINT16_C(0x0028), {0x0010u, 0u}, 1u, 8u, 0x170u, 0x170u, 0x180u, 0u,
         "d16(An)"},
        {UINT16_C(0x0030), {0x9010u, 0u}, 1u, 10u, 0x170u, 0x170u, 0x180u, 0u,
         "d8(An,A1.w)"},
        {UINT16_C(0x0038), {0x0180u, 0u}, 1u, 8u, 0u, 0u, 0x180u, 0u,
         "absolute short"},
        {UINT16_C(0x0039), {0x0000u, 0x0180u}, 2u, 12u, 0u, 0u, 0x180u, 0u,
         "absolute long"},
        {UINT16_C(0x003a), {0x007eu, 0u}, 1u, 8u, 0u, 0u, 0x180u, 0u,
         "d16(PC)"},
        {UINT16_C(0x003b), {0x907eu, 0u}, 1u, 10u, 0u, 0u, 0x180u, 0u,
         "d8(PC,A1.w)"},
        {UINT16_C(0x003c), {0x0101u, 0u}, 1u, 4u, 0u, 0u, 0u, 1u,
         "#<data>"},
    };

    for (size_t form = 0u; form < sizeof(cases) / sizeof(cases[0]); ++form) {
        for (unsigned destination = 0u; destination < 8u; ++destination) {
            setUp();
            create_cpu();
            uint8_t program[6];
            size_t length = 0u;
            emit_word(program, &length,
                      divu_word_ea_opcode(destination, cases[form].ea));
            for (size_t word = 0u; word < cases[form].extension_words; ++word)
                emit_word(program, &length, cases[form].extension[word]);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              reset_with_program(program, length));

            owned_cpu_state before;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_capture_state(cpu, &before));
            before.data_registers[destination] = UINT32_C(0x00010000);
            before.address_registers[0] =
                cases[form].address_register_zero;
            before.address_registers[1] = 0u;
            before.sr = (destination & 1u) != 0u
                ? UINT16_C(0x271f) : UINT16_C(0x2700);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_restore_state(cpu, &before));
            if (cases[form].immediate == 0u) {
                memory.rom[cases[form].operand_address] = 0x01u;
                memory.rom[cases[form].operand_address + 1u] = 0x01u;
            }

            const uint64_t expected_cycles = UINT64_C(122) +
                                              cases[form].ea_cycles;
            const size_t reads_before = memory.reads;
            const owned_cpu_run_result result =
                owned_cpu_run(cpu, expected_cycles);
            TEST_ASSERT_EQUAL_MESSAGE(OWNED_CPU_BUDGET, result.reason,
                                      cases[form].name);
            TEST_ASSERT_EQUAL_UINT64(expected_cycles, result.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
            TEST_ASSERT_EQUAL_UINT(
                reads_before + 1u + cases[form].extension_words +
                    (cases[form].immediate == 0u ? 1u : 0u),
                memory.reads);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0100),
                                    memory.read_addresses[reads_before]);
            for (size_t word = 0u; word < cases[form].extension_words; ++word)
                TEST_ASSERT_EQUAL_HEX32(
                    UINT32_C(0x0102) + (uint32_t)word * UINT32_C(2),
                    memory.read_addresses[reads_before + 1u + word]);
            if (cases[form].immediate == 0u)
                TEST_ASSERT_EQUAL_HEX32(
                    cases[form].operand_address,
                    memory.read_addresses[reads_before + 1u +
                                          cases[form].extension_words]);

            owned_cpu_observation after;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_observe(cpu, &after));
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x000100ff),
                                    after.data_registers[destination]);
            TEST_ASSERT_EQUAL_HEX32(
                cases[form].expected_address_register_zero,
                after.address_registers[0]);
            TEST_ASSERT_EQUAL_HEX32(0u, after.address_registers[1]);
            TEST_ASSERT_EQUAL_HEX16(
                (uint16_t)(before.sr & (uint16_t)~UINT16_C(0x000f)),
                after.sr);
            TEST_ASSERT_EQUAL_HEX32(
                UINT32_C(0x0100) + (uint32_t)length, after.pc);
            tearDown();
        }
    }
}

