static void divu_word_auto_update_odd_source_updates_before_vector_three(void) {
    static const struct {
        uint16_t opcode;
        unsigned base_register;
        uint32_t initial_base;
        uint32_t expected_base;
        const char *name;
    } cases[] = {
        {UINT16_C(0x80d9), 1u, UINT32_C(0x181), UINT32_C(0x183), "(A1)+"},
        {UINT16_C(0x80e0), 0u, UINT32_C(0x183), UINT32_C(0x181), "-(A0)"},
    };
    for (size_t index = 0u; index < sizeof(cases) / sizeof(cases[0]); ++index) {
        setUp();
        create_cpu();
        set_vector(UINT32_C(3) * UINT32_C(4), UINT32_C(0x0180));
        uint8_t program[2];
        size_t length = 0u;
        emit_word(program, &length, cases[index].opcode);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          reset_with_program(program, length));
        owned_cpu_state before;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          owned_cpu_capture_state(cpu, &before));
        before.address_registers[cases[index].base_register] =
            cases[index].initial_base;
        before.address_registers[7] = UINT32_C(0x01c0);
        before.ssp = UINT32_C(0x01c0);
        before.usp = UINT32_C(0x01e0);
        before.data_registers[0] = UINT32_C(0x00010000);
        before.sr = UINT16_C(0x271f);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          owned_cpu_restore_state(cpu, &before));
        const size_t reads_before = memory.reads;

        const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(50));
        TEST_ASSERT_EQUAL_MESSAGE(OWNED_CPU_BUDGET, result.reason,
                                  cases[index].name);
        TEST_ASSERT_EQUAL_UINT64(50u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64_MESSAGE(0u, result.instructions,
                                         cases[index].name);
        for (size_t read = reads_before; read < memory.reads; ++read)
            TEST_ASSERT_NOT_EQUAL(UINT32_C(0x181),
                                  memory.read_addresses[read]);
        owned_cpu_observation after;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          owned_cpu_observe(cpu, &after));
        TEST_ASSERT_EQUAL_UINT8(3u, after.last_exception_vector);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0180), after.pc);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0100), after.previous_pc);
        TEST_ASSERT_EQUAL_HEX32(cases[index].expected_base,
                                after.address_registers[cases[index].base_register]);
        tearDown();
    }
}

static void divu_word_update_source_fault_and_counter_boundaries_are_ordered(void) {
    const uint8_t counter_program[] = {UINT8_C(0x80), UINT8_C(0xd8)};
    static const struct {
        uint16_t opcode;
        uint32_t initial_base;
    } fault_cases[] = {
        {UINT16_C(0x80d8), UINT32_C(0x180)}, /* (A0)+ */
        {UINT16_C(0x80e0), UINT32_C(0x182)}, /* -(A0) */
    };
    for (size_t index = 0u;
         index < sizeof(fault_cases) / sizeof(fault_cases[0]); ++index) {
        setUp();
        create_cpu();
        uint8_t fault_program[2];
        size_t fault_length = 0u;
        emit_word(fault_program, &fault_length, fault_cases[index].opcode);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          reset_with_program(fault_program, fault_length));
        owned_cpu_state before;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          owned_cpu_capture_state(cpu, &before));
        before.address_registers[0] = fault_cases[index].initial_base;
        before.data_registers[0] = UINT32_C(0x00010000);
        before.sr = UINT16_C(0x271f);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          owned_cpu_restore_state(cpu, &before));
        const size_t fault_reads_before = memory.reads;
        memory.fail_read_on = fault_reads_before + 2u;
        const owned_cpu_run_result failed_read =
            owned_cpu_run(cpu, UINT64_C(200));
        TEST_ASSERT_EQUAL(OWNED_CPU_HOST_FAULT, failed_read.reason);
        TEST_ASSERT_EQUAL_UINT(fault_reads_before + 2u, memory.reads);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0100), failed_read.fault_pc);
        TEST_ASSERT_EQUAL_HEX16(fault_cases[index].opcode,
                                failed_read.instruction_register);
        owned_cpu_state faulted;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          owned_cpu_test_capture_faulted_state(cpu, &faulted));
        TEST_ASSERT_EQUAL_HEX32(before.address_registers[0],
                                faulted.address_registers[0]);
        TEST_ASSERT_EQUAL_HEX32(before.data_registers[0],
                                faulted.data_registers[0]);
        TEST_ASSERT_EQUAL_HEX16(before.sr, faulted.sr);
        tearDown();
    }

    setUp();
    create_cpu();
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      reset_with_program(counter_program,
                                         sizeof(counter_program)));
    owned_cpu_state counter_before;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_capture_state(cpu, &counter_before));
    counter_before.address_registers[0] = UINT32_C(0x180);
    counter_before.data_registers[0] = UINT32_C(0x00010000);
    counter_before.sr = UINT16_C(0x270f);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_restore_state(cpu, &counter_before));
    memory.rom[UINT32_C(0x180)] = 0x01u;
    memory.rom[UINT32_C(0x181)] = 0x01u;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_test_seed_counters(
        cpu, 0u, 0u, 0u, 0u, UINT64_MAX - UINT64_C(125)));
    const size_t overflow_reads_before = memory.reads;
    const owned_cpu_run_result overflow =
        owned_cpu_run(cpu, UINT64_C(126));
    TEST_ASSERT_EQUAL(OWNED_CPU_COUNTER_OVERFLOW, overflow.reason);
    TEST_ASSERT_EQUAL_UINT64(0u, overflow.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(0u, overflow.instructions);
    TEST_ASSERT_EQUAL_UINT(overflow_reads_before + 2u, memory.reads);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x180),
                            memory.read_addresses[overflow_reads_before + 1u]);
    owned_cpu_observation after_overflow;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_observe(cpu, &after_overflow));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0100), after_overflow.pc);
    TEST_ASSERT_EQUAL_HEX32(counter_before.address_registers[0],
                            after_overflow.address_registers[0]);
    TEST_ASSERT_EQUAL_HEX32(counter_before.data_registers[0],
                            after_overflow.data_registers[0]);
    TEST_ASSERT_EQUAL_HEX16(counter_before.sr, after_overflow.sr);
    tearDown();
}

static void divu_word_register_and_immediate_counter_preflight_follow_source_fetch(void) {
    static const struct {
        uint16_t opcode;
        uint16_t extension;
        size_t extension_words;
        uint64_t cycles;
        const char *name;
    } cases[] = {
        {UINT16_C(0x82c0), 0u, 0u, 122u, "register source"},
        {UINT16_C(0x82fc), UINT16_C(0x0101), 1u, 126u, "immediate source"},
    };
    for (size_t index = 0u; index < sizeof(cases) / sizeof(cases[0]); ++index) {
        setUp();
        create_cpu();
        uint8_t program[4];
        size_t length = 0u;
        emit_word(program, &length, cases[index].opcode);
        if (cases[index].extension_words != 0u)
            emit_word(program, &length, cases[index].extension);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          reset_with_program(program, length));
        owned_cpu_state before;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          owned_cpu_capture_state(cpu, &before));
        before.data_registers[0] = cases[index].extension_words == 0u
            ? UINT32_C(0x0101) : UINT32_C(0xdeadbeef);
        before.data_registers[1] = UINT32_C(0x00010000);
        before.sr = UINT16_C(0x271f);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          owned_cpu_restore_state(cpu, &before));
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_test_seed_counters(
            cpu, 0u, 0u, 0u, 0u, UINT64_MAX - (cases[index].cycles - 1u)));
        const size_t reads_before = memory.reads;

        const owned_cpu_run_result result =
            owned_cpu_run(cpu, cases[index].cycles);
        TEST_ASSERT_EQUAL_MESSAGE(OWNED_CPU_COUNTER_OVERFLOW, result.reason,
                                  cases[index].name);
        TEST_ASSERT_EQUAL_UINT64(0u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(0u, result.instructions);
        TEST_ASSERT_EQUAL_UINT(reads_before + 1u + cases[index].extension_words,
                               memory.reads);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0100),
                                memory.read_addresses[reads_before]);
        if (cases[index].extension_words != 0u)
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0102),
                                    memory.read_addresses[reads_before + 1u]);
        owned_cpu_observation after;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          owned_cpu_observe(cpu, &after));
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0100), after.pc);
        TEST_ASSERT_EQUAL_HEX32(before.data_registers[0],
                                after.data_registers[0]);
        TEST_ASSERT_EQUAL_HEX32(before.data_registers[1],
                                after.data_registers[1]);
        TEST_ASSERT_EQUAL_HEX16(before.sr, after.sr);
        tearDown();
    }
}

static void divu_word_a7_postincrement_synchronizes_only_the_active_stack_bank(void) {
    static const struct {
        uint16_t sr;
        uint32_t ssp;
        uint32_t usp;
    } cases[] = {
        {UINT16_C(0x271f), UINT32_C(0x180), UINT32_C(0x1e0)},
        {UINT16_C(0x001f), UINT32_C(0x1c0), UINT32_C(0x180)},
    };
    const uint8_t program[] = {UINT8_C(0x80), UINT8_C(0xdf)};
    for (size_t index = 0u; index < sizeof(cases) / sizeof(cases[0]); ++index) {
        setUp();
        create_cpu();
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          reset_with_program(program, sizeof(program)));
        memory.rom[UINT32_C(0x180)] = 0x01u;
        memory.rom[UINT32_C(0x181)] = 0x01u;
        owned_cpu_state before;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          owned_cpu_capture_state(cpu, &before));
        before.sr = cases[index].sr;
        before.ssp = cases[index].ssp;
        before.usp = cases[index].usp;
        before.address_registers[7] =
            (cases[index].sr & UINT16_C(0x2000)) != 0u
                ? cases[index].ssp : cases[index].usp;
        before.data_registers[0] = UINT32_C(0x00010000);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          owned_cpu_restore_state(cpu, &before));

        const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(126));
        TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
        TEST_ASSERT_EQUAL_UINT64(126u, result.elapsed_cycles);
        owned_cpu_observation after;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          owned_cpu_observe(cpu, &after));
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x182),
                                after.address_registers[7]);
        if ((cases[index].sr & UINT16_C(0x2000)) != 0u) {
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x182), after.ssp);
            TEST_ASSERT_EQUAL_HEX32(cases[index].usp, after.usp);
        } else {
            TEST_ASSERT_EQUAL_HEX32(cases[index].ssp, after.ssp);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x182), after.usp);
        }
        tearDown();
    }
}

