    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0102), memory.read_addresses[reads_before + 1u]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0180), memory.read_addresses[reads_before + 2u]);
