/* LEA (xxx).W,An (guest demanded, plan 05-22 rerun 18). Semantics: M68000
 * Family Programmer's Reference Manual LEA, p. 4-110 (effective address to An,
 * all 32 bits, condition codes unaffected); the absolute short address is the
 * sign-extended extension word (PRM section 2, absolute short addressing).
 * Timing: MC68000 User's Manual Rev. 9.1 Table 8-10 (printed p. 8-8), LEA
 * (xxx).W is 8(2/0). Bus-tally reconciliation: the no-prefetch core reads the
 * opcode word and the extension word (2 reads, 0 writes, 0 byte reads), equal
 * to Section 8 with no refill read. */
static void lea_absolute_short_address_to_register_uses_8_cycles(void) {
    static const struct {
        uint16_t opcode;
        uint16_t address_word;
        unsigned destination;
        uint32_t expected;
    } cases[] = {
        {0x41f8u, 0x0124u, 0u, UINT32_C(0x00000124)},
        {0x41f8u, 0xfffeu, 0u, UINT32_C(0xfffffffe)},
        {0x47f8u, 0x7fffu, 3u, UINT32_C(0x00007fff)},
        {0x4ff8u, 0x8000u, 7u, UINT32_C(0xffff8000)},
    };
    static const uint16_t sr_values[] = {UINT16_C(0x2700), UINT16_C(0x271f)};
    for (size_t index = 0u; index < sizeof(cases) / sizeof(cases[0]); ++index) {
        for (size_t flags = 0u; flags < 2u; ++flags) {
            setUp();
            create_cpu();
            uint8_t program[4];
            size_t length = 0u;
            emit_word(program, &length, cases[index].opcode);
            emit_word(program, &length, cases[index].address_word);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, length));
            owned_cpu_state state;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
            state.sr = sr_values[flags];
            state.address_registers[0] = UINT32_C(0xdeadbeef);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
            const size_t reads_before = memory.reads;
            owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(8));
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
            TEST_ASSERT_EQUAL_UINT64(8u, result.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
            TEST_ASSERT_EQUAL_UINT(2u, (unsigned)(memory.reads - reads_before));
            TEST_ASSERT_EQUAL_UINT(0u, (unsigned)memory.write_attempts);
            TEST_ASSERT_EQUAL_UINT(0u, (unsigned)memory.byte_reads);
            owned_cpu_state after;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &after));
            TEST_ASSERT_EQUAL_HEX32(cases[index].expected,
                                    after.address_registers[cases[index].destination]);
            TEST_ASSERT_EQUAL_HEX16(sr_values[flags], after.sr);
            if (cases[index].destination == 7u) {
                TEST_ASSERT_EQUAL_HEX32(cases[index].expected, after.ssp);
                TEST_ASSERT_EQUAL_HEX32(UINT32_C(0xdeadbeef), after.address_registers[0]);
            } else if (cases[index].destination != 0u) {
                TEST_ASSERT_EQUAL_HEX32(UINT32_C(0xdeadbeef), after.address_registers[0]);
            }
            owned_cpu_observation observation;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x104), observation.pc);
            tearDown();
        }
    }
}

/* LEA (d8,An,Xn),An (guest demanded, plan 05-27 rerun 37). M68000 Family
 * Programmer's Reference Manual LEA, p. 4-110: the effective address is
 * loaded into all 32 bits of An and condition codes are unaffected. PRM
 * §2.2.7, printed p. 2-9, defines the single extension word, sign-extended
 * 8-bit displacement and sign-extended index. User's Manual Rev. 9.1 Table
 * 8-10, printed p. 8-8: LEA (d8,An,Xn) is 12(2/0). The no-prefetch core reads
 * the opcode and extension words (2 reads, 0 writes); it never reads the
 * effective address. Only the brief MC68000 extension is admitted. */
static void lea_address_register_indexed_to_register_uses_12_cycles(void) {
    static const struct {
        uint16_t opcode;
        uint16_t extension;
        uint32_t base;
        uint32_t expected;
        unsigned destination;
    } cases[] = {
        {0x41f0u, 0x20fdu, UINT32_C(0x00001000), UINT32_C(0x00000ffb), 0u},
        {0x43f0u, 0xc805u, UINT32_C(0xfffffff0), UINT32_C(0x7ffffff9), 1u},
        {0x4ff0u, 0x10ffu, UINT32_C(0x00002000), UINT32_C(0x00001ffe), 7u},
    };
    static const uint16_t sr_values[] = {UINT16_C(0x271f), UINT16_C(0x2700)};
    for (size_t index = 0u; index < sizeof(cases) / sizeof(cases[0]); ++index) {
        for (size_t flags = 0u; flags < sizeof(sr_values) / sizeof(sr_values[0]);
             ++flags) {
            setUp();
            create_cpu();
            uint8_t program[4];
            size_t length = 0u;
            emit_word(program, &length, cases[index].opcode);
            emit_word(program, &length, cases[index].extension);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, length));
            owned_cpu_state state;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
            state.sr = sr_values[flags];
            state.address_registers[0] = cases[index].base;
            state.address_registers[4] = UINT32_C(0x80000004);
            state.address_registers[7] = UINT32_C(0x00002400);
            state.ssp = UINT32_C(0x00002400);
            state.data_registers[1] = UINT32_C(0x1234ffff);
            state.data_registers[2] = UINT32_C(0xabcdfffe);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
            const size_t reads_before = memory.reads;
            owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(12));
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
            TEST_ASSERT_EQUAL_UINT64(12u, result.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
            TEST_ASSERT_EQUAL_UINT(2u, (unsigned)(memory.reads - reads_before));
            TEST_ASSERT_EQUAL_UINT(0u, (unsigned)memory.write_attempts);
            TEST_ASSERT_EQUAL_UINT(0u, (unsigned)memory.byte_reads);
            owned_cpu_state after;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &after));
            TEST_ASSERT_EQUAL_HEX32(cases[index].expected,
                                    after.address_registers[cases[index].destination]);
            TEST_ASSERT_EQUAL_HEX16(sr_values[flags], after.sr);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x80000004), after.address_registers[4]);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x1234ffff), after.data_registers[1]);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0xabcdfffe), after.data_registers[2]);
            if (cases[index].destination == 7u) {
                TEST_ASSERT_EQUAL_HEX32(cases[index].expected, after.ssp);
            } else {
                TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x00002400), after.ssp);
            }
            owned_cpu_observation observation;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x104), observation.pc);
            tearDown();
        }
    }
}

/* A full-format extension is not this core's brief MC68000 indexed form. */
static void lea_address_register_indexed_full_extension_stays_unsupported(void) {
    create_cpu();
    const uint8_t program[] = {0x41u, 0xf0u, 0x01u, 0x04u};
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    owned_cpu_state before;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(20));
    TEST_ASSERT_EQUAL(OWNED_CPU_UNSUPPORTED_OPCODE, result.reason);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x41f0), result.instruction_register);
    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
    owned_cpu_state after;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &after));
    TEST_ASSERT_EQUAL_HEX32(before.pc, after.pc);
    TEST_ASSERT_EQUAL_HEX16(before.sr, after.sr);
    for (unsigned reg = 0u; reg < 8u; ++reg) {
        TEST_ASSERT_EQUAL_HEX32(before.address_registers[reg],
                                after.address_registers[reg]);
        TEST_ASSERT_EQUAL_HEX32(before.data_registers[reg],
                                after.data_registers[reg]);
    }
    tearDown();
}

/* ADD.B (An)+,Dn (guest demanded, plan 05-22 rerun 19). Semantics: M68000
 * Family Programmer's Reference Manual ADD, pp. 4-3 to 4-5 (the source byte
 * read at (An) is added to the low byte of Dn, Dn[31:8] preserved; An
 * advances by 1, or by 2 for A7 to keep the stack word aligned, PRM section
 * 2.2.4 p. 2-6; X and C are the carry, N and Z from the byte, V on signed
 * overflow). Timing: MC68000 User's Manual Rev. 9.1 Table 8-4 (printed p.
 * 8-4) ADD byte <ea>,Dn 4(1/0)+ plus Table 8-1 (printed p. 8-2) (An)+ byte
 * 4(1/0) = 8(2/0). Bus-tally reconciliation: one opcode word read and one
 * byte read at the source address (2 reads, 0 writes), equal to Section 8. */
static void add_byte_postincrement_to_data_register_adds_in_8_cycles(void) {
    static const struct {
        uint8_t program[2];
        unsigned source;
        uint32_t pointer;
        uint8_t operand;
        unsigned destination;
        uint32_t before;
        uint16_t sr_before;
        uint32_t after;
        uint16_t sr_after;
        uint32_t pointer_after;
    } cases[] = {
        {{0xd0, 0x18}, 0u, UINT32_C(0x1e0), 0x7fu, 0u, UINT32_C(0x1234ab01), UINT16_C(0x2700),
         UINT32_C(0x1234ab80), UINT16_C(0x270a), UINT32_C(0x1e1)},
        {{0xd4, 0x19}, 1u, UINT32_C(0x1e1), 0xffu, 2u, UINT32_C(0xdead0001), UINT16_C(0x2700),
         UINT32_C(0xdead0000), UINT16_C(0x2715), UINT32_C(0x1e2)},
        {{0xd6, 0x1f}, 7u, UINT32_C(0x1e0), 0x10u, 3u, UINT32_C(0x00000010), UINT16_C(0x271f),
         UINT32_C(0x00000020), UINT16_C(0x2700), UINT32_C(0x1e2)},
    };
    for (size_t index = 0u; index < sizeof(cases) / sizeof(cases[0]); ++index) {
        memset(&memory, 0, sizeof(memory));
        create_cpu();
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(cases[index].program, 2u));
        memory.rom[cases[index].pointer] = cases[index].operand;
        owned_cpu_state state;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
        state.address_registers[cases[index].source] = cases[index].pointer;
        if (cases[index].source == 7u) state.ssp = cases[index].pointer;
        state.data_registers[cases[index].destination] = cases[index].before;
        state.sr = cases[index].sr_before;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
        const size_t reads_before = memory.reads;
        owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(8));
        TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
        TEST_ASSERT_EQUAL_UINT64(8u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
        TEST_ASSERT_EQUAL_UINT(1u, memory.reads - reads_before);
        TEST_ASSERT_EQUAL_UINT(1u, memory.byte_reads);
        TEST_ASSERT_EQUAL_HEX32(cases[index].pointer, memory.byte_read_addresses[0]);
        TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
        owned_cpu_observation observation;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
        TEST_ASSERT_EQUAL_HEX32(cases[index].after,
                                observation.data_registers[cases[index].destination]);
        TEST_ASSERT_EQUAL_HEX16(cases[index].sr_after, observation.sr);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102), observation.pc);
        TEST_ASSERT_EQUAL_HEX32(cases[index].pointer_after,
                                observation.address_registers[cases[index].source]);
        owned_cpu_destroy(cpu);
        cpu = NULL;
    }
}

/* Address-register and PC-relative sources remain outside the shared ADD
 * memory-source slice. ADDA's address-register-direct source form is tested
 * separately because it uses the address arithmetic instruction family. */
static void add_memory_source_unimplemented_boundaries_stay_unsupported(void) {
    static const struct {
        uint8_t program[2];
        const char *name;
    } neighbors[] = {
        {{0xd0, 0x08}, "ADD.B A0,D0"},
        {{0xd0, 0x3a}, "ADD.B (PC),D0"},
        {{0xd0, 0x3c}, "ADD.B #imm,D0"},
    };
    for (size_t index = 0u; index < sizeof(neighbors) / sizeof(neighbors[0]); ++index) {
        memset(&memory, 0, sizeof(memory));
        create_cpu();
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(neighbors[index].program, 2u));
        owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(32));
        TEST_ASSERT_EQUAL_MESSAGE(OWNED_CPU_UNSUPPORTED_OPCODE, result.reason,
                                  neighbors[index].name);
        TEST_ASSERT_EQUAL_UINT(0u, memory.byte_reads);
        TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
        owned_cpu_destroy(cpu);
        cpu = NULL;
    }
}

/* Guest-observed ADD.B Dn,(d8,An,Xn). PRM §4 ADD, pp. 4-3 to 4-5, defines
 * byte addition and X/C/N/Z/V flags. MC68000 UM Rev. 9.1 Table 8-4 p. 8-4
 * gives ADD.B Dn to memory 8(1/1)+; Table 8-1 p. 8-2 adds 10(2/0) for a
 * brief indexed byte EA, totaling 18(3/1). Odd byte addresses are valid. */
static void add_byte_data_register_to_indexed_memory_covers_all_registers_and_index_forms(void) {
    static const uint8_t sources[8] = {
        UINT8_C(0x00), UINT8_C(0x01), UINT8_C(0x7f), UINT8_C(0x80),
        UINT8_C(0xff), UINT8_C(0xfe), UINT8_C(0x55), UINT8_C(0xaa)};
    static const uint8_t destinations[8] = {
        UINT8_C(0x00), UINT8_C(0x01), UINT8_C(0x7f), UINT8_C(0x80),
        UINT8_C(0xff), UINT8_C(0xfe), UINT8_C(0x55), UINT8_C(0xaa)};
    static const uint32_t index_values[8] = {
        UINT32_C(0x00000000), UINT32_C(0x0000007f), UINT32_C(0x00000080),
        UINT32_C(0x0000ffff), UINT32_C(0x00010001), UINT32_C(0x80000000),
        UINT32_C(0xffff0001), UINT32_C(0x1234ff81)};
    static const int8_t displacements[4] = {-128, -1, 0, 127};
    size_t case_index = 0u;
    for (unsigned source_register = 0u; source_register < 8u;
         ++source_register) {
        for (unsigned base_register = 0u; base_register < 8u;
             ++base_register) {
            for (unsigned index_register = 0u; index_register < 8u;
                 ++index_register) {
                for (unsigned index_is_address = 0u; index_is_address < 2u;
                     ++index_is_address) {
                    if (index_is_address != 0u &&
                        index_register == base_register)
                        continue;
                    for (unsigned index_is_long = 0u; index_is_long < 2u;
                         ++index_is_long) {
                        setUp();
                        create_cpu();
                        const int8_t displacement =
                            displacements[case_index % 4u];
                        const uint8_t encoded_index = (uint8_t)displacement;
                        const uint16_t extension = (uint16_t)(
                            (index_is_address != 0u ? UINT16_C(0x8000) : 0u) |
                            (uint16_t)(index_register << 12) |
                            (index_is_long != 0u ? UINT16_C(0x0800) : 0u) |
                            encoded_index);
                        uint8_t program[4];
                        size_t length = 0u;
                        emit_word(program, &length, (uint16_t)(
                            UINT16_C(0xd130) |
                            (uint16_t)(source_register << 9) |
                            base_register));
                        emit_word(program, &length, extension);
                        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                          reset_with_program(program, length));

                        owned_cpu_state before;
                        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                          owned_cpu_capture_state(cpu,
                                                                  &before));
                        for (unsigned reg = 0u; reg < 8u; ++reg) {
                            before.data_registers[reg] =
                                UINT32_C(0xa5c30000) | reg;
                            before.address_registers[reg] =
                                UINT32_C(0x0300) + (uint32_t)reg *
                                                       UINT32_C(0x20);
                        }
                        if (index_is_address != 0u)
                            before.address_registers[index_register] =
                                index_values[index_register];
                        else
                            before.data_registers[index_register] =
                                index_values[index_register];
                        before.data_registers[source_register] =
                            UINT32_C(0xface0000) | sources[source_register];
                        const uint32_t index_full = index_is_address != 0u
                            ? before.address_registers[index_register]
                            : before.data_registers[index_register];
                        const uint32_t index_value = index_is_long != 0u
                            ? index_full
                            : expected_sign_extend_word(
                                  (uint16_t)index_full);
                        const uint32_t target = case_index == 0u
                            ? UINT32_C(0x0181)
                            : UINT32_C(0x0180) +
                                  (uint32_t)(case_index % 127u);
                        before.address_registers[base_register] = target -
                            (uint32_t)(int32_t)displacement - index_value;
                        before.ssp = before.address_registers[7];
                        const uint16_t initial_flags = (uint16_t)(
                            UINT16_C(0x2700) | (uint16_t)(case_index & 0x1fu));
                        before.sr = initial_flags;
                        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                          owned_cpu_restore_state(cpu,
                                                                  &before));

                        const uint8_t destination =
                            destinations[case_index % 8u];
                        memory.rom[target] = destination;
                        if (target > 0u)
                            memory.rom[target - 1u] = UINT8_C(0x5a);
                        memory.rom[target + 1u] = UINT8_C(0xa5);
                        const uint8_t source = sources[source_register];
                        const uint16_t full_result =
                            (uint16_t)destination + (uint16_t)source;
                        const uint8_t result = (uint8_t)full_result;
                        uint16_t expected_sr =
                            (uint16_t)(initial_flags & UINT16_C(0xffe0));
                        if (result == 0u)
                            expected_sr = (uint16_t)(expected_sr |
                                                     UINT16_C(0x0004));
                        if ((result & UINT8_C(0x80)) != 0u)
                            expected_sr = (uint16_t)(expected_sr |
                                                     UINT16_C(0x0008));
                        if (((uint8_t)~(destination ^ source) &
                             (destination ^ result) & UINT8_C(0x80)) != 0u)
                            expected_sr = (uint16_t)(expected_sr |
                                                     UINT16_C(0x0002));
                        if (full_result > UINT8_MAX)
                            expected_sr = (uint16_t)(expected_sr |
                                                     UINT16_C(0x0011));

                        const size_t reads_before = memory.reads;
                        const size_t byte_reads_before = memory.byte_reads;
                        const owned_cpu_run_result run =
                            owned_cpu_run(cpu, UINT64_C(18));
                        TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, run.reason);
                        TEST_ASSERT_EQUAL_UINT64(18u, run.elapsed_cycles);
                        TEST_ASSERT_EQUAL_UINT64(1u, run.instructions);
                        TEST_ASSERT_EQUAL_UINT(reads_before + 2u,
                                               memory.reads);
                        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                            memory.read_addresses[reads_before]);
                        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102),
                            memory.read_addresses[reads_before + 1u]);
                        TEST_ASSERT_EQUAL_UINT(byte_reads_before + 1u,
                                               memory.byte_reads);
                        TEST_ASSERT_EQUAL_HEX32(target,
                            memory.byte_read_addresses[byte_reads_before]);
                        TEST_ASSERT_EQUAL_UINT(1u, memory.write_attempts);
                        TEST_ASSERT_EQUAL_UINT(1u, memory.successful_writes);
                        TEST_ASSERT_EQUAL_HEX32(target,
                                                memory.byte_write_addresses[0]);
                        TEST_ASSERT_EQUAL_HEX8(result,
                                               memory.byte_write_values[0]);
                        TEST_ASSERT_EQUAL_HEX8(result, memory.rom[target]);
                        TEST_ASSERT_EQUAL_HEX8(UINT8_C(0xa5),
                                               memory.rom[target + 1u]);
                        if (target > 0u)
                            TEST_ASSERT_EQUAL_HEX8(UINT8_C(0x5a),
                                                   memory.rom[target - 1u]);

                        owned_cpu_observation after;
                        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                          owned_cpu_observe(cpu, &after));
                        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x104), after.pc);
                        TEST_ASSERT_EQUAL_HEX16(expected_sr, after.sr);
                        for (unsigned reg = 0u; reg < 8u; ++reg) {
                            TEST_ASSERT_EQUAL_HEX32(
                                before.data_registers[reg],
                                after.data_registers[reg]);
                            TEST_ASSERT_EQUAL_HEX32(
                                before.address_registers[reg],
                                after.address_registers[reg]);
                        }
                        TEST_ASSERT_EQUAL_HEX32(before.ssp, after.ssp);
                        tearDown();
                        ++case_index;
                    }
                }
            }
        }
    }
}

static void add_byte_data_register_to_indexed_memory_rejects_full_extension(void) {
    setUp();
    create_cpu();
    const uint8_t program[] = {0xd3u, 0x36u, 0x01u, 0x00u};
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      reset_with_program(program, sizeof(program)));
    owned_cpu_state before;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_capture_state(cpu, &before));
    before.address_registers[6] = UINT32_C(0x0180);
    before.sr = UINT16_C(0x271f);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_restore_state(cpu, &before));
    const size_t reads_before = memory.reads;
    const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(18));
    TEST_ASSERT_EQUAL(OWNED_CPU_UNSUPPORTED_OPCODE, result.reason);
    TEST_ASSERT_EQUAL_UINT64(0u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(0u, result.instructions);
    TEST_ASSERT_EQUAL_UINT(reads_before + 2u, memory.reads);
    TEST_ASSERT_EQUAL_UINT(0u, memory.byte_reads);
    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
    owned_cpu_observation after;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_observe(cpu, &after));
    TEST_ASSERT_EQUAL_HEX32(before.pc, after.pc);
    TEST_ASSERT_EQUAL_HEX16(before.sr, after.sr);
    for (unsigned reg = 0u; reg < 8u; ++reg) {
        TEST_ASSERT_EQUAL_HEX32(before.data_registers[reg],
                                after.data_registers[reg]);
        TEST_ASSERT_EQUAL_HEX32(before.address_registers[reg],
                                after.address_registers[reg]);
    }
    tearDown();
}

static void add_byte_data_register_to_indexed_memory_neighbors_stay_unsupported(void) {
    static const uint8_t neighbors[][2] = {
        {0xd1u, 0x08u}, /* ADD.B D0,A0 (address-register direct is illegal) */
        {0xd1u, 0x3au}, /* ADD.B D0,(d16,PC) */
    };
    for (size_t index = 0u;
         index < sizeof(neighbors) / sizeof(neighbors[0]); ++index) {
        setUp();
        assert_unobserved_encoding_has_no_side_effect(neighbors[index], 2u);
        tearDown();
    }
}

/* Selected guest-path extension: MC68000 ADD.L Dn,(d8,An,Xn). The brief
 * indexed destination contributes 14 clocks and ADD.L Dn-to-memory contributes
 * 12, per User's Manual Rev. 9.1 Tables 8-1 and 8-4 (pp. 8-2, 8-4): 26 clocks. */
static void add_long_data_register_to_indexed_memory_covers_all_registers_and_index_forms(void) {
    static const uint32_t values[8] = {
        UINT32_C(0x00000000), UINT32_C(0x00000001), UINT32_C(0x7fffffff),
        UINT32_C(0x80000000), UINT32_C(0xffffffff), UINT32_C(0xfffffffe),
        UINT32_C(0x55555555), UINT32_C(0xaaaaaaaa)};
    static const int8_t displacements[4] = {-128, -1, 0, 127};
    size_t case_index = 0u;
    for (unsigned source_register = 0u; source_register < 8u;
         ++source_register) {
        for (unsigned base_register = 0u; base_register < 8u;
             ++base_register) {
            for (unsigned index_register = 0u; index_register < 8u;
                 ++index_register) {
                for (unsigned index_is_address = 0u; index_is_address < 2u;
                     ++index_is_address) {
                    if (index_is_address != 0u &&
                        index_register == base_register)
                        continue;
                    for (unsigned index_is_long = 0u; index_is_long < 2u;
                         ++index_is_long) {
                        setUp();
                        create_cpu();
                        const int8_t displacement =
                            displacements[case_index % 4u];
                        const uint16_t extension = (uint16_t)(
                            (index_is_address != 0u ? UINT16_C(0x8000) : 0u) |
                            (uint16_t)(index_register << 12) |
                            (index_is_long != 0u ? UINT16_C(0x0800) : 0u) |
                            (uint8_t)displacement);
                        uint8_t program[4];
                        size_t length = 0u;
                        emit_word(program, &length, (uint16_t)(
                            UINT16_C(0xd1b0) |
                            (uint16_t)(source_register << 9) | base_register));
                        emit_word(program, &length, extension);
                        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                          reset_with_program(program, length));

                        owned_cpu_state before;
                        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                          owned_cpu_capture_state(cpu, &before));
                        for (unsigned reg = 0u; reg < 8u; ++reg) {
                            before.data_registers[reg] = values[reg];
                            before.address_registers[reg] =
                                UINT32_C(0x0300) + (uint32_t)reg * UINT32_C(0x20);
                        }
                        const uint32_t target = UINT32_C(0x0180) +
                            (uint32_t)(case_index % 60u) * UINT32_C(2);
                        before.address_registers[base_register] = target -
                            (uint32_t)(int32_t)displacement;
                        if (index_is_address != 0u)
                            before.address_registers[index_register] =
                                values[(index_register + 3u) % 8u];
                        else
                            before.data_registers[index_register] =
                                values[(index_register + 3u) % 8u];
                        const uint32_t index_full = index_is_address != 0u
                            ? before.address_registers[index_register]
                            : before.data_registers[index_register];
                        const uint32_t index_value = index_is_long != 0u
                            ? index_full
                            : expected_sign_extend_word((uint16_t)index_full);
                        before.address_registers[base_register] -= index_value;
                        before.ssp = before.address_registers[7];
                        const uint16_t initial_flags = (uint16_t)(
                            UINT16_C(0x2700) | (uint16_t)(case_index & 0x1fu));
                        before.sr = initial_flags;
                        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                          owned_cpu_restore_state(cpu, &before));

                        const uint32_t source = before.data_registers[source_register];
                        /* Make the arithmetic independent of zero-filled RAM. */
                        const uint32_t destination_pattern = values[(case_index + 5u) % 8u];
                        memory.rom[target] = (uint8_t)(destination_pattern >> 24);
                        memory.rom[target + 1u] = (uint8_t)(destination_pattern >> 16);
                        memory.rom[target + 2u] = (uint8_t)(destination_pattern >> 8);
                        memory.rom[target + 3u] = (uint8_t)destination_pattern;
                        const uint64_t full_sum =
                            (uint64_t)destination_pattern + source;
                        const uint32_t result = (uint32_t)full_sum;
                        uint16_t expected_sr = (uint16_t)(
                            initial_flags & UINT16_C(0xffe0));
                        if (result == 0u)
                            expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0004));
                        if ((result & UINT32_C(0x80000000)) != 0u)
                            expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0008));
                        if (((~(destination_pattern ^ source) &
                              (destination_pattern ^ result)) &
                             UINT32_C(0x80000000)) != 0u)
                            expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0002));
                        if (full_sum > UINT32_MAX)
                            expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0011));

                        const size_t reads_before = memory.reads;
                        const owned_cpu_run_result run =
                            owned_cpu_run(cpu, UINT64_C(26));
                        TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, run.reason);
                        TEST_ASSERT_EQUAL_UINT64(26u, run.elapsed_cycles);
                        TEST_ASSERT_EQUAL_UINT64(1u, run.instructions);
                        TEST_ASSERT_EQUAL_UINT(reads_before + 4u, memory.reads);
                        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                            memory.read_addresses[reads_before]);
                        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102),
                            memory.read_addresses[reads_before + 1u]);
                        TEST_ASSERT_EQUAL_HEX32(target,
                            memory.read_addresses[reads_before + 2u]);
                        TEST_ASSERT_EQUAL_HEX32(target + UINT32_C(2),
                            memory.read_addresses[reads_before + 3u]);
                        TEST_ASSERT_EQUAL_UINT(0u, memory.byte_reads);
                        TEST_ASSERT_EQUAL_UINT(2u, memory.write_attempts);
                        TEST_ASSERT_EQUAL_UINT(2u, memory.successful_writes);
                        TEST_ASSERT_EQUAL_HEX32(target, memory.write_addresses[0]);
                        TEST_ASSERT_EQUAL_HEX32(target + UINT32_C(2),
                                                memory.write_addresses[1]);
                        TEST_ASSERT_EQUAL_HEX16((uint16_t)(result >> 16),
                                                memory.write_values[0]);
                        TEST_ASSERT_EQUAL_HEX16((uint16_t)result,
                                                memory.write_values[1]);

                        owned_cpu_observation after;
                        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                          owned_cpu_observe(cpu, &after));
                        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x104), after.pc);
                        TEST_ASSERT_EQUAL_HEX16(expected_sr, after.sr);
                        for (unsigned reg = 0u; reg < 8u; ++reg) {
                            TEST_ASSERT_EQUAL_HEX32(before.data_registers[reg],
                                                    after.data_registers[reg]);
                            TEST_ASSERT_EQUAL_HEX32(before.address_registers[reg],
                                                    after.address_registers[reg]);
                        }
                        TEST_ASSERT_EQUAL_HEX32(before.ssp, after.ssp);
                        tearDown();
                        ++case_index;
                    }
                }
            }
        }
    }
}

static void add_long_data_register_to_indexed_memory_odd_address_takes_vector_three_before_operand_read(void) {
    const uint8_t program[] = {0xd1, 0xb0, 0x00, 0x01};
    setUp();
    create_cpu();
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      reset_with_program(program, sizeof(program)));
    set_vector(12u, UINT32_C(0x0140));
    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.address_registers[0] = UINT32_C(0x0180);
    state.address_registers[7] = UINT32_C(0x01f0);
    state.ssp = UINT32_C(0x01f0);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
    const size_t reads_before = memory.reads;
    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(50));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(50u, result.elapsed_cycles);
    owned_cpu_observation observation;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_UINT8(3u, observation.last_exception_vector);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0140), observation.pc);
    for (size_t i = reads_before; i < memory.reads && i < ROM_SIZE; ++i) {
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x0181), memory.read_addresses[i]);
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x0182), memory.read_addresses[i]);
    }
    tearDown();
}

static void add_long_data_register_to_indexed_memory_full_extension_and_neighbors_stay_unsupported(void) {
    static const uint8_t full_extension[] = {0xd1, 0xb0, 0x01, 0x00};
    static const struct {
        uint8_t program[4];
        size_t length;
        size_t expected_fetches;
    } neighbors[] = {
        {{0xd1, 0x88, 0x00, 0x00}, 2u, 1u}, /* ADD.L D0,A0 */
        {{0xd1, 0x3a, 0x00, 0x00}, 4u, 1u}, /* ADD.B D0,(d16,PC) */
    };
    setUp();
    create_cpu();
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      reset_with_program(full_extension, sizeof(full_extension)));
    const size_t reads_before = memory.reads;
    const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(26));
    TEST_ASSERT_EQUAL(OWNED_CPU_UNSUPPORTED_OPCODE, result.reason);
    TEST_ASSERT_EQUAL_UINT64(0u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(0u, result.instructions);
    TEST_ASSERT_EQUAL_UINT(reads_before + 2u, memory.reads);
    TEST_ASSERT_EQUAL_UINT(0u, memory.byte_reads);
    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
    tearDown();
    for (size_t index = 0u;
         index < sizeof(neighbors) / sizeof(neighbors[0]); ++index) {
        setUp();
        assert_unobserved_encoding_has_no_side_effect_after_fetches(
            neighbors[index].program, neighbors[index].length,
            neighbors[index].expected_fetches);
        tearDown();
    }
}

/* SUB.B (An),Dn subtracts the byte source and preserves Dn[31:8]. The MC68000
 * UM Rev. 9.1 Table 8-4 p. 8-4 gives 4(1/0)+; Table 8-1 p. 8-2 adds 4(1/0)
 * for (An), totaling 8 clocks and one byte operand read. */
static void sub_byte_address_indirect_to_data_register_covers_registers_and_odd_addresses(void) {
    static const uint8_t values[8] = {
        UINT8_C(0x00), UINT8_C(0x01), UINT8_C(0x7f), UINT8_C(0x80),
        UINT8_C(0xff), UINT8_C(0xfe), UINT8_C(0x55), UINT8_C(0xaa)};
    size_t case_index = 0u;
    for (unsigned source_register = 0u; source_register < 8u;
         ++source_register) {
        for (unsigned destination_register = 0u; destination_register < 8u;
             ++destination_register) {
            setUp();
            create_cpu();
            uint8_t program[2];
            size_t length = 0u;
            emit_word(program, &length, (uint16_t)(
                UINT16_C(0x9010) | (uint16_t)(destination_register << 9) |
                source_register));
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              reset_with_program(program, length));
            owned_cpu_state before;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_capture_state(cpu, &before));
            for (unsigned reg = 0u; reg < 8u; ++reg) {
                before.data_registers[reg] = UINT32_C(0xa5c30000) | reg;
                before.address_registers[reg] =
                    UINT32_C(0x0300) + (uint32_t)reg * UINT32_C(0x20);
            }
            const uint32_t target = UINT32_C(0x0181) +
                (uint32_t)(case_index % 64u);
            before.address_registers[source_register] = target;
            before.ssp = before.address_registers[7];
            const uint8_t destination = values[(case_index + 3u) % 8u];
            const uint8_t source = values[case_index % 8u];
            before.data_registers[destination_register] =
                UINT32_C(0xface0000) | ((uint32_t)destination << 8) | destination;
            const uint16_t initial_flags = (uint16_t)(
                UINT16_C(0x2700) | (uint16_t)(case_index & 0x1fu));
            before.sr = initial_flags;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_restore_state(cpu, &before));
            memory.rom[target] = source;
            const uint16_t full_difference =
                (uint16_t)destination - (uint16_t)source;
            const uint8_t result = (uint8_t)full_difference;
            uint16_t expected_sr = (uint16_t)(
                initial_flags & UINT16_C(0xffe0));
            if (result == 0u)
                expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0004));
            if ((result & UINT8_C(0x80)) != 0u)
                expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0008));
            if (((destination ^ source) & (destination ^ result) &
                 UINT8_C(0x80)) != 0u)
                expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0002));
            if (source > destination)
                expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0011));

            const size_t reads_before = memory.reads;
            const size_t byte_reads_before = memory.byte_reads;
            const owned_cpu_run_result run = owned_cpu_run(cpu, UINT64_C(8));
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, run.reason);
            TEST_ASSERT_EQUAL_UINT64(8u, run.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, run.instructions);
            TEST_ASSERT_EQUAL_UINT(reads_before + 1u, memory.reads);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                                    memory.read_addresses[reads_before]);
            TEST_ASSERT_EQUAL_UINT(byte_reads_before + 1u, memory.byte_reads);
            TEST_ASSERT_EQUAL_HEX32(target,
                                    memory.byte_read_addresses[byte_reads_before]);
            TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
            owned_cpu_observation after;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102), after.pc);
            TEST_ASSERT_EQUAL_HEX16(expected_sr, after.sr);
            for (unsigned reg = 0u; reg < 8u; ++reg) {
                const uint32_t expected_data = reg == destination_register
                    ? ((before.data_registers[reg] & UINT32_C(0xffffff00)) |
                       result)
                    : before.data_registers[reg];
                TEST_ASSERT_EQUAL_HEX32(expected_data, after.data_registers[reg]);
                TEST_ASSERT_EQUAL_HEX32(before.address_registers[reg],
                                        after.address_registers[reg]);
            }
            TEST_ASSERT_EQUAL_HEX32(before.ssp, after.ssp);
            tearDown();
            ++case_index;
        }
    }
}

/* SUB.L Dm,Dn is the remaining register-direct width in the source-to-Dn
 * direction. UM Rev. 9.1 Table 8-4 p. 8-4 gives the long register-direct
 * footnoted base as 8 clocks; PRM §4 SUB defines width-limited subtraction
 * and X/N/Z/V/C. */
static void sub_long_data_register_to_data_register_covers_all_pairs(void) {
    static const uint32_t values[] = {
        UINT32_C(0x00000000), UINT32_C(0x00000001), UINT32_C(0x7fffffff),
        UINT32_C(0x80000000), UINT32_C(0xffffffff), UINT32_C(0xfffffffe),
        UINT32_C(0x55555555), UINT32_C(0xaaaaaaaa),
    };
    for (unsigned source_register = 0u; source_register < 8u;
         ++source_register) {
        for (unsigned destination_register = 0u; destination_register < 8u;
             ++destination_register) {
            setUp();
            create_cpu();
            uint8_t program[2];
            size_t program_length = 0u;
            emit_word(program, &program_length, (uint16_t)(
                UINT16_C(0x9080) | (uint16_t)(destination_register << 9) |
                source_register));
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              reset_with_program(program, program_length));
            owned_cpu_state before;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_capture_state(cpu, &before));
            const uint32_t source = values[source_register];
            const uint32_t destination = values[destination_register];
            for (unsigned reg = 0u; reg < 8u; ++reg)
                before.data_registers[reg] = UINT32_C(0x13570000) | reg;
            before.data_registers[source_register] = source;
            before.data_registers[destination_register] = destination;
            const uint16_t initial_sr = (uint16_t)(UINT16_C(0x271f) ^
                (uint16_t)((source_register + destination_register) & 0x1fu));
            before.sr = initial_sr;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_restore_state(cpu, &before));

            const uint32_t result_value = destination - source;
            uint16_t expected_sr = (uint16_t)(initial_sr & UINT16_C(0xffe0));
            if (result_value == 0u)
                expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0004));
            if ((result_value & UINT32_C(0x80000000)) != 0u)
                expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0008));
            if (((destination ^ source) & (destination ^ result_value) &
                 UINT32_C(0x80000000)) != 0u)
                expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0002));
            if (source > destination)
                expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0011));

            const size_t reads_before = memory.reads;
            const size_t ordered_before = memory.ordered_read_count;
            const owned_cpu_run_result run = owned_cpu_run(cpu, UINT64_C(8));
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, run.reason);
            TEST_ASSERT_EQUAL_UINT64(8u, run.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, run.instructions);
            TEST_ASSERT_EQUAL_UINT(reads_before + 1u, memory.reads);
            TEST_ASSERT_EQUAL_UINT(ordered_before + 1u,
                                   memory.ordered_read_count);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                                    memory.ordered_read_addresses[ordered_before]);
            TEST_ASSERT_EQUAL_UINT8(2u,
                                    memory.ordered_read_widths[ordered_before]);
            TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
            owned_cpu_observation after;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102), after.pc);
            TEST_ASSERT_EQUAL_HEX16(expected_sr, after.sr);
            for (unsigned reg = 0u; reg < 8u; ++reg)
                TEST_ASSERT_EQUAL_HEX32(reg == destination_register
                    ? result_value : before.data_registers[reg],
                    after.data_registers[reg]);
            tearDown();
        }
    }
}

/* SUB.W/L An,Dn are legal source forms. SUB.B An,Dn is explicitly prohibited
 * by the SUB source-EA table footnote. An-direct register cycles use the
 * register-direct base; the long form takes the Table 8-4 ** adjustment. */
static void sub_word_long_address_register_sources_cover_all_pairs(void) {
    static const uint32_t values[] = {
        UINT32_C(0x00000000), UINT32_C(0x00000001), UINT32_C(0x00007fff),
        UINT32_C(0x00008000), UINT32_C(0x0000ffff), UINT32_C(0x1234fffe),
        UINT32_C(0x7fffffff), UINT32_C(0x80000000),
    };
    for (unsigned width_index = 0u; width_index < 2u; ++width_index) {
        const unsigned width = width_index == 0u ? 2u : 4u;
        const unsigned opmode = width_index == 0u ? 1u : 2u;
        const uint32_t mask = width == 2u ? UINT32_C(0xffff) : UINT32_MAX;
        const uint32_t sign = width == 2u ? UINT32_C(0x8000) :
            UINT32_C(0x80000000);
        const uint64_t cycles = width == 2u ? UINT64_C(4) : UINT64_C(8);
        for (unsigned source_register = 0u; source_register < 8u;
             ++source_register) {
            for (unsigned destination_register = 0u; destination_register < 8u;
                 ++destination_register) {
                setUp();
                create_cpu();
                uint8_t program[2];
                size_t program_length = 0u;
                emit_word(program, &program_length, (uint16_t)(
                    UINT16_C(0x9000) | (uint16_t)(destination_register << 9) |
                    (uint16_t)(opmode << 6) | UINT16_C(0x0008) |
                    source_register));
                TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                    reset_with_program(program, program_length));
                owned_cpu_state before;
                TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                  owned_cpu_capture_state(cpu, &before));
                const uint32_t source = values[source_register];
                const uint32_t destination = values[destination_register];
                for (unsigned reg = 0u; reg < 8u; ++reg) {
                    before.address_registers[reg] = values[reg];
                    before.data_registers[reg] = UINT32_C(0xa5a50000) | reg;
                }
                before.address_registers[source_register] = source;
                before.data_registers[destination_register] = width == 4u
                    ? destination : UINT32_C(0xface0000) | destination;
                before.ssp = before.address_registers[7];
                const uint16_t initial_sr = (uint16_t)(UINT16_C(0x2700) |
                    (((source_register + destination_register) & 1u) != 0u
                        ? UINT16_C(0x001f) : 0u));
                before.sr = initial_sr;
                TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                  owned_cpu_restore_state(cpu, &before));

                const uint32_t source_width = source & mask;
                const uint32_t destination_width = destination & mask;
                const uint32_t result_value =
                    (destination_width - source_width) & mask;
                uint16_t expected_sr = (uint16_t)(initial_sr & UINT16_C(0xffe0));
                if (result_value == 0u)
                    expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0004));
                if ((result_value & sign) != 0u)
                    expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0008));
                if (((destination_width ^ source_width) &
                     (destination_width ^ result_value) & sign) != 0u)
                    expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0002));
                if (source_width > destination_width)
                    expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0011));

                const size_t reads_before = memory.reads;
                const owned_cpu_run_result run = owned_cpu_run(cpu, cycles);
                TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, run.reason);
                TEST_ASSERT_EQUAL_UINT64(cycles, run.elapsed_cycles);
                TEST_ASSERT_EQUAL_UINT64(1u, run.instructions);
                TEST_ASSERT_EQUAL_UINT(reads_before + 1u, memory.reads);
                TEST_ASSERT_EQUAL_UINT(0u, memory.byte_reads);
                TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
                owned_cpu_observation after;
                TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
                TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102), after.pc);
                TEST_ASSERT_EQUAL_HEX16(expected_sr, after.sr);
                for (unsigned reg = 0u; reg < 8u; ++reg) {
                    const uint32_t expected_data = reg == destination_register
                        ? (width == 4u ? result_value :
                            ((before.data_registers[reg] & ~mask) |
                             result_value))
                        : before.data_registers[reg];
                    TEST_ASSERT_EQUAL_HEX32(expected_data,
                                             after.data_registers[reg]);
                    TEST_ASSERT_EQUAL_HEX32(before.address_registers[reg],
                                             after.address_registers[reg]);
                }
                TEST_ASSERT_EQUAL_HEX32(before.ssp, after.ssp);
                tearDown();
            }
        }
    }
}

/* SUB byte/word/long data-alterable memory sources share source EA resolution
 * and subtraction semantics, but not SUB's Dn-source memory-destination
 * direction. Table 8-4's long memory-source base is six clocks; byte/word is
 * four, with Table 8-1 EA costs. */
static void sub_byte_word_long_memory_sources_cover_all_data_alterable_eas(void) {
    static const uint16_t ea_codes[] = {
        UINT16_C(0x10), UINT16_C(0x18), UINT16_C(0x20), UINT16_C(0x28),
        UINT16_C(0x30), UINT16_C(0x38), UINT16_C(0x39),
    };
    static const uint64_t byte_word_ea_cycles[] = {
        4u, 4u, 6u, 8u, 10u, 8u, 12u,
    };
    static const uint64_t long_ea_cycles[] = {
        8u, 8u, 10u, 12u, 14u, 12u, 16u,
    };
    static const unsigned widths[] = {1u, 2u, 4u};
    const uint32_t target = UINT32_C(0x0180);
    size_t case_number = 0u;

    for (size_t width_index = 0u; width_index < 3u; ++width_index) {
        const unsigned width = widths[width_index];
        const unsigned opmode = (unsigned)width_index;
        const uint32_t mask = width == 1u ? UINT32_C(0xff) :
            width == 2u ? UINT32_C(0xffff) : UINT32_MAX;
        const uint32_t sign = width == 1u ? UINT32_C(0x80) :
            width == 2u ? UINT32_C(0x8000) : UINT32_C(0x80000000);
        for (size_t ea_index = 0u; ea_index < 7u; ++ea_index) {
            const unsigned base_count = ea_index < 5u ? 8u : 1u;
            for (unsigned source_register = 0u; source_register < base_count;
                 ++source_register) {
                for (unsigned destination_register = 0u;
                     destination_register < 8u;
                     ++destination_register, ++case_number) {
                    const unsigned ea_register = ea_index < 5u
                        ? source_register : (unsigned)(ea_codes[ea_index] & 7u);
                    const uint16_t source_ea = (uint16_t)(ea_codes[ea_index] |
                        (ea_index < 5u ? source_register : 0u));
                    const uint16_t opcode = (uint16_t)(UINT16_C(0x9000) |
                        (uint16_t)(destination_register << 9) |
                        (uint16_t)(opmode << 6) | source_ea);
                    uint8_t program[8] = {0};
                    size_t program_length = 0u;
                    emit_word(program, &program_length, opcode);
                    unsigned extension_words = 0u;
                    if (ea_index == 3u) {
                        emit_word(program, &program_length, UINT16_C(0x0010));
                        extension_words = 1u;
                    } else if (ea_index == 4u) {
                        emit_word(program, &program_length, (uint16_t)(
                            (uint16_t)(destination_register << 12) |
                            UINT16_C(0x0004)));
                        extension_words = 1u;
                    } else if (ea_index == 5u) {
                        emit_word(program, &program_length, (uint16_t)target);
                        extension_words = 1u;
                    } else if (ea_index == 6u) {
                        emit_word(program, &program_length,
                                  (uint16_t)(target >> 16));
                        emit_word(program, &program_length, (uint16_t)target);
                        extension_words = 2u;
                    }

                    setUp();
                    create_cpu();
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                        reset_with_program(program, program_length));
                    const unsigned scenario = (unsigned)(case_number & 3u);
                    const uint32_t destination = scenario == 0u ? 0u :
                        scenario == 1u ? UINT32_C(1) : scenario == 2u ? sign :
                        UINT32_C(0x35);
                    const uint32_t source = scenario == 0u ? 0u :
                        scenario == 1u ? UINT32_C(2) : scenario == 2u ?
                        UINT32_C(1) : UINT32_C(0x11);
                    const uint32_t result_value = (destination - source) & mask;
                    uint16_t expected_sr = UINT16_C(0x2700);
                    if (result_value == 0u)
                        expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0004));
                    if ((result_value & sign) != 0u)
                        expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0008));
                    if (((destination ^ source) &
                         (destination ^ result_value) & sign) != 0u)
                        expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0002));
                    if (source > destination)
                        expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0011));

                    if (width == 1u) {
                        memory.rom[target] = (uint8_t)source;
                    } else {
                        memory.rom[target] = (uint8_t)(source >>
                            (width == 2u ? 8u : 24u));
                        memory.rom[target + 1u] = (uint8_t)(source >>
                            (width == 2u ? 0u : 16u));
                        if (width == 4u) {
                            memory.rom[target + 2u] = (uint8_t)(source >> 8);
                            memory.rom[target + 3u] = (uint8_t)source;
                        }
                    }

                    owned_cpu_state before;
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      owned_cpu_capture_state(cpu, &before));
                    for (unsigned reg = 0u; reg < 8u; ++reg) {
                        before.address_registers[reg] =
                            UINT32_C(0x0300) + reg * UINT32_C(0x20);
                        before.data_registers[reg] = UINT32_C(0xa5a50000) | reg;
                    }
                    before.data_registers[destination_register] = width == 4u
                        ? destination : UINT32_C(0xa5a50000) | destination;
                    const uint32_t step = width == 1u && ea_register == 7u
                        ? UINT32_C(2) : width;
                    if (ea_index <= 1u) {
                        before.address_registers[ea_register] = target;
                    } else if (ea_index == 2u) {
                        before.address_registers[ea_register] = target + step;
                    } else if (ea_index == 3u) {
                        before.address_registers[ea_register] =
                            target - UINT32_C(0x10);
                    } else if (ea_index == 4u) {
                        const uint16_t index_word =
                            (uint16_t)before.data_registers[destination_register];
                        const int32_t signed_index = index_word <= UINT16_C(0x7fff)
                            ? (int32_t)index_word
                            : (int32_t)index_word - INT32_C(0x10000);
                        before.address_registers[ea_register] =
                            (uint32_t)((int64_t)target - INT64_C(4) - signed_index);
                    }
                    before.ssp = before.address_registers[7];
                    before.sr = UINT16_C(0x271f);
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      owned_cpu_restore_state(cpu, &before));

                    const size_t reads_before = memory.reads;
                    const size_t byte_reads_before = memory.byte_reads;
                    const size_t ordered_before = memory.ordered_read_count;
                    const uint64_t ea_cycles = width == 4u
                        ? long_ea_cycles[ea_index]
                        : byte_word_ea_cycles[ea_index];
                    const uint64_t cycles = (width == 4u ? UINT64_C(6) :
                        UINT64_C(4)) + ea_cycles;
                    const owned_cpu_run_result run = owned_cpu_run(cpu, cycles);
                    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, run.reason);
                    TEST_ASSERT_EQUAL_UINT64(cycles, run.elapsed_cycles);
                    TEST_ASSERT_EQUAL_UINT64(1u, run.instructions);
                    const unsigned operand_words = width == 4u ? 2u :
                        width == 2u ? 1u : 0u;
                    TEST_ASSERT_EQUAL_UINT((size_t)(1u + extension_words +
                        operand_words), memory.reads - reads_before);
                    TEST_ASSERT_EQUAL_UINT(width == 1u ? 1u : 0u,
                        memory.byte_reads - byte_reads_before);
                    TEST_ASSERT_EQUAL_UINT((size_t)(1u + extension_words +
                        operand_words + (width == 1u ? 1u : 0u)),
                        memory.ordered_read_count - ordered_before);
                    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                        memory.ordered_read_addresses[ordered_before]);
                    for (unsigned ext = 0u; ext < extension_words; ++ext)
                        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102) + ext * 2u,
                            memory.ordered_read_addresses[ordered_before + 1u + ext]);
                    const size_t operand_event = ordered_before + 1u + extension_words;
                    TEST_ASSERT_EQUAL_HEX32(target,
                        memory.ordered_read_addresses[operand_event]);
                    TEST_ASSERT_EQUAL_UINT8(width == 1u ? 1u : 2u,
                        memory.ordered_read_widths[operand_event]);
                    if (width == 4u) {
                        TEST_ASSERT_EQUAL_HEX32(target + UINT32_C(2),
                            memory.ordered_read_addresses[operand_event + 1u]);
                        TEST_ASSERT_EQUAL_UINT8(2u,
                            memory.ordered_read_widths[operand_event + 1u]);
                    }
                    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);

                    owned_cpu_observation after;
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      owned_cpu_observe(cpu, &after));
                    const uint32_t expected_data = width == 4u ? result_value :
                        ((before.data_registers[destination_register] & ~mask) |
                         result_value);
                    TEST_ASSERT_EQUAL_HEX32(expected_data,
                        after.data_registers[destination_register]);
                    TEST_ASSERT_EQUAL_HEX16(expected_sr, after.sr);
                    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100) + program_length,
                                             after.pc);
                    if (ea_index < 5u) {
                        const uint32_t expected_base = ea_index == 1u
                            ? target + step : ea_index == 2u ? target :
                            before.address_registers[ea_register];
                        TEST_ASSERT_EQUAL_HEX32(expected_base,
                            after.address_registers[ea_register]);
                        if (ea_register == 7u)
                            TEST_ASSERT_EQUAL_HEX32(expected_base, after.ssp);
                    }
                    tearDown();
                }
            }
        }
    }
}

static void sub_word_long_postincrement_odd_sources_commit_before_vector_three(void) {
    /* The primary manual establishes vector 3 for odd word/long operands; the
     * pre-read postincrement is checked as pinned-emulator differential state. */
    assert_memory_source_odd_postincrement_commits_before_vector_three(
        UINT16_C(0x905a), 2u); /* SUB.W (A2)+,D0 */
    assert_memory_source_odd_postincrement_commits_before_vector_three(
        UINT16_C(0x909a), 4u); /* SUB.L (A2)+,D0 */
}

static void sub_word_long_predecrement_odd_sources_commit_before_vector_three(void) {
    static const struct {
        uint16_t opcode;
        unsigned width;
        uint32_t initial_base;
        uint32_t decremented_base;
    } cases[] = {
        {UINT16_C(0x9062), 2u, UINT32_C(0x0183), UINT32_C(0x0181)},
        {UINT16_C(0x90a2), 4u, UINT32_C(0x0185), UINT32_C(0x0181)},
    };
    for (size_t index = 0u; index < sizeof(cases) / sizeof(cases[0]); ++index) {
        setUp();
        create_cpu();
        uint8_t program[2];
        size_t length = 0u;
        emit_word(program, &length, cases[index].opcode);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, length));
        set_vector(12u, UINT32_C(0x0140));
        owned_cpu_state before;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
        before.address_registers[2] = cases[index].initial_base;
        before.ssp = before.address_registers[7];
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));

        const size_t reads_before = memory.reads;
        const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(50));
        TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
        TEST_ASSERT_EQUAL_UINT64(50u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(0u, result.instructions);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0100), result.fault_pc);
        TEST_ASSERT_EQUAL_HEX16(cases[index].opcode, result.instruction_register);
        for (size_t read = reads_before; read < memory.reads; ++read) {
            TEST_ASSERT_NOT_EQUAL(cases[index].decremented_base,
                                  memory.read_addresses[read]);
            if (cases[index].width == 4u)
                TEST_ASSERT_NOT_EQUAL(cases[index].decremented_base + 2u,
                                      memory.read_addresses[read]);
        }
        owned_cpu_observation after;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
        TEST_ASSERT_EQUAL_UINT8(3u, after.last_exception_vector);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0140), after.pc);
        TEST_ASSERT_EQUAL_HEX32(cases[index].decremented_base,
                                after.address_registers[2]);
        tearDown();
    }
}

static void sub_word_postincrement_host_fault_and_counter_preflight_keep_base(void) {
    const uint8_t program[] = {UINT8_C(0x90), UINT8_C(0x58)};

    setUp();
    create_cpu();
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      reset_with_program(program, sizeof(program)));
    owned_cpu_state before;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
    before.address_registers[0] = UINT32_C(0x0180);
    before.data_registers[0] = UINT32_C(0x12340010);
    before.sr = UINT16_C(0x271f);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));
    memory.fail_read_on = memory.reads + 2u;
    const owned_cpu_run_result host_fault = owned_cpu_run(cpu, UINT64_C(100));
    TEST_ASSERT_EQUAL(OWNED_CPU_HOST_FAULT, host_fault.reason);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0100), host_fault.fault_pc);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x9058), host_fault.instruction_register);
    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
    owned_cpu_state faulted;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_test_capture_faulted_state(cpu, &faulted));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0180), faulted.address_registers[0]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x12340010), faulted.data_registers[0]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x271f), faulted.sr);
    tearDown();

    setUp();
    create_cpu();
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      reset_with_program(program, sizeof(program)));
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
    before.address_registers[0] = UINT32_C(0x0180);
    before.data_registers[0] = UINT32_C(0x12340010);
    before.sr = UINT16_C(0x271f);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_test_seed_counters(
        cpu, 0u, 0u, 0u, 0u, UINT64_MAX - UINT64_C(1)));
    const size_t reads_before = memory.reads;
    const size_t byte_reads_before = memory.byte_reads;
    const owned_cpu_run_result overflow = owned_cpu_run(cpu, UINT64_C(8));
    TEST_ASSERT_EQUAL(OWNED_CPU_COUNTER_OVERFLOW, overflow.reason);
    TEST_ASSERT_EQUAL_UINT64(0u, overflow.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(0u, overflow.instructions);
    TEST_ASSERT_EQUAL_UINT(reads_before + 1u, memory.reads);
    TEST_ASSERT_EQUAL_UINT(byte_reads_before, memory.byte_reads);
    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
    owned_cpu_observation after;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0100), after.pc);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0180), after.address_registers[0]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x12340010), after.data_registers[0]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x271f), after.sr);
    tearDown();
}

/* PC-relative and immediate SUB sources are legal source EAs but intentionally
 * do not enter the data-alterable-only SUB memory direction. */
static void sub_byte_word_long_pc_and_immediate_sources_load_data_registers(void) {
    static const unsigned widths[] = {1u, 2u, 4u};
    static const uint16_t source_eas[] = {UINT16_C(0x3a), UINT16_C(0x3b),
                                          UINT16_C(0x3c)};
    const uint32_t target = UINT32_C(0x0180);
    for (size_t width_index = 0u; width_index < 3u; ++width_index) {
        const unsigned width = widths[width_index];
        const unsigned opmode = (unsigned)width_index;
        const uint32_t mask = width == 1u ? UINT32_C(0xff) :
            width == 2u ? UINT32_C(0xffff) : UINT32_MAX;
        const uint32_t sign = width == 1u ? UINT32_C(0x80) :
            width == 2u ? UINT32_C(0x8000) : UINT32_C(0x80000000);
        for (size_t source_index = 0u; source_index < 3u; ++source_index) {
            for (unsigned destination_register = 0u;
                 destination_register < 8u; ++destination_register) {
                setUp();
                create_cpu();
                uint8_t program[8] = {0};
                size_t program_length = 0u;
                emit_word(program, &program_length, (uint16_t)(
                    UINT16_C(0x9000) | (uint16_t)(destination_register << 9) |
                    (uint16_t)(opmode << 6) | source_eas[source_index]));
                uint32_t target_address = 0u;
                unsigned extension_words = 0u;
                if (source_index == 0u) {
                    target_address = target;
                    emit_word(program, &program_length, UINT16_C(0x007e));
                    extension_words = 1u;
                } else if (source_index == 1u) {
                    /* Brief An.W + d8, based at the extension-word address. */
                    target_address = UINT32_C(0x010a);
                    emit_word(program, &program_length, UINT16_C(0x8004));
                    extension_words = 1u;
                } else if (width == 4u) {
                    emit_word(program, &program_length, UINT16_C(0x0000));
                    emit_word(program, &program_length, UINT16_C(0x0035));
                    extension_words = 2u;
                } else {
                    emit_word(program, &program_length, UINT16_C(0x0035));
                    extension_words = 1u;
                }
                TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                  reset_with_program(program, program_length));
                if (source_index != 2u) {
                    const uint32_t source_value = UINT32_C(0x11);
                    if (width == 1u) {
                        memory.rom[target_address] = (uint8_t)source_value;
                    } else {
                        memory.rom[target_address] = (uint8_t)(source_value >>
                            (width == 2u ? 8u : 24u));
                        memory.rom[target_address + 1u] = (uint8_t)(source_value >>
                            (width == 2u ? 0u : 16u));
                        if (width == 4u) {
                            memory.rom[target_address + 2u] = 0u;
                            memory.rom[target_address + 3u] = UINT8_C(0x11);
                        }
                    }
                }
                owned_cpu_state before;
                TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                  owned_cpu_capture_state(cpu, &before));
                for (unsigned reg = 0u; reg < 8u; ++reg) {
                    before.data_registers[reg] = UINT32_C(0xa5a50000) | reg;
                    before.address_registers[reg] =
                        UINT32_C(0x0300) + reg * UINT32_C(0x20);
                }
                if (source_index == 1u) before.address_registers[0] = 4u;
                const uint32_t destination = width == 1u ? UINT32_C(0x40) :
                    width == 2u ? UINT32_C(0x4000) : UINT32_C(0x40000000);
                before.data_registers[destination_register] = width == 4u
                    ? destination : UINT32_C(0xa5a50000) | destination;
                before.ssp = before.address_registers[7];
                before.sr = UINT16_C(0x271f);
                TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                  owned_cpu_restore_state(cpu, &before));

                const uint32_t source_value = source_index == 2u
                    ? (width == 4u ? UINT32_C(0x35) : UINT32_C(0x35))
                    : UINT32_C(0x11);
                const uint32_t result_value = (destination - source_value) & mask;
                uint16_t expected_sr = UINT16_C(0x2700);
                if (result_value == 0u)
                    expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0004));
                if ((result_value & sign) != 0u)
                    expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0008));
                if (((destination ^ source_value) &
                     (destination ^ result_value) & sign) != 0u)
                    expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0002));
                if (source_value > destination)
                    expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0011));

                const size_t reads_before = memory.reads;
                const size_t byte_reads_before = memory.byte_reads;
                const size_t ordered_before = memory.ordered_read_count;
                const uint64_t cycles = source_index == 2u
                    ? (width == 4u ? UINT64_C(16) : UINT64_C(8))
                    : source_index == 0u
                        ? (width == 4u ? UINT64_C(18) : UINT64_C(12))
                        : (width == 4u ? UINT64_C(20) : UINT64_C(14));
                const owned_cpu_run_result run = owned_cpu_run(cpu, cycles);
                TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, run.reason);
                TEST_ASSERT_EQUAL_UINT64(cycles, run.elapsed_cycles);
                TEST_ASSERT_EQUAL_UINT64(1u, run.instructions);
                const size_t operand_word_reads = source_index == 2u ? 0u :
                    width == 4u ? 2u : width == 2u ? 1u : 0u;
                TEST_ASSERT_EQUAL_UINT((size_t)(1u + extension_words +
                    operand_word_reads),
                    memory.reads - reads_before);
                TEST_ASSERT_EQUAL_UINT(source_index == 2u || width != 1u ? 0u : 1u,
                                       memory.byte_reads - byte_reads_before);
                TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
                TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                    memory.ordered_read_addresses[ordered_before]);
                if (source_index != 2u) {
                    const size_t operand_event = ordered_before + 1u + extension_words;
                    TEST_ASSERT_EQUAL_HEX32(target_address,
                        memory.ordered_read_addresses[operand_event]);
                    if (width == 4u)
                        TEST_ASSERT_EQUAL_HEX32(target_address + 2u,
                            memory.ordered_read_addresses[operand_event + 1u]);
                }
                owned_cpu_observation after;
                TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                  owned_cpu_observe(cpu, &after));
                TEST_ASSERT_EQUAL_HEX32(width == 4u ? result_value :
                    ((before.data_registers[destination_register] & ~mask) |
                     result_value),
                    after.data_registers[destination_register]);
                TEST_ASSERT_EQUAL_HEX16(expected_sr, after.sr);
                TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100) + program_length,
                                         after.pc);
                tearDown();
            }
        }
    }
}

static void sub_byte_immediate_uses_only_low_extension_byte_for_borrow(void) {
    const uint8_t program[] = {UINT8_C(0x90), UINT8_C(0x3c),
                               UINT8_C(0x12), UINT8_C(0x05)};
    setUp();
    create_cpu();
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      reset_with_program(program, sizeof(program)));
    owned_cpu_state before;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
    before.data_registers[0] = UINT32_C(0xabcd0040);
    before.sr = UINT16_C(0x271f);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));

    const size_t reads_before = memory.reads;
    const owned_cpu_run_result run = owned_cpu_run(cpu, UINT64_C(8));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, run.reason);
    TEST_ASSERT_EQUAL_UINT64(8u, run.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(1u, run.instructions);
    TEST_ASSERT_EQUAL_UINT(reads_before + 2u, memory.reads);
    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
    owned_cpu_observation after;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0xabcd003b), after.data_registers[0]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2700), after.sr);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x104), after.pc);
    tearDown();
}

/* SUB.B Dm,Dn is the Dn-destination form with data-register direct source.
 * MC68000 UM Rev. 9.1 Table 8-4 p. 8-4 gives 4(1/0)+; Dn source EA adds no
 * clocks. PRM §4 SUB p. 4-174 defines destination minus source and flags. */
static void sub_byte_data_register_to_data_register_covers_registers_and_flags(void) {
    static const uint8_t values[8] = {
        UINT8_C(0x00), UINT8_C(0x01), UINT8_C(0x7f), UINT8_C(0x80),
        UINT8_C(0xff), UINT8_C(0xfe), UINT8_C(0x55), UINT8_C(0xaa)};
    size_t case_index = 0u;
    for (unsigned source_register = 0u; source_register < 8u;
         ++source_register) {
        for (unsigned destination_register = 0u; destination_register < 8u;
             ++destination_register) {
            setUp();
            create_cpu();
            uint8_t program[2];
            size_t length = 0u;
            emit_word(program, &length, (uint16_t)(
                UINT16_C(0x9000) | (uint16_t)(destination_register << 9) |
                source_register));
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              reset_with_program(program, length));
            owned_cpu_state before;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_capture_state(cpu, &before));
            for (unsigned reg = 0u; reg < 8u; ++reg)
                before.data_registers[reg] = UINT32_C(0xface0000) | reg;
            const uint8_t source = values[case_index % 8u];
            const uint8_t destination = source_register == destination_register
                ? source : values[(case_index + 3u) % 8u];
            before.data_registers[source_register] =
                (before.data_registers[source_register] & UINT32_C(0xffffff00)) |
                source;
            before.data_registers[destination_register] =
                (before.data_registers[destination_register] & UINT32_C(0xffffff00)) |
                destination;
            const uint16_t initial_flags = (uint16_t)(
                UINT16_C(0x2700) | (uint16_t)(case_index & 0x1fu));
            before.sr = initial_flags;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_restore_state(cpu, &before));
            const uint8_t result = (uint8_t)((uint16_t)destination -
                                             (uint16_t)source);
            uint16_t expected_sr = (uint16_t)(
                initial_flags & UINT16_C(0xffe0));
            if (result == 0u)
                expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0004));
            if ((result & UINT8_C(0x80)) != 0u)
                expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0008));
            if (((destination ^ source) & (destination ^ result) &
                 UINT8_C(0x80)) != 0u)
                expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0002));
            if (source > destination)
                expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0011));

            const size_t reads_before = memory.reads;
            const size_t byte_reads_before = memory.byte_reads;
            const size_t writes_before = memory.write_attempts;
            const owned_cpu_run_result run = owned_cpu_run(cpu, UINT64_C(4));
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, run.reason);
            TEST_ASSERT_EQUAL_UINT64(4u, run.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, run.instructions);
            TEST_ASSERT_EQUAL_UINT(reads_before + 1u, memory.reads);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                                    memory.read_addresses[reads_before]);
            TEST_ASSERT_EQUAL_UINT(byte_reads_before, memory.byte_reads);
            TEST_ASSERT_EQUAL_UINT(writes_before, memory.write_attempts);
            owned_cpu_observation after;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102), after.pc);
            TEST_ASSERT_EQUAL_HEX16(expected_sr, after.sr);
            for (unsigned reg = 0u; reg < 8u; ++reg) {
                const uint32_t expected_data = reg == destination_register
                    ? ((before.data_registers[reg] & UINT32_C(0xffffff00)) |
                       result)
                    : before.data_registers[reg];
                TEST_ASSERT_EQUAL_HEX32(expected_data,
                                        after.data_registers[reg]);
                TEST_ASSERT_EQUAL_HEX32(before.address_registers[reg],
                                        after.address_registers[reg]);
            }
            TEST_ASSERT_EQUAL_HEX32(before.ssp, after.ssp);
            tearDown();
            ++case_index;
        }
    }
}

static void sub_byte_address_register_source_stays_illegal(void) {
    static const uint8_t neighbors[][2] = {
        {0x90u, 0x08u}, /* SUB.B A0,D0: An direct is forbidden for byte. */
    };
    for (size_t index = 0u;
         index < sizeof(neighbors) / sizeof(neighbors[0]); ++index) {
        setUp();
        assert_unobserved_encoding_has_no_side_effect(neighbors[index], 2u);
        tearDown();
    }
}

/* SUB.W Dm,Dn is a Dn-destination register-direct operation. The MC68000 UM
 * Rev. 9.1 Table 8-4 p. 8-4 gives 4(1/0)+; the Dn source EA adds 0(0/0) in
 * Table 8-1 p. 8-2. The PRM §4 SUB operation sign/flag rules preserve Dn's
 * upper word for a word-sized destination. */
static void sub_word_data_register_to_data_register_subtracts_all_pairs_in_4_cycles(void) {
    static const uint16_t values[8] = {
        UINT16_C(0x0000), UINT16_C(0x0001), UINT16_C(0x7fff), UINT16_C(0x8000),
        UINT16_C(0xffff), UINT16_C(0xfffe), UINT16_C(0x5555), UINT16_C(0xaaaa)};
    for (unsigned source_register = 0u; source_register < 8u;
         ++source_register) {
        for (unsigned destination_register = 0u; destination_register < 8u;
             ++destination_register) {
            const size_t case_index = (size_t)(source_register * 8u +
                                               destination_register);
            setUp();
            create_cpu();
            uint8_t program[2];
            size_t length = 0u;
            emit_word(program, &length, (uint16_t)(
                UINT16_C(0x9040) | (uint16_t)(destination_register << 9) |
                source_register));
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              reset_with_program(program, length));
            owned_cpu_state before;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_capture_state(cpu, &before));
            for (unsigned reg = 0u; reg < 8u; ++reg)
                before.data_registers[reg] =
                    UINT32_C(0xa5a50000) | values[reg];
            const uint16_t source = values[source_register];
            const uint16_t destination = values[destination_register];
            const uint16_t result = (uint16_t)(destination - source);
            const uint16_t initial_flags = (uint16_t)(
                UINT16_C(0x2700) | (uint16_t)((case_index * 7u) & 0x1fu));
            before.sr = initial_flags;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_restore_state(cpu, &before));

            uint16_t expected_sr = (uint16_t)(
                initial_flags & UINT16_C(0xffe0));
            if (result == 0u)
                expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0004));
            if ((result & UINT16_C(0x8000)) != 0u)
                expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0008));
            if (((destination ^ source) & (destination ^ result) &
                 UINT16_C(0x8000)) != 0u)
                expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0002));
            if (source > destination)
                expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0011));

            const size_t reads_before = memory.reads;
            const size_t byte_reads_before = memory.byte_reads;
            const size_t writes_before = memory.write_attempts;
            const owned_cpu_run_result run = owned_cpu_run(cpu, UINT64_C(4));
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, run.reason);
            TEST_ASSERT_EQUAL_UINT64(4u, run.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, run.instructions);
            TEST_ASSERT_EQUAL_UINT(reads_before + 1u, memory.reads);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                                    memory.read_addresses[reads_before]);
            TEST_ASSERT_EQUAL_UINT(byte_reads_before, memory.byte_reads);
            TEST_ASSERT_EQUAL_UINT(writes_before, memory.write_attempts);
            owned_cpu_observation after;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102), after.pc);
            TEST_ASSERT_EQUAL_HEX16(expected_sr, after.sr);
            for (unsigned reg = 0u; reg < 8u; ++reg) {
                const uint32_t expected_data = reg == destination_register
                    ? ((before.data_registers[reg] & UINT32_C(0xffff0000)) |
                       result)
                    : before.data_registers[reg];
                TEST_ASSERT_EQUAL_HEX32(expected_data,
                                        after.data_registers[reg]);
                TEST_ASSERT_EQUAL_HEX32(before.address_registers[reg],
                                        after.address_registers[reg]);
            }
            TEST_ASSERT_EQUAL_HEX32(before.ssp, after.ssp);
            tearDown();
        }
    }
}

