/* Guest-observed (05-02 task 2): MOVEA.L (d8,An,Xn),An. UM Rev. 9.1
 * Table 8-3 p. 8-3 gives 18(4/0); PRM §2.2.7 defines the brief indexed EA. */
static void movea_long_address_index_loads_every_base_and_destination(void) {
    for (unsigned base_register = 0u; base_register < 8u; ++base_register) {
        for (unsigned destination_register = 0u; destination_register < 8u;
             ++destination_register) {
            memset(&memory, 0, sizeof(memory));
            create_cpu();
            uint8_t program[4];
            size_t length = 0u;
            emit_word(program, &length,
                      (uint16_t)(UINT16_C(0x2070) |
                          (uint16_t)(destination_register << 9) |
                          (uint16_t)base_register));
            emit_word(program, &length, UINT16_C(0x00fc)); /* D0.W - 4 */
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              reset_with_program(program, length));
            owned_cpu_state before;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_capture_state(cpu, &before));
            before.address_registers[base_register] =
                UINT32_C(0x0140) + (uint32_t)(base_register * 0x08u);
            before.ssp = before.address_registers[7];
            before.data_registers[0] = UINT32_C(0x10);
            before.sr = UINT16_C(0x271f);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_restore_state(cpu, &before));
            const uint32_t address = before.address_registers[base_register] +
                                     UINT32_C(0x10) - UINT32_C(4);
            const uint32_t value = UINT32_C(0x89abcdef);
            memory.rom[address] = (uint8_t)(value >> 24);
            memory.rom[address + 1u] = (uint8_t)(value >> 16);
            memory.rom[address + 2u] = (uint8_t)(value >> 8);
            memory.rom[address + 3u] = (uint8_t)value;
            const size_t reads_before = memory.reads;
            const owned_cpu_run_result result = owned_cpu_run(cpu, 18u);
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
            TEST_ASSERT_EQUAL_UINT64(18u, result.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
            TEST_ASSERT_EQUAL_UINT(4u, memory.reads - reads_before);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                                    memory.read_addresses[reads_before]);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102),
                                    memory.read_addresses[reads_before + 1u]);
            TEST_ASSERT_EQUAL_HEX32(address,
                                    memory.read_addresses[reads_before + 2u]);
            TEST_ASSERT_EQUAL_HEX32(address + 2u,
                                    memory.read_addresses[reads_before + 3u]);
            TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
            owned_cpu_observation after;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_observe(cpu, &after));
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x104), after.pc);
            TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x271f), after.sr);
            for (unsigned reg = 0u; reg < 8u; ++reg) {
                TEST_ASSERT_EQUAL_HEX32(
                    reg == destination_register ? value :
                    before.address_registers[reg], after.address_registers[reg]);
                TEST_ASSERT_EQUAL_HEX32(before.data_registers[reg],
                                        after.data_registers[reg]);
            }
            if (destination_register == 7u)
                TEST_ASSERT_EQUAL_HEX32(value, after.ssp);
            else
                TEST_ASSERT_EQUAL_HEX32(before.ssp, after.ssp);
            owned_cpu_destroy(cpu);
            cpu = NULL;
        }
    }
}

static void movea_long_address_index_sign_extends_and_selects_index_size(void) {
    static const struct {
        uint8_t base_register;
        uint8_t destination_register;
        uint8_t index_register;
        uint16_t index_flags;
        uint8_t displacement;
        uint32_t base_value;
        uint32_t index_value;
    } cases[] = {
        {0u, 3u, 0u, 0u, 0xfcu, UINT32_C(0x0140), UINT32_C(0x0000fff0)},
        {1u, 1u, 1u, UINT16_C(0x1800), 0x08u, UINT32_C(0x0160), UINT32_C(0x20)},
        {2u, 4u, 4u, UINT16_C(0xc000), 0x04u, UINT32_C(0x0180), UINT32_C(0x1234fff0)},
        {3u, 5u, 5u, UINT16_C(0xd800), 0xfcu, UINT32_C(0x01a0), UINT32_C(0x20)},
    };
    for (size_t index = 0u; index < sizeof(cases) / sizeof(cases[0]); ++index) {
        memset(&memory, 0, sizeof(memory));
        create_cpu();
        uint8_t program[4];
        size_t length = 0u;
        emit_word(program, &length,
                  (uint16_t)(UINT16_C(0x2070) |
                      (uint16_t)(cases[index].destination_register << 9) |
                      (uint16_t)cases[index].base_register));
        emit_word(program, &length,
                  (uint16_t)(cases[index].index_flags |
                             cases[index].displacement));
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, length));
        owned_cpu_state before;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
        before.address_registers[cases[index].base_register] = cases[index].base_value;
        if ((cases[index].index_flags & UINT16_C(0x8000)) != 0u)
            before.address_registers[cases[index].index_register] = cases[index].index_value;
        else
            before.data_registers[cases[index].index_register] = cases[index].index_value;
        before.sr = UINT16_C(0x271f);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));
        const uint32_t full_index = cases[index].index_value;
        const uint32_t selected_index =
            (cases[index].index_flags & UINT16_C(0x0800)) != 0u
                ? full_index
                : expected_sign_extend_word((uint16_t)full_index);
        const uint32_t address = cases[index].base_value + selected_index +
                                 (uint32_t)(int32_t)(int8_t)cases[index].displacement;
        const uint32_t value = UINT32_C(0x76543210) + (uint32_t)index;
        memory.rom[address] = (uint8_t)(value >> 24);
        memory.rom[address + 1u] = (uint8_t)(value >> 16);
        memory.rom[address + 2u] = (uint8_t)(value >> 8);
        memory.rom[address + 3u] = (uint8_t)value;
        const size_t reads_before = memory.reads;
        const owned_cpu_run_result result = owned_cpu_run(cpu, 18u);
        TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
        TEST_ASSERT_EQUAL_UINT64(18u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
        TEST_ASSERT_EQUAL_UINT(4u, memory.reads - reads_before);
        TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
        owned_cpu_observation after;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
        TEST_ASSERT_EQUAL_HEX32(value,
            after.address_registers[cases[index].destination_register]);
        TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x271f), after.sr);
        owned_cpu_destroy(cpu);
        cpu = NULL;
    }
}

