static void movea_long_address_index_neighbors_stay_unsupported(void) {
    static const uint8_t programs[][4] = {
        {0x36u, 0x70u, 0x00u, 0x00u}, /* MOVEA.W (d8,A0,Xn),A3 */
        {0x26u, 0x70u, 0x07u, 0x00u}, /* reserved/full-format extension bits */
    };
    for (size_t i = 0u; i < sizeof(programs) / sizeof(programs[0]); ++i) {
        memset(&memory, 0, sizeof(memory));
        create_cpu();
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          reset_with_program(programs[i], sizeof(programs[i])));
        const owned_cpu_run_result result = owned_cpu_run(cpu, 32u);
        TEST_ASSERT_EQUAL(OWNED_CPU_UNSUPPORTED_OPCODE, result.reason);
        TEST_ASSERT_EQUAL_UINT64(0u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(0u, result.instructions);
        TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
        owned_cpu_destroy(cpu);
        cpu = NULL;
    }
}

/* Guest-observed (05-02 task 2): MOVEA.L (An),An. UM Rev. 9.1 Table 8-3
 * p. 8-3 gives (An) long source to An 12(3/0); flags are unchanged. */
static void movea_long_address_indirect_loads_all_registers(void) {
    for (unsigned source_register = 0u; source_register < 8u; ++source_register) {
        for (unsigned destination_register = 0u; destination_register < 8u;
             ++destination_register) {
            memset(&memory, 0, sizeof(memory));
            create_cpu();
            const uint16_t opcode = (uint16_t)(UINT16_C(0x2050) |
                (uint16_t)(destination_register << 9) | (uint16_t)source_register);
            const uint8_t program[] = {
                (uint8_t)(opcode >> 8), (uint8_t)opcode};
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              reset_with_program(program, sizeof(program)));
            owned_cpu_state before;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_capture_state(cpu, &before));
            before.address_registers[source_register] =
                UINT32_C(0x0140) + (uint32_t)(source_register * 0x08u);
            before.ssp = before.address_registers[7];
            before.sr = UINT16_C(0x271f);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_restore_state(cpu, &before));
            const uint32_t address = before.address_registers[source_register];
            const uint32_t value = UINT32_C(0x89abcdef);
            memory.rom[address] = (uint8_t)(value >> 24);
            memory.rom[address + 1u] = (uint8_t)(value >> 16);
            memory.rom[address + 2u] = (uint8_t)(value >> 8);
            memory.rom[address + 3u] = (uint8_t)value;
            const size_t reads_before = memory.reads;
            const owned_cpu_run_result result = owned_cpu_run(cpu, 12u);
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
            TEST_ASSERT_EQUAL_UINT64(12u, result.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
            TEST_ASSERT_EQUAL_UINT(3u, memory.reads - reads_before);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                                    memory.read_addresses[reads_before]);
            TEST_ASSERT_EQUAL_HEX32(address,
                                    memory.read_addresses[reads_before + 1u]);
            TEST_ASSERT_EQUAL_HEX32(address + 2u,
                                    memory.read_addresses[reads_before + 2u]);
            TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
            owned_cpu_observation after;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_observe(cpu, &after));
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102), after.pc);
            TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x271f), after.sr);
            for (unsigned reg = 0u; reg < 8u; ++reg) {
                TEST_ASSERT_EQUAL_HEX32(
                    reg == destination_register ? value :
                    before.address_registers[reg], after.address_registers[reg]);
                TEST_ASSERT_EQUAL_HEX32(before.data_registers[reg],
                                        after.data_registers[reg]);
            }
            if (destination_register == 7u)
                TEST_ASSERT_EQUAL_HEX32(value, after.ssp);
            else
                TEST_ASSERT_EQUAL_HEX32(before.ssp, after.ssp);
            owned_cpu_destroy(cpu);
            cpu = NULL;
        }
    }
}

static void movea_long_address_indirect_odd_address_enters_vector_three(void) {
    create_cpu();
    const uint8_t program[] = {0x20u, 0x50u}; /* MOVEA.L (A0),A0 */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      reset_with_program(program, sizeof(program)));
    set_vector(12u, UINT32_C(0x140));
    owned_cpu_state before;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
    before.address_registers[0] = UINT32_C(0x141);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));
    const size_t reads_before = memory.reads;
    const owned_cpu_run_result result = owned_cpu_run(cpu, 50u);
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    owned_cpu_observation after;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
    TEST_ASSERT_EQUAL_UINT8(3u, after.last_exception_vector);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x140), after.pc);
    for (size_t i = reads_before; i < memory.reads && i < ROM_SIZE; ++i) {
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x141), memory.read_addresses[i]);
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x143), memory.read_addresses[i]);
    }
}

