/* Guest-observed (05-02 task 2): MOVEA.L (d16,An),An. Motorola PRM §2.2.5
 * defines signed displacement from the base register; §4 MOVEA, pp. 4-119–
 * 4-120 preserves condition codes. UM Rev. 9.1 Table 8-3 p. 8-3 gives
 * 16(4/0), including opcode/extension and two operand-word reads. */
static void movea_long_displacement_loads_every_base_and_destination(void) {
    for (unsigned source_register = 0u; source_register < 8u; ++source_register) {
        for (unsigned destination_register = 0u; destination_register < 8u;
             ++destination_register) {
            memset(&memory, 0, sizeof(memory));
            create_cpu();
            uint8_t program[4];
            size_t length = 0u;
            emit_word(program, &length,
                      (uint16_t)(UINT16_C(0x2068) |
                          (uint16_t)(destination_register << 9) |
                          (uint16_t)source_register));
            const int16_t displacement =
                ((source_register + destination_register) & 1u) == 0u
                    ? INT16_C(32) : INT16_C(-32);
            emit_word(program, &length, (uint16_t)displacement);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              reset_with_program(program, length));

            owned_cpu_state before;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_capture_state(cpu, &before));
            for (unsigned reg = 0u; reg < 8u; ++reg) {
                before.address_registers[reg] =
                    UINT32_C(0x500) + (uint32_t)(reg * 0x20u);
                before.data_registers[reg] =
                    UINT32_C(0x10203040) + (uint32_t)reg;
            }
            const uint32_t target = UINT32_C(0x180) +
                (uint32_t)(source_register * 8u + destination_register * 4u);
            before.address_registers[source_register] =
                target - (uint32_t)(int32_t)displacement;
            before.ssp = before.address_registers[7];
            before.sr = UINT16_C(0x271f);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_restore_state(cpu, &before));

            const uint32_t value = UINT32_C(0x80000000) |
                (uint32_t)(source_register << 24) |
                (uint32_t)(destination_register << 16) | UINT32_C(0x1234);
            memory.rom[target] = (uint8_t)(value >> 24);
            memory.rom[target + 1u] = (uint8_t)(value >> 16);
            memory.rom[target + 2u] = (uint8_t)(value >> 8);
            memory.rom[target + 3u] = (uint8_t)value;

            const size_t reads_before = memory.reads;
            const owned_cpu_run_result result = owned_cpu_run(cpu, 16u);
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
            TEST_ASSERT_EQUAL_UINT64(16u, result.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
            TEST_ASSERT_EQUAL_UINT(4u, memory.reads - reads_before);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                                    memory.read_addresses[reads_before]);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102),
                                    memory.read_addresses[reads_before + 1u]);
            TEST_ASSERT_EQUAL_HEX32(target,
                                    memory.read_addresses[reads_before + 2u]);
            TEST_ASSERT_EQUAL_HEX32(target + 2u,
                                    memory.read_addresses[reads_before + 3u]);
            TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);

            owned_cpu_observation after;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_observe(cpu, &after));
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x104), after.pc);
            TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x271f), after.sr);
            for (unsigned reg = 0u; reg < 8u; ++reg) {
                TEST_ASSERT_EQUAL_HEX32(
                    reg == destination_register ? value :
                    before.address_registers[reg], after.address_registers[reg]);
                TEST_ASSERT_EQUAL_HEX32(before.data_registers[reg],
                                        after.data_registers[reg]);
            }
            if (destination_register == 7u)
                TEST_ASSERT_EQUAL_HEX32(value, after.ssp);
            else
                TEST_ASSERT_EQUAL_HEX32(before.ssp, after.ssp);
            owned_cpu_destroy(cpu);
            cpu = NULL;
        }
    }
}

static void movea_long_displacement_odd_source_enters_vector_three_before_operand_read(void) {
    create_cpu();
    const uint8_t program[] = {
        0x22u, 0x68u, 0x00u, 0x01u}; /* MOVEA.L (1,A0),A1 */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    set_vector(12u, UINT32_C(0x140)); /* vector 3 table byte offset */
    owned_cpu_state before;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
    before.address_registers[0] = UINT32_C(0x180);
    before.address_registers[1] = UINT32_C(0x777);
    before.ssp = before.address_registers[7];
    before.sr = UINT16_C(0x271f);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));

    const size_t reads_before = memory.reads;
    const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(50));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(50u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(0u, result.instructions);
    owned_cpu_observation after;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
    TEST_ASSERT_EQUAL_UINT8(3u, after.last_exception_vector);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x140), after.pc);
    TEST_ASSERT_EQUAL_HEX32(before.address_registers[0],
                            after.address_registers[0]);
    TEST_ASSERT_EQUAL_HEX32(before.address_registers[1],
                            after.address_registers[1]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x271f), after.sr);
    for (size_t i = reads_before; i < memory.reads; ++i) {
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x181), memory.read_addresses[i]);
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x183), memory.read_addresses[i]);
    }
}

