static void movea_long_pc_index_loads_address_register_in_18_cycles(void) {
    create_cpu();
    const uint8_t program[] = {
        0x26, 0x7b, 0x18, 0x20,  /* MOVEA.L (32,PC,D1.L),A3 : extension word at $102 */
        0x26, 0x7b, 0xa0, 0xfc,  /* MOVEA.L (-4,PC,A2.W),A3 : extension word at $106 */
        0x26, 0x7b, 0x08, 0x21}; /* MOVEA.L (33,PC,D0.L),A3 : odd address */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    memcpy(memory.rom + 0x132, (const uint8_t[]){0xde, 0xad, 0xbe, 0xef}, 4u);
    memcpy(memory.rom + 0xf2, (const uint8_t[]){0x00, 0x11, 0x22, 0x33}, 4u);
    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.data_registers[1] = UINT32_C(0x00000010);
    state.address_registers[2] = UINT32_C(0x1234fff0); /* word index is -16 */
    state.address_registers[3] = UINT32_C(0x55555555);
    state.sr = UINT16_C(0x271f); /* every flag set: MOVEA must not touch them */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
    const size_t reads_before = memory.reads;
    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(18));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(18u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
    /* Opcode, extension word and a two-word operand read; no write. */
    TEST_ASSERT_EQUAL_UINT(4u, memory.reads - reads_before);
    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
    owned_cpu_observation observation;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x104), observation.pc);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0xdeadbeef), observation.address_registers[3]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x271f), observation.sr);

    result = owned_cpu_run(cpu, UINT64_C(18));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(18u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x00112233), observation.address_registers[3]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x1234fff0), observation.address_registers[2]);

    /* An odd effective address is a word-access address error. */
    set_vector(12u, UINT32_C(0x140));
    result = owned_cpu_run(cpu, UINT64_C(18));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_UINT8(3u, observation.last_exception_vector);
}

/* Unobserved neighbors of MOVEA.L (d8,PC,Xn),An must stay unsupported. */
static void movea_pc_index_neighbors_stay_unsupported(void) {
    static const struct {
        uint8_t program[4];
        const char *name;
    } neighbors[] = {
        {{0x36, 0x7b, 0x18, 0x20}, "MOVEA.W (d8,PC,Xn),A3"},
        {{0x26, 0x7a, 0x00, 0x20}, "MOVEA.L (d16,PC),A3"},
        {{0x26, 0x7b, 0x19, 0x20}, "MOVEA.L (bd,PC,Xn),A3 with extension bit 8 set"},
        {{0x26, 0x7b, 0x1a, 0x20}, "MOVEA.L (d8,PC,Xn*scale),A3 with scale bits set"},
    };
    for (size_t index = 0u; index < sizeof(neighbors) / sizeof(neighbors[0]); ++index) {
        memset(&memory, 0, sizeof(memory));
        create_cpu();
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(neighbors[index].program, 4u));
        owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(32));
        TEST_ASSERT_EQUAL_MESSAGE(OWNED_CPU_UNSUPPORTED_OPCODE, result.reason,
                                  neighbors[index].name);
        TEST_ASSERT_EQUAL_UINT_MESSAGE(0u, memory.write_attempts, neighbors[index].name);
        owned_cpu_destroy(cpu);
        cpu = NULL;
    }
}

/* MOVE.B (d8,PC,Xn),Dn (05-27 rerun 39). PRM section 2.2.12 p. 2-14:
 * PC is the extension-word address; the brief displacement and word index are
 * sign extended. PRM MOVE pp. 4-116 to 4-118 sets N/Z from the byte, clears
 * V/C, and preserves X. UM Rev. 9.1 Table 8-2 p. 8-2 gives 14(3/0). Bus
 * tally: opcode word, brief extension word, one byte read, no writes. */
static void move_byte_pc_indexed_to_data_register_loads_in_14_cycles(void) {
    static const struct {
        uint8_t displacement;
        int32_t index;
        uint8_t value;
        uint16_t flags;
    } cases[] = {
        {0x00u, -33, 0x80u, 0x0008u}, {0x20u, -65, 0x00u, 0x0004u},
        {0xe0u, -1, 0x01u, 0u}, {0x01u, -34, 0xffu, 0x0008u},
        {0x7fu, -160, 0x7fu, 0u},
    };
    for (unsigned data_reg = 0u; data_reg < 8u; ++data_reg) {
        for (unsigned index_reg = 0u; index_reg < 8u; ++index_reg) {
            for (unsigned index_kind = 0u; index_kind < 2u; ++index_kind) {
                for (unsigned index_size = 0u; index_size < 2u; ++index_size) {
                    for (unsigned x = 0u; x < 2u; ++x) {
                        for (size_t c = 0u; c < sizeof(cases) / sizeof(cases[0]); ++c) {
                            memset(&memory, 0, sizeof(memory));
                            create_cpu();
                            const uint32_t source_address = 0x00e1u;
                            const uint32_t index_value = index_size == 0u
                                ? (UINT32_C(0x12340000) | (uint16_t)cases[c].index)
                                : (uint32_t)cases[c].index;
                            const uint16_t extension = (uint16_t)(
                                (index_kind != 0u ? UINT16_C(0x8000) : 0u) |
                                (index_reg << 12) |
                                (index_size != 0u ? UINT16_C(0x0800) : 0u) |
                                cases[c].displacement);
                            uint8_t program[4];
                            size_t length = 0u;
                            emit_word(program, &length,
                                      (uint16_t)(UINT16_C(0x103b) | (data_reg << 9)));
                            emit_word(program, &length, extension);
                            TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, length));
                            memory.rom[source_address] = cases[c].value;
                            owned_cpu_state before;
                            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                              owned_cpu_capture_state(cpu, &before));
                            for (unsigned i = 0u; i < 8u; ++i) {
                                before.data_registers[i] = UINT32_C(0xaabbcc00) | i;
                                before.address_registers[i] = UINT32_C(0x11223000) | (i * 2u);
                            }
                            if (index_kind == 0u) before.data_registers[index_reg] = index_value;
                            else before.address_registers[index_reg] = index_value;
                            before.sr = (uint16_t)(0x270fu | (x << 4));
                            before.ssp = before.address_registers[7];
                            const uint32_t expected_destination =
                                (before.data_registers[data_reg] & UINT32_C(0xffffff00)) |
                                cases[c].value;
                            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                              owned_cpu_restore_state(cpu, &before));
                            const size_t reads_before = memory.reads;
                            owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(14));
                            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
                            TEST_ASSERT_EQUAL_UINT64(14u, result.elapsed_cycles);
                            TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
                            TEST_ASSERT_EQUAL_UINT(2u, memory.reads - reads_before);
                            TEST_ASSERT_EQUAL_UINT(1u, memory.byte_reads);
                            TEST_ASSERT_EQUAL_HEX32(source_address,
                                                    memory.byte_read_addresses[0]);
                            TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
                            TEST_ASSERT_EQUAL_HEX8(cases[c].value, memory.rom[source_address]);
                            owned_cpu_observation observation;
                            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                              owned_cpu_observe(cpu, &observation));
                            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x104), observation.pc);
                            TEST_ASSERT_EQUAL_HEX16(
                                (uint16_t)(0x2700u | (x << 4) | cases[c].flags),
                                observation.sr);
                            for (unsigned i = 0u; i < 8u; ++i) {
                                const uint32_t expected = i == data_reg
                                    ? expected_destination : before.data_registers[i];
                                TEST_ASSERT_EQUAL_HEX32(expected, observation.data_registers[i]);
                                TEST_ASSERT_EQUAL_HEX32(before.address_registers[i],
                                                        observation.address_registers[i]);
                            }
                            owned_cpu_destroy(cpu);
                            cpu = NULL;
                        }
                    }
                }
            }
        }
    }
}

static void move_byte_pc_indexed_neighbors_stay_unsupported(void) {
    static const struct { uint8_t program[4]; const char *name; } neighbors[] = {
        {{0x10u, 0x3bu, 0x01u, 0u}, "MOVE.B full-format (bd,PC,Xn),D0"},
        {{0x10u, 0x3bu, 0x02u, 0u}, "MOVE.B scaled (d8,PC,Xn),D0"},
    };
    for (size_t i = 0u; i < sizeof(neighbors) / sizeof(neighbors[0]); ++i) {
        memset(&memory, 0, sizeof(memory));
        create_cpu();
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(neighbors[i].program, 4u));
        owned_cpu_observation before, after;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &before));
        owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(32));
        TEST_ASSERT_EQUAL_MESSAGE(OWNED_CPU_UNSUPPORTED_OPCODE, result.reason,
                                  neighbors[i].name);
        TEST_ASSERT_EQUAL_UINT64(0u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(0u, result.instructions);
        TEST_ASSERT_EQUAL_UINT(0u, memory.byte_reads);
        TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
        TEST_ASSERT_EQUAL_HEX32(before.pc, after.pc);
        TEST_ASSERT_EQUAL_HEX16(before.sr, after.sr);
        for (unsigned r = 0u; r < 8u; ++r) {
            TEST_ASSERT_EQUAL_HEX32(before.data_registers[r], after.data_registers[r]);
            TEST_ASSERT_EQUAL_HEX32(before.address_registers[r], after.address_registers[r]);
        }
        owned_cpu_destroy(cpu);
        cpu = NULL;
    }
}

/* MOVE.B (d8,An,Xn),Dn is guest-observed; timing from UM Rev. 9.1
 * Table 8-2 p. 8-2 is 14(3/0). */
static void move_byte_address_index_to_data_register_loads_in_14_cycles(void) {
    static const struct {
        uint8_t displacement;
        uint32_t word_index;
        uint32_t long_index;
        uint8_t value;
        uint16_t flags;
    } cases[] = {
        {0x80u, UINT32_C(0x1234ff80), UINT32_C(0xfffffff0), 0x80u, 0x0008u},
        {0xffu, UINT32_C(0x5678ffff), UINT32_C(0x00000002), 0x00u, 0x0004u},
        {0x01u, UINT32_C(0x9abc7fff), UINT32_C(0x00007fff), 0x7fu, 0x0000u},
        {0x7fu, UINT32_C(0xdefe8000), UINT32_C(0xffff8000), 0xffu, 0x0008u},
    };
    for (unsigned source_base = 0u; source_base < 8u; ++source_base) {
        for (unsigned destination_reg = 0u; destination_reg < 8u;
             ++destination_reg) {
            for (unsigned index_kind = 0u; index_kind < 2u; ++index_kind) {
                for (unsigned index_size = 0u; index_size < 2u; ++index_size) {
                    const size_t case_index =
                        (source_base + destination_reg + index_kind + index_size) %
                        (sizeof(cases) / sizeof(cases[0]));
                    const unsigned index_reg =
                        ((source_base + destination_reg + 1u) & 7u) == source_base
                            ? (source_base + destination_reg + 2u) & 7u
                            : (source_base + destination_reg + 1u) & 7u;
                    const uint32_t index_full = index_size != 0u
                        ? cases[case_index].long_index
                        : cases[case_index].word_index;
                    const uint32_t index_value = index_size != 0u
                        ? index_full
                        : expected_sign_extend_word((uint16_t)index_full);
                    const uint32_t source_address = UINT32_C(0x00e1);
                    const uint16_t extension = (uint16_t)(
                        (index_kind != 0u ? UINT16_C(0x8000) : 0u) |
                        (uint16_t)(index_reg << 12) |
                        (index_size != 0u ? UINT16_C(0x0800) : 0u) |
                        cases[case_index].displacement);
                    uint8_t program[4];
                    size_t length = 0u;
                    emit_word(program, &length,
                              (uint16_t)(UINT16_C(0x1030) |
                                         (uint16_t)(destination_reg << 9) |
                                         (uint16_t)source_base));
                    emit_word(program, &length, extension);
                    memset(&memory, 0, sizeof(memory));
                    create_cpu();
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      reset_with_program(program, length));
                    owned_cpu_state before;
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      owned_cpu_capture_state(cpu, &before));
                    for (unsigned reg = 0u; reg < 8u; ++reg) {
                        before.data_registers[reg] =
                            UINT32_C(0xaabbcc00) | reg;
                        before.address_registers[reg] =
                            UINT32_C(0x11223000) + reg * UINT32_C(2);
                    }
                    if (index_kind == 0u)
                        before.data_registers[index_reg] = index_full;
                    else
                        before.address_registers[index_reg] = index_full;
                    before.address_registers[source_base] =
                        source_address -
                        (uint32_t)(int32_t)(int8_t)cases[case_index].displacement -
                        index_value;
                    before.ssp = before.address_registers[7];
                    const uint16_t x = (uint16_t)((case_index & 1u) != 0u
                        ? UINT16_C(0x0010) : 0u);
                    before.sr = (uint16_t)(UINT16_C(0x270f) | x);
                    const uint32_t expected_destination =
                        (before.data_registers[destination_reg] &
                         UINT32_C(0xffffff00)) | cases[case_index].value;
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      owned_cpu_restore_state(cpu, &before));
                    memory.rom[source_address] = cases[case_index].value;
                    const size_t reads_before = memory.reads;
                    const owned_cpu_run_result result =
                        owned_cpu_run(cpu, UINT64_C(14));
                    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
                    TEST_ASSERT_EQUAL_UINT64(14u, result.elapsed_cycles);
                    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
                    TEST_ASSERT_EQUAL_UINT(2u, memory.reads - reads_before);
                    TEST_ASSERT_EQUAL_UINT(1u, memory.byte_reads);
                    TEST_ASSERT_EQUAL_HEX32(source_address,
                                            memory.byte_read_addresses[0]);
                    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
                    owned_cpu_observation after;
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      owned_cpu_observe(cpu, &after));
                    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x104), after.pc);
                    TEST_ASSERT_EQUAL_HEX16(
                        (uint16_t)(UINT16_C(0x2700) | x |
                                   cases[case_index].flags),
                        after.sr);
                    for (unsigned reg = 0u; reg < 8u; ++reg) {
                        const uint32_t expected = reg == destination_reg
                            ? expected_destination : before.data_registers[reg];
                        TEST_ASSERT_EQUAL_HEX32(expected,
                                                after.data_registers[reg]);
                        TEST_ASSERT_EQUAL_HEX32(before.address_registers[reg],
                                                after.address_registers[reg]);
                    }
                    owned_cpu_destroy(cpu);
                    cpu = NULL;
                }
            }
        }
    }
}

static void move_byte_address_index_rejects_nonbrief_extensions(void) {
    static const uint16_t extensions[] = {UINT16_C(0x0100), UINT16_C(0x0400)};
    for (size_t index = 0u;
         index < sizeof(extensions) / sizeof(extensions[0]); ++index) {
        memset(&memory, 0, sizeof(memory));
        create_cpu();
        uint8_t program[4];
        size_t length = 0u;
        emit_word(program, &length, UINT16_C(0x1030));
        emit_word(program, &length, extensions[index]);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          reset_with_program(program, length));
        const owned_cpu_run_result result =
            owned_cpu_run(cpu, UINT64_C(14));
        TEST_ASSERT_EQUAL(OWNED_CPU_UNSUPPORTED_OPCODE, result.reason);
        TEST_ASSERT_EQUAL_UINT64(0u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(0u, result.instructions);
        TEST_ASSERT_EQUAL_UINT(0u, memory.byte_reads);
        TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
        owned_cpu_destroy(cpu);
        cpu = NULL;
    }
}

static void move_byte_address_index_neighbors_stay_unsupported(void) {
    static const struct { uint8_t program[4]; const char *name; } neighbors[] = {
        {{0x15u, 0xf0u, 0u, 0u}, "MOVE.B (d8,A0,Xn),(d16,PC)"},
    };
    for (size_t i = 0u; i < sizeof(neighbors) / sizeof(neighbors[0]); ++i) {
        memset(&memory, 0, sizeof(memory));
        create_cpu();
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          reset_with_program(neighbors[i].program, 4u));
        owned_cpu_observation before, after;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &before));
        const owned_cpu_run_result result =
            owned_cpu_run(cpu, UINT64_C(32));
        TEST_ASSERT_EQUAL_MESSAGE(OWNED_CPU_UNSUPPORTED_OPCODE, result.reason,
                                  neighbors[i].name);
        TEST_ASSERT_EQUAL_UINT64(0u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(0u, result.instructions);
        TEST_ASSERT_EQUAL_UINT(0u, memory.byte_reads);
        TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
        TEST_ASSERT_EQUAL_HEX32(before.pc, after.pc);
        TEST_ASSERT_EQUAL_HEX16(before.sr, after.sr);
        for (unsigned reg = 0u; reg < 8u; ++reg) {
            TEST_ASSERT_EQUAL_HEX32(before.data_registers[reg],
                                    after.data_registers[reg]);
            TEST_ASSERT_EQUAL_HEX32(before.address_registers[reg],
                                    after.address_registers[reg]);
        }
        owned_cpu_destroy(cpu);
        cpu = NULL;
    }
}

/* Guest-observed encoding (05-11): JSR (An). */
static void jsr_address_register_indirect_pushes_return_pc_in_16_cycles(void) {
    create_cpu();
    const uint8_t program[] = {0x4e, 0x93, 0x4e, 0x71}; /* JSR (A3); NOP */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.address_registers[3] = UINT32_C(0x120);
    state.sr = UINT16_C(0x271f);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
    const size_t reads_before = memory.reads;
    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(16));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(16u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
    TEST_ASSERT_EQUAL_UINT(1u, memory.reads - reads_before);
    TEST_ASSERT_EQUAL_UINT(2u, memory.write_attempts);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x1ffc), memory.write_addresses[0]);
    TEST_ASSERT_EQUAL_HEX16(0u, memory.write_values[0]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x1ffe), memory.write_addresses[1]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x0102), memory.write_values[1]);
    owned_cpu_observation observation;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x120), observation.pc);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x1ffc), observation.address_registers[7]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x120), observation.address_registers[3]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x271f), observation.sr);
}

/* JSR accepts only control EAs: auto-update, register-direct and immediate
 * forms remain outside its MC68000 destination set. */
static void jsr_address_register_indirect_neighbors_stay_unsupported(void) {
    static const struct {
        uint8_t program[4];
        const char *name;
    } neighbors[] = {
        {{0x4e, 0x98, 0x00, 0x00}, "JSR (A0)+"},
        {{0x4e, 0xa0, 0x00, 0x00}, "JSR -(A0)"},
        {{(uint8_t)(JSR_EA(0u, 0u) >> 8), (uint8_t)JSR_EA(0u, 0u), 0x00, 0x00},
         "JSR D0 (illegal mode)"},
        {{(uint8_t)(JSR_EA(1u, 0u) >> 8), (uint8_t)JSR_EA(1u, 0u), 0x00, 0x00},
         "JSR A0 direct (illegal mode)"},
        {{(uint8_t)(JSR_EA(7u, 4u) >> 8), (uint8_t)JSR_EA(7u, 4u), 0x00, 0x00},
         "JSR immediate (illegal mode)"},
        {{(uint8_t)(JSR_EA(6u, 0u) >> 8), (uint8_t)JSR_EA(6u, 0u), 0x07, 0x00},
         "JSR full-format indexed (unsupported subset)"},
    };
    for (size_t index = 0u; index < sizeof(neighbors) / sizeof(neighbors[0]); ++index) {
        memset(&memory, 0, sizeof(memory));
        create_cpu();
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(neighbors[index].program, 4u));
        owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(32));
        TEST_ASSERT_EQUAL_MESSAGE(OWNED_CPU_UNSUPPORTED_OPCODE, result.reason,
                                  neighbors[index].name);
        TEST_ASSERT_EQUAL_UINT_MESSAGE(0u, memory.write_attempts, neighbors[index].name);
        owned_cpu_destroy(cpu);
        cpu = NULL;
    }
}
#undef JSR_EA

/* Guest-observed encoding (05-11): MOVE.W (An)+,Dn. */
static void move_word_postincrement_to_data_register_uses_8_cycles(void) {
    create_cpu();
    const uint8_t program[] = {
        0x3c, 0x19,  /* MOVE.W (A1)+,D6 */
        0x3c, 0x19,  /* MOVE.W (A1)+,D6 */
        0x3c, 0x19}; /* MOVE.W (A1)+,D6: odd address */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    memcpy(memory.rom + 0x1e0, (const uint8_t[]){0x80, 0x01, 0x00, 0x00}, 4u);
    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.address_registers[1] = UINT32_C(0x1e0);
    state.data_registers[6] = UINT32_C(0xaabbccdd);
    state.sr = UINT16_C(0x271f); /* X N Z V C all set beforehand */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
    const size_t reads_before = memory.reads;
    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(8));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(8u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
    TEST_ASSERT_EQUAL_UINT(2u, memory.reads - reads_before);
    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
    owned_cpu_observation observation;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0xaabb8001), observation.data_registers[6]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x1e2), observation.address_registers[1]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2718), observation.sr); /* N set; Z V C clear; X kept */

    result = owned_cpu_run(cpu, UINT64_C(8));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0xaabb0000), observation.data_registers[6]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x1e4), observation.address_registers[1]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2714), observation.sr); /* Z set; X kept */

    /* The pinned MAME differential increments the EA before vector 3. */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.address_registers[1] = UINT32_C(0x1e1);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
    set_vector(12u, UINT32_C(0x140));
    const size_t odd_calls_before = memory.read_calls;
    result = owned_cpu_run(cpu, UINT64_C(8));
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_UINT8(3u, observation.last_exception_vector);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x1e3), observation.address_registers[1]);
    for (size_t call = odd_calls_before;
         call < memory.read_calls && call < ROM_SIZE; ++call)
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x1e1),
                              memory.read_call_addresses[call]);
}

static void move_word_postincrement_host_read_failure_keeps_state_and_fault_context(void) {
    setUp();
    create_cpu();
    const uint8_t program[] = {0x3cu, 0x19u}; /* MOVE.W (A1)+,D6 */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      reset_with_program(program, sizeof(program)));
    owned_cpu_state before;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_capture_state(cpu, &before));
    before.address_registers[1] = UINT32_C(0x180);
    before.data_registers[6] = UINT32_C(0xaabb7654);
    before.sr = UINT16_C(0x2715);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_restore_state(cpu, &before));
    const size_t reads_before = memory.reads;
    memory.fail_read_on = reads_before + 2u; /* opcode then failed operand */

    const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(8));
    TEST_ASSERT_EQUAL(OWNED_CPU_HOST_FAULT, result.reason);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100), result.fault_pc);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x3c19), result.instruction_register);
    TEST_ASSERT_EQUAL_UINT(reads_before + 2u, memory.reads);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x180),
                            memory.read_addresses[reads_before + 1u]);
    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);

    owned_cpu_state faulted;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
        owned_cpu_test_capture_faulted_state(cpu, &faulted));
    TEST_ASSERT_EQUAL_HEX32(before.address_registers[1],
                            faulted.address_registers[1]);
    TEST_ASSERT_EQUAL_HEX32(before.data_registers[6],
                            faulted.data_registers[6]);
    TEST_ASSERT_EQUAL_HEX16(before.sr, faulted.sr);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100), faulted.fault_pc);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x3c19), faulted.instruction_register);
    tearDown();
}

/* Bounded selected continuation: the shared MOVE.W readable-memory source
 * family includes the documented predecrement source. */
static void move_word_predecrement_to_data_register_covers_all_pairs(void) {
    static const uint16_t values[] = {
        UINT16_C(0x8001), UINT16_C(0x0000), UINT16_C(0x7fff),
        UINT16_C(0x1234)};
    static const uint16_t status_seeds[] = {
        UINT16_C(0x271f), UINT16_C(0x2700)};
    for (unsigned source_register = 0u; source_register < 8u;
         ++source_register) {
        for (unsigned destination_register = 0u; destination_register < 8u;
             ++destination_register) {
            for (size_t value_index = 0u;
                 value_index < sizeof(values) / sizeof(values[0]);
                 ++value_index) {
                for (size_t seed_index = 0u;
                     seed_index < sizeof(status_seeds) / sizeof(status_seeds[0]);
                     ++seed_index) {
                    memset(&memory, 0, sizeof(memory));
                    create_cpu();
                    uint8_t program[2];
                    size_t length = 0u;
                    const uint16_t opcode = (uint16_t)(
                        UINT16_C(0x3020) | (destination_register << 9) |
                        source_register);
                    emit_word(program, &length, opcode);
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      reset_with_program(program, length));

                    owned_cpu_state before;
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      owned_cpu_capture_state(cpu, &before));
                    const uint32_t base_address = UINT32_C(0x160) +
                        (uint32_t)source_register * UINT32_C(0x10);
                    for (unsigned reg = 0u; reg < 8u; ++reg)
                        before.data_registers[reg] =
                            UINT32_C(0xa5a50000) | (uint32_t)reg;
                    before.data_registers[destination_register] =
                        (before.data_registers[destination_register] &
                         UINT32_C(0xffff0000)) | UINT32_C(0x55aa);
                    before.address_registers[source_register] = base_address;
                    if (source_register == 7u) before.ssp = base_address;
                    before.sr = status_seeds[seed_index];
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      owned_cpu_restore_state(cpu, &before));
                    const uint32_t source_address = base_address - UINT32_C(2);
                    TEST_ASSERT_TRUE(source_address <=
                                     sizeof(memory.rom) - sizeof(uint16_t));
                    memory.rom[source_address] =
                        (uint8_t)(values[value_index] >> 8);
                    memory.rom[source_address + 1u] =
                        (uint8_t)values[value_index];

                    const size_t reads_before = memory.reads;
                    const size_t writes_before = memory.write_attempts;
                    const owned_cpu_run_result result =
                        owned_cpu_run(cpu, UINT64_C(10));
                    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
                    TEST_ASSERT_EQUAL_UINT64(10u, result.elapsed_cycles);
                    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
                    TEST_ASSERT_EQUAL_UINT(2u, memory.reads - reads_before);
                    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                                            memory.read_addresses[reads_before]);
                    TEST_ASSERT_EQUAL_HEX32(source_address,
                                            memory.read_addresses[reads_before + 1u]);
                    TEST_ASSERT_EQUAL_UINT(writes_before,
                                           memory.write_attempts);

                    owned_cpu_state after;
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      owned_cpu_capture_state(cpu, &after));
                    for (unsigned reg = 0u; reg < 8u; ++reg) {
                        const uint32_t expected_data = reg == destination_register
                            ? (before.data_registers[reg] & UINT32_C(0xffff0000)) |
                                values[value_index]
                            : before.data_registers[reg];
                        TEST_ASSERT_EQUAL_HEX32(expected_data,
                                                after.data_registers[reg]);
                        const uint32_t expected_address = reg == source_register
                            ? base_address - UINT32_C(2)
                            : before.address_registers[reg];
                        TEST_ASSERT_EQUAL_HEX32(expected_address,
                                                after.address_registers[reg]);
                    }
                    uint16_t expected_sr = (uint16_t)(
                        status_seeds[seed_index] & UINT16_C(0x2710));
                    if (values[value_index] == 0u)
                        expected_sr |= UINT16_C(0x0004);
                    if ((values[value_index] & UINT16_C(0x8000)) != 0u)
                        expected_sr |= UINT16_C(0x0008);
                    TEST_ASSERT_EQUAL_HEX16(expected_sr, after.sr);
                    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102), after.pc);
                    if (source_register == 7u) {
                        TEST_ASSERT_EQUAL_HEX32(base_address - UINT32_C(2),
                                                after.ssp);
                        TEST_ASSERT_EQUAL_HEX32(before.usp, after.usp);
                    }
                    owned_cpu_destroy(cpu);
                    cpu = NULL;
                }
            }
        }
    }
}

static void move_word_pc_relative_sources_to_data_register_use_table_timings(void) {
    for (unsigned destination_register = 0u; destination_register < 8u;
         ++destination_register) {
        for (unsigned indexed = 0u; indexed < 2u; ++indexed) {
            memset(&memory, 0, sizeof(memory));
            create_cpu();
            uint8_t program[4];
            size_t length = 0u;
            const uint16_t opcode = (uint16_t)(
                (indexed != 0u ? UINT16_C(0x303b) : UINT16_C(0x303a)) |
                (destination_register << 9));
            const uint16_t extension = indexed != 0u
                ? UINT16_C(0xa05e) : UINT16_C(0x007e);
            emit_word(program, &length, opcode);
            emit_word(program, &length, extension);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              reset_with_program(program, length));
            owned_cpu_state before;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_capture_state(cpu, &before));
            for (unsigned reg = 0u; reg < 8u; ++reg)
                before.data_registers[reg] = UINT32_C(0xa5a50000) | reg;
            before.data_registers[destination_register] =
                (before.data_registers[destination_register] &
                 UINT32_C(0xffff0000)) | UINT32_C(0x55aa);
            before.address_registers[2] = UINT32_C(0x20);
            before.ssp = before.address_registers[7];
            before.sr = UINT16_C(0x271f);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_restore_state(cpu, &before));
            const uint32_t source_address = UINT32_C(0x180);
            memory.rom[source_address] = UINT8_C(0x80);
            memory.rom[source_address + 1u] = UINT8_C(0x01);

            const size_t reads_before = memory.reads;
            const size_t writes_before = memory.write_attempts;
            const uint64_t expected_cycles = indexed != 0u ? UINT64_C(14)
                                                            : UINT64_C(12);
            const owned_cpu_run_result result =
                owned_cpu_run(cpu, expected_cycles);
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
            TEST_ASSERT_EQUAL_UINT64(expected_cycles, result.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
            TEST_ASSERT_EQUAL_UINT(3u, memory.reads - reads_before);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                                    memory.read_addresses[reads_before]);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102),
                                    memory.read_addresses[reads_before + 1u]);
            TEST_ASSERT_EQUAL_HEX32(source_address,
                                    memory.read_addresses[reads_before + 2u]);
            TEST_ASSERT_EQUAL_UINT(writes_before, memory.write_attempts);

            owned_cpu_state after;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_capture_state(cpu, &after));
            for (unsigned reg = 0u; reg < 8u; ++reg) {
                const uint32_t expected = reg == destination_register
                    ? (before.data_registers[reg] & UINT32_C(0xffff0000)) |
                        UINT32_C(0x8001)
                    : before.data_registers[reg];
                TEST_ASSERT_EQUAL_HEX32(expected, after.data_registers[reg]);
                TEST_ASSERT_EQUAL_HEX32(before.address_registers[reg],
                                        after.address_registers[reg]);
            }
            TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2718), after.sr);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x104), after.pc);
            TEST_ASSERT_EQUAL_HEX32(before.ssp, after.ssp);
            owned_cpu_destroy(cpu);
            cpu = NULL;
        }
    }
}

