static void move_word_predecrement_faults_and_counter_preflight_keep_boundaries(void) {
    setUp();
    create_cpu();
    const uint8_t odd_program[] = {0x30u, 0x20u}; /* MOVE.W -(A0),D0 */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      reset_with_program(odd_program, sizeof(odd_program)));
    set_vector(12u, UINT32_C(0x140));
    owned_cpu_state before;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_capture_state(cpu, &before));
    before.address_registers[0] = UINT32_C(0x181);
    before.data_registers[0] = UINT32_C(0xfacebeef);
    before.sr = UINT16_C(0x2715);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_restore_state(cpu, &before));
    const size_t odd_reads_before = memory.reads;
    const owned_cpu_run_result odd = owned_cpu_run(cpu, UINT64_C(50));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, odd.reason);
    TEST_ASSERT_EQUAL_UINT64(0u, odd.instructions);
    owned_cpu_observation odd_after;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_observe(cpu, &odd_after));
    TEST_ASSERT_EQUAL_UINT8(3u, odd_after.last_exception_vector);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x140), odd_after.pc);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x17f), odd_after.address_registers[0]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0xfacebeef), odd_after.data_registers[0]);
    for (size_t read = odd_reads_before;
         read < memory.reads && read < ROM_SIZE; ++read)
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x17f), memory.read_addresses[read]);
    tearDown();

    setUp();
    create_cpu();
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      reset_with_program(odd_program, sizeof(odd_program)));
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_capture_state(cpu, &before));
    before.address_registers[0] = UINT32_C(0x182);
    before.data_registers[0] = UINT32_C(0xfacebeef);
    before.sr = UINT16_C(0x2715);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_restore_state(cpu, &before));
    memory.fail_read_on = memory.reads + 2u; /* opcode then failed operand */
    const owned_cpu_run_result host = owned_cpu_run(cpu, UINT64_C(10));
    TEST_ASSERT_EQUAL(OWNED_CPU_HOST_FAULT, host.reason);
    owned_cpu_state faulted;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
        owned_cpu_test_capture_faulted_state(cpu, &faulted));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x180), faulted.address_registers[0]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0xfacebeef), faulted.data_registers[0]);
    TEST_ASSERT_EQUAL_HEX16(before.sr, faulted.sr);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100), faulted.fault_pc);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x3020), faulted.instruction_register);
    tearDown();

    setUp();
    create_cpu();
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      reset_with_program(odd_program, sizeof(odd_program)));
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_capture_state(cpu, &before));
    before.address_registers[0] = UINT32_C(0x182);
    before.data_registers[0] = UINT32_C(0xfacebeef);
    before.sr = UINT16_C(0x2715);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_restore_state(cpu, &before));
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_test_seed_counters(
        cpu, 0u, 0u, 0u, 0u, UINT64_MAX - UINT64_C(1)));
    const size_t counter_reads_before = memory.reads;
    const owned_cpu_run_result overflow = owned_cpu_run(cpu, UINT64_C(10));
    TEST_ASSERT_EQUAL(OWNED_CPU_COUNTER_OVERFLOW, overflow.reason);
    TEST_ASSERT_EQUAL_UINT64(0u, overflow.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(0u, overflow.instructions);
    TEST_ASSERT_EQUAL_UINT(counter_reads_before + 1u, memory.reads);
    owned_cpu_observation counter_after;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_observe(cpu, &counter_after));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100), counter_after.pc);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x182),
                            counter_after.address_registers[0]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0xfacebeef),
                            counter_after.data_registers[0]);
    TEST_ASSERT_EQUAL_HEX16(before.sr, counter_after.sr);
    tearDown();
}

