/* Guest-observed encoding (05-02 task 2): MOVEA.L #<data>,An. Motorola PRM
 * §4 MOVEA, pp. 4-119–4-120: all 32 source bits load An and flags are
 * unchanged. UM Rev. 9.1 Table 8-3, p. 8-3: immediate long takes 12 clocks. */
static void movea_long_immediate_to_all_address_registers_uses_12_cycles(void) {
    static const uint32_t values[8] = {
        UINT32_C(0x00000000), UINT32_C(0xffffffff),
        UINT32_C(0x80000000), UINT32_C(0x7fffffff),
        UINT32_C(0x12345678), UINT32_C(0x89abcdef),
        UINT32_C(0x0000ffff), UINT32_C(0xfedcba98)};
    uint8_t program[8u * 6u];
    for (unsigned reg = 0u; reg < 8u; ++reg) {
        const size_t offset = (size_t)reg * 6u;
        const uint16_t opcode = (uint16_t)(UINT16_C(0x207c) | (reg << 9));
        program[offset] = (uint8_t)(opcode >> 8);
        program[offset + 1u] = (uint8_t)opcode;
        program[offset + 2u] = (uint8_t)(values[reg] >> 24);
        program[offset + 3u] = (uint8_t)(values[reg] >> 16);
        program[offset + 4u] = (uint8_t)(values[reg] >> 8);
        program[offset + 5u] = (uint8_t)values[reg];
    }

    create_cpu();
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.data_registers[0] = UINT32_C(0x13579bdf);
    state.sr = UINT16_C(0x271f); /* MOVEA preserves all condition codes. */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));

    for (unsigned reg = 0u; reg < 8u; ++reg) {
        const size_t reads_before = memory.reads;
        owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(12));
        TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
        TEST_ASSERT_EQUAL_UINT_MESSAGE(1u, result.instructions,
                                       "each MOVEA.L immediate is one instruction");
        TEST_ASSERT_EQUAL_UINT64(12u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT(3u, memory.reads - reads_before);
        TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
        owned_cpu_observation observation;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
        TEST_ASSERT_EQUAL_HEX32(values[reg], observation.address_registers[reg]);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x13579bdf), observation.data_registers[0]);
        TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x271f), observation.sr);
    }
}

/* MOVEA.W #imm,An sign-extends one immediate word to all of An and leaves
 * every condition code unchanged (PRM §4 MOVEA pp. 4-119–4-120; UM Rev. 9.1
 * Table 8-3 p. 8-3: 8(2/0)). */
static void movea_word_immediate_sign_extends_for_all_address_registers(void) {
    static const uint16_t immediates[8] = {
        UINT16_C(0x0000), UINT16_C(0x7fff),
        UINT16_C(0x8000), UINT16_C(0xffff),
        UINT16_C(0x8001), UINT16_C(0x1234),
        UINT16_C(0x7f00), UINT16_C(0xff00)};
    uint8_t program[8u * 4u];
    for (unsigned reg = 0u; reg < 8u; ++reg) {
        const size_t offset = (size_t)reg * 4u;
        const uint16_t opcode =
            (uint16_t)(UINT16_C(0x307c) | (reg << 9));
        program[offset] = (uint8_t)(opcode >> 8);
        program[offset + 1u] = (uint8_t)opcode;
        program[offset + 2u] = (uint8_t)(immediates[reg] >> 8);
        program[offset + 3u] = (uint8_t)immediates[reg];
    }

    create_cpu();
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      reset_with_program(program, sizeof(program)));
    owned_cpu_state before;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_capture_state(cpu, &before));
    before.sr = UINT16_C(0x271f);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_restore_state(cpu, &before));
    uint32_t expected_address_registers[8];
    memcpy(expected_address_registers, before.address_registers,
           sizeof(expected_address_registers));

    for (unsigned reg = 0u; reg < 8u; ++reg) {
        const size_t reads_before = memory.reads;
        const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(8));
        TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
        TEST_ASSERT_EQUAL_UINT64(8u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
        TEST_ASSERT_EQUAL_UINT(reads_before + 2u, memory.reads);
        TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);

        const int32_t signed_value = (immediates[reg] & UINT16_C(0x8000)) != 0u
            ? (int32_t)immediates[reg] - INT32_C(0x10000)
            : (int32_t)immediates[reg];
        expected_address_registers[reg] = (uint32_t)signed_value;
        owned_cpu_observation after;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          owned_cpu_observe(cpu, &after));
        for (unsigned address_register = 0u; address_register < 8u;
             ++address_register)
            TEST_ASSERT_EQUAL_HEX32(
                expected_address_registers[address_register],
                after.address_registers[address_register]);
        TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x271f), after.sr);
        if (reg == 7u)
            TEST_ASSERT_EQUAL_HEX32(expected_address_registers[7],
                                    after.ssp);
    }
}

static void movea_word_immediate_counter_preflight_follows_extension_fetch(void) {
    const uint8_t program[] = {
        0x36u, 0x7cu, 0x80u, 0x01u}; /* MOVEA.W #$8001,A3 */
    create_cpu();
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      reset_with_program(program, sizeof(program)));
    owned_cpu_state before;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_capture_state(cpu, &before));
    before.address_registers[3] = UINT32_C(0x12345678);
    before.sr = UINT16_C(0x271f);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_restore_state(cpu, &before));
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_test_seed_counters(
        cpu, 0u, 0u, 0u, 0u, UINT64_MAX - UINT64_C(1)));

    const size_t reads_before = memory.reads;
    const owned_cpu_run_result result =
        owned_cpu_run(cpu, UINT64_C(20));
    TEST_ASSERT_EQUAL(OWNED_CPU_COUNTER_OVERFLOW, result.reason);
    TEST_ASSERT_EQUAL_UINT64(0u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(0u, result.instructions);
    TEST_ASSERT_EQUAL_UINT(reads_before + 2u, memory.reads);
    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
    owned_cpu_observation after;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_observe(cpu, &after));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0100), after.pc);
    TEST_ASSERT_EQUAL_HEX32(before.address_registers[3],
                            after.address_registers[3]);
    TEST_ASSERT_EQUAL_HEX16(before.sr, after.sr);
    TEST_ASSERT_EQUAL_UINT64(UINT64_MAX - UINT64_C(1), after.total_cycles);
}

