/* ORI.L to Dn and the separate full-SR form remain unimplemented. */
static void ori_byte_immediate_neighbors_stay_unsupported(void) {
    static const struct {
        uint8_t program[4];
        const char *name;
    } neighbors[] = {
        {{0x00, 0x80, 0x00, 0x01}, "ORI.L #imm,D0"},
        {{0x00, 0x7c, 0x00, 0x01}, "ORI.W #1,SR remains outside CCR family"},
    };
    for (size_t index = 0u; index < sizeof(neighbors) / sizeof(neighbors[0]); ++index) {
        memset(&memory, 0, sizeof(memory));
        create_cpu();
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(neighbors[index].program, 4u));
        owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(32));
        TEST_ASSERT_EQUAL_MESSAGE(OWNED_CPU_UNSUPPORTED_OPCODE, result.reason,
                                  neighbors[index].name);
        TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
        owned_cpu_destroy(cpu);
        cpu = NULL;
    }
}

/* ORI/ANDI/EORI to CCR are distinct byte-immediate control operations, not
 * general immediate-to-EA forms. The PRM specifies operations on implemented
 * CCR bits; UM Rev. 9.1 Table 8-12 (printed p. 8-10) gives 20 clocks. */
static void immediate_logic_to_ccr_updates_implemented_flags_in_20_cycles(void) {
    static const struct {
        uint16_t opcode;
        uint16_t sr_before;
        uint16_t immediate;
        uint16_t expected_flags;
    } cases[] = {
        {UINT16_C(0x003c), UINT16_C(0x0005), UINT16_C(0x00f8), UINT16_C(0x001d)},
        {UINT16_C(0x023c), UINT16_C(0x001f), UINT16_C(0x00e7), UINT16_C(0x0007)},
        {UINT16_C(0x0a3c), UINT16_C(0x0015), UINT16_C(0x00f8), UINT16_C(0x000d)},
    };

    for (size_t index = 0u; index < sizeof(cases) / sizeof(cases[0]); ++index) {
        memset(&memory, 0, sizeof(memory));
        create_cpu();
        uint8_t program[4];
        size_t length = 0u;
        emit_word(program, &length, cases[index].opcode);
        emit_word(program, &length, cases[index].immediate);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, length));

        owned_cpu_state before;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
        /* Preserve non-implemented CCR bits if supplied in restored core
         * state. The hardware manuals define the five X/N/Z/V/C bits but do
         * not establish behavior for an impossible nonzero reserved state. */
        before.sr = (uint16_t)(UINT16_C(0x07e0) | cases[index].sr_before);
        before.address_registers[7] = UINT32_C(0x00000700);
        before.usp = UINT32_C(0x00000700);
        before.ssp = UINT32_C(0x00000600);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));

        const size_t reads_before = memory.reads;
        const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(20));
        TEST_ASSERT_EQUAL_MESSAGE(OWNED_CPU_BUDGET, result.reason,
                                  "byte immediate CCR form is legal in user mode");
        TEST_ASSERT_EQUAL_UINT64(20u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
        TEST_ASSERT_EQUAL_UINT(2u, memory.reads - reads_before);
        TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);

        owned_cpu_state after;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &after));
        TEST_ASSERT_EQUAL_HEX16(
            (uint16_t)(UINT16_C(0x07e0) | cases[index].expected_flags), after.sr);
        TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x00e0),
                                (uint16_t)(after.sr & UINT16_C(0x00e0)));
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x00000700),
                                after.address_registers[7]);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x00000700), after.usp);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x00000600), after.ssp);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x00000104), after.pc);
        owned_cpu_destroy(cpu);
        cpu = NULL;
    }

    /* A failed immediate extension read leaves the user CCR and stack banks
     * untouched while retaining the current instruction context. */
    memset(&memory, 0, sizeof(memory));
    create_cpu();
    const uint8_t read_fault_program[] = {0x00u, 0x3cu, 0xffu, 0xf8u};
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(
        read_fault_program, sizeof(read_fault_program)));
    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.sr = UINT16_C(0x0715);
    state.address_registers[7] = UINT32_C(0x00000700);
    state.usp = UINT32_C(0x00000700);
    state.ssp = UINT32_C(0x00000600);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
    memory.fail_read_on = memory.reads + 2u;
    const owned_cpu_run_result read_fault = owned_cpu_run(cpu, UINT64_C(20));
    TEST_ASSERT_EQUAL(OWNED_CPU_HOST_FAULT, read_fault.reason);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x00000100), read_fault.fault_pc);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x003c), read_fault.instruction_register);
    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_test_capture_faulted_state(cpu, &state));
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x0715), state.sr);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x00000700),
                            state.address_registers[7]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x00000700), state.usp);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x00000600), state.ssp);
    owned_cpu_destroy(cpu);
    cpu = NULL;

    /* Counter overflow occurs after the two instruction-stream reads but
     * before any status-register update. */
    memset(&memory, 0, sizeof(memory));
    create_cpu();
    const uint8_t counter_program[] = {0x0au, 0x3cu, 0xffu, 0xf8u};
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(
        counter_program, sizeof(counter_program)));
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.sr = UINT16_C(0x0715);
    state.address_registers[7] = UINT32_C(0x00000700);
    state.usp = UINT32_C(0x00000700);
    state.ssp = UINT32_C(0x00000600);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_test_seed_counters(
        cpu, 0u, 0u, 0u, 0u, UINT64_MAX - UINT64_C(1)));
    const size_t counter_reads = memory.reads;
    const owned_cpu_run_result overflow = owned_cpu_run(cpu, UINT64_C(20));
    TEST_ASSERT_EQUAL(OWNED_CPU_COUNTER_OVERFLOW, overflow.reason);
    TEST_ASSERT_EQUAL_UINT64(0u, overflow.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(0u, overflow.instructions);
    TEST_ASSERT_EQUAL_UINT(counter_reads + 2u, memory.reads);
    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
    owned_cpu_observation observation;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x0715), observation.sr);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x00000100), observation.pc);
    owned_cpu_destroy(cpu);
    cpu = NULL;
}

/* EORI.B #<data>,Dn (guest demanded, plan 05-22 rerun 10). Semantics: M68000
 * Family Programmer's Reference Manual EORI, pp. 4-101 to 4-102 (the low byte
 * of Dn is exclusive-ORed with the immediate byte, taken from the low byte of
 * the extension word; Dn[31:8] preserved; N and Z from the byte, V and C
 * cleared, X unaffected). Timing: MC68000 User's Manual Rev. 9.1 Table 8-5
 * (printed p. 8-5), EORI byte to Dn 8(2/0). Bus-tally reconciliation: the
 * no-prefetch core reads the opcode and the immediate word (2 reads, 0
 * writes), equal to Section 8 with no refill read. */
static void eori_byte_immediate_to_data_register_xors_in_8_cycles(void) {
    static const struct {
        uint8_t program[4];
        unsigned destination;
        uint32_t before;
        uint16_t sr_before;
        uint32_t after;
        uint16_t sr_after;
    } cases[] = {
        {{0x0a, 0x00, 0x00, 0x0f}, 0u, UINT32_C(0x1234ab5a), UINT16_C(0x2700),
         UINT32_C(0x1234ab55), UINT16_C(0x2700)},
        {{0x0a, 0x03, 0x12, 0xa5}, 3u, UINT32_C(0xaaaa00a5), UINT16_C(0x271f),
         UINT32_C(0xaaaa0000), UINT16_C(0x2714)},
        {{0x0a, 0x07, 0x00, 0x80}, 7u, UINT32_C(0xffffff01), UINT16_C(0x2713),
         UINT32_C(0xffffff81), UINT16_C(0x2718)},
        {{0x0a, 0x01, 0x00, 0xff}, 1u, UINT32_C(0xdead00ff), UINT16_C(0x2700),
         UINT32_C(0xdead0000), UINT16_C(0x2704)},
    };
    for (size_t index = 0u; index < sizeof(cases) / sizeof(cases[0]); ++index) {
        memset(&memory, 0, sizeof(memory));
        create_cpu();
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(cases[index].program, 4u));
        owned_cpu_state state;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
        state.data_registers[cases[index].destination] = cases[index].before;
        state.sr = cases[index].sr_before;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
        const size_t reads_before = memory.reads;
        owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(8));
        TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
        TEST_ASSERT_EQUAL_UINT64(8u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
        TEST_ASSERT_EQUAL_UINT(2u, memory.reads - reads_before);
        TEST_ASSERT_EQUAL_UINT(0u, memory.byte_reads);
        TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
        owned_cpu_observation observation;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
        TEST_ASSERT_EQUAL_HEX32(cases[index].after,
                                observation.data_registers[cases[index].destination]);
        TEST_ASSERT_EQUAL_HEX16(cases[index].sr_after, observation.sr);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x104), observation.pc);
        owned_cpu_destroy(cpu);
        cpu = NULL;
    }
}

/* EORI word/long-to-Dn and full-SR forms remain unimplemented. */
static void eori_byte_immediate_neighbors_stay_unsupported(void) {
    static const struct {
        uint8_t program[4];
        const char *name;
    } neighbors[] = {
        {{0x0a, 0x40, 0x00, 0x01}, "EORI.W #1,D0"},
        {{0x0a, 0x80, 0x00, 0x00}, "EORI.L #imm,D0"},
        {{0x0a, 0x7c, 0x00, 0x01}, "EORI.W #1,SR remains outside CCR family"},
    };
    for (size_t index = 0u; index < sizeof(neighbors) / sizeof(neighbors[0]); ++index) {
        memset(&memory, 0, sizeof(memory));
        create_cpu();
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(neighbors[index].program, 4u));
        owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(32));
        TEST_ASSERT_EQUAL_MESSAGE(OWNED_CPU_UNSUPPORTED_OPCODE, result.reason,
                                  neighbors[index].name);
        TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
        owned_cpu_destroy(cpu);
        cpu = NULL;
    }
}

/* Guest-observed encoding (05-20): OR.L Dm,Dn. PRM section 4 OR, pp. 4-150 to
 * 4-151 (opmode 010: <ea> OR Dn -> Dn; N/Z from the long result, V/C clear,
 * X preserved); UM Rev. 9.1 Table 8-4 (p. 8-4): OR long <ea>,Dn 6(1/0)+**
 * where footnote ** raises the base time to 8 for register direct, so 8(1/0). */
static void or_long_data_register_to_data_register_uses_8_cycles(void) {
    static const struct {
        uint8_t program[2];
        unsigned source;
        unsigned destination;
        uint32_t source_value;
        uint32_t destination_value;
        uint32_t expected;
        uint16_t sr_before;
        uint16_t sr_after;
    } cases[] = {
        {{0x88, 0x84}, 4u, 4u, UINT32_C(0x00000000), UINT32_C(0x00000000), UINT32_C(0x00000000),
         UINT16_C(0x271f), UINT16_C(0x2714)},
        {{0x88, 0x84}, 4u, 4u, UINT32_C(0x80000001), UINT32_C(0x80000001), UINT32_C(0x80000001),
         UINT16_C(0x2700), UINT16_C(0x2708)},
        {{0x84, 0x81}, 1u, 2u, UINT32_C(0x0000ff00), UINT32_C(0x12340056), UINT32_C(0x1234ff56),
         UINT16_C(0x2713), UINT16_C(0x2710)},
        {{0x8e, 0x83}, 3u, 7u, UINT32_C(0x00ff0000), UINT32_C(0x80000000), UINT32_C(0x80ff0000),
         UINT16_C(0x2700), UINT16_C(0x2708)},
    };
    for (size_t index = 0u; index < sizeof(cases) / sizeof(cases[0]); ++index) {
        memset(&memory, 0, sizeof(memory));
        create_cpu();
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(cases[index].program, 2u));
        owned_cpu_state state;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
        state.data_registers[cases[index].destination] = cases[index].destination_value;
        state.data_registers[cases[index].source] = cases[index].source_value;
        state.sr = cases[index].sr_before;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
        const size_t reads_before = memory.reads;
        owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(8));
        TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
        TEST_ASSERT_EQUAL_UINT64(8u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
        TEST_ASSERT_EQUAL_UINT(1u, memory.reads - reads_before);
        TEST_ASSERT_EQUAL_UINT(0u, memory.byte_reads);
        TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
        owned_cpu_observation observation;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
        TEST_ASSERT_EQUAL_HEX32(cases[index].expected,
                                observation.data_registers[cases[index].destination]);
        if (cases[index].source != cases[index].destination)
            TEST_ASSERT_EQUAL_HEX32(cases[index].source_value,
                                    observation.data_registers[cases[index].source]);
        TEST_ASSERT_EQUAL_HEX16(cases[index].sr_after, observation.sr);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102), observation.pc);
        owned_cpu_destroy(cpu);
        cpu = NULL;
    }
}

/* Guest-observed encoding: OR.B d16(A5),D0. UM Rev. 9.1 Table 8-4 p. 8-4
 * gives 4(1/0)+ and Table 8-1 p. 8-2 gives displacement byte 8(2/0), for
 * twelve cycles and an ordered opcode/extension/byte read. */
static void or_byte_displacement_memory_source_to_data_register_uses_12_cycles(void) {
    const uint8_t program[] = {UINT8_C(0x80), UINT8_C(0x2d),
                               UINT8_C(0x00), UINT8_C(0x04)};
    create_cpu();
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    memory.rom[UINT32_C(0x184)] = UINT8_C(0x80);

    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.address_registers[5] = UINT32_C(0x180);
    state.data_registers[0] = UINT32_C(0x12340040);
    state.sr = UINT16_C(0x271f);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));

    const size_t reads_before = memory.reads;
    const size_t byte_reads_before = memory.byte_reads;
    const size_t ordered_before = memory.ordered_read_count;
    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(12));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(12u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
    TEST_ASSERT_EQUAL_UINT(2u, memory.reads - reads_before);
    TEST_ASSERT_EQUAL_UINT(1u, memory.byte_reads - byte_reads_before);
    TEST_ASSERT_EQUAL_UINT(3u, memory.ordered_read_count - ordered_before);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                            memory.ordered_read_addresses[ordered_before]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102),
                            memory.ordered_read_addresses[ordered_before + 1u]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x184),
                            memory.ordered_read_addresses[ordered_before + 2u]);
    TEST_ASSERT_EQUAL_UINT8(2u, memory.ordered_read_widths[ordered_before]);
    TEST_ASSERT_EQUAL_UINT8(2u, memory.ordered_read_widths[ordered_before + 1u]);
    TEST_ASSERT_EQUAL_UINT8(1u, memory.ordered_read_widths[ordered_before + 2u]);
    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);

    owned_cpu_observation observation;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x123400c0), observation.data_registers[0]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2718), observation.sr);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x104), observation.pc);
}

/* AND.<size> memory sources use seven MC68000 data-alterable EAs. */
static void and_byte_word_long_memory_sources_cover_all_data_alterable_eas(void) {
    static const uint16_t ea_codes[] = {
        UINT16_C(0x10), UINT16_C(0x18), UINT16_C(0x20), UINT16_C(0x28),
        UINT16_C(0x30), UINT16_C(0x38), UINT16_C(0x39),
    };
    static const uint64_t byte_word_ea_cycles[] = {
        4u, 4u, 6u, 8u, 10u, 8u, 12u,
    };
    static const uint64_t long_ea_cycles[] = {
        8u, 8u, 10u, 12u, 14u, 12u, 16u,
    };
    static const unsigned widths[] = {1u, 2u, 4u};
    const uint32_t target = UINT32_C(0x0180);

    for (size_t width_index = 0u; width_index < 3u; ++width_index) {
        const unsigned width = widths[width_index];
        const uint32_t mask = width == 1u ? UINT32_C(0xff) :
            width == 2u ? UINT32_C(0xffff) : UINT32_MAX;
        const uint32_t sign = width == 1u ? UINT32_C(0x80) :
            width == 2u ? UINT32_C(0x8000) : UINT32_C(0x80000000);
        for (size_t ea_index = 0u; ea_index < 7u; ++ea_index) {
            uint8_t program[8] = {0};
            const uint16_t opcode = (uint16_t)(UINT16_C(0xc000) |
                UINT16_C(0x0400) | (uint16_t)(width_index << 6) |
                ea_codes[ea_index]);
            size_t program_length = 0u;
            emit_word(program, &program_length, opcode);
            unsigned extension_words = 0u;
            if (ea_index == 3u) {
                emit_word(program, &program_length, UINT16_C(0x0010));
                extension_words = 1u;
            } else if (ea_index == 4u) {
                /* D1.W + d8: A0 0x178 + 4 + 4 = 0x180. */
                emit_word(program, &program_length, UINT16_C(0x1004));
                extension_words = 1u;
            } else if (ea_index == 5u) {
                emit_word(program, &program_length, UINT16_C(0x0180));
                extension_words = 1u;
            } else if (ea_index == 6u) {
                emit_word(program, &program_length, UINT16_C(0x0000));
                emit_word(program, &program_length, UINT16_C(0x0180));
                extension_words = 2u;
            }

            create_cpu();
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              reset_with_program(program, program_length));
            const uint32_t source = (ea_index & 1u) == 0u ? sign : 0u;
            for (unsigned byte = 0u; byte < width; ++byte) {
                const unsigned shift = (width - byte - 1u) * 8u;
                memory.rom[target + byte] = (uint8_t)(source >> shift);
            }

            owned_cpu_state before;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_capture_state(cpu, &before));
            uint32_t initial_a0 = UINT32_C(0x140);
            if (ea_index <= 1u) initial_a0 = target;
            if (ea_index == 2u) initial_a0 = target + width;
            if (ea_index == 3u) initial_a0 = target - UINT32_C(0x10);
            if (ea_index == 4u) initial_a0 = target - UINT32_C(8);
            before.address_registers[0] = initial_a0;
            before.data_registers[1] = UINT32_C(4);
            const uint32_t destination = mask;
            before.data_registers[2] = UINT32_C(0x12340000) | destination;
            before.sr = UINT16_C(0x271f);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_restore_state(cpu, &before));

            const size_t words_before = memory.reads;
            const size_t bytes_before = memory.byte_reads;
            const size_t ordered_before = memory.ordered_read_count;
            const uint64_t ea_cycles = width == 4u
                ? long_ea_cycles[ea_index] : byte_word_ea_cycles[ea_index];
            const uint64_t cycles = (width == 4u ? UINT64_C(6) : UINT64_C(4)) +
                                    ea_cycles;
            const owned_cpu_run_result result = owned_cpu_run(cpu, cycles);
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
            TEST_ASSERT_EQUAL_UINT64(cycles, result.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
            const unsigned operand_words = width == 4u ? 2u :
                width == 2u ? 1u : 0u;
            TEST_ASSERT_EQUAL_UINT((size_t)(1u + extension_words + operand_words),
                                   memory.reads - words_before);
            TEST_ASSERT_EQUAL_UINT(width == 1u ? 1u : 0u,
                                   memory.byte_reads - bytes_before);
            TEST_ASSERT_EQUAL_UINT((size_t)(1u + extension_words + operand_words +
                                             (width == 1u ? 1u : 0u)),
                                   memory.ordered_read_count - ordered_before);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                                    memory.ordered_read_addresses[ordered_before]);
            for (unsigned extension = 0u; extension < extension_words; ++extension) {
                TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102) + 2u * extension,
                    memory.ordered_read_addresses[ordered_before + 1u + extension]);
                TEST_ASSERT_EQUAL_UINT8(2u,
                    memory.ordered_read_widths[ordered_before + 1u + extension]);
            }
            const size_t operand_event = ordered_before + 1u + extension_words;
            TEST_ASSERT_EQUAL_HEX32(target,
                                    memory.ordered_read_addresses[operand_event]);
            TEST_ASSERT_EQUAL_UINT8(width == 1u ? 1u : 2u,
                                    memory.ordered_read_widths[operand_event]);
            if (width == 4u) {
                TEST_ASSERT_EQUAL_HEX32(target + UINT32_C(2),
                    memory.ordered_read_addresses[operand_event + 1u]);
                TEST_ASSERT_EQUAL_UINT8(2u,
                    memory.ordered_read_widths[operand_event + 1u]);
            }
            TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);

            owned_cpu_observation after;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
            const uint32_t result_value = destination & source;
            const uint32_t expected_destination =
                (UINT32_C(0x12340000) & ~mask) | result_value;
            TEST_ASSERT_EQUAL_HEX32(expected_destination,
                                    after.data_registers[2]);
            const uint16_t expected_sr = (uint16_t)(UINT16_C(0x2710) |
                (result_value == 0u ? UINT16_C(0x0004) : UINT16_C(0x0008)));
            TEST_ASSERT_EQUAL_HEX16(expected_sr, after.sr);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100) +
                                    (uint32_t)program_length, after.pc);
            const uint32_t expected_a0 = ea_index == 1u ? target + width :
                ea_index == 2u ? target : initial_a0;
            TEST_ASSERT_EQUAL_HEX32(expected_a0, after.address_registers[0]);
            owned_cpu_destroy(cpu);
            cpu = NULL;
        }
    }
}

static void and_byte_postincrement_a7_uses_two_byte_stack_step(void) {
    static const uint8_t program[] = {UINT8_C(0xc0), UINT8_C(0x1f)};
    memset(&memory, 0, sizeof(memory));
    create_cpu();
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    memory.rom[UINT32_C(0x180)] = UINT8_C(0x00);
    owned_cpu_state before;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
    before.address_registers[7] = UINT32_C(0x180);
    before.ssp = UINT32_C(0x180);
    before.data_registers[0] = UINT32_C(0x12340080);
    before.sr = UINT16_C(0x271f);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));

    const size_t words_before = memory.reads;
    const size_t bytes_before = memory.byte_reads;
    const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(8));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
    TEST_ASSERT_EQUAL_UINT(1u, memory.reads - words_before);
    TEST_ASSERT_EQUAL_UINT(1u, memory.byte_reads - bytes_before);
    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
    owned_cpu_observation after;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x12340000), after.data_registers[0]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2714), after.sr);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x182), after.address_registers[7]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x182), after.ssp);
    owned_cpu_destroy(cpu);
    cpu = NULL;
}

static void and_word_postincrement_odd_source_commits_before_vector_three(void) {
    assert_memory_source_odd_postincrement_commits_before_vector_three(
        UINT16_C(0xc05a), 2u); /* AND.W (A2)+,D0 */
}

static void and_long_postincrement_odd_source_commits_before_vector_three(void) {
    assert_memory_source_odd_postincrement_commits_before_vector_three(
        UINT16_C(0xc09a), 4u); /* AND.L (A2)+,D0 */
}

static void and_long_postincrement_low_half_host_fault_keeps_state(void) {
    static const uint8_t program[] = {UINT8_C(0xc0), UINT8_C(0x98)};
    memset(&memory, 0, sizeof(memory));
    create_cpu();
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    owned_cpu_state before;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
    before.address_registers[0] = UINT32_C(0x180);
    before.data_registers[0] = UINT32_C(0xf0f0f0f0);
    before.sr = UINT16_C(0x271f);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));
    const size_t reads_before = memory.reads;
    memory.fail_read_on = reads_before + 3u; /* opcode, high source word, low failure */

    const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(14));
    TEST_ASSERT_EQUAL(OWNED_CPU_HOST_FAULT, result.reason);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100), result.fault_pc);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0xc098), result.instruction_register);
    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
    owned_cpu_state after;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_test_capture_faulted_state(cpu, &after));
    TEST_ASSERT_EQUAL_HEX32(before.data_registers[0], after.data_registers[0]);
    TEST_ASSERT_EQUAL_HEX32(before.address_registers[0], after.address_registers[0]);
    TEST_ASSERT_EQUAL_HEX16(before.sr, after.sr);
    owned_cpu_destroy(cpu);
    cpu = NULL;
}

static void and_long_postincrement_counter_preflight_leaves_operand_unread(void) {
    static const uint8_t program[] = {UINT8_C(0xc0), UINT8_C(0x98)};
    memset(&memory, 0, sizeof(memory));
    create_cpu();
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    owned_cpu_state before;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
    before.address_registers[0] = UINT32_C(0x180);
    before.data_registers[0] = UINT32_C(0xf0f0f0f0);
    before.sr = UINT16_C(0x271f);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
        owned_cpu_test_seed_counters(cpu, 0u, 0u, 0u, 0u,
                                     UINT64_MAX - UINT64_C(13)));

    const size_t reads_before = memory.reads;
    const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(14));
    TEST_ASSERT_EQUAL(OWNED_CPU_COUNTER_OVERFLOW, result.reason);
    TEST_ASSERT_EQUAL_UINT64(0u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(0u, result.instructions);
    TEST_ASSERT_EQUAL_UINT(reads_before + 1u, memory.reads);
    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
    owned_cpu_observation after;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
    TEST_ASSERT_EQUAL_HEX32(before.data_registers[0], after.data_registers[0]);
    TEST_ASSERT_EQUAL_HEX32(before.address_registers[0], after.address_registers[0]);
    TEST_ASSERT_EQUAL_HEX16(before.sr, after.sr);
    owned_cpu_destroy(cpu);
    cpu = NULL;
}

/* OR.<size> memory sources use the same seven MC68000 data-alterable EAs as
 * CMP. Exercise every width/mode pair against UM Tables 8-1 and 8-4, checking
 * extension-fetch order, operand bus width, flags, and auto-update. */
static void or_byte_word_long_memory_sources_cover_all_data_alterable_eas(void) {
    static const uint16_t ea_codes[] = {
        UINT16_C(0x10), UINT16_C(0x18), UINT16_C(0x20), UINT16_C(0x28),
        UINT16_C(0x30), UINT16_C(0x38), UINT16_C(0x39),
    };
    static const uint64_t byte_word_ea_cycles[] = {4u, 4u, 6u, 8u, 10u, 8u, 12u};
    static const uint64_t long_ea_cycles[] = {8u, 8u, 10u, 12u, 14u, 12u, 16u};
    static const unsigned widths[] = {1u, 2u, 4u};

    for (size_t width_index = 0u; width_index < 3u; ++width_index) {
        const unsigned width = widths[width_index];
        const unsigned opmode = (unsigned)width_index;
        for (size_t ea_index = 0u; ea_index < 7u; ++ea_index) {
            uint8_t program[8] = {0};
            const uint16_t opcode = (uint16_t)(UINT16_C(0x8400) |
                (uint16_t)(opmode << 6) | ea_codes[ea_index]);
            size_t program_length = 0u;
            emit_word(program, &program_length, opcode);
            unsigned extension_words = 0u;
            if (ea_index == 3u) {
                emit_word(program, &program_length, UINT16_C(0x0010));
                extension_words = 1u;
            } else if (ea_index == 4u) {
                /* D1.W + d8: A0 0x178 + 4 + 4 = 0x180. */
                emit_word(program, &program_length, UINT16_C(0x1004));
                extension_words = 1u;
            } else if (ea_index == 5u) {
                emit_word(program, &program_length, UINT16_C(0x0180));
                extension_words = 1u;
            } else if (ea_index == 6u) {
                emit_word(program, &program_length, UINT16_C(0x0000));
                emit_word(program, &program_length, UINT16_C(0x0180));
                extension_words = 2u;
            }

            create_cpu();
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              reset_with_program(program, program_length));
            if (width == 1u) {
                memory.rom[UINT32_C(0x180)] = UINT8_C(0x80);
            } else if (width == 2u) {
                memory.rom[UINT32_C(0x180)] = UINT8_C(0x80);
                memory.rom[UINT32_C(0x181)] = UINT8_C(0x00);
            } else {
                memory.rom[UINT32_C(0x180)] = UINT8_C(0x80);
                memory.rom[UINT32_C(0x181)] = UINT8_C(0x00);
                memory.rom[UINT32_C(0x182)] = UINT8_C(0x00);
                memory.rom[UINT32_C(0x183)] = UINT8_C(0x00);
            }

            owned_cpu_state state;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
            uint32_t initial_a0 = UINT32_C(0x140);
            if (ea_index == 0u || ea_index == 1u) initial_a0 = UINT32_C(0x180);
            if (ea_index == 2u) initial_a0 = UINT32_C(0x180) + width;
            if (ea_index == 3u) initial_a0 = UINT32_C(0x170);
            if (ea_index == 4u) initial_a0 = UINT32_C(0x178);
            state.address_registers[0] = initial_a0;
            state.data_registers[1] = UINT32_C(4);
            state.data_registers[2] = width == 1u ? UINT32_C(0x12340040) :
                width == 2u ? UINT32_C(0x12344000) : UINT32_C(0x40000000);
            state.sr = UINT16_C(0x271f);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));

            const size_t words_before = memory.reads;
            const size_t bytes_before = memory.byte_reads;
            const size_t ordered_before = memory.ordered_read_count;
            const uint64_t ea_cycles = width == 4u
                ? long_ea_cycles[ea_index] : byte_word_ea_cycles[ea_index];
            const uint64_t cycles = (width == 4u ? UINT64_C(6) : UINT64_C(4)) +
                                    ea_cycles;
            owned_cpu_run_result result = owned_cpu_run(cpu, cycles);
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
            TEST_ASSERT_EQUAL_UINT64(cycles, result.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
            const unsigned operand_words = width == 4u ? 2u : width == 2u ? 1u : 0u;
            TEST_ASSERT_EQUAL_UINT((size_t)(1u + extension_words + operand_words),
                                   memory.reads - words_before);
            TEST_ASSERT_EQUAL_UINT(width == 1u ? 1u : 0u,
                                   memory.byte_reads - bytes_before);
            TEST_ASSERT_EQUAL_UINT((size_t)(1u + extension_words + operand_words +
                                             (width == 1u ? 1u : 0u)),
                                   memory.ordered_read_count - ordered_before);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                                    memory.ordered_read_addresses[ordered_before]);
            for (unsigned extension = 0u; extension < extension_words; ++extension) {
                TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102) + 2u * extension,
                    memory.ordered_read_addresses[ordered_before + 1u + extension]);
                TEST_ASSERT_EQUAL_UINT8(2u,
                    memory.ordered_read_widths[ordered_before + 1u + extension]);
            }
            const size_t operand_event = ordered_before + 1u + extension_words;
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x180),
                                    memory.ordered_read_addresses[operand_event]);
            TEST_ASSERT_EQUAL_UINT8(width == 1u ? 1u : 2u,
                                    memory.ordered_read_widths[operand_event]);
            if (width == 4u) {
                TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x182),
                    memory.ordered_read_addresses[operand_event + 1u]);
                TEST_ASSERT_EQUAL_UINT8(2u,
                    memory.ordered_read_widths[operand_event + 1u]);
            }
            TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);

            owned_cpu_observation observation;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
            const uint32_t expected = width == 1u ? UINT32_C(0x123400c0) :
                width == 2u ? UINT32_C(0x1234c000) : UINT32_C(0xc0000000);
            TEST_ASSERT_EQUAL_HEX32(expected, observation.data_registers[2]);
            TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2718), observation.sr);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100) + (uint32_t)program_length,
                                    observation.pc);
            const uint32_t expected_a0 = ea_index == 1u
                ? UINT32_C(0x180) + width
                : ea_index == 2u ? UINT32_C(0x180) : initial_a0;
            TEST_ASSERT_EQUAL_HEX32(expected_a0, observation.address_registers[0]);
            owned_cpu_destroy(cpu);
            cpu = NULL;
        }
    }
}

/* ADD.<size> data-alterable memory source to Dn uses the same seven source
 * EAs as CMP/OR. Exercise all operand sizes, EA registers and Dn destinations;
 * vary operands across signed overflow, carry/zero, sign-boundary and plain
 * addition cases. Timing is UM Rev. 9.1 Table 8-4 p. 8-4 plus Table 8-1
 * p. 8-2. */
static void add_byte_word_long_memory_sources_cover_all_data_alterable_eas(void) {
    static const uint16_t ea_codes[] = {
        UINT16_C(0x10), UINT16_C(0x18), UINT16_C(0x20), UINT16_C(0x28),
        UINT16_C(0x30), UINT16_C(0x38), UINT16_C(0x39),
    };
    static const uint64_t byte_word_ea_cycles[] = {
        4u, 4u, 6u, 8u, 10u, 8u, 12u,
    };
    static const uint64_t long_ea_cycles[] = {
        8u, 8u, 10u, 12u, 14u, 12u, 16u,
    };
    static const unsigned widths[] = {1u, 2u, 4u};
    const uint32_t target = UINT32_C(0x0180);
    unsigned case_number = 0u;

    for (size_t width_index = 0u; width_index < 3u; ++width_index) {
        const unsigned width = widths[width_index];
        const unsigned opmode = (unsigned)width_index;
        const uint32_t mask = width == 1u ? UINT32_C(0xff) :
            width == 2u ? UINT32_C(0xffff) : UINT32_MAX;
        const uint32_t sign = width == 1u ? UINT32_C(0x80) :
            width == 2u ? UINT32_C(0x8000) : UINT32_C(0x80000000);
        for (size_t ea_index = 0u; ea_index < 7u; ++ea_index) {
            const unsigned source_register_count = ea_index < 5u ? 8u : 1u;
            for (unsigned source_register = 0u;
                 source_register < source_register_count; ++source_register) {
                for (unsigned destination_register = 0u;
                     destination_register < 8u;
                     ++destination_register, ++case_number) {
                    const unsigned ea_register = ea_index < 5u
                        ? source_register : (unsigned)(ea_codes[ea_index] & 7u);
                    const uint16_t source_ea = (uint16_t)(ea_codes[ea_index] |
                        (ea_index < 5u ? source_register : 0u));
                    const uint16_t opcode = (uint16_t)(UINT16_C(0xd000) |
                        (uint16_t)(destination_register << 9) |
                        (uint16_t)(opmode << 6) | source_ea);
                    uint8_t program[8] = {0};
                    size_t program_length = 0u;
                    emit_word(program, &program_length, opcode);
                    unsigned extension_words = 0u;
                    if (ea_index == 3u) {
                        emit_word(program, &program_length, UINT16_C(0x0010));
                        extension_words = 1u;
                    } else if (ea_index == 4u) {
                        const uint16_t index_extension = (uint16_t)(
                            (uint16_t)(destination_register << 12) |
                            UINT16_C(0x0004)); /* Dn.W + d8 */
                        emit_word(program, &program_length, index_extension);
                        extension_words = 1u;
                    } else if (ea_index == 5u) {
                        emit_word(program, &program_length, (uint16_t)target);
                        extension_words = 1u;
                    } else if (ea_index == 6u) {
                        emit_word(program, &program_length,
                                  (uint16_t)(target >> 16));
                        emit_word(program, &program_length, (uint16_t)target);
                        extension_words = 2u;
                    }

                    memset(&memory, 0, sizeof(memory));
                    create_cpu();
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                        reset_with_program(program, program_length));

                    const unsigned scenario = case_number & 3u;
                    const uint32_t destination = scenario == 0u ?
                        (sign - UINT32_C(1)) : scenario == 1u ? mask :
                        scenario == 2u ? sign : UINT32_C(0x11);
                    const uint32_t source = scenario == 0u ? UINT32_C(1) :
                        scenario == 1u ? UINT32_C(1) :
                        scenario == 2u ? sign : UINT32_C(0x35);
                    const uint64_t sum = (uint64_t)destination + source;
                    const uint32_t result_value = (uint32_t)sum & mask;
                    uint16_t expected_sr = UINT16_C(0x2700);
                    if (result_value == 0u) expected_sr |= UINT16_C(0x0004);
                    if ((result_value & sign) != 0u) expected_sr |= UINT16_C(0x0008);
                    if (((~(destination ^ source) &
                          (destination ^ result_value)) & sign) != 0u)
                        expected_sr |= UINT16_C(0x0002);
                    if (sum > mask) expected_sr |= UINT16_C(0x0011);

                    if (width == 1u) {
                        memory.rom[target] = (uint8_t)source;
                    } else {
                        memory.rom[target] = (uint8_t)(source >>
                            (width == 2u ? 8u : 24u));
                        memory.rom[target + 1u] = (uint8_t)(source >>
                            (width == 2u ? 0u : 16u));
                        if (width == 4u) {
                            memory.rom[target + 2u] = (uint8_t)(source >> 8);
                            memory.rom[target + 3u] = (uint8_t)source;
                        }
                    }

                    owned_cpu_state state;
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      owned_cpu_capture_state(cpu, &state));
                    for (unsigned reg = 0u; reg < 8u; ++reg)
                        state.address_registers[reg] =
                            UINT32_C(0x0300) + reg * UINT32_C(8);
                    for (unsigned reg = 0u; reg < 8u; ++reg)
                        state.data_registers[reg] = UINT32_C(0xa5a50000);
                    state.data_registers[destination_register] =
                        width == 4u ? destination :
                        (UINT32_C(0xa5a50000) | destination);
                    if (ea_index == 0u || ea_index == 1u) {
                        state.address_registers[ea_register] = target;
                    } else if (ea_index == 2u) {
                        const uint32_t step = width == 1u && ea_register == 7u
                            ? UINT32_C(2) : width;
                        state.address_registers[ea_register] = target + step;
                    } else if (ea_index == 3u) {
                        state.address_registers[ea_register] =
                            target - UINT32_C(0x10);
                    } else if (ea_index == 4u) {
                        const uint16_t index_word =
                            (uint16_t)state.data_registers[destination_register];
                        const int32_t index_value = index_word <= UINT16_C(0x7fff)
                            ? (int32_t)index_word
                            : (int32_t)index_word - INT32_C(0x10000);
                        state.address_registers[ea_register] =
                            (uint32_t)((int64_t)target - INT64_C(4) - index_value);
                    }
                    /* Keep the captured active supervisor stack bank in sync
                     * with A7 even when another An is this instruction's EA. */
                    state.ssp = state.address_registers[7];
                    state.sr = UINT16_C(0x271f);
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      owned_cpu_restore_state(cpu, &state));

                    const size_t reads_before = memory.reads;
                    const size_t byte_reads_before = memory.byte_reads;
                    const size_t ordered_before = memory.ordered_read_count;
                    const uint64_t ea_cycles = width == 4u
                        ? long_ea_cycles[ea_index]
                        : byte_word_ea_cycles[ea_index];
                    const uint64_t cycles = (width == 4u ? UINT64_C(6) :
                        UINT64_C(4)) + ea_cycles;
                    const owned_cpu_run_result run = owned_cpu_run(cpu, cycles);
                    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, run.reason);
                    TEST_ASSERT_EQUAL_UINT64(cycles, run.elapsed_cycles);
                    TEST_ASSERT_EQUAL_UINT64(1u, run.instructions);
                    const unsigned source_words = width == 4u ? 2u :
                        width == 2u ? 1u : 0u;
                    TEST_ASSERT_EQUAL_UINT((size_t)(1u + extension_words +
                        source_words), memory.reads - reads_before);
                    TEST_ASSERT_EQUAL_UINT(width == 1u ? 1u : 0u,
                        memory.byte_reads - byte_reads_before);
                    TEST_ASSERT_EQUAL_UINT((size_t)(1u + extension_words +
                        source_words + (width == 1u ? 1u : 0u)),
                        memory.ordered_read_count - ordered_before);
                    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                        memory.ordered_read_addresses[ordered_before]);
                    for (unsigned ext = 0u; ext < extension_words; ++ext) {
                        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102) + ext * 2u,
                            memory.ordered_read_addresses[ordered_before + 1u + ext]);
                        TEST_ASSERT_EQUAL_UINT8(2u,
                            memory.ordered_read_widths[ordered_before + 1u + ext]);
                    }
                    const size_t operand_event = ordered_before + 1u + extension_words;
                    TEST_ASSERT_EQUAL_HEX32(target,
                        memory.ordered_read_addresses[operand_event]);
                    TEST_ASSERT_EQUAL_UINT8(width == 1u ? 1u : 2u,
                        memory.ordered_read_widths[operand_event]);
                    if (width == 4u) {
                        TEST_ASSERT_EQUAL_HEX32(target + UINT32_C(2),
                            memory.ordered_read_addresses[operand_event + 1u]);
                        TEST_ASSERT_EQUAL_UINT8(2u,
                            memory.ordered_read_widths[operand_event + 1u]);
                    }
                    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);

                    owned_cpu_observation observation;
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      owned_cpu_observe(cpu, &observation));
                    const uint32_t expected_data = width == 4u ? result_value :
                        ((UINT32_C(0xa5a50000) & ~mask) | result_value);
                    TEST_ASSERT_EQUAL_HEX32(expected_data,
                        observation.data_registers[destination_register]);
                    TEST_ASSERT_EQUAL_HEX16(expected_sr, observation.sr);
                    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100) + program_length,
                                             observation.pc);
                    const uint32_t expected_base = ea_index == 1u
                        ? target + (width == 1u && ea_register == 7u
                            ? UINT32_C(2) : width)
                        : ea_index == 2u ? target :
                        (ea_index == 0u ? target : state.address_registers[ea_register]);
                    if (ea_index < 5u) {
                        TEST_ASSERT_EQUAL_HEX32(expected_base,
                            observation.address_registers[ea_register]);
                        if (ea_register == 7u)
                            TEST_ASSERT_EQUAL_HEX32(expected_base, observation.ssp);
                    }
                    owned_cpu_destroy(cpu);
                    cpu = NULL;
                }
            }
        }
    }
}

/* ADD/SUB.B/W/L Dn,<data-alterable memory> is the read-modify-write
 * direction. Exercise every documented memory EA, source register and base
 * register; Dn also serves as the brief index in alias cases. UM Rev. 9.1
 * Table 8-4 p. 8-4 plus Table 8-1 p. 8-2 define the exact timing totals. */
static void check_byte_word_long_data_register_memory_destinations(int subtract) {
    static const uint16_t ea_codes[] = {
        UINT16_C(0x28), UINT16_C(0x10), UINT16_C(0x18), UINT16_C(0x20),
        UINT16_C(0x30), UINT16_C(0x38), UINT16_C(0x39),
    };
    static const uint64_t byte_word_ea_cycles[] = {
        8u, 4u, 4u, 6u, 10u, 8u, 12u,
    };
    static const uint64_t long_ea_cycles[] = {
        12u, 8u, 8u, 10u, 14u, 12u, 16u,
    };
    static const unsigned widths[] = {1u, 2u, 4u};
    const uint32_t target = UINT32_C(0x0180);
    unsigned case_number = 0u;

    for (size_t width_index = 0u; width_index < 3u; ++width_index) {
        const unsigned width = widths[width_index];
        const unsigned opmode = 4u + (unsigned)width_index;
        const uint32_t mask = width == 1u ? UINT32_C(0xff) :
            width == 2u ? UINT32_C(0xffff) : UINT32_MAX;
        const uint32_t sign = width == 1u ? UINT32_C(0x80) :
            width == 2u ? UINT32_C(0x8000) : UINT32_C(0x80000000);
        for (size_t ea_index = 0u; ea_index < 7u; ++ea_index) {
            const unsigned base_register_count = ea_index < 5u ? 8u : 1u;
            for (unsigned base_register = 0u;
                 base_register < base_register_count; ++base_register) {
                for (unsigned source_register = 0u; source_register < 8u;
                     ++source_register, ++case_number) {
                    const unsigned ea_register = ea_index < 5u
                        ? base_register : (unsigned)(ea_codes[ea_index] & 7u);
                    const uint16_t destination_ea = (uint16_t)(ea_codes[ea_index] |
                        (ea_index < 5u ? base_register : 0u));
                    const uint16_t opcode = (uint16_t)(
                        (subtract != 0 ? UINT16_C(0x9000) : UINT16_C(0xd000)) |
                        (uint16_t)(source_register << 9) |
                        (uint16_t)(opmode << 6) | destination_ea);
                    uint8_t program[8] = {0};
                    size_t program_length = 0u;
                    emit_word(program, &program_length, opcode);
                    unsigned extension_words = 0u;
                    if (ea_index == 0u) {
                        emit_word(program, &program_length, UINT16_C(0x0010));
                        extension_words = 1u;
                    } else if (ea_index == 4u) {
                        emit_word(program, &program_length, (uint16_t)(
                            (uint16_t)(source_register << 12) | UINT16_C(0x0004)));
                        extension_words = 1u;
                    } else if (ea_index == 5u) {
                        emit_word(program, &program_length, (uint16_t)target);
                        extension_words = 1u;
                    } else if (ea_index == 6u) {
                        emit_word(program, &program_length,
                                  (uint16_t)(target >> 16));
                        emit_word(program, &program_length, (uint16_t)target);
                        extension_words = 2u;
                    }

                    setUp();
                    create_cpu();
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                        reset_with_program(program, program_length));

                    const unsigned scenario = case_number %
                        (subtract != 0 ? 6u : 4u);
                    const uint32_t destination = scenario == 0u ?
                        sign - UINT32_C(1) : scenario == 1u ? mask :
                        scenario == 2u ? sign : scenario == 3u ? UINT32_C(0x11) :
                        scenario == 4u ? sign - UINT32_C(1) : sign;
                    const uint32_t source = scenario == 0u ? UINT32_C(1) :
                        scenario == 1u ? UINT32_C(1) :
                        scenario == 2u ? sign : scenario == 3u ? UINT32_C(0x35) :
                        scenario == 4u ? sign : UINT32_C(1);
                    const uint64_t full_sum =
                        (uint64_t)destination + (uint64_t)source;
                    const uint32_t result_value = subtract != 0
                        ? (destination - source) & mask
                        : (uint32_t)full_sum & mask;
                    uint16_t expected_sr = UINT16_C(0x2700);
                    if (result_value == 0u)
                        expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0004));
                    if ((result_value & sign) != 0u)
                        expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0008));
                    if (subtract != 0) {
                        if (((destination ^ source) &
                             (destination ^ result_value) & sign) != 0u)
                            expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0002));
                        if (destination < source)
                            expected_sr = (uint16_t)(expected_sr |
                                UINT16_C(0x0011));
                    } else {
                        if (((~(destination ^ source) &
                              (destination ^ result_value)) & sign) != 0u)
                            expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0002));
                        if (full_sum > mask)
                            expected_sr = (uint16_t)(expected_sr |
                                UINT16_C(0x0011));
                    }

                    if (width == 1u) {
                        memory.rom[target] = (uint8_t)destination;
                    } else {
                        memory.rom[target] = (uint8_t)(destination >>
                            (width == 2u ? 8u : 24u));
                        memory.rom[target + 1u] = (uint8_t)(destination >>
                            (width == 2u ? 0u : 16u));
                        if (width == 4u) {
                            memory.rom[target + 2u] = (uint8_t)(destination >> 8);
                            memory.rom[target + 3u] = (uint8_t)destination;
                        }
                    }

                    owned_cpu_state before;
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      owned_cpu_capture_state(cpu, &before));
                    for (unsigned reg = 0u; reg < 8u; ++reg) {
                        before.address_registers[reg] =
                            UINT32_C(0x0300) + reg * UINT32_C(8);
                        before.data_registers[reg] = UINT32_C(0xa5a50000) | reg;
                    }
                    before.data_registers[source_register] = width == 4u
                        ? source : UINT32_C(0xa5a50000) | source;
                    if (ea_index == 1u || ea_index == 2u) {
                        before.address_registers[ea_register] = target;
                    } else if (ea_index == 3u) {
                        before.address_registers[ea_register] =
                            target + (width == 1u && ea_register == 7u
                                ? UINT32_C(2) : width);
                    } else if (ea_index == 0u) {
                        before.address_registers[ea_register] =
                            target - UINT32_C(0x10);
                    } else if (ea_index == 4u) {
                        const uint16_t index_word = (uint16_t)source;
                        const int32_t signed_index =
                            index_word <= UINT16_C(0x7fff)
                                ? (int32_t)index_word
                                : (int32_t)index_word - INT32_C(0x10000);
                        before.address_registers[ea_register] =
                            (uint32_t)((int64_t)target - INT64_C(4) -
                                       signed_index);
                    }
                    before.ssp = before.address_registers[7];
                    before.sr = UINT16_C(0x271f);
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      owned_cpu_restore_state(cpu, &before));

                    const size_t reads_before = memory.reads;
                    const size_t byte_reads_before = memory.byte_reads;
                    const size_t ordered_before = memory.ordered_read_count;
                    const size_t writes_before = memory.write_attempts;
                    const uint64_t ea_cycles = width == 4u
                        ? long_ea_cycles[ea_index]
                        : byte_word_ea_cycles[ea_index];
                    const uint64_t cycles =
                        (width == 4u ? UINT64_C(12) : UINT64_C(8)) + ea_cycles;
                    const owned_cpu_run_result run = owned_cpu_run(cpu, cycles);
                    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, run.reason);
                    TEST_ASSERT_EQUAL_UINT64(cycles, run.elapsed_cycles);
                    TEST_ASSERT_EQUAL_UINT64(1u, run.instructions);
                    const unsigned operand_words = width == 4u ? 2u :
                        width == 2u ? 1u : 0u;
                    TEST_ASSERT_EQUAL_UINT((size_t)(1u + extension_words +
                        operand_words), memory.reads - reads_before);
                    TEST_ASSERT_EQUAL_UINT(width == 1u ? 1u : 0u,
                        memory.byte_reads - byte_reads_before);
                    TEST_ASSERT_EQUAL_UINT((size_t)(1u + extension_words +
                        operand_words + (width == 1u ? 1u : 0u)),
                        memory.ordered_read_count - ordered_before);
                    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                        memory.ordered_read_addresses[ordered_before]);
                    for (unsigned ext = 0u; ext < extension_words; ++ext) {
                        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102) + ext * 2u,
                            memory.ordered_read_addresses[ordered_before + 1u + ext]);
                        TEST_ASSERT_EQUAL_UINT8(2u,
                            memory.ordered_read_widths[ordered_before + 1u + ext]);
                    }
                    const size_t operand_event = ordered_before + 1u +
                        extension_words;
                    TEST_ASSERT_EQUAL_HEX32(target,
                        memory.ordered_read_addresses[operand_event]);
                    TEST_ASSERT_EQUAL_UINT8(width == 1u ? 1u : 2u,
                        memory.ordered_read_widths[operand_event]);
                    if (width == 4u) {
                        TEST_ASSERT_EQUAL_HEX32(target + UINT32_C(2),
                            memory.ordered_read_addresses[operand_event + 1u]);
                        TEST_ASSERT_EQUAL_UINT8(2u,
                            memory.ordered_read_widths[operand_event + 1u]);
                    }
                    const size_t write_words = width == 4u ? 2u : 1u;
                    TEST_ASSERT_EQUAL_UINT(writes_before + write_words,
                                           memory.write_attempts);
                    TEST_ASSERT_EQUAL_UINT(write_words,
                                           memory.successful_writes);
                    if (width == 1u) {
                        TEST_ASSERT_EQUAL_HEX32(target,
                            memory.byte_write_addresses[0]);
                        TEST_ASSERT_EQUAL_HEX8((uint8_t)result_value,
                            memory.byte_write_values[0]);
                        TEST_ASSERT_EQUAL_HEX8((uint8_t)result_value,
                                               memory.rom[target]);
                    } else {
                        TEST_ASSERT_EQUAL_HEX32(target, memory.write_addresses[0]);
                        TEST_ASSERT_EQUAL_HEX16(width == 2u
                            ? (uint16_t)result_value
                            : (uint16_t)(result_value >> 16),
                            memory.write_values[0]);
                        if (width == 4u) {
                            TEST_ASSERT_EQUAL_HEX32(target + UINT32_C(2),
                                memory.write_addresses[1]);
                            TEST_ASSERT_EQUAL_HEX16((uint16_t)result_value,
                                                    memory.write_values[1]);
                        }
                    }

                    owned_cpu_observation after;
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      owned_cpu_observe(cpu, &after));
                    TEST_ASSERT_EQUAL_HEX16(expected_sr, after.sr);
                    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100) + program_length,
                                             after.pc);
                    for (unsigned reg = 0u; reg < 8u; ++reg)
                        TEST_ASSERT_EQUAL_HEX32(before.data_registers[reg],
                                                after.data_registers[reg]);
                    for (unsigned reg = 0u; reg < 8u; ++reg) {
                        uint32_t expected_base = before.address_registers[reg];
                        if (ea_index == 2u && reg == ea_register)
                            expected_base = target +
                                (width == 1u && ea_register == 7u
                                    ? UINT32_C(2) : width);
                        else if (ea_index == 3u && reg == ea_register)
                            expected_base = target;
                        TEST_ASSERT_EQUAL_HEX32(expected_base,
                                                after.address_registers[reg]);
                    }
                    TEST_ASSERT_EQUAL_HEX32(after.address_registers[7], after.ssp);
                    tearDown();
                }
            }
        }
    }
}

static void add_byte_word_long_data_registers_cover_all_data_alterable_destinations(void) {
    check_byte_word_long_data_register_memory_destinations(0);
}

static void sub_byte_word_long_data_registers_cover_all_data_alterable_destinations(void) {
    check_byte_word_long_data_register_memory_destinations(1);
}

/* The selected guest reaches SUB.W Dn,(d16,An). UM Rev. 9.1 Table 8-4
 * assigns 8(1/1)+ to word Dn-to-memory SUB and Table 8-1 adds 8 clocks for
 * d16(An), for 16 clocks total. */
static void sub_word_data_register_to_displacement_memory_subtracts_in_16_cycles(void) {
    setUp();
    create_cpu();
    uint8_t program[4];
    size_t length = 0u;
    emit_word(program, &length, UINT16_C(0x9168)); /* SUB.W D0,(d16,A0) */
    emit_word(program, &length, UINT16_C(0x0010));
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, length));

    const uint32_t target = UINT32_C(0x0180);
    memory.rom[target] = 0u;
    memory.rom[target + 1u] = 1u;
    owned_cpu_state before;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
    before.data_registers[0] = UINT32_C(0xabcd0002);
    before.address_registers[0] = target - UINT32_C(0x10);
    before.sr = UINT16_C(0x271f);
    before.ssp = before.address_registers[7];
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));

    const size_t reads_before = memory.reads;
    const size_t writes_before = memory.write_attempts;
    const owned_cpu_run_result run = owned_cpu_run(cpu, UINT64_C(16));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, run.reason);
    TEST_ASSERT_EQUAL_UINT64(16u, run.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(1u, run.instructions);
    TEST_ASSERT_EQUAL_UINT(reads_before + 3u, memory.reads);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100), memory.read_addresses[reads_before]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102), memory.read_addresses[reads_before + 1u]);
    TEST_ASSERT_EQUAL_HEX32(target, memory.read_addresses[reads_before + 2u]);
    TEST_ASSERT_EQUAL_UINT(writes_before + 1u, memory.write_attempts);
    TEST_ASSERT_EQUAL_UINT(1u, memory.successful_writes);
    TEST_ASSERT_EQUAL_HEX32(target, memory.write_addresses[writes_before]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0xffff),
                            memory.write_values[writes_before]);

    owned_cpu_observation after;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2719), after.sr);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0xabcd0002), after.data_registers[0]);
    TEST_ASSERT_EQUAL_HEX32(target - UINT32_C(0x10),
                            after.address_registers[0]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x104), after.pc);
    TEST_ASSERT_EQUAL_HEX32(after.address_registers[7], after.ssp);
    tearDown();
}

static void or_byte_address_seven_postincrement_uses_two_byte_stack_step(void) {
    const uint8_t program[] = {UINT8_C(0x80), UINT8_C(0x1f)};
    create_cpu();
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    memory.rom[UINT32_C(0x180)] = UINT8_C(0x40);
    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.address_registers[7] = UINT32_C(0x180);
    state.ssp = UINT32_C(0x180);
    state.data_registers[0] = UINT32_C(0x12340080);
    state.sr = UINT16_C(0x271f);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));

    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(8));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(8u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
    owned_cpu_observation observation;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x123400c0), observation.data_registers[0]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x182), observation.address_registers[7]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x182), observation.ssp);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2718), observation.sr);
}

static void or_byte_indexed_source_resolves_before_overwriting_index_register(void) {
    const uint8_t program[] = {UINT8_C(0x84), UINT8_C(0x30),
                               UINT8_C(0x20), UINT8_C(0x00)};
    create_cpu();
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    memory.rom[UINT32_C(0x184)] = UINT8_C(0x80);
    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.address_registers[0] = UINT32_C(0x180);
    state.data_registers[2] = UINT32_C(0x00000004);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));

    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(14));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(14u, result.elapsed_cycles);
    owned_cpu_observation observation;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x84), observation.data_registers[2]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x104), observation.pc);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x184), memory.byte_read_addresses[0]);
}

static void or_memory_source_counter_preflight_keeps_operand_untouched(void) {
    const uint8_t program[] = {UINT8_C(0x80), UINT8_C(0x2d),
                               UINT8_C(0x00), UINT8_C(0x04)};
    create_cpu();
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    memory.rom[UINT32_C(0x184)] = UINT8_C(0x80);
    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.address_registers[5] = UINT32_C(0x180);
    state.data_registers[0] = UINT32_C(0x12340040);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_test_seed_counters(
        cpu, 0u, 0u, 0u, 0u, UINT64_MAX - UINT64_C(1)));

    const size_t byte_reads_before = memory.byte_reads;
    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(12));
    TEST_ASSERT_EQUAL(OWNED_CPU_COUNTER_OVERFLOW, result.reason);
    TEST_ASSERT_EQUAL_UINT64(0u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(0u, result.instructions);
    TEST_ASSERT_EQUAL_UINT(byte_reads_before, memory.byte_reads);
    owned_cpu_observation observation;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100), observation.pc);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x12340040), observation.data_registers[0]);
}

static void or_word_postincrement_read_fault_keeps_fault_context(void) {
    const uint8_t program[] = {UINT8_C(0x80), UINT8_C(0x58)};
    create_cpu();
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.address_registers[0] = UINT32_C(0x180);
    state.data_registers[0] = UINT32_C(0x12344000);
    state.sr = UINT16_C(0x271f);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
    memory.fail_read_on = memory.reads + 2u;

    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(100));
    TEST_ASSERT_EQUAL(OWNED_CPU_HOST_FAULT, result.reason);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100), result.fault_pc);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x8058), result.instruction_register);
    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
}

static void or_word_predecrement_odd_source_commits_before_vector_three(void) {
    const uint8_t program[] = {UINT8_C(0x80), UINT8_C(0x60)};
    create_cpu();
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    set_vector(12u, UINT32_C(0x140));
    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.address_registers[0] = UINT32_C(0x183);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));

    const size_t reads_before = memory.reads;
    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(50));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(50u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(0u, result.instructions);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100), result.fault_pc);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x8060), result.instruction_register);
    for (size_t read = reads_before; read < memory.reads; ++read)
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x181), memory.read_addresses[read]);
    owned_cpu_observation observation;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_UINT8(3u, observation.last_exception_vector);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x140), observation.pc);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x181), observation.address_registers[0]);
}

static void or_long_data_register_neighbors_stay_unsupported(void) {
    static const struct {
        uint8_t program[2];
        const char *name;
    } neighbors[] = {
        {{0x84, 0x3a}, "OR.B (PC),D2 (PC-relative source outside this slice)"},
        {{0x84, 0x3c}, "OR.B #imm,D2 (immediate source outside this slice)"},
        {{0x80, 0x7a}, "OR.W (d16,PC),D0 (PC-relative source outside this slice)"},
        {{0x80, 0x7c}, "OR.W #imm,D0 (immediate source outside this slice)"},
        {{0x84, 0xba}, "OR.L (PC),D2 (PC-relative source outside this slice)"},
    };
    for (size_t index = 0u; index < sizeof(neighbors) / sizeof(neighbors[0]); ++index) {
        memset(&memory, 0, sizeof(memory));
        create_cpu();
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(neighbors[index].program, 2u));
        owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(32));
        TEST_ASSERT_EQUAL_MESSAGE(OWNED_CPU_UNSUPPORTED_OPCODE, result.reason,
                                  neighbors[index].name);
        TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
        owned_cpu_destroy(cpu);
        cpu = NULL;
    }
}

/* Guest-observed encoding (05-20): MOVE.L #<data>,(An). PRM section 4 MOVE,
 * pp. 4-116 to 4-118 (high word then low word; N/Z from the long value, V/C
 * clear, X preserved, An unchanged); UM Rev. 9.1 Table 8-3 (p. 8-3): immediate
 * source to (An) destination 20(3/2): the fixture sees opcode plus two
 * immediate words (3 reads) and two word writes. */
static void move_long_immediate_to_address_indirect_writes_two_words_in_20_cycles(void) {
    static const struct {
        uint8_t program[6];
        unsigned address_register;
        uint32_t address;
        uint16_t sr_before;
        uint16_t sr_after;
    } cases[] = {
        {{0x2e, 0xbc, 0x89, 0xab, 0xcd, 0xef}, 7u, UINT32_C(0x1c0), UINT16_C(0x271f),
         UINT16_C(0x2718)},
        {{0x20, 0xbc, 0x00, 0x00, 0x00, 0x00}, 0u, UINT32_C(0x180), UINT16_C(0x2710),
         UINT16_C(0x2714)},
        {{0x24, 0xbc, 0x12, 0x34, 0x56, 0x78}, 2u, UINT32_C(0x1a0), UINT16_C(0x2703),
         UINT16_C(0x2700)},
    };
    for (size_t index = 0u; index < sizeof(cases) / sizeof(cases[0]); ++index) {
        memset(&memory, 0, sizeof(memory));
        create_cpu();
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(cases[index].program, 6u));
        owned_cpu_state state;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
        state.address_registers[cases[index].address_register] = cases[index].address;
        if (cases[index].address_register == 7u) state.ssp = cases[index].address;
        state.sr = cases[index].sr_before;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
        const size_t reads_before = memory.reads;
        owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(20));
        TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
        TEST_ASSERT_EQUAL_UINT64(20u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
        TEST_ASSERT_EQUAL_UINT(3u, memory.reads - reads_before);
        TEST_ASSERT_EQUAL_UINT(0u, memory.byte_reads);
        TEST_ASSERT_EQUAL_UINT(2u, memory.write_attempts);
        TEST_ASSERT_EQUAL_HEX32(cases[index].address, memory.write_addresses[0]);
        TEST_ASSERT_EQUAL_HEX32(cases[index].address + 2u, memory.write_addresses[1]);
        TEST_ASSERT_EQUAL_HEX16(((uint16_t)cases[index].program[2] << 8) | cases[index].program[3],
                                memory.write_values[0]);
        TEST_ASSERT_EQUAL_HEX16(((uint16_t)cases[index].program[4] << 8) | cases[index].program[5],
                                memory.write_values[1]);
        owned_cpu_observation observation;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
        TEST_ASSERT_EQUAL_HEX32(cases[index].address,
                                observation.address_registers[cases[index].address_register]);
        TEST_ASSERT_EQUAL_HEX16(cases[index].sr_after, observation.sr);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x106), observation.pc);
        owned_cpu_destroy(cpu);
        cpu = NULL;
    }
}

