    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x5678), memory.write_values[0]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x1c0), memory.write_addresses[1]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x1234), memory.write_values[1]);
