/* ANDI.W #imm,(An), required by the matched no-input guest continuation.
 * Table 8-5's 12-cycle memory base plus the word (An) EA cost of four clocks
 * gives 16 clocks; the operation clears N/Z/V/C as appropriate and preserves
 * X. */
static void andi_word_immediate_to_address_indirect_ands_in_16_cycles(void) {
    setUp();
    create_cpu();
    const uint8_t program[] = {0x02u, 0x50u, 0x80u, 0x01u};
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      reset_with_program(program, sizeof(program)));
    memory.rom[UINT32_C(0x180)] = UINT8_C(0x80);
    memory.rom[UINT32_C(0x181)] = UINT8_C(0x03);

    owned_cpu_state before;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_capture_state(cpu, &before));
    before.address_registers[0] = UINT32_C(0x180);
    before.sr = UINT16_C(0x2717);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_restore_state(cpu, &before));

    const size_t reads_before = memory.reads;
    const size_t writes_before = memory.write_attempts;
    const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(16));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(16u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
    TEST_ASSERT_EQUAL_UINT(reads_before + 3u, memory.reads);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                            memory.read_addresses[reads_before]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102),
                            memory.read_addresses[reads_before + 1u]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x180),
                            memory.read_addresses[reads_before + 2u]);
    TEST_ASSERT_EQUAL_UINT(writes_before + 1u, memory.write_attempts);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x180),
                            memory.write_addresses[writes_before]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x8001),
                            memory.write_values[writes_before]);
    owned_cpu_observation after;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2718), after.sr);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x104), after.pc);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x180), after.address_registers[0]);
    tearDown();
}

static void andi_byte_word_long_immediate_covers_data_alterable_memory_eas(void) {
    static const struct {
        unsigned mode;
        unsigned absolute_register;
        unsigned first_register;
        unsigned register_limit;
    } forms[] = {
        {2u, 0u, 0u, 8u}, /* (An) */
        {3u, 0u, 0u, 8u}, /* (An)+ */
        {4u, 0u, 0u, 8u}, /* -(An) */
        {5u, 0u, 0u, 8u}, /* d16(An) */
        {6u, 0u, 0u, 8u}, /* brief indexed */
        {7u, 0u, 0u, 1u}, /* absolute short */
        {7u, 1u, 1u, 2u}, /* absolute long */
    };
    static const uint32_t initial_values[] = {
        UINT32_C(0x00000000), UINT32_C(0x0000007f),
        UINT32_C(0x00000080), UINT32_C(0x7fffffff),
        UINT32_C(0xffffffff)};
    static const uint32_t immediate_values[] = {
        UINT32_C(0xffffffff), UINT32_C(0x00000000),
        UINT32_C(0x80808080), UINT32_C(0x0f0ff0f0),
        UINT32_C(0xa55aa55a)};
    static const uint8_t short_word_cycles[] = {
        4u, 4u, 6u, 8u, 10u, 8u, 12u};
    static const uint8_t long_cycles[] = {
        8u, 8u, 10u, 12u, 14u, 12u, 16u};
    size_t case_number = 0u;

    for (unsigned width_index = 0u; width_index < 3u; ++width_index) {
        const unsigned width = width_index == 0u ? 1u :
                               width_index == 1u ? 2u : 4u;
        const uint32_t mask = width == 4u ? UINT32_MAX :
            (UINT32_C(1) << (width * 8u)) - UINT32_C(1);
        const uint32_t sign_bit = UINT32_C(1) << (width * 8u - 1u);
        const unsigned immediate_words = width == 4u ? 2u : 1u;
        const unsigned size_field = width_index;

        for (size_t form_index = 0u;
             form_index < sizeof(forms) / sizeof(forms[0]); ++form_index) {
            for (unsigned ea_register = forms[form_index].first_register;
                 ea_register < forms[form_index].register_limit;
                 ++ea_register) {
                setUp();
                create_cpu();
                const uint32_t target = UINT32_C(0x0180) +
                    (uint32_t)(case_number % 8u) * UINT32_C(4) +
                    (width == 1u ? (uint32_t)(case_number & 1u) : 0u);
                const uint32_t initial =
                    initial_values[case_number %
                        (sizeof(initial_values) / sizeof(initial_values[0]))] &
                    mask;
                const uint32_t immediate =
                    immediate_values[(case_number / 3u + width_index) %
                        (sizeof(immediate_values) /
                         sizeof(immediate_values[0]))] & mask;
                const uint32_t expected_result = initial & immediate;
                uint8_t program[12] = {0};
                size_t length = 0u;
                const uint16_t opcode = (uint16_t)(UINT16_C(0x0200) |
                    (uint16_t)(size_field << 6) |
                    (uint16_t)(forms[form_index].mode << 3) |
                    (uint16_t)(forms[form_index].mode == 7u
                                   ? forms[form_index].absolute_register
                                   : ea_register));
                emit_word(program, &length, opcode);
                if (width == 4u) {
                    emit_word(program, &length, (uint16_t)(immediate >> 16));
                    emit_word(program, &length, (uint16_t)immediate);
                } else {
                    emit_word(program, &length, (uint16_t)immediate);
                }

                unsigned ea_extension_words = 0u;
                uint32_t initial_base = 0u;
                const unsigned step = width == 1u && ea_register == 7u
                    ? 2u : width;
                if (forms[form_index].mode == 5u) {
                    emit_word(program, &length, UINT16_C(0x0020));
                    ea_extension_words = 1u;
                    initial_base = target - UINT32_C(0x20);
                } else if (forms[form_index].mode == 6u) {
                    emit_word(program, &length, UINT16_C(0x1000)); /* D1.W */
                    ea_extension_words = 1u;
                    initial_base = target - UINT32_C(2);
                } else if (forms[form_index].mode == 7u &&
                           forms[form_index].absolute_register == 0u) {
                    emit_word(program, &length, (uint16_t)target);
                    ea_extension_words = 1u;
                } else if (forms[form_index].mode == 7u) {
                    emit_word(program, &length, (uint16_t)(target >> 16));
                    emit_word(program, &length, (uint16_t)target);
                    ea_extension_words = 2u;
                } else if (forms[form_index].mode == 4u) {
                    initial_base = target + (uint32_t)step;
                } else {
                    initial_base = target;
                }
                TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                  reset_with_program(program, length));

                owned_cpu_state before;
                TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                  owned_cpu_capture_state(cpu, &before));
                for (unsigned reg = 0u; reg < 8u; ++reg) {
                    before.data_registers[reg] =
                        UINT32_C(0x11220000) + (uint32_t)reg;
                    before.address_registers[reg] =
                        UINT32_C(0x0600) + (uint32_t)reg * UINT32_C(0x40);
                }
                before.data_registers[1] = UINT32_C(2); /* brief D1.W index */
                if (forms[form_index].mode < 7u)
                    before.address_registers[ea_register] = initial_base;
                before.ssp = before.address_registers[7];
                before.sr = UINT16_C(0x271f);
                TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                  owned_cpu_restore_state(cpu, &before));

                if (width == 1u) {
                    memory.rom[target] = (uint8_t)initial;
                } else if (width == 2u) {
                    memory.rom[target] = (uint8_t)(initial >> 8);
                    memory.rom[target + UINT32_C(1)] = (uint8_t)initial;
                } else {
                    memory.rom[target] = (uint8_t)(initial >> 24);
                    memory.rom[target + UINT32_C(1)] = (uint8_t)(initial >> 16);
                    memory.rom[target + UINT32_C(2)] = (uint8_t)(initial >> 8);
                    memory.rom[target + UINT32_C(3)] = (uint8_t)initial;
                }

                const size_t reads_before = memory.reads;
                const size_t byte_reads_before = memory.byte_reads;
                const size_t ordered_before = memory.ordered_read_count;
                const size_t writes_before = memory.write_attempts;
                const uint64_t expected_cycles =
                    (width == 4u ? UINT64_C(20) : UINT64_C(12)) +
                    (width == 4u ? long_cycles[form_index]
                                 : short_word_cycles[form_index]);
                const owned_cpu_run_result result =
                    owned_cpu_run(cpu, expected_cycles);
                TEST_ASSERT_EQUAL_MESSAGE(OWNED_CPU_BUDGET, result.reason,
                                          "legal ANDI memory EA must execute");
                TEST_ASSERT_EQUAL_UINT64(expected_cycles,
                                         result.elapsed_cycles);
                TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);

                const size_t fetched_words = 1u + immediate_words +
                                             ea_extension_words;
                TEST_ASSERT_EQUAL_UINT(reads_before + fetched_words +
                                           (width == 4u ? 2u : width == 2u ? 1u : 0u),
                                       memory.reads);
                TEST_ASSERT_EQUAL_UINT(byte_reads_before +
                                           (width == 1u ? 1u : 0u),
                                       memory.byte_reads);
                for (size_t word_index = 0u; word_index < fetched_words;
                     ++word_index) {
                    TEST_ASSERT_EQUAL_HEX32(
                        UINT32_C(0x100) + (uint32_t)word_index * UINT32_C(2),
                        memory.ordered_read_addresses[ordered_before + word_index]);
                    TEST_ASSERT_EQUAL_UINT8(
                        2u,
                        memory.ordered_read_widths[ordered_before + word_index]);
                }
                const size_t operand_order = ordered_before + fetched_words;
                if (width == 1u) {
                    TEST_ASSERT_EQUAL_HEX32(
                        target, memory.ordered_read_addresses[operand_order]);
                    TEST_ASSERT_EQUAL_UINT8(
                        1u, memory.ordered_read_widths[operand_order]);
                    TEST_ASSERT_EQUAL_HEX32(
                        target, memory.byte_read_addresses[byte_reads_before]);
                    TEST_ASSERT_EQUAL_UINT(writes_before + 1u,
                                           memory.write_attempts);
                    TEST_ASSERT_EQUAL_HEX32(
                        target, memory.byte_write_addresses[writes_before]);
                    TEST_ASSERT_EQUAL_HEX8(
                        (uint8_t)expected_result,
                        memory.byte_write_values[writes_before]);
                } else {
                    const unsigned operand_words = width == 4u ? 2u : 1u;
                    for (unsigned word = 0u; word < operand_words; ++word) {
                        TEST_ASSERT_EQUAL_HEX32(
                            target + (uint32_t)word * UINT32_C(2),
                            memory.ordered_read_addresses[operand_order + word]);
                        TEST_ASSERT_EQUAL_UINT8(
                            2u,
                            memory.ordered_read_widths[operand_order + word]);
                    }
                    const unsigned writes = width == 4u ? 2u : 1u;
                    TEST_ASSERT_EQUAL_UINT(writes_before + writes,
                                           memory.write_attempts);
                    for (unsigned word = 0u; word < writes; ++word) {
                        const uint16_t expected_word = width == 4u
                            ? (uint16_t)(expected_result >>
                                  (word == 0u ? 16u : 0u))
                            : (uint16_t)expected_result;
                        TEST_ASSERT_EQUAL_HEX32(
                            target + (uint32_t)word * UINT32_C(2),
                            memory.write_addresses[writes_before + word]);
                        TEST_ASSERT_EQUAL_HEX16(
                            expected_word, memory.write_values[writes_before + word]);
                    }
                }

                uint16_t expected_sr =
                    (uint16_t)(before.sr & (uint16_t)~UINT16_C(0x000f));
                if (expected_result == 0u)
                    expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0004));
                if ((expected_result & sign_bit) != 0u)
                    expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0008));
                owned_cpu_observation after;
                TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                  owned_cpu_observe(cpu, &after));
                TEST_ASSERT_EQUAL_HEX16(expected_sr, after.sr);
                TEST_ASSERT_EQUAL_HEX32(
                    UINT32_C(0x100) + (uint32_t)length, after.pc);
                for (unsigned reg = 0u; reg < 8u; ++reg) {
                    uint32_t expected_address = before.address_registers[reg];
                    if (forms[form_index].mode == 3u && reg == ea_register)
                        expected_address += (uint32_t)step;
                    else if (forms[form_index].mode == 4u && reg == ea_register)
                        expected_address -= (uint32_t)step;
                    TEST_ASSERT_EQUAL_HEX32(expected_address,
                                            after.address_registers[reg]);
                    TEST_ASSERT_EQUAL_HEX32(before.data_registers[reg],
                                            after.data_registers[reg]);
                }
                TEST_ASSERT_EQUAL_HEX32(after.address_registers[7], after.ssp);
                tearDown();
                ++case_number;
            }
        }
    }
}

/* ORI/EORI immediate-to-memory use the same instruction-extensions, EA,
 * width-limited read/modify/write, and CCR boundary as the established ANDI
 * family. Table 8-5 p. 8-5 supplies 12/20-cycle bases; Table 8-1 p. 8-2
 * supplies each data-alterable EA surcharge. */
static void ori_eori_byte_word_long_immediate_cover_all_data_alterable_memory_eas(void) {
    static const struct {
        unsigned mode;
        unsigned absolute_register;
        unsigned first_register;
        unsigned register_limit;
    } forms[] = {
        {2u, 0u, 0u, 8u}, /* (An) */
        {3u, 0u, 0u, 8u}, /* (An)+ */
        {4u, 0u, 0u, 8u}, /* -(An) */
        {5u, 0u, 0u, 8u}, /* d16(An) */
        {6u, 0u, 0u, 8u}, /* brief indexed */
        {7u, 0u, 0u, 1u}, /* absolute short */
        {7u, 1u, 1u, 2u}, /* absolute long */
    };
    static const uint32_t initial_values[] = {
        UINT32_C(0x00000000), UINT32_C(0x0000007f),
        UINT32_C(0x00000080), UINT32_C(0x7fffffff),
        UINT32_C(0xffffffff)};
    static const uint32_t immediate_values[] = {
        UINT32_C(0xffffffff), UINT32_C(0x00000000),
        UINT32_C(0x80808080), UINT32_C(0x0f0ff0f0),
        UINT32_C(0xa55aa55a)};
    static const uint8_t byte_word_ea_cycles[] = {
        4u, 4u, 6u, 8u, 10u, 8u, 12u};
    static const uint8_t long_ea_cycles[] = {
        8u, 8u, 10u, 12u, 14u, 12u, 16u};
    size_t case_number = 0u;

    for (unsigned operation = 0u; operation < 2u; ++operation) {
        const uint16_t opcode_family = operation == 0u
            ? UINT16_C(0x0000) : UINT16_C(0x0a00); /* ORI / EORI */
        for (unsigned width_index = 0u; width_index < 3u; ++width_index) {
            const unsigned width = width_index == 0u ? 1u :
                                   width_index == 1u ? 2u : 4u;
            const uint32_t mask = width == 4u ? UINT32_MAX :
                (UINT32_C(1) << (width * 8u)) - UINT32_C(1);
            const uint32_t sign_bit = UINT32_C(1) << (width * 8u - 1u);
            const unsigned immediate_words = width == 4u ? 2u : 1u;
            for (size_t form_index = 0u;
                 form_index < sizeof(forms) / sizeof(forms[0]);
                 ++form_index) {
                for (unsigned ea_register = forms[form_index].first_register;
                     ea_register < forms[form_index].register_limit;
                     ++ea_register, ++case_number) {
                    setUp();
                    create_cpu();
                    const uint32_t target = UINT32_C(0x0180) +
                        (uint32_t)(case_number % 8u) * UINT32_C(4) +
                        (width == 1u ? (uint32_t)(case_number & 1u) : 0u);
                    const uint32_t initial =
                        initial_values[case_number %
                            (sizeof(initial_values) / sizeof(initial_values[0]))] &
                        mask;
                    const uint32_t immediate =
                        immediate_values[(case_number / 3u + operation +
                                          width_index) %
                            (sizeof(immediate_values) /
                             sizeof(immediate_values[0]))] & mask;
                    const uint32_t expected_result = operation == 0u
                        ? (initial | immediate) & mask
                        : (initial ^ immediate) & mask;

                    uint8_t program[12] = {0};
                    size_t length = 0u;
                    const uint16_t ea = forms[form_index].mode == 7u
                        ? (uint16_t)(UINT16_C(0x38) |
                            forms[form_index].absolute_register)
                        : (uint16_t)((forms[form_index].mode << 3) |
                                     ea_register);
                    const uint16_t opcode = (uint16_t)(opcode_family |
                        (uint16_t)(width_index << 6) | ea);
                    emit_word(program, &length, opcode);
                    if (width == 4u) {
                        emit_word(program, &length,
                                  (uint16_t)(immediate >> 16));
                        emit_word(program, &length, (uint16_t)immediate);
                    } else {
                        emit_word(program, &length, (uint16_t)immediate);
                    }

                    unsigned ea_extension_words = 0u;
                    uint32_t initial_base = 0u;
                    const unsigned step = width == 1u && ea_register == 7u
                        ? 2u : width;
                    if (forms[form_index].mode == 5u) {
                        emit_word(program, &length, UINT16_C(0x0020));
                        ea_extension_words = 1u;
                        initial_base = target - UINT32_C(0x20);
                    } else if (forms[form_index].mode == 6u) {
                        emit_word(program, &length, UINT16_C(0x1000));
                        ea_extension_words = 1u;
                        initial_base = target - UINT32_C(2);
                    } else if (forms[form_index].mode == 7u &&
                               forms[form_index].absolute_register == 0u) {
                        emit_word(program, &length, (uint16_t)target);
                        ea_extension_words = 1u;
                    } else if (forms[form_index].mode == 7u) {
                        emit_word(program, &length,
                                  (uint16_t)(target >> 16));
                        emit_word(program, &length, (uint16_t)target);
                        ea_extension_words = 2u;
                    } else if (forms[form_index].mode == 4u) {
                        initial_base = target + (uint32_t)step;
                    } else {
                        initial_base = target;
                    }
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      reset_with_program(program, length));

                    owned_cpu_state before;
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      owned_cpu_capture_state(cpu, &before));
                    for (unsigned reg = 0u; reg < 8u; ++reg) {
                        before.data_registers[reg] =
                            UINT32_C(0x11220000) + (uint32_t)reg;
                        before.address_registers[reg] =
                            UINT32_C(0x0600) + (uint32_t)reg * UINT32_C(0x40);
                    }
                    before.data_registers[1] = UINT32_C(2); /* D1.W index */
                    if (forms[form_index].mode < 7u)
                        before.address_registers[ea_register] = initial_base;
                    before.ssp = before.address_registers[7];
                    before.sr = UINT16_C(0x271f);
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      owned_cpu_restore_state(cpu, &before));
                    for (unsigned byte = 0u; byte < width; ++byte)
                        memory.rom[target + byte] = (uint8_t)(initial >>
                            ((width - 1u - byte) * 8u));

                    const size_t reads_before = memory.reads;
                    const size_t byte_reads_before = memory.byte_reads;
                    const size_t ordered_before = memory.ordered_read_count;
                    const size_t writes_before = memory.write_attempts;
                    const uint64_t ea_cycles = width == 4u
                        ? long_ea_cycles[form_index]
                        : byte_word_ea_cycles[form_index];
                    const uint64_t cycles =
                        (width == 4u ? UINT64_C(20) : UINT64_C(12)) +
                        ea_cycles;
                    const owned_cpu_run_result result =
                        owned_cpu_run(cpu, cycles);
                    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
                    TEST_ASSERT_EQUAL_UINT64(cycles, result.elapsed_cycles);
                    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);

                    const size_t fetched_words = 1u + immediate_words +
                                                 ea_extension_words;
                    const unsigned operand_words = width == 4u ? 2u :
                                                   width == 2u ? 1u : 0u;
                    const size_t operand_reads = width == 1u ? 1u : operand_words;
                    TEST_ASSERT_EQUAL_UINT(
                        reads_before + fetched_words + operand_words,
                        memory.reads);
                    TEST_ASSERT_EQUAL_UINT(byte_reads_before +
                        (width == 1u ? 1u : 0u), memory.byte_reads);
                    TEST_ASSERT_EQUAL_UINT(ordered_before + fetched_words +
                        operand_reads, memory.ordered_read_count);
                    for (size_t word = 0u; word < fetched_words; ++word) {
                        TEST_ASSERT_EQUAL_HEX32(
                            UINT32_C(0x100) + (uint32_t)word * UINT32_C(2),
                            memory.ordered_read_addresses[ordered_before + word]);
                        TEST_ASSERT_EQUAL_UINT8(
                            2u, memory.ordered_read_widths[ordered_before + word]);
                    }
                    const size_t operand_order = ordered_before + fetched_words;
                    for (unsigned word = 0u; word < operand_words; ++word) {
                        TEST_ASSERT_EQUAL_HEX32(
                            target + (uint32_t)word * UINT32_C(2),
                            memory.ordered_read_addresses[operand_order + word]);
                        TEST_ASSERT_EQUAL_UINT8(
                            2u, memory.ordered_read_widths[operand_order + word]);
                    }
                    if (width == 1u) {
                        TEST_ASSERT_EQUAL_HEX32(
                            target, memory.ordered_read_addresses[operand_order]);
                        TEST_ASSERT_EQUAL_UINT8(
                            1u, memory.ordered_read_widths[operand_order]);
                        TEST_ASSERT_EQUAL_HEX32(
                            target, memory.byte_read_addresses[byte_reads_before]);
                        TEST_ASSERT_EQUAL_UINT(writes_before + 1u,
                                               memory.write_attempts);
                        TEST_ASSERT_EQUAL_UINT(writes_before + 1u,
                                               memory.successful_writes);
                        TEST_ASSERT_EQUAL_HEX32(
                            target, memory.byte_write_addresses[writes_before]);
                        TEST_ASSERT_EQUAL_HEX8(
                            (uint8_t)expected_result,
                            memory.byte_write_values[writes_before]);
                    } else {
                        const unsigned writes = width == 4u ? 2u : 1u;
                        TEST_ASSERT_EQUAL_UINT(writes_before + writes,
                                               memory.write_attempts);
                        TEST_ASSERT_EQUAL_UINT(writes_before + writes,
                                               memory.successful_writes);
                        for (unsigned word = 0u; word < writes; ++word) {
                            const uint16_t expected_word = width == 4u
                                ? (uint16_t)(expected_result >>
                                    (word == 0u ? 16u : 0u))
                                : (uint16_t)expected_result;
                            TEST_ASSERT_EQUAL_HEX32(
                                target + (uint32_t)word * UINT32_C(2),
                                memory.write_addresses[writes_before + word]);
                            TEST_ASSERT_EQUAL_HEX16(
                                expected_word,
                                memory.write_values[writes_before + word]);
                        }
                    }

                    uint16_t expected_sr = (uint16_t)(before.sr &
                        (uint16_t)~UINT16_C(0x000f));
                    if (expected_result == 0u)
                        expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0004));
                    if ((expected_result & sign_bit) != 0u)
                        expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0008));
                    owned_cpu_observation after;
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      owned_cpu_observe(cpu, &after));
                    TEST_ASSERT_EQUAL_HEX16(expected_sr, after.sr);
                    TEST_ASSERT_EQUAL_HEX32(
                        UINT32_C(0x100) + (uint32_t)length, after.pc);
                    for (unsigned reg = 0u; reg < 8u; ++reg) {
                        uint32_t expected_address = before.address_registers[reg];
                        if (forms[form_index].mode == 3u && reg == ea_register)
                            expected_address += (uint32_t)step;
                        else if (forms[form_index].mode == 4u &&
                                 reg == ea_register)
                            expected_address -= (uint32_t)step;
                        TEST_ASSERT_EQUAL_HEX32(
                            expected_address, after.address_registers[reg]);
                        TEST_ASSERT_EQUAL_HEX32(
                            before.data_registers[reg], after.data_registers[reg]);
                    }
                    TEST_ASSERT_EQUAL_HEX32(
                        after.address_registers[7], after.ssp);
                    tearDown();
                }
            }
        }
    }
}

static void logical_immediate_memory_preflight_and_host_faults_keep_boundaries(void) {
    setUp();
    create_cpu();
    const uint8_t overflow_program[] = {
        0x00u, 0xafu, 0x12u, 0x34u, 0x56u, 0x78u, 0x00u, 0x20u};
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(
        overflow_program, sizeof(overflow_program)));
    owned_cpu_state before;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
    before.address_registers[7] = UINT32_C(0x0170);
    before.ssp = UINT32_C(0x0170);
    before.data_registers[0] = UINT32_C(0x87654321);
    before.sr = UINT16_C(0x271f);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));
    const uint64_t prior_cycles = UINT64_MAX - UINT64_C(31);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_test_seed_counters(
        cpu, 0u, 0u, 0u, 0u, prior_cycles));
    const size_t words_before = memory.reads;
    const owned_cpu_run_result overflow = owned_cpu_run(cpu, UINT64_C(32));
    TEST_ASSERT_EQUAL(OWNED_CPU_COUNTER_OVERFLOW, overflow.reason);
    TEST_ASSERT_EQUAL_UINT64(0u, overflow.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(0u, overflow.instructions);
    TEST_ASSERT_EQUAL_UINT(words_before + 4u, memory.reads);
    for (unsigned word = 0u; word < 4u; ++word)
        TEST_ASSERT_EQUAL_HEX32(
            UINT32_C(0x100) + (uint32_t)word * UINT32_C(2),
            memory.read_addresses[words_before + word]);
    TEST_ASSERT_EQUAL_UINT(0u, memory.byte_reads);
    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
    owned_cpu_observation after;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100), after.pc);
    TEST_ASSERT_EQUAL_HEX32(before.address_registers[7],
                            after.address_registers[7]);
    TEST_ASSERT_EQUAL_HEX32(before.ssp, after.ssp);
    TEST_ASSERT_EQUAL_HEX32(before.data_registers[0],
                            after.data_registers[0]);
    TEST_ASSERT_EQUAL_HEX16(before.sr, after.sr);
    TEST_ASSERT_EQUAL_UINT64(prior_cycles, after.total_cycles);
    tearDown();

    setUp();
    create_cpu();
    const uint8_t byte_program[] = {
        0x00u, 0x2du, 0x00u, 0x8fu, 0x00u, 0x04u};
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      reset_with_program(byte_program, sizeof(byte_program)));
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
    before.address_registers[5] = UINT32_C(0x0180);
    before.sr = UINT16_C(0x271f);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));
    memory.rom[UINT32_C(0x0184)] = UINT8_C(0x40);
    memory.fail_byte_read_on = 1u;
    const owned_cpu_run_result read_fault = owned_cpu_run(cpu, UINT64_C(20));
    TEST_ASSERT_EQUAL(OWNED_CPU_HOST_FAULT, read_fault.reason);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0100), read_fault.fault_pc);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x002d),
                            read_fault.instruction_register);
    TEST_ASSERT_EQUAL_UINT(1u, memory.byte_reads);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0184),
                            memory.byte_read_addresses[0]);
    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
    owned_cpu_state after_read_fault;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_test_capture_faulted_state(
                          cpu, &after_read_fault));
    TEST_ASSERT_EQUAL_HEX16(before.sr, after_read_fault.sr);
    TEST_ASSERT_EQUAL_HEX32(before.address_registers[5],
                            after_read_fault.address_registers[5]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0100), after_read_fault.fault_pc);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x002d),
                            after_read_fault.instruction_register);
    tearDown();

    setUp();
    create_cpu();
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      reset_with_program(byte_program, sizeof(byte_program)));
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
    before.address_registers[5] = UINT32_C(0x0180);
    before.sr = UINT16_C(0x271f);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));
    memory.rom[UINT32_C(0x0184)] = UINT8_C(0x40);
    memory.fail_write_on = 1u;
    const owned_cpu_run_result write_fault = owned_cpu_run(cpu, UINT64_C(20));
    TEST_ASSERT_EQUAL(OWNED_CPU_HOST_FAULT, write_fault.reason);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0100), write_fault.fault_pc);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x002d),
                            write_fault.instruction_register);
    TEST_ASSERT_EQUAL_UINT(1u, memory.byte_reads);
    TEST_ASSERT_EQUAL_UINT(1u, memory.write_attempts);
    TEST_ASSERT_EQUAL_UINT(0u, memory.successful_writes);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0184),
                            memory.byte_write_addresses[0]);
    TEST_ASSERT_EQUAL_HEX8(UINT8_C(0xcf), memory.byte_write_values[0]);
    TEST_ASSERT_EQUAL_HEX8(UINT8_C(0x40), memory.rom[UINT32_C(0x0184)]);
    owned_cpu_state after_write_fault;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_test_capture_faulted_state(
                          cpu, &after_write_fault));
    TEST_ASSERT_EQUAL_HEX16(before.sr, after_write_fault.sr);
    TEST_ASSERT_EQUAL_HEX32(before.address_registers[5],
                            after_write_fault.address_registers[5]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0100), after_write_fault.fault_pc);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x002d),
                            after_write_fault.instruction_register);
    tearDown();
}

/* The brief index may name the same An that supplies the base; resolve the
 * effective address from that original register value and use the A-index
 * encoding rather than the D-index decoy. */
static void logical_immediate_memory_index_may_alias_address_base(void) {
    static const struct {
        uint16_t opcode;
        uint16_t immediate[2];
        uint16_t index_extension;
        unsigned address_register;
        uint32_t base;
        uint32_t target;
        uint32_t data_index_decoy;
        uint32_t initial;
        uint32_t expected;
        unsigned width;
        unsigned immediate_words;
        uint64_t cycles;
    } cases[] = {
        {UINT16_C(0x0072), {UINT16_C(0x000f), 0u}, UINT16_C(0xa004),
         2u, UINT32_C(0x0060), UINT32_C(0x00c4), UINT32_C(0x0001),
         UINT32_C(0x8001), UINT32_C(0x800f), 2u, 1u, UINT64_C(22)},
        {UINT16_C(0x0ab5), {UINT16_C(0x8000), 0u}, UINT16_C(0xd004),
         5u, UINT32_C(0x0040), UINT32_C(0x0084), UINT32_C(0x0003),
         UINT32_C(0x80000001), UINT32_C(0x00000001), 4u, 2u, UINT64_C(34)},
    };

    for (size_t index = 0u; index < sizeof(cases) / sizeof(cases[0]); ++index) {
        setUp();
        create_cpu();
        uint8_t program[10] = {0};
        size_t length = 0u;
        emit_word(program, &length, cases[index].opcode);
        for (unsigned word = 0u; word < cases[index].immediate_words; ++word)
            emit_word(program, &length, cases[index].immediate[word]);
        emit_word(program, &length, cases[index].index_extension);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          reset_with_program(program, length));

        owned_cpu_state before;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          owned_cpu_capture_state(cpu, &before));
        before.address_registers[cases[index].address_register] =
            cases[index].base;
        before.data_registers[cases[index].address_register] =
            cases[index].data_index_decoy;
        before.sr = UINT16_C(0x271f);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          owned_cpu_restore_state(cpu, &before));
        for (unsigned byte = 0u; byte < cases[index].width; ++byte)
            memory.rom[cases[index].target + byte] = (uint8_t)(
                cases[index].initial >>
                ((cases[index].width - 1u - byte) * 8u));
        memory.rom[cases[index].base + cases[index].data_index_decoy + 4u] =
            UINT8_C(0x5a);

        const size_t reads_before = memory.reads;
        const size_t writes_before = memory.write_attempts;
        const owned_cpu_run_result result =
            owned_cpu_run(cpu, cases[index].cycles);
        TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
        TEST_ASSERT_EQUAL_UINT64(cases[index].cycles, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
        const size_t program_words = 1u + cases[index].immediate_words + 1u;
        const unsigned operand_words = cases[index].width == 4u ? 2u : 1u;
        TEST_ASSERT_EQUAL_UINT(reads_before + program_words + operand_words,
                               memory.reads);
        TEST_ASSERT_EQUAL_HEX32(cases[index].target,
            memory.ordered_read_addresses[memory.ordered_read_count -
                                           operand_words]);
        TEST_ASSERT_EQUAL_UINT(writes_before + operand_words,
                               memory.write_attempts);
        for (unsigned word = 0u; word < operand_words; ++word) {
            const uint16_t expected_word = cases[index].width == 4u
                ? (uint16_t)(cases[index].expected >>
                             (word == 0u ? 16u : 0u))
                : (uint16_t)cases[index].expected;
            TEST_ASSERT_EQUAL_HEX32(cases[index].target + word * 2u,
                memory.write_addresses[writes_before + word]);
            TEST_ASSERT_EQUAL_HEX16(expected_word,
                memory.write_values[writes_before + word]);
        }
        owned_cpu_observation after;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
        TEST_ASSERT_EQUAL_HEX16(index == 0u ? UINT16_C(0x2718)
                                           : UINT16_C(0x2710), after.sr);
        TEST_ASSERT_EQUAL_HEX32(cases[index].base,
            after.address_registers[cases[index].address_register]);
        TEST_ASSERT_EQUAL_HEX32(cases[index].data_index_decoy,
            after.data_registers[cases[index].address_register]);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100) + (uint32_t)length,
                                after.pc);
        tearDown();
    }
}

static void andi_word_long_auto_update_commits_before_odd_vector_three(void) {
    static const struct {
        uint16_t postincrement_opcode;
        uint16_t predecrement_opcode;
        unsigned width;
    } forms[] = {
        {UINT16_C(0x0258), UINT16_C(0x0260), 2u}, /* ANDI.W */
        {UINT16_C(0x0298), UINT16_C(0x02a0), 4u}, /* ANDI.L */
    };
    const uint32_t odd_target = UINT32_C(0x01e1);

    for (size_t form = 0u; form < sizeof(forms) / sizeof(forms[0]); ++form) {
        for (unsigned predecrement = 0u; predecrement < 2u; ++predecrement) {
            setUp();
            create_cpu();
            uint8_t program[8] = {0};
            size_t length = 0u;
            emit_word(program, &length, predecrement != 0u
                ? forms[form].predecrement_opcode
                : forms[form].postincrement_opcode);
            if (forms[form].width == 2u) {
                emit_word(program, &length, UINT16_C(0x0001));
            } else {
                emit_word(program, &length, UINT16_C(0x0000));
                emit_word(program, &length, UINT16_C(0x0001));
            }
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              reset_with_program(program, length));
            set_vector(12u, UINT32_C(0x0140));

            owned_cpu_state before;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_capture_state(cpu, &before));
            before.address_registers[0] = predecrement != 0u
                ? odd_target + forms[form].width : odd_target;
            before.address_registers[7] = UINT32_C(0x0200);
            before.ssp = UINT32_C(0x0200);
            before.sr = UINT16_C(0x271f);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_restore_state(cpu, &before));

            const size_t reads_before = memory.reads;
            const size_t writes_before = memory.write_attempts;
            const owned_cpu_run_result result =
                owned_cpu_run(cpu, UINT64_C(50));
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
            TEST_ASSERT_EQUAL_UINT64(50u, result.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(0u, result.instructions);
            owned_cpu_observation after;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_observe(cpu, &after));
            TEST_ASSERT_EQUAL_UINT8(3u, after.last_exception_vector);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0140), after.pc);
            TEST_ASSERT_EQUAL_HEX32(
                predecrement != 0u ? odd_target
                                   : odd_target + forms[form].width,
                after.address_registers[0]);
            TEST_ASSERT_EQUAL_UINT(writes_before + 7u,
                                   memory.write_attempts);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x01f2),
                                    memory.write_addresses[writes_before + 6u]);
            TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x001d),
                                    memory.write_values[writes_before + 6u]);
            for (size_t read = reads_before;
                 read < memory.reads && read < ROM_SIZE; ++read) {
                TEST_ASSERT_NOT_EQUAL(odd_target, memory.read_addresses[read]);
                if (forms[form].width == 4u)
                    TEST_ASSERT_NOT_EQUAL(odd_target + UINT32_C(2),
                                          memory.read_addresses[read]);
            }
            tearDown();
        }
    }
}

static void andi_host_operand_faults_keep_postincrement_contract_and_context(void) {
    setUp();
    create_cpu();
    const uint8_t word_program[] = {0x02u, 0x58u, 0x12u, 0x34u};
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      reset_with_program(word_program, sizeof(word_program)));
    owned_cpu_state before;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_capture_state(cpu, &before));
    before.address_registers[0] = UINT32_C(0x0180);
    before.sr = UINT16_C(0x271f);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_restore_state(cpu, &before));
    const size_t reads_before = memory.reads;
    memory.fail_read_on = reads_before + 3u; /* opcode, immediate, operand */
    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(16));
    TEST_ASSERT_EQUAL(OWNED_CPU_HOST_FAULT, result.reason);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0100), result.fault_pc);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x0258), result.instruction_register);
    TEST_ASSERT_EQUAL_UINT(reads_before + 3u, memory.reads);
    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
    owned_cpu_state after_read_fault;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_test_capture_faulted_state(
        cpu, &after_read_fault));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0180),
                            after_read_fault.address_registers[0]);
    TEST_ASSERT_EQUAL_HEX16(before.sr, after_read_fault.sr);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0100), after_read_fault.fault_pc);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x0258),
                            after_read_fault.instruction_register);
    tearDown();

    setUp();
    create_cpu();
    const uint8_t long_program[] = {
        0x02u, 0x98u, 0xffu, 0xffu, 0x00u, 0x00u};
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      reset_with_program(long_program, sizeof(long_program)));
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_capture_state(cpu, &before));
    before.address_registers[0] = UINT32_C(0x0180);
    before.sr = UINT16_C(0x271f);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_restore_state(cpu, &before));
    memory.rom[UINT32_C(0x0180)] = UINT8_C(0x12);
    memory.rom[UINT32_C(0x0181)] = UINT8_C(0x34);
    memory.rom[UINT32_C(0x0182)] = UINT8_C(0x56);
    memory.rom[UINT32_C(0x0183)] = UINT8_C(0x78);
    memory.fail_write_on = 2u;
    result = owned_cpu_run(cpu, UINT64_C(28));
    TEST_ASSERT_EQUAL(OWNED_CPU_HOST_FAULT, result.reason);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0100), result.fault_pc);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x0298), result.instruction_register);
    TEST_ASSERT_EQUAL_UINT(2u, memory.write_attempts);
    TEST_ASSERT_EQUAL_UINT(1u, memory.successful_writes);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0180), memory.write_addresses[0]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x1234), memory.write_values[0]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0182), memory.write_addresses[1]);
    owned_cpu_state after_write_fault;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_test_capture_faulted_state(
        cpu, &after_write_fault));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0184),
                            after_write_fault.address_registers[0]);
    TEST_ASSERT_EQUAL_HEX16(before.sr, after_write_fault.sr);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0100), after_write_fault.fault_pc);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x0298),
                            after_write_fault.instruction_register);
    tearDown();
}

/* Guest-observed CLR.W (An). MC68000 PRM CLR pp. 4-73 to 4-74 explicitly
 * requires a memory read before clearing. UM Rev. 9.1 Table 8-6 p. 8-6 gives
 * memory CLR word 8(1/1)+; Table 8-1 p. 8-2 adds 4(1/0) for (An), totaling
 * 12(2/1), including one operand read and one word write. */
static void clr_word_address_indirect_reads_then_clears_all_bases_in_12_cycles(void) {
    for (unsigned base_register = 0u; base_register < 8u; ++base_register) {
        setUp();
        create_cpu();
        uint8_t program[] = {0x42u, (uint8_t)(0x50u | base_register)};
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          reset_with_program(program, sizeof(program)));
        const uint32_t destination =
            UINT32_C(0x0180) + (uint32_t)base_register * UINT32_C(4);
        memory.rom[destination] = UINT8_C(0x8a);
        memory.rom[destination + 1u] = UINT8_C(0x5f);
        owned_cpu_state before;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          owned_cpu_capture_state(cpu, &before));
        before.address_registers[base_register] = destination;
        if (base_register == 7u) before.ssp = destination;
        before.sr = UINT16_C(0x271f);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          owned_cpu_restore_state(cpu, &before));

        const size_t reads_before = memory.reads;
        const owned_cpu_run_result result =
            owned_cpu_run(cpu, UINT64_C(12));
        TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
        TEST_ASSERT_EQUAL_UINT64(12u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
        TEST_ASSERT_EQUAL_UINT(reads_before + 2u, memory.reads);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                                memory.read_addresses[reads_before]);
        TEST_ASSERT_EQUAL_HEX32(destination,
                                memory.read_addresses[reads_before + 1u]);
        TEST_ASSERT_EQUAL_UINT(1u, memory.write_attempts);
        TEST_ASSERT_EQUAL_UINT(1u, memory.successful_writes);
        TEST_ASSERT_EQUAL_HEX32(destination, memory.write_addresses[0]);
        TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x0000), memory.write_values[0]);

        owned_cpu_observation after;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          owned_cpu_observe(cpu, &after));
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102), after.pc);
        TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2714), after.sr);
        for (unsigned reg = 0u; reg < 8u; ++reg)
            TEST_ASSERT_EQUAL_HEX32(before.address_registers[reg],
                                    after.address_registers[reg]);
        TEST_ASSERT_EQUAL_HEX32(before.ssp, after.ssp);
        tearDown();
    }
}

