/* CMP.L Dm,Dn is a register-only compare: it updates N/Z/V/C, preserves X,
 * and leaves both operands unchanged (PRM §4 CMP pp. 4-75–4-76; UM Rev. 9.1
 * Table 8-4 p. 8-4: 6 clocks for long op<ea>,Dn with Dn source). */
static void cmp_long_data_register_pairs_set_flags_without_writing_operands(void) {
    static const uint32_t values[8] = {
        UINT32_C(0x00000000), UINT32_C(0x00000001),
        UINT32_C(0x7fffffff), UINT32_C(0x80000000),
        UINT32_C(0xffffffff), UINT32_C(0x80000001),
        UINT32_C(0x7ffffffe), UINT32_C(0x12345678)};
    for (unsigned destination_reg = 0u; destination_reg < 8u;
         ++destination_reg) {
        for (unsigned source_reg = 0u; source_reg < 8u; ++source_reg) {
            setUp();
            create_cpu();
            const uint16_t opcode = (uint16_t)(
                UINT16_C(0xb080) | (destination_reg << 9) | source_reg);
            const uint8_t program[] = {
                (uint8_t)(opcode >> 8), (uint8_t)opcode};
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              reset_with_program(program, sizeof(program)));
            owned_cpu_state before;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_capture_state(cpu, &before));
            for (unsigned reg = 0u; reg < 8u; ++reg)
                before.data_registers[reg] = values[reg];
            before.sr = ((destination_reg + source_reg) & 1u) != 0u
                ? UINT16_C(0x271f) : UINT16_C(0x2700);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_restore_state(cpu, &before));

            const uint32_t destination = values[destination_reg];
            const uint32_t source = values[source_reg];
            const uint32_t difference = destination - source;
            const int64_t signed_destination =
                (destination & UINT32_C(0x80000000)) != 0u
                ? (int64_t)destination - INT64_C(0x100000000)
                : (int64_t)destination;
            const int64_t signed_source =
                (source & UINT32_C(0x80000000)) != 0u
                ? (int64_t)source - INT64_C(0x100000000)
                : (int64_t)source;
            const int64_t signed_difference =
                signed_destination - signed_source;
            uint16_t expected_sr = (uint16_t)(before.sr &
                (uint16_t)~UINT16_C(0x000f));
            if ((difference & UINT32_C(0x80000000)) != 0u)
                expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0008));
            if (difference == 0u)
                expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0004));
            if (signed_difference < -INT64_C(2147483648) ||
                signed_difference > INT64_C(2147483647))
                expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0002));
            if (destination < source)
                expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0001));

            const size_t reads_before = memory.reads;
            const owned_cpu_run_result result =
                owned_cpu_run(cpu, UINT64_C(6));
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
            TEST_ASSERT_EQUAL_UINT64(6u, result.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
            TEST_ASSERT_EQUAL_UINT(reads_before + 1u, memory.reads);
            TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
            owned_cpu_observation after;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_observe(cpu, &after));
            for (unsigned reg = 0u; reg < 8u; ++reg) {
                TEST_ASSERT_EQUAL_HEX32(before.data_registers[reg],
                                        after.data_registers[reg]);
                TEST_ASSERT_EQUAL_HEX32(before.address_registers[reg],
                                        after.address_registers[reg]);
            }
            TEST_ASSERT_EQUAL_HEX16(expected_sr, after.sr);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0102), after.pc);
            tearDown();
        }
    }
}

static void bcc_word_uses_condition_flags_and_exact_timing(void) {
    create_cpu();
    const uint8_t program[] = {
        0x66u, 0x00u, 0x00u, 0x04u, /* BNE.w +4, taken when Z clear. */
        0x70u, 0x01u,
        0x70u, 0x02u,
        0x70u, 0x03u};
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.sr = UINT16_C(0x2710); /* X set, Z clear. */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
    /* MC68000 UM Rev. 9.1 Table 8-9 (p. 8-7): Bcc word taken 10(2/0), not
     * taken 12(2/0); the fixture sees opcode + displacement (2 reads). */
    size_t reads_before = memory.reads;
    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(10));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(10u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
    TEST_ASSERT_EQUAL_UINT(2u, memory.reads - reads_before);
    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
    owned_cpu_observation observation;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x106), observation.pc);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2710), observation.sr);

    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.sr = UINT16_C(0x2714); /* Z set: BNE not taken. */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
    reads_before = memory.reads;
    result = owned_cpu_run(cpu, UINT64_C(12));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(12u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
    TEST_ASSERT_EQUAL_UINT(2u, memory.reads - reads_before);
    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x104), observation.pc);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2714), observation.sr);

}

static void bcc_byte_uses_taken_and_not_taken_timing(void) {
    create_cpu();
    const uint8_t program[] = {0x66u, 0x04u}; /* BNE.s +4 */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.sr = UINT16_C(0x2710);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
    /* MC68000 UM Rev. 9.1 Table 8-9 (p. 8-7): Bcc byte taken 10(2/0), not
     * taken 8(1/0). Taken: the second Section 8 read is the target refill
     * the no-prefetch core does not perform (fixture: opcode only). */
    size_t reads_before = memory.reads;
    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(10));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(10u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
    TEST_ASSERT_EQUAL_UINT(1u, memory.reads - reads_before);
    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
    owned_cpu_observation observation;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x106), observation.pc);

    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.sr = UINT16_C(0x2714);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
    reads_before = memory.reads;
    result = owned_cpu_run(cpu, UINT64_C(8));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(8u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
    TEST_ASSERT_EQUAL_UINT(1u, memory.reads - reads_before);
    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102), observation.pc);
}

static void bra_byte_branches_unconditionally_in_10_cycles_and_leaves_flags(void) {
    create_cpu();
    /* PRM section 4 BRA: PC + 2 + sign-extended 8-bit displacement, condition
     * codes unaffected. MC68000 UM Rev. 9.1 Table 8-9 (p. 8-7): BRA byte
     * 10(2/0); the second read is the target refill the no-prefetch core does
     * not perform, so the fixture sees the opcode word read only. */
    static const struct {
        uint8_t displacement;
        uint32_t target;
    } cases[] = {{0x02u, UINT32_C(0x104)}, {0x7fu, UINT32_C(0x181)}, {0xfeu, UINT32_C(0x100)},
                 {0x80u, UINT32_C(0x082)}};
    static const uint16_t flags[] = {UINT16_C(0x2700), UINT16_C(0x271f), UINT16_C(0x2715)};
    for (size_t index = 0u; index < sizeof(cases) / sizeof(cases[0]); index++) {
        for (size_t flag = 0u; flag < sizeof(flags) / sizeof(flags[0]); flag++) {
            const uint8_t program[] = {0x60u, cases[index].displacement};
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
            owned_cpu_state state;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
            state.sr = flags[flag];
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
            const size_t reads_before = memory.reads;
            owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(10));
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
            TEST_ASSERT_EQUAL_UINT64(10u, result.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
            TEST_ASSERT_EQUAL_UINT(1u, memory.reads - reads_before);
            TEST_ASSERT_EQUAL_UINT(0u, memory.byte_reads);
            TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
            owned_cpu_observation observation;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
            TEST_ASSERT_EQUAL_HEX32(cases[index].target, observation.pc);
            TEST_ASSERT_EQUAL_HEX16(flags[flag], observation.sr);
        }
    }
}

static void bra_word_uses_signed_extension_and_10_cycles(void) {
    static const struct {
        uint16_t displacement;
        uint32_t target;
    } cases[] = {
        {UINT16_C(0x0008), UINT32_C(0x10a)},
        {UINT16_C(0xfffc), UINT32_C(0x0fe)},
    };
    static const uint16_t flags[] = {
        UINT16_C(0x2700), UINT16_C(0x271f), UINT16_C(0x2715)};
    create_cpu();
    for (size_t index = 0u; index < sizeof(cases) / sizeof(cases[0]); ++index) {
        for (size_t flag = 0u; flag < sizeof(flags) / sizeof(flags[0]); ++flag) {
            const uint8_t program[] = {
                0x60u, 0x00u, /* BRA.W */
                (uint8_t)(cases[index].displacement >> 8),
                (uint8_t)cases[index].displacement};
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
            owned_cpu_state before;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
            before.sr = flags[flag];
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));

            const size_t reads_before = memory.reads;
            const size_t writes_before = memory.write_attempts;
            const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(10));
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
            TEST_ASSERT_EQUAL_UINT64(10u, result.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
            TEST_ASSERT_EQUAL_UINT(2u, memory.reads - reads_before);
            TEST_ASSERT_EQUAL_UINT(writes_before, memory.write_attempts);

            owned_cpu_observation after;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
            TEST_ASSERT_EQUAL_HEX32(cases[index].target, after.pc);
            TEST_ASSERT_EQUAL_HEX16(flags[flag], after.sr);
            for (unsigned reg = 0u; reg < 8u; ++reg) {
                TEST_ASSERT_EQUAL_HEX32(before.data_registers[reg], after.data_registers[reg]);
                TEST_ASSERT_EQUAL_HEX32(before.address_registers[reg], after.address_registers[reg]);
            }
        }
    }
}

