/* MC68000 ADDQ/SUBQ word and long address-register forms use the full 32-bit
 * An regardless of the encoded size, leave SR unchanged, and fetch only the
 * opcode. PRM §4 ADDQ pp. 4-11–4-12 and SUBQ pp. 4-181–4-182; UM Rev. 9.1
 * Table 8-5 p. 8-5. The ADDQ.W An timing differs between the Motorola table
 * (4) and Rockwell R68000 Data Book Table 27 (8); this owned slice follows the
 * Rockwell 8-cycle row, while keeping the hardware timing claim qualified. */
static void quick_address_register_word_long_forms_use_full_width_and_preserve_ccr(void) {
    static const struct {
        unsigned subtract;
        unsigned size_code;
        uint64_t cycles;
    } forms[] = {
        {0u, 1u, UINT64_C(8)}, {0u, 2u, UINT64_C(8)},
        {1u, 1u, UINT64_C(8)}, {1u, 2u, UINT64_C(8)},
    };

    for (size_t form_index = 0u;
         form_index < sizeof(forms) / sizeof(forms[0]); ++form_index) {
        for (unsigned quick = 1u; quick <= 8u; ++quick) {
            for (unsigned reg = 0u; reg < 8u; ++reg) {
                setUp();
                create_cpu();
                const uint16_t opcode = (uint16_t)(UINT16_C(0x5008) |
                    (uint16_t)(forms[form_index].subtract << 8) |
                    (uint16_t)((quick & 7u) << 9) |
                    (uint16_t)(forms[form_index].size_code << 6) |
                    (uint16_t)reg);
                uint8_t program[2];
                size_t length = 0u;
                emit_word(program, &length, opcode);
                TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                    reset_with_program(program, length));

                owned_cpu_state before;
                TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                    owned_cpu_capture_state(cpu, &before));
                for (unsigned other = 0u; other < 8u; ++other)
                    before.address_registers[other] =
                        UINT32_C(0x55660000) | (uint32_t)(other * 16u);
                uint32_t initial;
                if (forms[form_index].subtract != 0u)
                    initial = reg == 7u && quick == 8u
                        ? UINT32_C(0)
                        : UINT32_C(0x12340000) + reg;
                else
                    initial = reg == 7u && quick == 8u
                        ? UINT32_C(0xfffffff8)
                        : UINT32_C(0x1234fff8) + reg;
                before.address_registers[reg] = initial;
                before.sr = UINT16_C(0x271f);
                before.ssp = before.address_registers[7];
                TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                    owned_cpu_restore_state(cpu, &before));

                const size_t reads_before = memory.reads;
                const owned_cpu_run_result result =
                    owned_cpu_run(cpu, forms[form_index].cycles);
                TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
                TEST_ASSERT_EQUAL_UINT64(forms[form_index].cycles,
                                         result.elapsed_cycles);
                TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
                TEST_ASSERT_EQUAL_UINT(reads_before + 1u, memory.reads);
                TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                    memory.read_addresses[reads_before]);
                TEST_ASSERT_EQUAL_UINT(0u, memory.byte_reads);
                TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);

                const uint32_t expected = forms[form_index].subtract != 0u
                    ? initial - (uint32_t)quick
                    : initial + (uint32_t)quick;
                owned_cpu_state after;
                TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                    owned_cpu_capture_state(cpu, &after));
                TEST_ASSERT_EQUAL_HEX32(expected,
                    after.address_registers[reg]);
                TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102), after.pc);
                TEST_ASSERT_EQUAL_HEX16(before.sr, after.sr);
                for (unsigned other = 0u; other < 8u; ++other) {
                    if (other != reg)
                        TEST_ASSERT_EQUAL_HEX32(before.address_registers[other],
                            after.address_registers[other]);
                }
                tearDown();
            }
        }
    }
}

static void quick_address_register_counter_overflow_preflight_is_atomic(void) {
    static const struct {
        uint16_t opcode;
        uint64_t cycles;
    } cases[] = {
        {UINT16_C(0x504f), UINT64_C(8)}, /* ADDQ.W #8,A7 */
        {UINT16_C(0x588f), UINT64_C(8)}, /* ADDQ.L #4,A7 */
        {UINT16_C(0x514f), UINT64_C(8)}, /* SUBQ.W #8,A7 */
        {UINT16_C(0x598f), UINT64_C(8)}, /* SUBQ.L #4,A7 */
    };
    for (size_t index = 0u; index < sizeof(cases) / sizeof(cases[0]); ++index) {
        setUp();
        create_cpu();
        uint8_t program[2];
        size_t length = 0u;
        emit_word(program, &length, cases[index].opcode);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
            reset_with_program(program, length));
        owned_cpu_state before;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
            owned_cpu_capture_state(cpu, &before));
        before.address_registers[7] = UINT32_C(0x12345678);
        before.ssp = UINT32_C(0x12345678);
        before.sr = UINT16_C(0x271f);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
            owned_cpu_restore_state(cpu, &before));
        const size_t reads_before = memory.reads;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
            owned_cpu_test_seed_counters(cpu, 0u, 0u, 0u, 0u,
                UINT64_MAX - (cases[index].cycles - UINT64_C(1))));

        const owned_cpu_run_result result =
            owned_cpu_run(cpu, cases[index].cycles);
        TEST_ASSERT_EQUAL(OWNED_CPU_COUNTER_OVERFLOW, result.reason);
        TEST_ASSERT_EQUAL_UINT64(0u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(0u, result.instructions);
        TEST_ASSERT_EQUAL_UINT(reads_before + 1u, memory.reads);
        TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);

        owned_cpu_observation after;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
            owned_cpu_observe(cpu, &after));
        TEST_ASSERT_EQUAL_HEX32(before.address_registers[7],
                                after.address_registers[7]);
        TEST_ASSERT_EQUAL_HEX32(before.ssp, after.ssp);
        TEST_ASSERT_EQUAL_HEX16(before.sr, after.sr);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100), after.pc);
        tearDown();
    }
}

static void quick_address_register_a7_updates_only_the_active_stack_bank(void) {
    static const struct {
        uint16_t opcode;
        int32_t delta;
    } forms[] = {
        {UINT16_C(0x504f), INT32_C(8)},  /* ADDQ.W #8,A7 */
        {UINT16_C(0x588f), INT32_C(4)},  /* ADDQ.L #4,A7 */
        {UINT16_C(0x514f), -INT32_C(8)}, /* SUBQ.W #8,A7 */
        {UINT16_C(0x598f), -INT32_C(4)}, /* SUBQ.L #4,A7 */
    };
    const uint32_t active_before = UINT32_C(0x12345678);
    const uint32_t inactive_supervisor = UINT32_C(0x87654320);
    const uint32_t inactive_user = UINT32_C(0xabcdef00);

    for (unsigned user_mode = 0u; user_mode < 2u; ++user_mode) {
        for (size_t index = 0u; index < sizeof(forms) / sizeof(forms[0]); ++index) {
            setUp();
            create_cpu();
            uint8_t program[2];
            size_t length = 0u;
            emit_word(program, &length, forms[index].opcode);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                reset_with_program(program, length));

            owned_cpu_state before;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                owned_cpu_capture_state(cpu, &before));
            before.sr = user_mode != 0u ? UINT16_C(0x001f)
                                        : UINT16_C(0x271f);
            before.address_registers[7] = active_before;
            before.ssp = user_mode != 0u
                ? inactive_user : active_before;
            before.usp = user_mode != 0u
                ? active_before : inactive_supervisor;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                owned_cpu_restore_state(cpu, &before));

            const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(8));
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
            TEST_ASSERT_EQUAL_UINT64(8u, result.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);

            const uint32_t expected_active = forms[index].delta < 0
                ? active_before - (uint32_t)(-forms[index].delta)
                : active_before + (uint32_t)forms[index].delta;
            owned_cpu_observation after;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                owned_cpu_observe(cpu, &after));
            TEST_ASSERT_EQUAL_HEX32(expected_active,
                after.address_registers[7]);
            TEST_ASSERT_EQUAL_HEX32(user_mode != 0u
                    ? inactive_user : expected_active,
                after.ssp);
            TEST_ASSERT_EQUAL_HEX32(user_mode != 0u
                    ? expected_active : inactive_supervisor,
                after.usp);
            TEST_ASSERT_EQUAL_HEX16(before.sr, after.sr);
            tearDown();
        }
    }
}

static void move_word_address_register_to_data_register_preserves_upper_word(void) {
    create_cpu();
    const uint8_t program[] = {0x38u, 0x0bu}; /* MOVE.W A3,D4 */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.address_registers[3] = UINT32_C(0x12348001);
    state.data_registers[4] = UINT32_C(0xabcdffff);
    state.sr = UINT16_C(0x2718);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(4));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(4u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
    owned_cpu_observation observation;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x12348001), observation.address_registers[3]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0xabcd8001), observation.data_registers[4]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2718), observation.sr);

    const uint8_t unsupported_memory_destination[] = {0x30u, 0x88u};
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(
        unsupported_memory_destination, sizeof(unsupported_memory_destination)));
    result = owned_cpu_run(cpu, UINT64_C(4));
    TEST_ASSERT_EQUAL(OWNED_CPU_UNSUPPORTED_OPCODE, result.reason);
}

