/* JMP brief-indexed control EAs resolve d8 + signed word/long index from
 * either An or the extension-word PC base. The target is not fetched until a
 * later CPU step. */
static void jmp_brief_indexed_address_and_pc_control_eas_set_pc_in_14_cycles(void) {
    static const struct {
        uint8_t opcode_low;
        uint16_t extension;
        unsigned index_address_register;
        unsigned index_register;
        unsigned base_register;
        uint32_t index_value;
        uint32_t expected_pc;
    } cases[] = {
        /* D0.W = -2, d8 = -4; vary every An base. */
        {0xf0u, 0x00fcu, 0u, 0u, 0u, UINT32_C(0x0000fffe), UINT32_C(0x000002fa)},
        {0xf1u, 0x00fcu, 0u, 0u, 1u, UINT32_C(0x0000fffe), UINT32_C(0x0000030a)},
        {0xf2u, 0x00fcu, 0u, 0u, 2u, UINT32_C(0x0000fffe), UINT32_C(0x0000031a)},
        {0xf3u, 0x00fcu, 0u, 0u, 3u, UINT32_C(0x0000fffe), UINT32_C(0x0000032a)},
        {0xf4u, 0x00fcu, 0u, 0u, 4u, UINT32_C(0x0000fffe), UINT32_C(0x0000033a)},
        {0xf5u, 0x00fcu, 0u, 0u, 5u, UINT32_C(0x0000fffe), UINT32_C(0x0000034a)},
        {0xf6u, 0x00fcu, 0u, 0u, 6u, UINT32_C(0x0000fffe), UINT32_C(0x0000035a)},
        /* A7 is both base and full-long index; restoration keeps SSP paired. */
        {0xf7u, 0xf8feu, 1u, 7u, 7u, UINT32_C(0x00000300), UINT32_C(0x000005fe)},
        /* PC base is the extension word at 0x102; D2.L is positive. */
        {0xfbu, 0x28fcu, 0u, 2u, 0u, UINT32_C(0x00010000), UINT32_C(0x000100fe)},
        /* A6.W = -2, d8 = +127, from the PC extension-word base. */
        {0xfbu, 0xe07fu, 1u, 6u, 0u, UINT32_C(0x0000fffe), UINT32_C(0x0000017f)},
    };

    for (size_t item = 0u; item < sizeof(cases) / sizeof(cases[0]); ++item) {
        memset(&memory, 0, sizeof(memory));
        create_cpu();
        const uint8_t program[] = {
            0x4eu, cases[item].opcode_low,
            (uint8_t)(cases[item].extension >> 8),
            (uint8_t)cases[item].extension};
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));

        owned_cpu_state before;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
        for (unsigned reg = 0u; reg < 8u; ++reg) {
            before.data_registers[reg] = UINT32_C(0x51000000) + reg;
            before.address_registers[reg] = UINT32_C(0x00000300) + reg * 16u;
        }
        if (cases[item].index_address_register != 0u) {
            before.address_registers[cases[item].index_register] =
                cases[item].index_value;
        } else {
            before.data_registers[cases[item].index_register] =
                cases[item].index_value;
        }
        if ((cases[item].opcode_low & 0xf8u) == 0xf0u) {
            TEST_ASSERT_EQUAL_UINT(cases[item].base_register,
                                   (unsigned)(cases[item].opcode_low & 7u));
        }
        /* Every matrix case assigns all An registers, so keep active SSP in
         * sync even when A7 is not the selected EA base. */
        before.ssp = before.address_registers[7];
        before.sr = UINT16_C(0x271f);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));

        const size_t reads_before = memory.reads;
        const size_t writes_before = memory.write_attempts;
        const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(14));
        TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
        TEST_ASSERT_EQUAL_UINT64(14u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
        TEST_ASSERT_EQUAL_UINT(reads_before + 2u, memory.reads);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100), memory.read_addresses[reads_before]);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102), memory.read_addresses[reads_before + 1u]);
        TEST_ASSERT_EQUAL_UINT(writes_before, memory.write_attempts);

        owned_cpu_state after;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &after));
        TEST_ASSERT_EQUAL_HEX32(cases[item].expected_pc, after.pc);
        TEST_ASSERT_EQUAL_HEX16(before.sr, after.sr);
        for (unsigned reg = 0u; reg < 8u; ++reg) {
            TEST_ASSERT_EQUAL_HEX32(before.data_registers[reg], after.data_registers[reg]);
            TEST_ASSERT_EQUAL_HEX32(before.address_registers[reg], after.address_registers[reg]);
        }
        TEST_ASSERT_EQUAL_HEX32(before.ssp, after.ssp);
        owned_cpu_destroy(cpu);
        cpu = NULL;
    }
}

static void jmp_brief_indexed_full_extensions_and_noncontrol_eas_stay_unsupported(void) {
    static const uint8_t an_full_extension[] = {0x4eu, 0xf0u, 0x07u, 0x00u};
    static const uint8_t pc_full_extension[] = {0x4eu, 0xfbu, 0x07u, 0x00u};
    assert_unobserved_encoding_has_no_side_effect_after_fetches(
        an_full_extension, sizeof(an_full_extension), 2u);
    assert_unobserved_encoding_has_no_side_effect_after_fetches(
        pc_full_extension, sizeof(pc_full_extension), 2u);

    static const struct { uint8_t program[2]; const char *name; } neighbors[] = {
        {{0x4eu, 0xc0u}, "JMP D0"},
        {{0x4eu, 0xc8u}, "JMP A0"},
        {{0x4eu, 0xd8u}, "JMP (A0)+"},
        {{0x4eu, 0xe0u}, "JMP -(A0)"},
    };
    for (size_t index = 0u; index < sizeof(neighbors) / sizeof(neighbors[0]); ++index) {
        memset(&memory, 0, sizeof(memory));
        create_cpu();
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          reset_with_program(neighbors[index].program, 2u));
        const size_t reads_before = memory.reads;
        const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(14));
        TEST_ASSERT_EQUAL_MESSAGE(OWNED_CPU_UNSUPPORTED_OPCODE, result.reason,
                                  neighbors[index].name);
        TEST_ASSERT_EQUAL_UINT64(0u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(0u, result.instructions);
        TEST_ASSERT_EQUAL_UINT(reads_before + 1u, memory.reads);
        TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
        owned_cpu_destroy(cpu);
        cpu = NULL;
    }
}

static void jmp_brief_indexed_odd_target_faults_on_the_later_fetch(void) {
    static const uint8_t program[] = {0x4eu, 0xf0u, 0x00u, 0x01u};
    memset(&memory, 0, sizeof(memory));
    create_cpu();
    set_vector(12u, UINT32_C(0x0140));
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      reset_with_program(program, sizeof(program)));
    owned_cpu_state before;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
    before.address_registers[0] = UINT32_C(0x0180);
    before.data_registers[0] = 0u;
    before.sr = UINT16_C(0x271f);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));

    const size_t reads_before = memory.reads;
    const size_t writes_before = memory.write_attempts;
    const owned_cpu_run_result jump = owned_cpu_run(cpu, UINT64_C(14));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, jump.reason);
    TEST_ASSERT_EQUAL_UINT64(14u, jump.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(1u, jump.instructions);
    TEST_ASSERT_EQUAL_UINT(reads_before + 2u, memory.reads);
    TEST_ASSERT_EQUAL_UINT(writes_before, memory.write_attempts);
    owned_cpu_observation after_jump;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after_jump));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0181), after_jump.pc);
    TEST_ASSERT_EQUAL_HEX16(before.sr, after_jump.sr);

    (void)owned_cpu_run(cpu, UINT64_C(50));
    owned_cpu_observation after_fetch;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after_fetch));
    TEST_ASSERT_EQUAL_UINT8(3u, after_fetch.last_exception_vector);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0140), after_fetch.pc);
}

static void jmp_brief_indexed_extension_fault_and_counter_preflight_keep_context(void) {
    static const uint8_t program[] = {0x4eu, 0xf0u, 0x00u, 0x04u};
    memset(&memory, 0, sizeof(memory));
    create_cpu();
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      reset_with_program(program, sizeof(program)));
    size_t reads_before = memory.reads;
    memory.fail_read_on = reads_before + 2u; /* the brief extension fetch */
    owned_cpu_run_result fault = owned_cpu_run(cpu, UINT64_C(14));
    TEST_ASSERT_EQUAL(OWNED_CPU_HOST_FAULT, fault.reason);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0100), fault.fault_pc);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x4ef0), fault.instruction_register);
    TEST_ASSERT_EQUAL_UINT(reads_before + 2u, memory.reads);
    const size_t reads_after_fault = memory.reads;
    fault = owned_cpu_run(cpu, UINT64_C(14));
    TEST_ASSERT_EQUAL(OWNED_CPU_HOST_FAULT, fault.reason);
    TEST_ASSERT_EQUAL_UINT(reads_after_fault, memory.reads);

    memset(&memory, 0, sizeof(memory));
    create_cpu();
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      reset_with_program(program, sizeof(program)));
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_test_seed_counters(
        cpu, UINT64_MAX, 0u, 0u, 0u, 0u));
    reads_before = memory.reads;
    const owned_cpu_run_result overflow = owned_cpu_run(cpu, UINT64_C(14));
    TEST_ASSERT_EQUAL(OWNED_CPU_COUNTER_OVERFLOW, overflow.reason);
    TEST_ASSERT_EQUAL_UINT64(0u, overflow.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(0u, overflow.instructions);
    TEST_ASSERT_EQUAL_UINT(reads_before + 2u, memory.reads);
    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
    owned_cpu_observation after;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0100), after.pc);
}

