/* Guest-observed continuation form: JMP (d16,An). The displacement is relative
 * to An, condition codes and address registers stay unchanged, and the target
 * instruction is fetched only by a later CPU step. */
static void jmp_address_displacement_sets_pc_for_all_bases_in_10_cycles(void) {
    static const uint16_t displacements[] = {
        UINT16_C(0x0008), UINT16_C(0xfffc),
        UINT16_C(0x8000), UINT16_C(0x7fff)};
    for (unsigned reg = 0u; reg < 8u; ++reg) {
        for (size_t index = 0u;
             index < sizeof(displacements) / sizeof(displacements[0]); ++index) {
            memset(&memory, 0, sizeof(memory));
            create_cpu();
            const uint8_t program[] = {
                0x4eu, (uint8_t)(0xe8u | reg),
                (uint8_t)(displacements[index] >> 8),
                (uint8_t)displacements[index]};
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              reset_with_program(program, sizeof(program)));
            owned_cpu_state before;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_capture_state(cpu, &before));
            for (unsigned address_register = 0u;
                 address_register < 8u; ++address_register) {
                before.address_registers[address_register] =
                    UINT32_C(0x0200) + (uint32_t)address_register * 16u;
                before.data_registers[address_register] =
                    UINT32_C(0xa5000000) + address_register;
            }
            before.ssp = before.address_registers[7];
            before.sr = UINT16_C(0x271f);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_restore_state(cpu, &before));

            const uint32_t expected_target =
                before.address_registers[reg] +
                expected_sign_extend_word(displacements[index]);
            const size_t reads_before = memory.reads;
            const size_t writes_before = memory.write_attempts;
            const owned_cpu_run_result result =
                owned_cpu_run(cpu, UINT64_C(10));
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
            TEST_ASSERT_EQUAL_UINT64(10u, result.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
            TEST_ASSERT_EQUAL_UINT(reads_before + 2u, memory.reads);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                                    memory.read_addresses[reads_before]);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102),
                                    memory.read_addresses[reads_before + 1u]);
            TEST_ASSERT_EQUAL_UINT(writes_before, memory.write_attempts);

            owned_cpu_state after;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_capture_state(cpu, &after));
            TEST_ASSERT_EQUAL_HEX32(expected_target, after.pc);
            TEST_ASSERT_EQUAL_HEX16(before.sr, after.sr);
            TEST_ASSERT_EQUAL_HEX32(before.ssp, after.ssp);
            for (unsigned address_register = 0u;
                 address_register < 8u; ++address_register) {
                TEST_ASSERT_EQUAL_HEX32(before.address_registers[address_register],
                    after.address_registers[address_register]);
                TEST_ASSERT_EQUAL_HEX32(before.data_registers[address_register],
                    after.data_registers[address_register]);
            }
            owned_cpu_destroy(cpu);
            cpu = NULL;
        }
    }
}

static void jmp_address_displacement_defers_odd_target_error_to_next_fetch(void) {
    static const uint8_t program[] = {
        0x4eu, 0xedu, 0x00u, 0x00u}; /* JMP (d16,A5) */
    memset(&memory, 0, sizeof(memory));
    create_cpu();
    set_vector(12u, UINT32_C(0x140)); /* vector 3 table byte offset */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      reset_with_program(program, sizeof(program)));
    owned_cpu_state before;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
    before.address_registers[5] = UINT32_C(0x0181);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));

    const size_t reads_before = memory.reads;
    const size_t writes_before = memory.write_attempts;
    const owned_cpu_run_result jump = owned_cpu_run(cpu, UINT64_C(10));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, jump.reason);
    TEST_ASSERT_EQUAL_UINT64(10u, jump.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(1u, jump.instructions);
    TEST_ASSERT_EQUAL_UINT(reads_before + 2u, memory.reads);
    TEST_ASSERT_EQUAL_UINT(writes_before, memory.write_attempts);
    owned_cpu_observation after_jump;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after_jump));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0181), after_jump.pc);

    (void)owned_cpu_run(cpu, UINT64_C(50));
    owned_cpu_observation after_fetch;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after_fetch));
    TEST_ASSERT_EQUAL_UINT8(3u, after_fetch.last_exception_vector);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x140), after_fetch.pc);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0181), after_fetch.address_registers[5]);
    owned_cpu_destroy(cpu);
    cpu = NULL;
}

static void jmp_pc_displacement_uses_extension_word_base_and_10_cycles(void) {
    static const struct {
        uint16_t displacement;
        uint32_t expected_pc;
    } cases[] = {
        {UINT16_C(0x0008), UINT32_C(0x10a)},
        {UINT16_C(0xfffc), UINT32_C(0x0fe)},
    };
    for (size_t index = 0u; index < sizeof(cases) / sizeof(cases[0]); ++index) {
        memset(&memory, 0, sizeof(memory));
        create_cpu();
        const uint8_t program[] = {
            0x4eu, 0xfau, /* JMP (d16,PC) */
            (uint8_t)(cases[index].displacement >> 8),
            (uint8_t)cases[index].displacement};
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));

        owned_cpu_state before;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
        before.sr = UINT16_C(0x271f);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));

        const size_t reads_before = memory.reads;
        const size_t writes_before = memory.write_attempts;
        const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(10));
        TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
        TEST_ASSERT_EQUAL_UINT64(10u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
        TEST_ASSERT_EQUAL_UINT(2u, memory.reads - reads_before);
        TEST_ASSERT_EQUAL_UINT(writes_before, memory.write_attempts);

        owned_cpu_observation after;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
        TEST_ASSERT_EQUAL_HEX32(cases[index].expected_pc, after.pc);
        TEST_ASSERT_EQUAL_HEX16(before.sr, after.sr);
        for (unsigned reg = 0u; reg < 8u; ++reg) {
            TEST_ASSERT_EQUAL_HEX32(before.data_registers[reg], after.data_registers[reg]);
            TEST_ASSERT_EQUAL_HEX32(before.address_registers[reg], after.address_registers[reg]);
        }
        owned_cpu_destroy(cpu);
        cpu = NULL;
    }

    static const struct {
        uint8_t program[4];
        size_t length;
    } unsupported_neighbors[] = {
        {{0x4eu, 0xd8u, 0x00u, 0x02u}, 4u}, /* JMP (A0)+ */
        {{0x4eu, 0xe0u, 0x00u, 0x02u}, 4u}, /* JMP -(A0) */
    };
    for (size_t index = 0u;
         index < sizeof(unsupported_neighbors) / sizeof(unsupported_neighbors[0]);
         ++index) {
        assert_unobserved_encoding_has_no_side_effect(unsupported_neighbors[index].program,
                                                      unsupported_neighbors[index].length);
    }
}

static void swap_data_registers_exchanges_words_and_sets_long_flags(void) {
    static const struct {
        uint32_t value;
        uint32_t expected;
        uint16_t result_flags;
    } cases[] = {
        {UINT32_C(0x00000000), UINT32_C(0x00000000), UINT16_C(0x0004)},
        {UINT32_C(0x00008000), UINT32_C(0x80000000), UINT16_C(0x0008)},
        {UINT32_C(0x80000001), UINT32_C(0x00018000), UINT16_C(0x0000)},
        {UINT32_C(0x12345678), UINT32_C(0x56781234), UINT16_C(0x0000)},
    };
    static const uint16_t initial_flags[] = {
        UINT16_C(0x2700), UINT16_C(0x271f), UINT16_C(0x2715)};
    create_cpu();
    for (unsigned destination = 0u; destination < 8u; ++destination) {
        for (size_t item = 0u; item < sizeof(cases) / sizeof(cases[0]); ++item) {
            for (size_t flag = 0u;
                 flag < sizeof(initial_flags) / sizeof(initial_flags[0]); ++flag) {
                const uint8_t program[] = {0x48u, (uint8_t)(0x40u + destination)};
                TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                  reset_with_program(program, sizeof(program)));
                owned_cpu_state before;
                TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
                for (unsigned reg = 0u; reg < 8u; ++reg)
                    before.data_registers[reg] = UINT32_C(0x13570000) + reg;
                before.data_registers[destination] = cases[item].value;
                before.sr = initial_flags[flag];
                TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));

                const size_t reads_before = memory.reads;
                const size_t writes_before = memory.write_attempts;
                const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(4));
                TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
                TEST_ASSERT_EQUAL_UINT64(4u, result.elapsed_cycles);
                TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
                TEST_ASSERT_EQUAL_UINT(1u, memory.reads - reads_before);
                TEST_ASSERT_EQUAL_UINT(writes_before, memory.write_attempts);

                owned_cpu_observation after;
                TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
                TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102), after.pc);
                TEST_ASSERT_EQUAL_HEX16(
                    (uint16_t)((initial_flags[flag] & UINT16_C(0x0010)) |
                               UINT16_C(0x2700) | cases[item].result_flags), after.sr);
                for (unsigned reg = 0u; reg < 8u; ++reg) {
                    const uint32_t expected = reg == destination
                        ? cases[item].expected : before.data_registers[reg];
                    TEST_ASSERT_EQUAL_HEX32(expected, after.data_registers[reg]);
                    TEST_ASSERT_EQUAL_HEX32(before.address_registers[reg],
                                            after.address_registers[reg]);
                }
            }
        }
    }

}

