/* MOVE.W #<data>,ea writes all seven data-alterable memory EAs. The fixed
 * immediate operand is fetched before any destination extensions. Motorola
 * MC68000 User's Manual Rev. 9.1 Table 8-2 (printed p. 8-2) gives 12/12/12/
 * 16/18/16/20 clocks; the resulting event sequence is checked as a core
 * contract, not claimed as undocumented hardware bus chronology. */
static void move_word_immediate_to_data_alterable_memory_eas_write_with_documented_timing(void) {
    static const struct {
        unsigned mode;
        unsigned ea_register;
        unsigned extension_words;
        uint64_t cycles;
    } forms[] = {
        {2u, 0u, 0u, 12u}, /* (An) */
        {3u, 0u, 0u, 12u}, /* (An)+ */
        {4u, 0u, 0u, 12u}, /* -(An) */
        {5u, 0u, 1u, 16u}, /* d16(An) */
        {6u, 0u, 1u, 18u}, /* brief d8(An,Xn) */
        {7u, 0u, 1u, 16u}, /* absolute short */
        {7u, 1u, 2u, 20u}, /* absolute long */
    };
    static const uint16_t immediates[] = {
        UINT16_C(0x0000), UINT16_C(0x0001),
        UINT16_C(0x7fff), UINT16_C(0x8000),
    };
    unsigned case_number = 0u;

    for (size_t form_index = 0u;
         form_index < sizeof(forms) / sizeof(forms[0]); ++form_index) {
        const unsigned register_count = forms[form_index].mode == 7u ? 1u : 8u;
        for (unsigned reg = 0u; reg < register_count; ++reg) {
            setUp();
            create_cpu();
            const uint16_t opcode = (uint16_t)(UINT16_C(0x303c) |
                (uint16_t)(forms[form_index].mode << 6) |
                (uint16_t)(forms[form_index].mode == 7u
                    ? forms[form_index].ea_register << 9 : reg << 9));
            uint8_t program[8] = {0};
            size_t length = 0u;
            emit_word(program, &length, opcode);
            const uint16_t immediate = immediates[case_number %
                (sizeof(immediates) / sizeof(immediates[0]))];
            emit_word(program, &length, immediate);
            if (forms[form_index].mode == 5u) {
                emit_word(program, &length, UINT16_C(4));
            } else if (forms[form_index].mode == 6u) {
                emit_word(program, &length, UINT16_C(0x1002));
            } else if (forms[form_index].mode == 7u &&
                       forms[form_index].ea_register == 0u) {
                emit_word(program, &length, UINT16_C(0x0160));
            } else if (forms[form_index].mode == 7u) {
                emit_word(program, &length, UINT16_C(0x0000));
                emit_word(program, &length, UINT16_C(0x0180));
            }
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, length));

            owned_cpu_state before;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
            for (unsigned address_register = 0u; address_register < 8u;
                 ++address_register) {
                before.address_registers[address_register] =
                    UINT32_C(0x0140) + address_register * UINT32_C(8);
                before.data_registers[address_register] =
                    UINT32_C(0x10001000) + address_register;
            }
            before.data_registers[1] = UINT32_C(4); /* D1.W index = 4 */
            before.sr = UINT16_C(0x2715); /* MOVE clears NZVC and preserves X */
            before.ssp = before.address_registers[7];
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));

            uint32_t destination = 0u;
            if (forms[form_index].mode <= 4u) {
                destination = before.address_registers[reg];
                if (forms[form_index].mode == 4u) destination -= UINT32_C(2);
            } else if (forms[form_index].mode == 5u) {
                destination = before.address_registers[reg] + UINT32_C(4);
            } else if (forms[form_index].mode == 6u) {
                destination = before.address_registers[reg] + UINT32_C(6);
            } else if (forms[form_index].ea_register == 0u) {
                destination = UINT32_C(0x0160);
            } else {
                destination = UINT32_C(0x0180);
            }

            const size_t reads_before = memory.reads;
            const size_t writes_before = memory.write_attempts;
            const owned_cpu_run_result result = owned_cpu_run(
                cpu, forms[form_index].cycles);
            TEST_ASSERT_EQUAL_MESSAGE(OWNED_CPU_BUDGET, result.reason,
                                      "immediate-to-memory MOVE form must execute");
            TEST_ASSERT_EQUAL_UINT64(forms[form_index].cycles, result.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
            TEST_ASSERT_EQUAL_UINT(forms[form_index].extension_words + 2u,
                                   memory.reads - reads_before);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0100),
                                    memory.read_addresses[reads_before]);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0102),
                                    memory.read_addresses[reads_before + 1u]);
            for (unsigned extension = 0u;
                 extension < forms[form_index].extension_words; ++extension) {
                TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0104) + extension * 2u,
                    memory.read_addresses[reads_before + 2u + extension]);
            }
            TEST_ASSERT_EQUAL_UINT(writes_before + 1u, memory.write_attempts);
            TEST_ASSERT_EQUAL_UINT(writes_before + 1u, memory.successful_writes);
            TEST_ASSERT_EQUAL_HEX32(destination, memory.write_addresses[writes_before]);
            TEST_ASSERT_EQUAL_HEX16(immediate, memory.write_values[writes_before]);

            owned_cpu_observation after;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0104) +
                forms[form_index].extension_words * 2u, after.pc);
            for (unsigned address_register = 0u; address_register < 8u;
                 ++address_register) {
                uint32_t expected_base = before.address_registers[address_register];
                if (forms[form_index].mode == 3u && address_register == reg)
                    expected_base += UINT32_C(2);
                if (forms[form_index].mode == 4u && address_register == reg)
                    expected_base -= UINT32_C(2);
                TEST_ASSERT_EQUAL_HEX32(expected_base,
                    after.address_registers[address_register]);
                TEST_ASSERT_EQUAL_HEX32(before.data_registers[address_register],
                    after.data_registers[address_register]);
            }
            const uint16_t expected_flags = immediate == 0u
                ? UINT16_C(0x2714)
                : (immediate & UINT16_C(0x8000)) != 0u
                    ? UINT16_C(0x2718) : UINT16_C(0x2710);
            TEST_ASSERT_EQUAL_HEX16(expected_flags, after.sr);
            TEST_ASSERT_EQUAL_HEX32(before.usp, after.usp);
            if (forms[form_index].mode == 3u && reg == 7u)
                TEST_ASSERT_EQUAL_HEX32(before.ssp + UINT32_C(2), after.ssp);
            else if (forms[form_index].mode == 4u && reg == 7u)
                TEST_ASSERT_EQUAL_HEX32(before.ssp - UINT32_C(2), after.ssp);
            else
                TEST_ASSERT_EQUAL_HEX32(before.ssp, after.ssp);
            ++case_number;
            tearDown();
        }
    }
}

/* MOVE.B #<data>,ea uses the word-sized extension then each data-alterable
 * destination's addressing extensions. UM Rev. 9.1 Table 8-2 (printed p. 8-2)
 * gives 12/12/12/16/18/16/20 clocks for the seven forms. The byte destination
 * is allowed to be odd; the test checks the owned core's fetch and register
 * update contract, including A7's two-byte step. */
static void move_byte_immediate_to_data_alterable_memory_eas_use_documented_timing(void) {
    static const struct {
        unsigned mode;
        unsigned absolute_register;
        unsigned extension_words;
        uint64_t cycles;
    } forms[] = {
        {2u, 0u, 0u, UINT64_C(12)}, /* (An) */
        {3u, 0u, 0u, UINT64_C(12)}, /* (An)+ */
        {4u, 0u, 0u, UINT64_C(12)}, /* -(An) */
        {5u, 0u, 1u, UINT64_C(16)}, /* d16(An) */
        {6u, 0u, 1u, UINT64_C(18)}, /* brief d8(An,Xn) */
        {7u, 0u, 1u, UINT64_C(16)}, /* absolute short */
        {7u, 1u, 2u, UINT64_C(20)}, /* absolute long */
    };
    static const uint8_t values[8] = {
        0x00u, 0x01u, 0x7fu, 0x80u, 0xffu, 0x55u, 0xaau, 0xe1u,
    };
    const uint32_t destination_address = UINT32_C(0x01a1);
    unsigned case_number = 0u;

    for (size_t form_index = 0u;
         form_index < sizeof(forms) / sizeof(forms[0]); ++form_index) {
        const unsigned first_register = forms[form_index].mode == 7u
            ? forms[form_index].absolute_register : 0u;
        const unsigned register_limit = forms[form_index].mode == 7u
            ? forms[form_index].absolute_register + 1u : 8u;
        for (unsigned reg = first_register; reg < register_limit; ++reg) {
            setUp();
            create_cpu();
            const uint16_t opcode = (uint16_t)(UINT16_C(0x103c) |
                (uint16_t)(forms[form_index].mode << 6) |
                (uint16_t)(reg << 9));
            uint8_t program[8] = {0};
            size_t length = 0u;
            emit_word(program, &length, opcode);
            const uint8_t value = values[case_number %
                (sizeof(values) / sizeof(values[0]))];
            emit_word(program, &length, (uint16_t)(UINT16_C(0xa500) | value));
            if (forms[form_index].mode == 5u) {
                emit_word(program, &length, UINT16_C(0x0020));
            } else if (forms[form_index].mode == 6u) {
                emit_word(program, &length, UINT16_C(0x1000)); /* D1.W index */
            } else if (forms[form_index].mode == 7u &&
                       forms[form_index].absolute_register == 0u) {
                emit_word(program, &length, UINT16_C(0x01a1));
            } else if (forms[form_index].mode == 7u) {
                emit_word(program, &length, UINT16_C(0x0000));
                emit_word(program, &length, UINT16_C(0x01a1));
            }
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, length));

            owned_cpu_state before;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
            for (unsigned address_register = 0u; address_register < 8u;
                 ++address_register)
                before.address_registers[address_register] =
                    UINT32_C(0x0140) + address_register * UINT32_C(8);
            if (forms[form_index].mode < 7u) {
                const unsigned byte_step = reg == 7u ? 2u : 1u;
                switch (forms[form_index].mode) {
                    case 2u:
                    case 3u:
                        before.address_registers[reg] = destination_address;
                        break;
                    case 4u:
                        before.address_registers[reg] = destination_address + byte_step;
                        break;
                    case 5u:
                        before.address_registers[reg] = destination_address -
                                                         UINT32_C(0x20);
                        break;
                    case 6u:
                        before.address_registers[reg] = destination_address -
                                                         UINT32_C(2);
                        before.data_registers[1] = UINT32_C(2);
                        break;
                    default:
                        TEST_FAIL_MESSAGE("unexpected MOVE.B immediate destination mode");
                }
            }
            before.sr = UINT16_C(0x271f);
            before.ssp = before.address_registers[7];
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));

            memory.rom[destination_address] = UINT8_C(0x33);
            const size_t reads_before = memory.reads;
            const size_t writes_before = memory.write_attempts;
            const owned_cpu_run_result result = owned_cpu_run(
                cpu, forms[form_index].cycles);
            TEST_ASSERT_EQUAL_MESSAGE(OWNED_CPU_BUDGET, result.reason,
                                      "MOVE.B immediate data-alterable EA must execute");
            TEST_ASSERT_EQUAL_UINT64(forms[form_index].cycles, result.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
            TEST_ASSERT_EQUAL_UINT(forms[form_index].extension_words + 2u,
                                   memory.reads - reads_before);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0100),
                                    memory.read_addresses[reads_before]);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0102),
                                    memory.read_addresses[reads_before + 1u]);
            for (unsigned extension = 0u;
                 extension < forms[form_index].extension_words; ++extension)
                TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0104) + extension * 2u,
                    memory.read_addresses[reads_before + 2u + extension]);
            TEST_ASSERT_EQUAL_UINT(0u, memory.byte_reads);
            TEST_ASSERT_EQUAL_UINT(writes_before + 1u, memory.write_attempts);
            TEST_ASSERT_EQUAL_UINT(writes_before + 1u, memory.successful_writes);
            TEST_ASSERT_EQUAL_HEX32(destination_address,
                memory.byte_write_addresses[writes_before]);
            TEST_ASSERT_EQUAL_HEX8(value, memory.byte_write_values[writes_before]);
            TEST_ASSERT_EQUAL_HEX8(value, memory.rom[destination_address]);

            owned_cpu_state after;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &after));
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0104) +
                forms[form_index].extension_words * 2u, after.pc);
            for (unsigned address_register = 0u; address_register < 8u;
                 ++address_register) {
                uint32_t expected_base = before.address_registers[address_register];
                if (forms[form_index].mode == 3u && address_register == reg)
                    expected_base += reg == 7u ? UINT32_C(2) : UINT32_C(1);
                if (forms[form_index].mode == 4u && address_register == reg)
                    expected_base = destination_address;
                TEST_ASSERT_EQUAL_HEX32(expected_base,
                    after.address_registers[address_register]);
                TEST_ASSERT_EQUAL_HEX32(before.data_registers[address_register],
                    after.data_registers[address_register]);
            }
            uint16_t expected_flags = UINT16_C(0x2710);
            if (value == 0u)
                expected_flags = (uint16_t)(expected_flags | UINT16_C(0x0004));
            else if ((value & UINT8_C(0x80)) != 0u)
                expected_flags = (uint16_t)(expected_flags | UINT16_C(0x0008));
            TEST_ASSERT_EQUAL_HEX16(expected_flags, after.sr);
            TEST_ASSERT_EQUAL_HEX32(after.address_registers[7], after.ssp);
            ++case_number;
            tearDown();
        }
    }
}

static void move_word_immediate_predecrement_odd_destination_commits_before_vector_three(void) {
    setUp();
    set_vector(12u, UINT32_C(0x0140));
    create_cpu();
    const uint8_t program[] = {
        0x31u, 0x3cu, 0x12u, 0x34u}; /* MOVE.W #$1234,-(A0) */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    owned_cpu_state before;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
    before.address_registers[0] = UINT32_C(0x0181);
    before.sr = UINT16_C(0x2710);
    before.ssp = before.address_registers[7];
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));
    const size_t reads_before = memory.reads;
    const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(50));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(50u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(0u, result.instructions);
    TEST_ASSERT_EQUAL_UINT(4u, memory.reads - reads_before);
    for (size_t read = reads_before; read < memory.reads; ++read)
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x017f), memory.read_addresses[read]);
    for (size_t write = 0u; write < memory.write_attempts; ++write)
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x017f), memory.write_addresses[write]);
    owned_cpu_observation after;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
    TEST_ASSERT_EQUAL_UINT8(3u, after.last_exception_vector);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0140), after.pc);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x017f), after.address_registers[0]);
    TEST_ASSERT_EQUAL_HEX16(before.sr, after.sr);
    tearDown();
}

static void move_word_immediate_postincrement_odd_destination_commits_before_vector_three(void) {
    setUp();
    set_vector(12u, UINT32_C(0x0140));
    create_cpu();
    const uint8_t program[] = {
        0x30u, 0xfcu, 0x12u, 0x34u}; /* MOVE.W #$1234,(A0)+ */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    owned_cpu_state before;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
    before.address_registers[0] = UINT32_C(0x0181);
    before.ssp = before.address_registers[7];
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));
    const size_t reads_before = memory.reads;
    const size_t writes_before = memory.write_attempts;
    const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(50));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(50u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(0u, result.instructions);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0100), memory.read_addresses[reads_before]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0102), memory.read_addresses[reads_before + 1u]);
    for (size_t read = reads_before + 2u;
         read < memory.reads && read < ROM_SIZE; ++read)
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x0181), memory.read_addresses[read]);
    for (size_t write = writes_before;
         write < memory.write_attempts && write < MAX_WRITES; ++write)
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x0181), memory.write_addresses[write]);
    owned_cpu_observation after;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
    TEST_ASSERT_EQUAL_UINT8(3u, after.last_exception_vector);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0140), after.pc);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x0183), after.address_registers[0]);
    TEST_ASSERT_EQUAL_HEX32(after.address_registers[7], after.ssp);
    tearDown();
}

static void move_long_immediate_to_postincrement_memory_uses_20_cycles(void) {
    create_cpu();
    const uint8_t program[] = {
        0x20u, 0xfcu, 0x89u, 0xabu, 0xcdu, 0xefu,
        0x25u, 0xfcu}; /* MOVE.L #imm,(d16,PC) remains unsupported. */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.address_registers[0] = UINT32_C(0x180);
    state.sr = UINT16_C(0x271f);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(20));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(20u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
    TEST_ASSERT_EQUAL_UINT(2u, memory.write_attempts);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x180), memory.write_addresses[0]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x89ab), memory.write_values[0]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x182), memory.write_addresses[1]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0xcdef), memory.write_values[1]);
    owned_cpu_observation observation;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x184), observation.address_registers[0]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2718), observation.sr);
    result = owned_cpu_run(cpu, UINT64_C(20));
    TEST_ASSERT_EQUAL(OWNED_CPU_UNSUPPORTED_OPCODE, result.reason);
}

static void lea_displacement_address_to_register_uses_8_cycles(void) {
    create_cpu();
    const uint8_t program[] = {
        0x43u, 0xe8u, 0x00u, 0x04u, /* LEA 4(A0),A1 */
        0x4eu, 0xd8u, 0x00u, 0x02u}; /* JMP (A0)+ remains unsupported. */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.address_registers[0] = UINT32_C(0x180);
    state.sr = UINT16_C(0x271f);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(8));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(8u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
    owned_cpu_observation observation;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x184), observation.address_registers[1]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x271f), observation.sr);
    result = owned_cpu_run(cpu, UINT64_C(8));
    TEST_ASSERT_EQUAL(OWNED_CPU_UNSUPPORTED_OPCODE, result.reason);
}

/* LEA (An),An does not read the operand, alter condition codes, or change the
 * source register unless it is also the destination. The M68000 Family PRM
 * section 4 LEA (p. 4-110) defines the address transfer; the MC68000 User's
 * Manual Rev. 9.1 Table 8-10 (printed p. 8-8) specifies 4(1/0): one
 * instruction-word read and no writes. */
static void lea_address_register_indirect_to_register_uses_4_cycles(void) {
    static const uint16_t sr_values[] = {UINT16_C(0x2700), UINT16_C(0x271f)};
    for (unsigned base = 0u; base < 8u; ++base) {
        for (unsigned destination = 0u; destination < 8u; ++destination) {
            for (size_t flags = 0u; flags < sizeof(sr_values) / sizeof(sr_values[0]);
                 ++flags) {
                setUp();
                create_cpu();
                const uint16_t opcode = (uint16_t)(UINT16_C(0x41d0) |
                    (uint16_t)(destination << 9) | (uint16_t)base);
                uint8_t program[2];
                size_t length = 0u;
                emit_word(program, &length, opcode);
                TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, length));

                owned_cpu_state state;
                TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
                for (unsigned reg = 0u; reg < 8u; ++reg)
                    state.address_registers[reg] = UINT32_C(0x100) + reg * UINT32_C(0x20);
                state.ssp = state.address_registers[7];
                state.sr = sr_values[flags];
                TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));

                const size_t reads_before = memory.reads;
                const unsigned writes_before = memory.write_attempts;
                const size_t byte_reads_before = memory.byte_reads;
                const uint32_t effective_address = state.address_registers[base];
                owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(4));
                TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
                TEST_ASSERT_EQUAL_UINT64(4u, result.elapsed_cycles);
                TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
                TEST_ASSERT_EQUAL_UINT(1u, (unsigned)(memory.reads - reads_before));
                TEST_ASSERT_EQUAL_UINT(writes_before, memory.write_attempts);
                TEST_ASSERT_EQUAL_UINT(byte_reads_before, (unsigned)memory.byte_reads);

                owned_cpu_state after;
                TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &after));
                TEST_ASSERT_EQUAL_HEX16(sr_values[flags], after.sr);
                if (destination == 7u) {
                    TEST_ASSERT_EQUAL_HEX32(effective_address, after.ssp);
                } else {
                    TEST_ASSERT_EQUAL_HEX32(effective_address,
                                            after.address_registers[destination]);
                }
                for (unsigned reg = 0u; reg < 8u; ++reg) {
                    const uint32_t expected = reg == destination
                        ? effective_address : state.address_registers[reg];
                    TEST_ASSERT_EQUAL_HEX32(expected, after.address_registers[reg]);
                }
                tearDown();
            }
        }
    }
}

static void lea_address_register_indirect_neighbors_stay_unsupported(void) {
    static const uint16_t opcodes[] = {UINT16_C(0x41d8), UINT16_C(0x41e0)};
    for (size_t index = 0u; index < sizeof(opcodes) / sizeof(opcodes[0]); ++index) {
        setUp();
        create_cpu();
        uint8_t program[2];
        size_t length = 0u;
        emit_word(program, &length, opcodes[index]);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, length));
        const size_t reads_before = memory.reads;
        const unsigned writes_before = memory.write_attempts;
        owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(4));
        TEST_ASSERT_EQUAL(OWNED_CPU_UNSUPPORTED_OPCODE, result.reason);
        TEST_ASSERT_EQUAL_UINT64(0u, result.instructions);
        TEST_ASSERT_EQUAL_UINT(1u, (unsigned)(memory.reads - reads_before));
        TEST_ASSERT_EQUAL_UINT(writes_before, memory.write_attempts);
        tearDown();
    }
}

/* LEA (d16,PC),An (guest demanded, plan 05-21 rerun 1). Semantics: M68000
 * Family Programmer's Reference Manual LEA, p. 4-110 (effective address to An,
 * all 32 bits, condition codes unaffected); PC-relative base is the extension
 * word address (PRM section 2, PC relative addressing). Timing: MC68000 User's
 * Manual Rev. 9.1 Table 8-10 (printed p. 8-8), LEA (d16 PC) is 8(2/0).
 * Bus-tally reconciliation: the no-prefetch core reads the opcode word and the
 * extension word (2 word reads); Section 8 counts the extension read plus the
 * next-instruction prefetch (also 2), so the tallies are equal with 0 writes
 * and 0 byte reads. */
static void lea_pc_displacement_address_to_register_uses_8_cycles(void) {
    static const struct {
        uint16_t opcode;
        uint16_t displacement;
        unsigned destination;
        uint32_t expected;
    } cases[] = {
        {0x41fau, 0x0002u, 0u, UINT32_C(0x104)},
        {0x41fau, 0xfffeu, 0u, UINT32_C(0x100)},
        {0x4ffau, 0x0002u, 7u, UINT32_C(0x104)},
        {0x4ffau, 0xfffeu, 7u, UINT32_C(0x100)},
    };
    static const uint16_t sr_values[] = {UINT16_C(0x2700), UINT16_C(0x271f)};
    for (size_t index = 0u; index < sizeof(cases) / sizeof(cases[0]); ++index) {
        for (size_t flags = 0u; flags < 2u; ++flags) {
            setUp();
            create_cpu();
            uint8_t program[4];
            size_t length = 0u;
            emit_word(program, &length, cases[index].opcode);
            emit_word(program, &length, cases[index].displacement);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, length));
            owned_cpu_state state;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
            state.sr = sr_values[flags];
            state.address_registers[0] = UINT32_C(0xdeadbeef);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
            const size_t reads_before = memory.reads;
            owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(8));
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
            TEST_ASSERT_EQUAL_UINT64(8u, result.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
            TEST_ASSERT_EQUAL_UINT(2u, (unsigned)(memory.reads - reads_before));
            TEST_ASSERT_EQUAL_UINT(0u, (unsigned)memory.write_attempts);
            TEST_ASSERT_EQUAL_UINT(0u, (unsigned)memory.byte_reads);
            owned_cpu_state after;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &after));
            TEST_ASSERT_EQUAL_HEX32(cases[index].expected,
                                    after.address_registers[cases[index].destination]);
            TEST_ASSERT_EQUAL_HEX16(sr_values[flags], after.sr);
            if (cases[index].destination == 7u) {
                TEST_ASSERT_EQUAL_HEX32(cases[index].expected, after.ssp);
                TEST_ASSERT_EQUAL_HEX32(UINT32_C(0xdeadbeef), after.address_registers[0]);
            } else {
                TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x2000), after.address_registers[7]);
            }
            owned_cpu_observation observation;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x104), observation.pc);
            tearDown();
        }
    }
}

// LEA (d8,PC,Xn),An stays unsupported; PEA control EAs are tested separately.
static void lea_pc_displacement_neighbors_stay_unsupported(void) {
    /* PEA (d16,PC) was admitted in plan 05-25 rerun 23. */
    static const uint16_t opcodes[] = {0x41fbu};
    for (size_t index = 0u; index < sizeof(opcodes) / sizeof(opcodes[0]); ++index) {
        setUp();
        create_cpu();
        uint8_t program[4];
        size_t length = 0u;
        emit_word(program, &length, opcodes[index]);
        emit_word(program, &length, 0x0002u);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, length));
        owned_cpu_state before;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
        owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(20));
        TEST_ASSERT_EQUAL_MESSAGE(OWNED_CPU_UNSUPPORTED_OPCODE, result.reason, "neighbor");
        TEST_ASSERT_EQUAL_HEX16(opcodes[index], result.instruction_register);
        TEST_ASSERT_EQUAL_UINT(0u, (unsigned)memory.write_attempts);
        owned_cpu_state after;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &after));
        TEST_ASSERT_EQUAL_HEX32(before.pc, after.pc);
        TEST_ASSERT_EQUAL_HEX16(before.sr, after.sr);
        for (unsigned reg = 0u; reg < 8u; ++reg) {
            TEST_ASSERT_EQUAL_HEX32(before.address_registers[reg], after.address_registers[reg]);
            TEST_ASSERT_EQUAL_HEX32(before.data_registers[reg], after.data_registers[reg]);
        }
        tearDown();
    }
}

/* CMPM.B (Ay)+,(Ax)+ (guest demanded, plan 05-21 rerun 2). Semantics: M68000
 * Family Programmer's Reference Manual CMPM, pp. 4-80 to 4-81 (destination
 * minus source, operands in memory, neither written; X unaffected, N Z V C
 * from the byte subtraction, C is the borrow); the byte postincrement is one,
 * two for A7 (PRM section 2, postincrement addressing). Timing: MC68000
 * User's Manual Rev. 9.1 Table 8-11 (printed p. 8-9), CMPM byte 12(3/0).
 * Bus-tally reconciliation: the no-prefetch core performs the opcode word
 * read plus the two operand byte reads (3 reads, 0 writes); Section 8 counts
 * 3 reads for the same instruction (two operands plus one fetch), so the
 * tallies are equal. */
static void cmpm_byte_postincrement_compares_memory_in_12_cycles(void) {
    static const struct {
        uint8_t destination;
        uint8_t source;
        uint16_t flags;
    } cases[] = {
        {0x80u, 0x01u, 0x0002u},  /* 0x7f: V set, N Z C clear */
        {0x00u, 0x01u, 0x0009u},  /* 0xff: N and C set */
        {0x55u, 0x55u, 0x0004u},  /* zero: Z set */
        {0x7fu, 0xffu, 0x000bu},  /* 0x80: N V C set */
        {0x90u, 0x10u, 0x0008u},  /* 0x80: N set, signed no overflow */
    };
    static const uint16_t sr_base[] = {UINT16_C(0x2700), UINT16_C(0x2710)};
    for (size_t index = 0u; index < sizeof(cases) / sizeof(cases[0]); ++index) {
        for (size_t base = 0u; base < 2u; ++base) {
            setUp();
            create_cpu();
            memory.rom[0x180] = cases[index].source;
            memory.rom[0x190] = cases[index].destination;
            const uint8_t program[] = {0xb5u, 0x09u}; /* CMPM.B (A1)+,(A2)+ */
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
            owned_cpu_state state;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
            state.address_registers[1] = UINT32_C(0x180);
            state.address_registers[2] = UINT32_C(0x190);
            state.sr = (uint16_t)(sr_base[base] | UINT16_C(0x000f));
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
            const size_t reads_before = memory.reads;
            owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(12));
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
            TEST_ASSERT_EQUAL_UINT64(12u, result.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
            TEST_ASSERT_EQUAL_UINT(1u, (unsigned)(memory.reads - reads_before));
            TEST_ASSERT_EQUAL_UINT(2u, (unsigned)memory.byte_reads);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x180), memory.byte_read_addresses[0]);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x190), memory.byte_read_addresses[1]);
            TEST_ASSERT_EQUAL_UINT(0u, (unsigned)memory.write_attempts);
            owned_cpu_state after;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &after));
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x181), after.address_registers[1]);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x191), after.address_registers[2]);
            TEST_ASSERT_EQUAL_HEX16((uint16_t)((sr_base[base] & ~UINT16_C(0x000f)) |
                                               cases[index].flags), after.sr);
            TEST_ASSERT_EQUAL_HEX8(cases[index].destination, memory.rom[0x190]);
            tearDown();
        }
    }

    /* Same register for both operands: the destination read sees the
     * already-incremented Ay (PRM postincrement order), and A7 steps by two. */
    setUp();
    create_cpu();
    memory.rom[0x180] = 0x20u;
    memory.rom[0x181] = 0x20u;
    memory.rom[0x182] = 0x20u;
    memory.rom[0x183] = 0x20u;
    const uint8_t same_register[] = {0xb1u, 0x08u}; /* CMPM.B (A0)+,(A0)+ */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(same_register, sizeof(same_register)));
    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.address_registers[0] = UINT32_C(0x180);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(12));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x180), memory.byte_read_addresses[0]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x181), memory.byte_read_addresses[1]);
    owned_cpu_state after;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &after));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x182), after.address_registers[0]);
    tearDown();
}

/* MOVE.W Dn,(abs.L) uses opcode 0x33c0 plus Dn in bits 2–0, followed by the
 * absolute-long destination extension. Table 8-2 gives 16 clocks; the bus
 * trace is opcode, high address extension, then low address extension before
 * the single word write. */
static void move_word_data_register_to_absolute_long_covers_all_registers(void) {
    static const uint16_t values[8] = {
        UINT16_C(0x0000), UINT16_C(0x0001), UINT16_C(0x7fff), UINT16_C(0x8000),
        UINT16_C(0xffff), UINT16_C(0x1234), UINT16_C(0x8001), UINT16_C(0x00ff),
    };
    for (unsigned source_register = 0u; source_register < 8u;
         ++source_register) {
        setUp();
        create_cpu();
        uint8_t program[6];
        size_t program_size = 0u;
        emit_word(program, &program_size,
                  (uint16_t)(UINT16_C(0x33c0) | (uint16_t)source_register));
        emit_word(program, &program_size, UINT16_C(0x0000));
        emit_word(program, &program_size, UINT16_C(0x01f0));
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          reset_with_program(program, program_size));
        memory.rom[0x01f0u] = 0xa5u;
        memory.rom[0x01f1u] = 0x5au;
        owned_cpu_state before;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          owned_cpu_capture_state(cpu, &before));
        for (unsigned reg = 0u; reg < 8u; ++reg)
            before.data_registers[reg] =
                UINT32_C(0x5a5a0000) | values[reg];
        before.sr = UINT16_C(0x271f);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          owned_cpu_restore_state(cpu, &before));

        const size_t reads_before = memory.reads;
        const owned_cpu_run_result result =
            owned_cpu_run(cpu, UINT64_C(16));
        TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
        TEST_ASSERT_EQUAL_UINT64(16u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
        TEST_ASSERT_EQUAL_UINT(reads_before + 3u, memory.reads);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                                memory.read_addresses[reads_before]);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102),
                                memory.read_addresses[reads_before + 1u]);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x104),
                                memory.read_addresses[reads_before + 2u]);
        TEST_ASSERT_EQUAL_UINT(0u, memory.byte_reads);
        TEST_ASSERT_EQUAL_UINT(1u, memory.write_attempts);
        TEST_ASSERT_EQUAL_UINT(1u, memory.successful_writes);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x01f0), memory.write_addresses[0]);
        TEST_ASSERT_EQUAL_HEX16(values[source_register], memory.write_values[0]);
        TEST_ASSERT_EQUAL_HEX8(UINT8_C(0xa5), memory.rom[0x01f0u]);
        TEST_ASSERT_EQUAL_HEX8(UINT8_C(0x5a), memory.rom[0x01f1u]);

        owned_cpu_state after;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          owned_cpu_capture_state(cpu, &after));
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x106), after.pc);
        uint16_t expected_sr = UINT16_C(0x2710);
        if (values[source_register] == 0u)
            expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0004));
        if ((values[source_register] & UINT16_C(0x8000)) != 0u)
            expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0008));
        TEST_ASSERT_EQUAL_HEX16(expected_sr, after.sr);
        for (unsigned reg = 0u; reg < 8u; ++reg) {
            TEST_ASSERT_EQUAL_HEX32(before.data_registers[reg],
                                    after.data_registers[reg]);
            TEST_ASSERT_EQUAL_HEX32(before.address_registers[reg],
                                    after.address_registers[reg]);
        }
        tearDown();
    }
}

static void move_word_data_register_to_absolute_long_odd_destination_traps_before_write(void) {
    setUp();
    create_cpu();
    const uint8_t program[] = {
        0x33u, 0xc0u, 0x00u, 0x00u, 0x01u, 0xf1u};
    set_vector(12u, UINT32_C(0x140));
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      reset_with_program(program, sizeof(program)));
    const size_t reads_before = memory.reads;
    const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(50));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    owned_cpu_observation after;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
    TEST_ASSERT_EQUAL_UINT8(3u, after.last_exception_vector);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x140), after.pc);
    TEST_ASSERT_EQUAL_UINT(5u, memory.reads - reads_before);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100), memory.read_addresses[reads_before]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102), memory.read_addresses[reads_before + 1u]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x104), memory.read_addresses[reads_before + 2u]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(12), memory.read_addresses[reads_before + 3u]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(14), memory.read_addresses[reads_before + 4u]);
    for (size_t write = 0u; write < memory.write_attempts && write < MAX_WRITES; ++write)
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x01f1), memory.write_addresses[write]);
    tearDown();
}

static void move_word_data_register_to_absolute_long_neighbors_stay_unsupported(void) {
    static const struct {
        uint8_t program[6];
        size_t length;
        const char *name;
    } neighbors[] = {
        {{0x31u, 0xc0u, 0x00u, 0x00u}, 4u, "MOVE.W D0,(xxx).W"},
    };
    for (size_t index = 0u;
         index < sizeof(neighbors) / sizeof(neighbors[0]); ++index) {
        memset(&memory, 0, sizeof(memory));
        create_cpu();
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          reset_with_program(neighbors[index].program,
                                             neighbors[index].length));
        owned_cpu_observation before, after;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &before));
        const size_t reads_before = memory.reads;
        const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(40));
        TEST_ASSERT_EQUAL_MESSAGE(OWNED_CPU_UNSUPPORTED_OPCODE, result.reason,
                                  neighbors[index].name);
        TEST_ASSERT_EQUAL_UINT64(0u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(0u, result.instructions);
        TEST_ASSERT_EQUAL_UINT(1u, memory.reads - reads_before);
        TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
        TEST_ASSERT_EQUAL_HEX32(before.pc, after.pc);
        TEST_ASSERT_EQUAL_HEX16(before.sr, after.sr);
        for (unsigned reg = 0u; reg < 8u; ++reg) {
            TEST_ASSERT_EQUAL_HEX32(before.data_registers[reg],
                                    after.data_registers[reg]);
            TEST_ASSERT_EQUAL_HEX32(before.address_registers[reg],
                                    after.address_registers[reg]);
        }
        owned_cpu_destroy(cpu);
        cpu = NULL;
    }
}

static void move_word_absolute_short_to_data_register_uses_12_cycles(void) {
    static const uint16_t values[] = {
        UINT16_C(0x0000), UINT16_C(0x0001), UINT16_C(0x7fff), UINT16_C(0x8000),
        UINT16_C(0xffff), UINT16_C(0x1234), UINT16_C(0x8001), UINT16_C(0x00ff),
    };
    for (unsigned destination_register = 0u; destination_register < 8u;
         ++destination_register) {
        setUp();
        create_cpu();
        uint8_t program[4];
        size_t program_size = 0u;
        emit_word(program, &program_size,
                  (uint16_t)(UINT16_C(0x3038) |
                             (uint16_t)(destination_register << 9)));
        emit_word(program, &program_size, UINT16_C(0x0180));
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          reset_with_program(program, program_size));
        memory.rom[0x180] = (uint8_t)(values[destination_register] >> 8);
        memory.rom[0x181] = (uint8_t)values[destination_register];
        owned_cpu_state before;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          owned_cpu_capture_state(cpu, &before));
        const uint32_t original =
            UINT32_C(0xa5a50000) | (uint32_t)(destination_register + 1u);
        before.data_registers[destination_register] = original;
        before.sr = UINT16_C(0x271f);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          owned_cpu_restore_state(cpu, &before));

        const size_t reads_before = memory.reads;
        const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(12));
        TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
        TEST_ASSERT_EQUAL_UINT64(12u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
        TEST_ASSERT_EQUAL_UINT(3u, (unsigned)(memory.reads - reads_before));
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                                memory.read_addresses[reads_before]);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102),
                                memory.read_addresses[reads_before + 1u]);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x180),
                                memory.read_addresses[reads_before + 2u]);
        TEST_ASSERT_EQUAL_UINT(0u, (unsigned)memory.byte_reads);
        TEST_ASSERT_EQUAL_UINT(0u, (unsigned)memory.write_attempts);
        owned_cpu_state after;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          owned_cpu_capture_state(cpu, &after));
        TEST_ASSERT_EQUAL_HEX32(
            (original & UINT32_C(0xffff0000)) | (uint32_t)values[destination_register],
            after.data_registers[destination_register]);
        uint16_t expected_sr = UINT16_C(0x2710);
        if ((values[destination_register] & UINT16_C(0x8000)) != 0u)
            expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0008));
        if (values[destination_register] == 0u)
            expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0004));
        TEST_ASSERT_EQUAL_HEX16(expected_sr, after.sr);
        tearDown();
    }
}

