static void move_word_absolute_short_to_indexed_memory_uses_22_cycles(void) {
    static const struct {
        unsigned base_register;
        unsigned index_register;
        int address_index;
        uint32_t index_value;
        uint16_t index_extension;
        uint16_t source_value;
        uint32_t destination_address;
    } cases[] = {
        {0u, 1u, 0, UINT32_C(4), UINT16_C(0x1006), UINT16_C(0x1234),
         UINT32_C(0x16a)},
        {2u, 3u, 1, UINT32_C(0xfffffffe), UINT16_C(0xb808), UINT16_C(0x8000),
         UINT32_C(0x166)},
        {4u, 5u, 0, UINT32_C(0xfffffff8), UINT16_C(0x5004), UINT16_C(0),
         UINT32_C(0x15c)},
        {6u, 7u, 1, UINT32_C(6), UINT16_C(0xf8fa), UINT16_C(0xffff),
         UINT32_C(0x160)},
    };

    for (size_t index = 0u; index < sizeof(cases) / sizeof(cases[0]); ++index) {
        setUp();
        create_cpu();
        uint8_t program[6];
        size_t program_size = 0u;
        const uint16_t opcode = (uint16_t)(UINT16_C(0x31b8) |
                                            (uint16_t)(cases[index].base_register << 9));
        emit_word(program, &program_size, opcode);
        emit_word(program, &program_size, UINT16_C(0x0180));
        emit_word(program, &program_size, cases[index].index_extension);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          reset_with_program(program, program_size));
        memory.rom[0x180] = (uint8_t)(cases[index].source_value >> 8);
        memory.rom[0x181] = (uint8_t)cases[index].source_value;
        owned_cpu_state before;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          owned_cpu_capture_state(cpu, &before));
        before.address_registers[cases[index].base_register] = UINT32_C(0x160);
        if (cases[index].base_register == 7u) before.ssp = UINT32_C(0x160);
        if (cases[index].address_index != 0) {
            before.address_registers[cases[index].index_register] =
                cases[index].index_value;
            if (cases[index].index_register == 7u)
                before.ssp = cases[index].index_value;
        } else {
            before.data_registers[cases[index].index_register] =
                cases[index].index_value;
        }
        before.sr = UINT16_C(0x271f);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          owned_cpu_restore_state(cpu, &before));

        const size_t reads_before = memory.reads;
        const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(22));
        TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
        TEST_ASSERT_EQUAL_UINT64(22u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
        TEST_ASSERT_EQUAL_UINT(4u, (unsigned)(memory.reads - reads_before));
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                                memory.read_addresses[reads_before]);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102),
                                memory.read_addresses[reads_before + 1u]);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x180),
                                memory.read_addresses[reads_before + 2u]);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x104),
                                memory.read_addresses[reads_before + 3u]);
        TEST_ASSERT_EQUAL_UINT(0u, (unsigned)memory.byte_reads);
        TEST_ASSERT_EQUAL_UINT(1u, (unsigned)memory.write_attempts);
        TEST_ASSERT_EQUAL_HEX32(cases[index].destination_address,
                                memory.write_addresses[0]);
        TEST_ASSERT_EQUAL_HEX16(cases[index].source_value,
                                memory.write_values[0]);
        owned_cpu_state after;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          owned_cpu_capture_state(cpu, &after));
        uint16_t expected_sr = UINT16_C(0x2710);
        if ((cases[index].source_value & UINT16_C(0x8000)) != 0u)
            expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0008));
        if (cases[index].source_value == 0u)
            expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0004));
        TEST_ASSERT_EQUAL_HEX16(expected_sr, after.sr);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x160),
                                after.address_registers[cases[index].base_register]);
        tearDown();
    }
}

