static void cmpa_long_address_registers_compares_all_register_pairs_in_6_cycles(void) {
    static const struct {
        uint32_t source;
        uint32_t destination;
        uint16_t flags;
    } cases[] = {
        {UINT32_C(1), UINT32_C(0x80000000), UINT16_C(0x0002)}, /* V */
        {UINT32_C(1), UINT32_C(0), UINT16_C(0x0009)}, /* N,C */
        {UINT32_C(0x12345678), UINT32_C(0x12345678), UINT16_C(0x0004)}, /* Z */
        {UINT32_C(0xffffffff), UINT32_C(0x7fffffff), UINT16_C(0x000b)}, /* N,V,C */
    };

    for (unsigned source_register = 0u; source_register < 8u; ++source_register) {
        for (unsigned destination_register = 0u; destination_register < 8u;
             ++destination_register) {
            const size_t case_index =
                (size_t)(source_register + destination_register) %
                (sizeof(cases) / sizeof(cases[0]));
            const int same_register = source_register == destination_register;
            const uint32_t source = cases[case_index].source;
            const uint32_t destination = same_register ? source :
                                                         cases[case_index].destination;
            const uint16_t expected_flags =
                same_register ? UINT16_C(0x0004) : cases[case_index].flags;
            setUp();
            create_cpu();
            uint8_t program[2];
            size_t program_size = 0u;
            emit_word(program, &program_size,
                      (uint16_t)(UINT16_C(0xb1c8) |
                                 (uint16_t)(destination_register << 9) |
                                 (uint16_t)source_register));
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              reset_with_program(program, program_size));
            owned_cpu_state before;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_capture_state(cpu, &before));
            before.address_registers[source_register] = source;
            before.address_registers[destination_register] = destination;
            if (destination_register == 7u) before.ssp = destination;
            else if (source_register == 7u) before.ssp = source;
            const uint16_t extend =
                (uint16_t)((source_register + destination_register) & 1u
                               ? UINT16_C(0x0010) : 0u);
            before.sr = (uint16_t)(UINT16_C(0x270f) | extend);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_restore_state(cpu, &before));

            const size_t reads_before = memory.reads;
            const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(6));
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
            TEST_ASSERT_EQUAL_UINT64(6u, result.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
            TEST_ASSERT_EQUAL_UINT(1u, (unsigned)(memory.reads - reads_before));
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                                    memory.read_addresses[reads_before]);
            TEST_ASSERT_EQUAL_UINT(0u, (unsigned)memory.byte_reads);
            TEST_ASSERT_EQUAL_UINT(0u, (unsigned)memory.write_attempts);

            owned_cpu_state after;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &after));
            TEST_ASSERT_EQUAL_HEX32(source,
                                    after.address_registers[source_register]);
            TEST_ASSERT_EQUAL_HEX32(destination,
                                    after.address_registers[destination_register]);
            TEST_ASSERT_EQUAL_HEX16(
                (uint16_t)(UINT16_C(0x2700) | extend | expected_flags),
                after.sr);
            tearDown();
        }
    }
}

static void cmpm_word_postincrement_compares_all_register_pairs_in_12_cycles(void) {
    static const struct {
        uint16_t source;
        uint16_t destination;
        uint16_t flags;
    } cases[] = {
        {UINT16_C(0x0001), UINT16_C(0x8000), UINT16_C(0x0002)}, /* V */
        {UINT16_C(0x0001), UINT16_C(0x0000), UINT16_C(0x0009)}, /* N,C */
        {UINT16_C(0x55aa), UINT16_C(0x55aa), UINT16_C(0x0004)}, /* Z */
        {UINT16_C(0xffff), UINT16_C(0x7fff), UINT16_C(0x000b)}, /* N,V,C */
    };

    for (unsigned source_register = 0u; source_register < 8u; ++source_register) {
        for (unsigned destination_register = 0u; destination_register < 8u;
             ++destination_register) {
            const size_t case_index =
                (size_t)(source_register + destination_register) %
                (sizeof(cases) / sizeof(cases[0]));
            const uint32_t source_address = UINT32_C(0x180) + source_register * 8u;
            const uint32_t destination_address = source_register == destination_register
                                                     ? source_address + UINT32_C(2)
                                                     : UINT32_C(0x1c0) +
                                                           destination_register * 8u;
            setUp();
            create_cpu();
            memory.rom[source_address] = (uint8_t)(cases[case_index].source >> 8);
            memory.rom[source_address + 1u] = (uint8_t)cases[case_index].source;
            memory.rom[destination_address] =
                (uint8_t)(cases[case_index].destination >> 8);
            memory.rom[destination_address + 1u] =
                (uint8_t)cases[case_index].destination;

            uint8_t program[2];
            size_t program_size = 0u;
            emit_word(program, &program_size,
                      (uint16_t)(UINT16_C(0xb148) |
                                 (uint16_t)(destination_register << 9) |
                                 (uint16_t)source_register));
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              reset_with_program(program, program_size));
            owned_cpu_state before;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_capture_state(cpu, &before));
            before.address_registers[source_register] = source_address;
            if (source_register == 7u) before.ssp = source_address;
            if (destination_register != source_register) {
                before.address_registers[destination_register] = destination_address;
                if (destination_register == 7u) before.ssp = destination_address;
            }
            const uint16_t extend =
                (uint16_t)((source_register + destination_register) & 1u ? 0x0010u : 0u);
            before.sr = (uint16_t)(UINT16_C(0x270f) | extend);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));

            const size_t reads_before = memory.reads;
            const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(12));
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
            TEST_ASSERT_EQUAL_UINT64(12u, result.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
            TEST_ASSERT_EQUAL_UINT(3u, (unsigned)(memory.reads - reads_before));
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                                    memory.read_addresses[reads_before]);
            TEST_ASSERT_EQUAL_HEX32(source_address,
                                    memory.read_addresses[reads_before + 1u]);
            TEST_ASSERT_EQUAL_HEX32(destination_address,
                                    memory.read_addresses[reads_before + 2u]);
            TEST_ASSERT_EQUAL_UINT(0u, (unsigned)memory.byte_reads);
            TEST_ASSERT_EQUAL_UINT(0u, (unsigned)memory.write_attempts);

            owned_cpu_state after;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &after));
            if (destination_register == source_register) {
                TEST_ASSERT_EQUAL_HEX32(source_address + UINT32_C(4),
                                        after.address_registers[destination_register]);
            } else {
                TEST_ASSERT_EQUAL_HEX32(source_address + UINT32_C(2),
                                        after.address_registers[source_register]);
                TEST_ASSERT_EQUAL_HEX32(destination_address + UINT32_C(2),
                                        after.address_registers[destination_register]);
            }
            TEST_ASSERT_EQUAL_HEX16(
                (uint16_t)(UINT16_C(0x2700) | extend | cases[case_index].flags),
                after.sr);
            tearDown();
        }
    }

    /* A misaligned source raises vector 3 before either operand read or
     * postincrement. */
    setUp();
    create_cpu();
    uint8_t program[2];
    size_t program_size = 0u;
    emit_word(program, &program_size, UINT16_C(0xb549)); /* CMPM.W (A1)+,(A2)+ */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, program_size));
    set_vector(12u, UINT32_C(0x140));
    owned_cpu_state before;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
    before.address_registers[1] = UINT32_C(0x181);
    before.address_registers[2] = UINT32_C(0x190);
    before.sr = UINT16_C(0x270f);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));
    const size_t reads_before = memory.reads;
    const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(50));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(50u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(0u, result.instructions);
    TEST_ASSERT_EQUAL_UINT(3u, (unsigned)(memory.reads - reads_before));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100), memory.read_addresses[reads_before]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(12), memory.read_addresses[reads_before + 1u]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(14), memory.read_addresses[reads_before + 2u]);
    TEST_ASSERT_EQUAL_UINT(7u, (unsigned)memory.write_attempts);
    owned_cpu_state after;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &after));
    TEST_ASSERT_EQUAL_UINT8(3u, after.last_exception_vector);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x140), after.pc);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x181), after.address_registers[1]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x190), after.address_registers[2]);
    tearDown();

    /* An odd destination is detected after the source word access and its
     * postincrement, but before any destination operand read. */
    setUp();
    create_cpu();
    program_size = 0u;
    emit_word(program, &program_size, UINT16_C(0xb549));
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, program_size));
    set_vector(12u, UINT32_C(0x140));
    memory.rom[0x180] = 0x12u;
    memory.rom[0x181] = 0x34u;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
    before.address_registers[1] = UINT32_C(0x180);
    before.address_registers[2] = UINT32_C(0x191);
    before.sr = UINT16_C(0x270f);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));
    const size_t destination_reads_before = memory.reads;
    const owned_cpu_run_result destination_result =
        owned_cpu_run(cpu, UINT64_C(50));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, destination_result.reason);
    TEST_ASSERT_EQUAL_UINT64(0u, destination_result.instructions);
    TEST_ASSERT_EQUAL_UINT(4u,
                           (unsigned)(memory.reads - destination_reads_before));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                            memory.read_addresses[destination_reads_before]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x180),
                            memory.read_addresses[destination_reads_before + 1u]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(12),
                            memory.read_addresses[destination_reads_before + 2u]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(14),
                            memory.read_addresses[destination_reads_before + 3u]);
    TEST_ASSERT_EQUAL_UINT(7u, (unsigned)memory.write_attempts);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &after));
    TEST_ASSERT_EQUAL_UINT8(3u, after.last_exception_vector);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x140), after.pc);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x182), after.address_registers[1]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x191), after.address_registers[2]);
    tearDown();
}

/* Unobserved size/direction neighbors remain unsupported without side effects. */
static void cmpm_unimplemented_long_neighbor_stays_unsupported(void) {
    static const uint16_t opcodes[] = {0xb389u}; /* CMPM.L (A1)+,(A1)+ */
    for (size_t index = 0u; index < sizeof(opcodes) / sizeof(opcodes[0]); ++index) {
        setUp();
        create_cpu();
        uint8_t program[2];
        size_t length = 0u;
        emit_word(program, &length, opcodes[index]);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, length));
        owned_cpu_state before;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
        owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(20));
        TEST_ASSERT_EQUAL_MESSAGE(OWNED_CPU_UNSUPPORTED_OPCODE, result.reason, "neighbor");
        TEST_ASSERT_EQUAL_HEX16(opcodes[index], result.instruction_register);
        TEST_ASSERT_EQUAL_UINT(0u, (unsigned)memory.write_attempts);
        TEST_ASSERT_EQUAL_UINT(0u, (unsigned)memory.byte_reads);
        owned_cpu_state after;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &after));
        TEST_ASSERT_EQUAL_HEX32(before.pc, after.pc);
        TEST_ASSERT_EQUAL_HEX16(before.sr, after.sr);
        for (unsigned reg = 0u; reg < 8u; ++reg) {
            TEST_ASSERT_EQUAL_HEX32(before.address_registers[reg], after.address_registers[reg]);
            TEST_ASSERT_EQUAL_HEX32(before.data_registers[reg], after.data_registers[reg]);
        }
        tearDown();
    }
}

