static void move_long_data_register_to_postincrement_writes_and_increments(void) {
    static const struct {
        uint32_t value;
        uint16_t sr_after;
    } cases[] = {{0x80000001u, 0x2718u}, {0x00000000u, 0x2714u}, {0x12345678u, 0x2710u}};
    for (size_t index = 0u; index < sizeof(cases) / sizeof(cases[0]); ++index) {
        setUp();
        create_cpu();
        const uint8_t program[] = {0x28u, 0xc3u}; /* MOVE.L D3,(A4)+ */
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
        owned_cpu_state state;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
        state.address_registers[4] = UINT32_C(0x180);
        state.data_registers[3] = cases[index].value;
        state.sr = UINT16_C(0x271f);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
        const size_t reads_before = memory.reads;
        owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(12));
        TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
        TEST_ASSERT_EQUAL_UINT64(12u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
        TEST_ASSERT_EQUAL_UINT(1u, (unsigned)(memory.reads - reads_before));
        TEST_ASSERT_EQUAL_UINT(0u, (unsigned)memory.byte_reads);
        TEST_ASSERT_EQUAL_UINT(2u, (unsigned)memory.write_attempts);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x180), memory.write_addresses[0]);
        TEST_ASSERT_EQUAL_HEX16((uint16_t)(cases[index].value >> 16), memory.write_values[0]);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x182), memory.write_addresses[1]);
        TEST_ASSERT_EQUAL_HEX16((uint16_t)cases[index].value, memory.write_values[1]);
        owned_cpu_state after;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &after));
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x184), after.address_registers[4]);
        TEST_ASSERT_EQUAL_HEX32(cases[index].value, after.data_registers[3]);
        TEST_ASSERT_EQUAL_HEX16(cases[index].sr_after, after.sr);
        tearDown();
    }

    /* Odd destination: address error (vector 3), no write, An unchanged. */
    setUp();
    create_cpu();
    set_vector(12u, UINT32_C(0x140));
    const uint8_t program[] = {0x28u, 0xc3u};
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.address_registers[4] = UINT32_C(0x181);
    state.data_registers[3] = UINT32_C(0x12345678);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(50));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    owned_cpu_observation observation;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_UINT8(3u, observation.last_exception_vector);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x181), observation.address_registers[4]);
    for (size_t i = 0; i < memory.write_attempts && i < MAX_WRITES; ++i)
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x181), memory.write_addresses[i]);
    tearDown();
}

/* MOVE.B Dn,(An)+ (guest demanded, plan 05-27). MOVE sets N/Z from the low
 * byte, clears V/C, and preserves X (M68000 Family PRM MOVE, pp. 4-116 to
 * 4-118). Byte postincrement is one except for A7, which advances by two to
 * preserve stack alignment (PRM §2.2.4). Timing: MC68000 User's Manual Rev.
 * 9.1 Table 8-2 (printed p. 8-2), Dn to (An)+ byte 8(1/1). */
static void move_byte_data_register_to_postincrement_writes_and_increments(void) {
    setUp();
    create_cpu();
    const uint8_t program[] = {0x1au, 0xc3u, 0x1eu, 0xc3u};
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.address_registers[5] = UINT32_C(0x181);
    state.address_registers[7] = UINT32_C(0x220);
    state.ssp = UINT32_C(0x220);
    state.data_registers[3] = UINT32_C(0x12345680);
    state.sr = UINT16_C(0x271f);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
    size_t reads_before = memory.reads;
    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(8));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(8u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
    TEST_ASSERT_EQUAL_UINT(1u, (unsigned)(memory.reads - reads_before));
    TEST_ASSERT_EQUAL_UINT(1u, (unsigned)memory.write_attempts);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x181), memory.byte_write_addresses[0]);
    TEST_ASSERT_EQUAL_HEX8(UINT8_C(0x80), memory.byte_write_values[0]);
    owned_cpu_observation observation;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102), observation.pc);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x182), observation.address_registers[5]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x220), observation.address_registers[7]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x12345680), observation.data_registers[3]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2718), observation.sr);

    /* A7 uses a two-byte byte-postincrement; a zero low byte sets Z. */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.data_registers[3] = UINT32_C(0x12345600);
    state.sr = UINT16_C(0x2713);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
    reads_before = memory.reads;
    result = owned_cpu_run(cpu, UINT64_C(8));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(8u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT(1u, (unsigned)(memory.reads - reads_before));
    TEST_ASSERT_EQUAL_UINT(2u, (unsigned)memory.write_attempts);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x220), memory.byte_write_addresses[1]);
    TEST_ASSERT_EQUAL_HEX8(UINT8_C(0x00), memory.byte_write_values[1]);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x104), observation.pc);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x182), observation.address_registers[5]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x222), observation.address_registers[7]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x12345600), observation.data_registers[3]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2714), observation.sr);
    tearDown();
}

static void move_byte_data_register_to_predecrement_neighbors_stay_unsupported(void) {
    static const struct {
        uint8_t program[2];
        const char *name;
    } neighbors[] = {
        {{0x1b, 0x09}, "MOVE.B A1,-(A5)"},
    };
    for (size_t index = 0u; index < sizeof(neighbors) / sizeof(neighbors[0]); ++index) {
        setUp();
        create_cpu();
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(neighbors[index].program, 2u));
        owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(32));
        TEST_ASSERT_EQUAL_MESSAGE(OWNED_CPU_UNSUPPORTED_OPCODE, result.reason,
                                  neighbors[index].name);
        TEST_ASSERT_EQUAL_UINT(0u, (unsigned)memory.write_attempts);
        TEST_ASSERT_EQUAL_UINT(0u, (unsigned)memory.byte_reads);
        tearDown();
    }
}

/* MOVE.B Dn,-(An) is an 8-clock MC68000 operation (UM Rev. 9.1 Table 8-2,
 * printed p. 8-2). MOVE sets N/Z from the byte, clears V/C and preserves X
 * (PRM §4 MOVE, pp. 4-116–4-118). A7 byte predecrement is two to preserve
 * stack alignment (PRM §2.2.4). */
static void move_byte_data_register_to_predecrement_covers_all_register_pairs(void) {
    static const uint8_t values[8] = {
        UINT8_C(0x00), UINT8_C(0x01), UINT8_C(0x7f), UINT8_C(0x80),
        UINT8_C(0xff), UINT8_C(0x34), UINT8_C(0x81), UINT8_C(0x55),
    };
    for (unsigned address_register = 0u; address_register < 8u;
         ++address_register) {
        for (unsigned data_register = 0u; data_register < 8u;
             ++data_register) {
            setUp();
            create_cpu();
            const uint16_t opcode = (uint16_t)(UINT16_C(0x1100) |
                (uint16_t)(address_register << 9) |
                (uint16_t)data_register);
            const uint8_t program[] = {
                (uint8_t)(opcode >> 8), (uint8_t)opcode};
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              reset_with_program(program, sizeof(program)));
            owned_cpu_state before;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_capture_state(cpu, &before));
            for (unsigned reg = 0u; reg < 8u; ++reg) {
                before.data_registers[reg] =
                    UINT32_C(0x5a5a0000) | (uint32_t)values[reg];
                before.address_registers[reg] =
                    UINT32_C(0x240) + (uint32_t)reg * UINT32_C(0x10);
            }
            before.address_registers[address_register] = UINT32_C(0x182);
            before.ssp = before.address_registers[7];
            before.usp = UINT32_C(0x350);
            before.sr = UINT16_C(0x271f);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_restore_state(cpu, &before));

            const size_t reads_before = memory.reads;
            const size_t writes_before = memory.write_attempts;
            const owned_cpu_run_result run =
                owned_cpu_run(cpu, UINT64_C(8));
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, run.reason);
            TEST_ASSERT_EQUAL_UINT64(8u, run.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, run.instructions);
            TEST_ASSERT_EQUAL_UINT(1u, (unsigned)(memory.reads - reads_before));
            TEST_ASSERT_EQUAL_UINT(1u,
                                   (unsigned)(memory.write_attempts - writes_before));
            const uint32_t decrement = address_register == 7u ? 2u : 1u;
            const uint32_t expected_address = UINT32_C(0x182) - decrement;
            TEST_ASSERT_EQUAL_HEX32(expected_address,
                                    memory.byte_write_addresses[writes_before]);
            TEST_ASSERT_EQUAL_HEX8(values[data_register],
                                   memory.byte_write_values[writes_before]);

            owned_cpu_observation after;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102), after.pc);
            uint16_t expected_sr = (uint16_t)(before.sr &
                                              (uint16_t)~UINT16_C(0x000f));
            if (values[data_register] == 0u)
                expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0004));
            if ((values[data_register] & UINT8_C(0x80)) != 0u)
                expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0008));
            TEST_ASSERT_EQUAL_HEX16(expected_sr, after.sr);
            for (unsigned reg = 0u; reg < 8u; ++reg) {
                TEST_ASSERT_EQUAL_HEX32(before.data_registers[reg],
                                        after.data_registers[reg]);
                const uint32_t expected_register = reg == address_register
                    ? expected_address : before.address_registers[reg];
                TEST_ASSERT_EQUAL_HEX32(expected_register,
                                        after.address_registers[reg]);
            }
            if (address_register == 7u) {
                TEST_ASSERT_EQUAL_HEX32(expected_address, after.ssp);
                TEST_ASSERT_EQUAL_HEX32(before.usp, after.usp);
            }
            tearDown();
        }
    }
}

static void move_byte_data_register_to_predecrement_faults_and_counter_preflight_keep_boundaries(void) {
    setUp();
    create_cpu();
    const uint16_t opcode = UINT16_C(0x1503); /* MOVE.B D3,-(A2) */
    const uint8_t program[] = {(uint8_t)(opcode >> 8), (uint8_t)opcode};
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      reset_with_program(program, sizeof(program)));
    owned_cpu_state before;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_capture_state(cpu, &before));
    before.address_registers[2] = UINT32_C(0x182);
    before.data_registers[3] = UINT32_C(0x12345680);
    before.sr = UINT16_C(0x271f);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_restore_state(cpu, &before));
    memory.fail_write_on = 1u;
    owned_cpu_run_result run = owned_cpu_run(cpu, UINT64_C(8));
    TEST_ASSERT_EQUAL(OWNED_CPU_HOST_FAULT, run.reason);
    TEST_ASSERT_EQUAL_UINT(1u, memory.write_attempts);
    TEST_ASSERT_EQUAL_UINT(0u, memory.successful_writes);
    owned_cpu_state faulted;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_test_capture_faulted_state(cpu, &faulted));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x181), faulted.address_registers[2]);
    TEST_ASSERT_EQUAL_HEX16(before.sr, faulted.sr);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100), faulted.fault_pc);
    TEST_ASSERT_EQUAL_HEX16(opcode, faulted.instruction_register);
    tearDown();

    setUp();
    create_cpu();
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      reset_with_program(program, sizeof(program)));
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_capture_state(cpu, &before));
    before.address_registers[2] = UINT32_C(0x182);
    before.data_registers[3] = UINT32_C(0x12345680);
    before.sr = UINT16_C(0x271f);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_restore_state(cpu, &before));
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_test_seed_counters(
        cpu, 0u, 0u, 0u, 0u, UINT64_MAX - UINT64_C(1)));
    const size_t reads_before = memory.reads;
    run = owned_cpu_run(cpu, UINT64_C(8));
    TEST_ASSERT_EQUAL(OWNED_CPU_COUNTER_OVERFLOW, run.reason);
    TEST_ASSERT_EQUAL_UINT(1u, memory.reads - reads_before);
    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
    owned_cpu_observation after;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_observe(cpu, &after));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x182), after.address_registers[2]);
    TEST_ASSERT_EQUAL_HEX16(before.sr, after.sr);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100), after.pc);
    tearDown();
}

/* Unobserved address-register-direct and PC-relative neighbors stay closed.
 * MOVE.L Dn,-(An) is separately admitted below. */
static void move_long_data_register_to_postincrement_neighbors_stay_unsupported(void) {
    static const uint16_t opcodes[] = {0x25cbu};
    for (size_t index = 0u; index < sizeof(opcodes) / sizeof(opcodes[0]); ++index) {
        setUp();
        create_cpu();
        uint8_t program[2];
        size_t length = 0u;
        emit_word(program, &length, opcodes[index]);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, length));
        owned_cpu_state before;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
        owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(32));
        TEST_ASSERT_EQUAL_MESSAGE(OWNED_CPU_UNSUPPORTED_OPCODE, result.reason, "neighbor");
        TEST_ASSERT_EQUAL_HEX16(opcodes[index], result.instruction_register);
        TEST_ASSERT_EQUAL_UINT(0u, (unsigned)memory.write_attempts);
        TEST_ASSERT_EQUAL_UINT(0u, (unsigned)memory.byte_reads);
        owned_cpu_state after;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &after));
        TEST_ASSERT_EQUAL_HEX32(before.pc, after.pc);
        for (unsigned reg = 0u; reg < 8u; ++reg) {
            TEST_ASSERT_EQUAL_HEX32(before.address_registers[reg], after.address_registers[reg]);
        }
        tearDown();
    }
}

/* MOVE.L Dn,-(An): the pinned MAME generated 68000 handler emits the low word
 * at An-2 followed by the high word at An-4. Final memory remains big-endian.
 * Then An reflects the decremented address. The value sets N/Z, clears V/C,
 * and preserves X. */
static void move_long_data_register_to_predecrement_covers_all_register_pairs(void) {
    static const uint32_t data_values[8] = {
        UINT32_C(0x80000000), UINT32_C(0x00000000), UINT32_C(0x00000001),
        UINT32_C(0xffffffff), UINT32_C(0x12345678), UINT32_C(0x7fffffff),
        UINT32_C(0xf0f0f0f0), UINT32_C(0x5555aaaa)};
    for (unsigned destination_base = 0u; destination_base < 8u;
         destination_base += 2u) {
        memset(&memory, 0, sizeof(memory));
        uint8_t program[32];
        size_t length = 0u;
        for (unsigned destination = destination_base;
             destination < destination_base + 2u; ++destination) {
            for (unsigned source = 0u; source < 8u; ++source) {
                const uint16_t opcode = (uint16_t)(UINT16_C(0x2100) |
                    (uint16_t)(destination << 9) | (uint16_t)source);
                emit_word(program, &length, opcode);
            }
        }
        create_cpu();
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, length));
        owned_cpu_state before;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          owned_cpu_capture_state(cpu, &before));
        uint32_t expected_addresses[8];
        for (unsigned reg = 0u; reg < 8u; ++reg) {
            expected_addresses[reg] = UINT32_C(0x700) +
                                      (uint32_t)(reg * 0x100u);
            before.address_registers[reg] = expected_addresses[reg];
            before.data_registers[reg] = data_values[reg];
        }
        before.sr = UINT16_C(0x271f);
        before.ssp = before.address_registers[7];
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          owned_cpu_restore_state(cpu, &before));

        size_t instruction = 0u;
        for (unsigned destination = destination_base;
             destination < destination_base + 2u; ++destination) {
            for (unsigned source = 0u; source < 8u; ++source, ++instruction) {
            const uint32_t value = data_values[source];
            expected_addresses[destination] -= UINT32_C(4);
            const size_t reads_before = memory.reads;
            const size_t writes_before = memory.write_attempts;
            const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(12));
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
            TEST_ASSERT_EQUAL_UINT64(12u, result.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
            TEST_ASSERT_EQUAL_UINT(1u, memory.reads - reads_before);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100) +
                                    (uint32_t)(instruction * 2u),
                                    memory.read_addresses[reads_before]);
            TEST_ASSERT_EQUAL_UINT(2u, memory.write_attempts - writes_before);
            TEST_ASSERT_EQUAL_HEX32(expected_addresses[destination] + 2u,
                                    memory.write_addresses[writes_before]);
            TEST_ASSERT_EQUAL_HEX16((uint16_t)value,
                                    memory.write_values[writes_before]);
            TEST_ASSERT_EQUAL_HEX32(expected_addresses[destination],
                                    memory.write_addresses[writes_before + 1u]);
            TEST_ASSERT_EQUAL_HEX16((uint16_t)(value >> 16),
                                    memory.write_values[writes_before + 1u]);

            owned_cpu_state after;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &after));
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102) +
                                    (uint32_t)(instruction * 2u), after.pc);
            uint16_t expected_sr = UINT16_C(0x2710);
            if (value == 0u) expected_sr |= UINT16_C(0x0004);
            if ((value & UINT32_C(0x80000000)) != 0u)
                expected_sr |= UINT16_C(0x0008);
            TEST_ASSERT_EQUAL_HEX16(expected_sr, after.sr);
            for (unsigned reg = 0u; reg < 8u; ++reg) {
                TEST_ASSERT_EQUAL_HEX32(data_values[reg], after.data_registers[reg]);
                TEST_ASSERT_EQUAL_HEX32(expected_addresses[reg],
                                        after.address_registers[reg]);
            }
            TEST_ASSERT_EQUAL_HEX32(expected_addresses[7], after.ssp);
            }
        }
        TEST_ASSERT_EQUAL_UINT(16u, instruction);
        TEST_ASSERT_EQUAL_UINT(32u, memory.write_attempts);
        owned_cpu_destroy(cpu);
        cpu = NULL;
    }
}

static void move_long_data_register_to_predecrement_odd_address_enters_address_error(void) {
    create_cpu();
    const uint8_t program[] = {0x21u, 0x00u}; /* MOVE.L D0,-(A0) */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      reset_with_program(program, sizeof(program)));
    set_vector(12u, UINT32_C(0x140));
    owned_cpu_state before;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_capture_state(cpu, &before));
    before.address_registers[0] = UINT32_C(0x201);
    before.data_registers[0] = UINT32_C(0x12345678);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_restore_state(cpu, &before));

    const size_t writes_before = memory.write_attempts;
    const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(50));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(50u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(0u, result.instructions);
    owned_cpu_observation after;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
    TEST_ASSERT_EQUAL_UINT8(3u, after.last_exception_vector);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x140), after.pc);
    /* The pinned candidate evaluates -(A0) before detecting odd alignment. */
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x1fd), after.address_registers[0]);
    for (size_t write = writes_before; write < memory.write_attempts; ++write) {
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x1fd), memory.write_addresses[write]);
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x1ff), memory.write_addresses[write]);
    }
    tearDown();
}

static void move_long_immediate_to_absolute_long_uses_28_cycles(void) {
    create_cpu();
    const uint8_t program[] = {
        0x23u, 0xfcu, 0x89u, 0xabu, 0xcdu, 0xefu,
        0x00u, 0x00u, 0x01u, 0x80u};
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(28));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(28u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
    TEST_ASSERT_EQUAL_UINT(2u, memory.write_attempts);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x180), memory.write_addresses[0]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x89ab), memory.write_values[0]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x182), memory.write_addresses[1]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0xcdef), memory.write_values[1]);

    const uint8_t unsupported_pc_destination[] = {
        0x25u, 0xfcu, 0x00u, 0x01u}; /* PC-relative destinations are not writable. */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(
        unsupported_pc_destination, sizeof(unsupported_pc_destination)));
    result = owned_cpu_run(cpu, UINT64_C(28));
    TEST_ASSERT_EQUAL(OWNED_CPU_UNSUPPORTED_OPCODE, result.reason);

    const uint8_t unsupported_absolute_short[] = {0x21u, 0xfcu};
    const size_t writes_before_short = memory.write_attempts;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(
        unsupported_absolute_short, sizeof(unsupported_absolute_short)));
    result = owned_cpu_run(cpu, UINT64_C(28));
    TEST_ASSERT_EQUAL(OWNED_CPU_UNSUPPORTED_OPCODE, result.reason);
    TEST_ASSERT_EQUAL_UINT(writes_before_short, memory.write_attempts);
}

