/* Guest-observed (05-02 task 2): MOVE.W Dn,(d8,An,Xn). The selected destination
 * uses only the MC68000 brief extension; all index classes/sizes and signed
 * displacements are covered. UM Rev. 9.1 Table 8-2, p. 8-2: 14(2/1). */
static void move_word_data_register_to_indexed_memory_covers_registers_and_index_forms(void) {
    static const uint32_t data_values[8] = {
        UINT32_C(0x12340000), UINT32_C(0x98760001), UINT32_C(0xaaaa7fff),
        UINT32_C(0x55558000), UINT32_C(0x0000ffff), UINT32_C(0x11110000),
        UINT32_C(0x22220002), UINT32_C(0x3333fffe)};
    static const uint32_t index_values[8] = {
        UINT32_C(0x00000002), UINT32_C(0xfffffffc), UINT32_C(0x00010003),
        UINT32_C(0xffff0005), UINT32_C(0x7fff0000), UINT32_C(0x80000004),
        UINT32_C(0x12340007), UINT32_C(0xfffffff9)};
    static const int8_t displacements[4] = {-128, -1, 0, 127};

    for (unsigned base_reg = 0u; base_reg < 8u; ++base_reg) {
        for (unsigned source_reg = 0u; source_reg < 8u; ++source_reg) {
            for (unsigned index_variant = 0u; index_variant < 4u;
                 ++index_variant) {
                const unsigned case_index = base_reg * 32u +
                    source_reg * 4u + index_variant;
                const unsigned index_reg = (source_reg + 1u) & 7u;
                const int index_is_address = (index_variant & 1u) != 0u;
                const int index_is_long = (index_variant & 2u) != 0u;
                const int aliased_address_index = index_is_address != 0 &&
                                                   index_reg == base_reg;
                const int8_t displacement = aliased_address_index != 0
                    ? 0 : displacements[case_index & 3u];
                const uint32_t target = UINT32_C(0x140) +
                    (case_index % 64u) * 2u;
                const uint16_t opcode = (uint16_t)(UINT16_C(0x3180) |
                    (base_reg << 9) | source_reg);
                const uint16_t extension = (uint16_t)(
                    (index_is_address != 0 ? UINT16_C(0x8000) : 0u) |
                    (index_reg << 12) |
                    (index_is_long != 0 ? UINT16_C(0x0800) : 0u) |
                    (uint8_t)displacement);
                const uint8_t program[] = {
                    (uint8_t)(opcode >> 8), (uint8_t)opcode,
                    (uint8_t)(extension >> 8), (uint8_t)extension};
                memset(&memory, 0, sizeof(memory));
                create_cpu();
                TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                  reset_with_program(program, sizeof(program)));
                owned_cpu_state before;
                TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                  owned_cpu_capture_state(cpu, &before));
                for (unsigned reg = 0u; reg < 8u; ++reg) {
                    before.data_registers[reg] = UINT32_C(0xa5a50000) | reg;
                    before.address_registers[reg] =
                        UINT32_C(0x0100) + reg * 2u;
                }
                before.data_registers[source_reg] = data_values[case_index & 7u];
                uint32_t index_full = 0u;
                if (index_is_address != 0) {
                    index_full = index_values[index_reg];
                    if (index_reg == base_reg) {
                        /* Aliased An is both terms in EA = An + d8 + Xn. */
                        before.address_registers[base_reg] = target / 2u;
                        index_full = before.address_registers[base_reg];
                    } else {
                        before.address_registers[index_reg] = index_full;
                    }
                } else {
                    index_full = before.data_registers[index_reg];
                    if (index_reg != source_reg)
                        before.data_registers[index_reg] =
                            index_values[index_reg];
                    index_full = before.data_registers[index_reg];
                }
                const uint32_t effective_index = index_is_long != 0
                    ? index_full
                    : expected_sign_extend_word((uint16_t)index_full);
                if (aliased_address_index == 0) {
                    before.address_registers[base_reg] = target -
                        (uint32_t)(int32_t)displacement - effective_index;
                }
                before.sr = UINT16_C(0x271f);
                before.ssp = before.address_registers[7];
                TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                  owned_cpu_restore_state(cpu, &before));

                const size_t reads_before = memory.reads;
                const size_t writes_before = memory.write_attempts;
                owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(14));
                TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
                TEST_ASSERT_EQUAL_UINT64(14u, result.elapsed_cycles);
                TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
                TEST_ASSERT_EQUAL_UINT(2u, memory.reads - reads_before);
                TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100),
                                        memory.read_addresses[reads_before]);
                TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102),
                                        memory.read_addresses[reads_before + 1u]);
                TEST_ASSERT_EQUAL_UINT(1u, memory.write_attempts - writes_before);
                TEST_ASSERT_EQUAL_HEX32(target,
                                        memory.write_addresses[writes_before]);
                const uint16_t value = (uint16_t)before.data_registers[source_reg];
                TEST_ASSERT_EQUAL_HEX16(value,
                                        memory.write_values[writes_before]);
                owned_cpu_observation after;
                TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
                uint16_t expected_sr = (uint16_t)(before.sr &
                    (uint16_t)~UINT16_C(0x000f));
                if ((value & UINT16_C(0x8000)) != 0u)
                    expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0008));
                if (value == 0u)
                    expected_sr = (uint16_t)(expected_sr | UINT16_C(0x0004));
                TEST_ASSERT_EQUAL_HEX16(expected_sr, after.sr);
                for (unsigned reg = 0u; reg < 8u; ++reg) {
                    TEST_ASSERT_EQUAL_HEX32(before.data_registers[reg],
                                            after.data_registers[reg]);
                    TEST_ASSERT_EQUAL_HEX32(before.address_registers[reg],
                                            after.address_registers[reg]);
                }
                owned_cpu_destroy(cpu);
                cpu = NULL;
            }
        }
    }
}

static void move_word_data_register_to_indexed_odd_destination_enters_address_error(void) {
    create_cpu();
    const uint8_t program[] = {0x31u, 0x80u, 0x10u, 0x01u};
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      reset_with_program(program, sizeof(program)));
    set_vector(12u, UINT32_C(0x140));
    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.address_registers[0] = UINT32_C(0x1e0);
    state.data_registers[0] = UINT32_C(0x1234abcd);
    state.data_registers[1] = 0u;
    state.ssp = state.address_registers[7];
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
    const size_t writes_before = memory.write_attempts;
    const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(50));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    owned_cpu_observation after;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
    TEST_ASSERT_EQUAL_UINT8(3u, after.last_exception_vector);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x140), after.pc);
    for (size_t i = writes_before; i < memory.write_attempts && i < MAX_WRITES; ++i)
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x1e1), memory.write_addresses[i]);
}

static void move_word_data_register_to_indexed_neighbors_stay_unsupported(void) {
    static const struct { uint8_t program[4]; const char *name; } neighbors[] = {
        {{0x31u, 0x88u, 0u, 0u}, "MOVE.W An,(d8,An,Xn)"},
        {{0x37u, 0xc0u, 0u, 0u}, "MOVE.W D0,(d8,PC,Xn)"},
        {{0x31u, 0x80u, 0x01u, 0x00u}, "MOVE.W reserved brief extension"},
        {{0x21u, 0x80u, 0x01u, 0x00u}, "MOVE.L reserved brief extension"},
    };
    for (size_t i = 0u; i < sizeof(neighbors) / sizeof(neighbors[0]); ++i) {
        memset(&memory, 0, sizeof(memory));
        create_cpu();
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          reset_with_program(neighbors[i].program,
                                             sizeof(neighbors[i].program)));
        const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(40));
        TEST_ASSERT_EQUAL_MESSAGE(OWNED_CPU_UNSUPPORTED_OPCODE, result.reason,
                                 neighbors[i].name);
        TEST_ASSERT_EQUAL_UINT64(0u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(0u, result.instructions);
        TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
        owned_cpu_destroy(cpu);
        cpu = NULL;
    }
}

static void move_word_data_register_to_address_indirect_uses_8_cycles(void) {
    create_cpu();
    const uint8_t program[] = {0x30u, 0x80u}; /* MOVE.W D0,(A0) */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    owned_cpu_state state;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.address_registers[0] = UINT32_C(0x120);
    state.data_registers[0] = UINT32_C(0x1234abcd);
    state.sr = UINT16_C(0x2710);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(8));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(8u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
    TEST_ASSERT_EQUAL_UINT(1u, memory.write_attempts);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x120), memory.write_addresses[0]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0xabcd), memory.write_values[0]);
    owned_cpu_observation observation;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x1234abcd), observation.data_registers[0]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2718), observation.sr);

    set_vector(12u, UINT32_C(0x140));
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &state));
    state.address_registers[0] = UINT32_C(0x121);
    state.data_registers[0] = UINT32_C(0x5678);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &state));
    result = owned_cpu_run(cpu, UINT64_C(50));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(50u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &observation));
    TEST_ASSERT_EQUAL_UINT8(3u, observation.last_exception_vector);
    for (size_t index = 0u; index < memory.write_attempts && index < MAX_WRITES; ++index)
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x121), memory.write_addresses[index]);

    const uint8_t unsupported_absolute_short[] = {0x31u, 0xc0u};
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(
        unsupported_absolute_short, sizeof(unsupported_absolute_short)));
    result = owned_cpu_run(cpu, UINT64_C(8));
    TEST_ASSERT_EQUAL(OWNED_CPU_UNSUPPORTED_OPCODE, result.reason);
}

