static void current_instruction_pc_is_visible_to_write_callbacks_without_state_change(void) {
    create_cpu();
    /* Two MOVE.B #imm,(xxx).L instructions at 0x100 and 0x108. */
    const uint8_t program[] = {
        0x13u, 0xfcu, 0x00u, 0x80u, 0x00u, 0x00u, 0x01u, 0x21u,
        0x13u, 0xfcu, 0x00u, 0x81u, 0x00u, 0x00u, 0x01u, 0x22u};
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100), owned_cpu_current_instruction_pc(cpu));
    TEST_ASSERT_EQUAL_HEX32(0u, owned_cpu_current_instruction_pc(NULL));
    owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(40));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(2u, result.instructions);
    TEST_ASSERT_EQUAL_UINT(2u, memory.write_attempts);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x121), memory.byte_write_addresses[0]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x122), memory.byte_write_addresses[1]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100), memory.write_callback_pcs[0]);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x108), memory.write_callback_pcs[1]);
    /* Outside a run it reports the last started instruction. */
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x108), owned_cpu_current_instruction_pc(cpu));
    owned_cpu_observation before;
    owned_cpu_observation after;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &before));
    (void)owned_cpu_current_instruction_pc(cpu);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
    TEST_ASSERT_EQUAL_MEMORY(&before, &after, sizeof(before));
}

