static void move_status_register_postincrement_user_mode_traps_before_operand_access(void) {
    memset(&memory, 0, sizeof(memory));
    create_cpu();
    const uint8_t program[] = {UINT8_C(0x46), UINT8_C(0xda)};
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      reset_with_program(program, sizeof(program)));
    set_vector(32u, UINT32_C(0x160));
    owned_cpu_state before;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_capture_state(cpu, &before));
    before.ssp = UINT32_C(0x340);
    before.usp = UINT32_C(0x360);
    before.address_registers[7] = before.usp;
    before.address_registers[2] = UINT32_C(0x201);
    before.sr = UINT16_C(0x0015);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      owned_cpu_restore_state(cpu, &before));
    const size_t reads_before = memory.reads;
    const size_t writes_before = memory.write_attempts;
    const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(34));
    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
    TEST_ASSERT_EQUAL_UINT64(34u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
    owned_cpu_observation after;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
    TEST_ASSERT_EQUAL_UINT8(8u, after.last_exception_vector);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x160), after.pc);
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x201), after.address_registers[2]);
    TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2015), after.sr);
    TEST_ASSERT_EQUAL_HEX32(before.ssp - UINT32_C(6), after.ssp);
    TEST_ASSERT_EQUAL_HEX32(before.usp, after.usp);
    TEST_ASSERT_EQUAL_HEX32(after.ssp, after.address_registers[7]);
    TEST_ASSERT_EQUAL_UINT(3u, memory.write_attempts - writes_before);
    int saved_sr_written = 0;
    for (size_t write = writes_before; write < memory.write_attempts; ++write) {
        if (memory.write_addresses[write] == after.ssp &&
            memory.write_values[write] == before.sr) {
            saved_sr_written = 1;
        }
    }
    TEST_ASSERT_EQUAL(1, saved_sr_written);
    for (size_t read = reads_before;
         read < memory.reads && read < ROM_SIZE; ++read)
        TEST_ASSERT_NOT_EQUAL(UINT32_C(0x201), memory.read_addresses[read]);
    owned_cpu_destroy(cpu);
    cpu = NULL;
}

