/* Guest-observed encoding from the bounded 05-03 continuation: ADD.B Dm,Dn. */
static void add_byte_data_register_to_data_register_adds_all_pairs_in_4_cycles(void) {
    static const uint8_t values[8] = {
        UINT8_C(0x00), UINT8_C(0x01), UINT8_C(0x7f), UINT8_C(0x80),
        UINT8_C(0xff), UINT8_C(0xfe), UINT8_C(0x55), UINT8_C(0xaa)};
    uint8_t program[128];
    size_t length = 0u;
    for (unsigned destination = 0u; destination < 8u; ++destination) {
        for (unsigned source = 0u; source < 8u; ++source) {
            const uint16_t opcode = (uint16_t)(UINT16_C(0xd000) |
                                               (destination << 9) | source);
            emit_word(program, &length, opcode);
        }
    }
    create_cpu();
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, length));
    owned_cpu_observation observation;
    size_t instruction = 0u;
    for (unsigned destination_register = 0u; destination_register < 8u;
         ++destination_register) {
        for (unsigned source_register = 0u; source_register < 8u;
             ++source_register, ++instruction) {
            const uint8_t destination = values[destination_register];
            const uint8_t source = values[source_register];
            const uint16_t full_sum =
                (uint16_t)destination + (uint16_t)source;
            const uint8_t result = (uint8_t)full_sum;
            uint16_t expected_flags = UINT16_C(0x2700);
            if (result == 0u) expected_flags |= UINT16_C(0x0004);
            if ((result & UINT8_C(0x80)) != 0u)
                expected_flags |= UINT16_C(0x0008);
            if (((uint8_t)(~(source ^ destination) &
                           (destination ^ result)) & UINT8_C(0x80)) != 0u)
                expected_flags |= UINT16_C(0x0002);
            if (full_sum > UINT8_MAX)
                expected_flags |= UINT16_C(0x0011); /* C and X */

            owned_cpu_state before;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_capture_state(cpu, &before));
            for (unsigned reg = 0u; reg < 8u; ++reg)
                before.data_registers[reg] =
                    UINT32_C(0x12345600) | values[reg];
            before.sr = UINT16_C(0x271f);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_restore_state(cpu, &before));
            const size_t reads_before = memory.reads;
            const size_t byte_reads_before = memory.byte_reads;
            const size_t writes_before = memory.write_attempts;
            owned_cpu_run_result run = owned_cpu_run(cpu, UINT64_C(4));
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, run.reason);
            TEST_ASSERT_EQUAL_UINT64(4u, run.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, run.instructions);
            TEST_ASSERT_EQUAL_UINT(1u, memory.reads - reads_before);
            TEST_ASSERT_EQUAL_UINT(0u,
                                  memory.byte_reads - byte_reads_before);
            TEST_ASSERT_EQUAL_UINT(0u,
                                  memory.write_attempts - writes_before);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_observe(cpu, &observation));
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102) +
                                        (uint32_t)(instruction * 2u),
                                    observation.pc);
            TEST_ASSERT_EQUAL_HEX16(expected_flags, observation.sr);
            for (unsigned reg = 0u; reg < 8u; ++reg) {
                const uint32_t expected_value = reg == destination_register
                    ? UINT32_C(0x12345600) | result
                    : UINT32_C(0x12345600) | values[reg];
                TEST_ASSERT_EQUAL_HEX32(expected_value,
                                        observation.data_registers[reg]);
            }
        }
    }
}

/* Guest-observed encoding (05-02): ADD.W Dm,Dn. */
static void add_word_data_register_to_data_register_adds_all_pairs_in_4_cycles(void) {
    static const uint16_t values[8] = {
        UINT16_C(0x0000), UINT16_C(0x0001), UINT16_C(0x7fff), UINT16_C(0x8000),
        UINT16_C(0xffff), UINT16_C(0xfffe), UINT16_C(0x5555), UINT16_C(0xaaaa)};
    uint8_t program[128];
    size_t length = 0u;
    for (unsigned destination = 0u; destination < 8u; ++destination) {
        for (unsigned source = 0u; source < 8u; ++source) {
            const uint16_t opcode = (uint16_t)(UINT16_C(0xd040) |
                                               (destination << 9) | source);
            emit_word(program, &length, opcode);
        }
    }
    create_cpu();
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, length));
    owned_cpu_observation observation;
    size_t instruction = 0u;
    for (unsigned destination_register = 0u; destination_register < 8u;
         ++destination_register) {
        for (unsigned source_register = 0u; source_register < 8u;
             ++source_register, ++instruction) {
            const uint16_t destination = values[destination_register];
            const uint16_t source = values[source_register];
            const uint32_t full_sum = (uint32_t)destination + (uint32_t)source;
            const uint16_t result = (uint16_t)full_sum;
            uint16_t expected_flags = UINT16_C(0x2700);
            if (result == 0u) expected_flags |= UINT16_C(0x0004);
            if ((result & UINT16_C(0x8000)) != 0u)
                expected_flags |= UINT16_C(0x0008);
            if (((uint16_t)(~(source ^ destination) & (destination ^ result)) &
                 UINT16_C(0x8000)) != 0u)
                expected_flags |= UINT16_C(0x0002);
            if (full_sum > UINT16_MAX)
                expected_flags |= UINT16_C(0x0011); /* C and X */

            /* Each pair begins with the same operands; only PC and counters
             * continue through the sequence of encoded register pairs. */
            owned_cpu_state before;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_capture_state(cpu, &before));
            for (unsigned reg = 0u; reg < 8u; ++reg)
                before.data_registers[reg] =
                    UINT32_C(0x12340000) | values[reg];
            before.sr = UINT16_C(0x271f);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_restore_state(cpu, &before));
            const size_t reads_before = memory.reads;
            owned_cpu_run_result run = owned_cpu_run(cpu, UINT64_C(4));
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, run.reason);
            TEST_ASSERT_EQUAL_UINT64(4u, run.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, run.instructions);
            TEST_ASSERT_EQUAL_UINT(1u, memory.reads - reads_before);
            TEST_ASSERT_EQUAL_UINT(0u, memory.byte_reads);
            TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_observe(cpu, &observation));
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102) +
                                        (uint32_t)(instruction * 2u),
                                    observation.pc);
            TEST_ASSERT_EQUAL_HEX16(expected_flags, observation.sr);
            for (unsigned reg = 0u; reg < 8u; ++reg) {
                const uint32_t expected_value = reg == destination_register
                    ? UINT32_C(0x12340000) | result
                    : UINT32_C(0x12340000) | values[reg];
                TEST_ASSERT_EQUAL_HEX32(expected_value,
                                        observation.data_registers[reg]);
            }
        }
    }
}

