static void add_data_register_direct_counter_preflight_preserves_operands(void) {
    const uint8_t program[] = {0xd0u, 0x01u}; /* ADD.B D1,D0 */
    memset(&memory, 0, sizeof(memory));
    create_cpu();
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    owned_cpu_state before;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
    before.data_registers[0] = UINT32_C(0x1234567f);
    before.data_registers[1] = UINT32_C(0x87654301);
    before.sr = UINT16_C(0x271f);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_test_seed_counters(
        cpu, 0u, 0u, 0u, 0u, UINT64_MAX - UINT64_C(1)));

    const size_t reads_before = memory.reads;
    const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(4));
    TEST_ASSERT_EQUAL(OWNED_CPU_COUNTER_OVERFLOW, result.reason);
    TEST_ASSERT_EQUAL_UINT64(0u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(0u, result.instructions);
    TEST_ASSERT_EQUAL_UINT(reads_before + 1u, memory.reads); /* opcode only */
    TEST_ASSERT_EQUAL_UINT(0u, memory.byte_reads);
    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
    owned_cpu_observation after;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100), after.pc);
    TEST_ASSERT_EQUAL_HEX32(before.data_registers[0], after.data_registers[0]);
    TEST_ASSERT_EQUAL_HEX32(before.data_registers[1], after.data_registers[1]);
    TEST_ASSERT_EQUAL_HEX16(before.sr, after.sr);
    owned_cpu_destroy(cpu);
    cpu = NULL;
}

/* Bounded no-input attract continuation reaches ADD.L D4,D7. Exercise the
 * full register-direct ADD family over every source/destination pair. */
static void add_long_data_register_to_data_register_adds_all_pairs_in_8_cycles(void) {
    static const uint32_t values[8] = {
        UINT32_C(0x00000000), UINT32_C(0x00000001),
        UINT32_C(0x7fffffff), UINT32_C(0x80000000),
        UINT32_C(0xffffffff), UINT32_C(0xfffffffe),
        UINT32_C(0x55555555), UINT32_C(0xaaaaaaaa)};
    uint8_t program[128];
    size_t length = 0u;
    for (unsigned destination = 0u; destination < 8u; ++destination) {
        for (unsigned source = 0u; source < 8u; ++source) {
            const uint16_t opcode = (uint16_t)(UINT16_C(0xd080) |
                                               (destination << 9) | source);
            emit_word(program, &length, opcode);
        }
    }
    create_cpu();
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, length));
    owned_cpu_observation observation;
    size_t instruction = 0u;
    for (unsigned destination_register = 0u; destination_register < 8u;
         ++destination_register) {
        for (unsigned source_register = 0u; source_register < 8u;
             ++source_register, ++instruction) {
            const uint32_t destination = values[destination_register];
            const uint32_t source = values[source_register];
            const uint64_t full_sum = (uint64_t)destination + source;
            const uint32_t result = (uint32_t)full_sum;
            uint16_t expected_flags = UINT16_C(0x2700);
            if (result == 0u) expected_flags |= UINT16_C(0x0004);
            if ((result & UINT32_C(0x80000000)) != 0u)
                expected_flags |= UINT16_C(0x0008);
            if (((~(source ^ destination) & (destination ^ result)) &
                 UINT32_C(0x80000000)) != 0u)
                expected_flags |= UINT16_C(0x0002);
            if (full_sum > UINT32_MAX)
                expected_flags |= UINT16_C(0x0011); /* C and X */

            owned_cpu_state before;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_capture_state(cpu, &before));
            for (unsigned reg = 0u; reg < 8u; ++reg)
                before.data_registers[reg] = values[reg];
            before.sr = UINT16_C(0x271f);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_restore_state(cpu, &before));
            const size_t reads_before = memory.reads;
            owned_cpu_run_result run = owned_cpu_run(cpu, UINT64_C(8));
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, run.reason);
            TEST_ASSERT_EQUAL_UINT64(8u, run.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, run.instructions);
            TEST_ASSERT_EQUAL_UINT(1u, memory.reads - reads_before);
            TEST_ASSERT_EQUAL_UINT(0u, memory.byte_reads);
            TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_observe(cpu, &observation));
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102) +
                                        (uint32_t)(instruction * 2u),
                                    observation.pc);
            TEST_ASSERT_EQUAL_HEX16(expected_flags, observation.sr);
            for (unsigned reg = 0u; reg < 8u; ++reg) {
                const uint32_t expected_value = reg == destination_register
                    ? result : values[reg];
                TEST_ASSERT_EQUAL_HEX32(expected_value,
                                        observation.data_registers[reg]);
            }
        }
    }
}

