/* MOVE.B #imm,(d16,An) (05-25 rerun 24). PRM MOVE pp. 4-116 to 4-118;
 * UM Rev. 9.1 Table 8-2 p. 8-2 gives 16(3/1): opcode, immediate,
 * displacement word reads, one byte write. Immediate high byte is ignored. */
static void move_byte_immediate_displacement_writes_low_byte_in_16_cycles(void) {
    for (unsigned reg = 0u; reg < 8u; ++reg) {
        for (unsigned negative = 0u; negative < 2u; ++negative) {
            memset(&memory, 0, sizeof(memory)); create_cpu();
            uint8_t program[6]; size_t length = 0u;
            emit_word(program, &length, (uint16_t)(0x117cu | (reg << 9)));
            emit_word(program, &length, negative != 0u ? 0x80feu : 0xaa00u);
            emit_word(program, &length, negative != 0u ? 0xfff1u : 0x0011u);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, length));
            owned_cpu_state before;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
            before.address_registers[reg] = 0x1c0u;
            if (reg == 7u) before.ssp = 0x1c0u;
            before.sr = (uint16_t)(0x270fu | (negative << 4));
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));
            const uint32_t address = negative != 0u ? 0x1b1u : 0x1d1u;
            memory.rom[address + 1u] = 0x5au;
            const size_t reads = memory.reads;
            owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(16));
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
            TEST_ASSERT_EQUAL_UINT64(16u, result.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
            TEST_ASSERT_EQUAL_UINT(3u, memory.reads - reads);
            TEST_ASSERT_EQUAL_UINT(0u, memory.byte_reads);
            TEST_ASSERT_EQUAL_UINT(1u, memory.write_attempts);
            TEST_ASSERT_EQUAL_HEX32(address, memory.byte_write_addresses[0]);
            TEST_ASSERT_EQUAL_HEX8(negative != 0u ? 0xfeu : 0u, memory.rom[address]);
            TEST_ASSERT_EQUAL_HEX8(0x5au, memory.rom[address + 1u]);
            owned_cpu_observation after;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
            TEST_ASSERT_EQUAL_HEX32(0x106u, after.pc);
            TEST_ASSERT_EQUAL_HEX16(negative != 0u ? 0x2718u : 0x2704u, after.sr);
            for (unsigned r = 0u; r < 8u; ++r) {
                TEST_ASSERT_EQUAL_HEX32(before.data_registers[r], after.data_registers[r]);
                TEST_ASSERT_EQUAL_HEX32(before.address_registers[r], after.address_registers[r]);
            }
            owned_cpu_destroy(cpu); cpu = NULL;
        }
    }
}

/* Closeout coverage for the already admitted SUBQ.L register/quick operands.
 * PRM SUBQ pp. 4-181 to 4-182; UM Rev. 9.1 Table 8-5 p. 8-5 8(1/0). */
static void subq_long_selects_every_register_and_every_quick_value(void) {
    const uint32_t expected[] = {7u, 6u, 5u, 4u, 3u, 2u, 1u, 0u};
    for (unsigned reg = 0u; reg < 8u; ++reg) {
        for (unsigned quick = 1u; quick <= 8u; ++quick) {
            memset(&memory, 0, sizeof(memory)); create_cpu();
            uint8_t program[2]; size_t length = 0u;
            emit_word(program, &length, (uint16_t)(0x5180u | ((quick & 7u) << 9) | reg));
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, length));
            owned_cpu_state before;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
            for (unsigned r = 0u; r < 8u; ++r) before.data_registers[r] = 0x100u + r;
            before.data_registers[reg] = 8u; before.sr = 0x271fu;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));
            const size_t reads = memory.reads;
            owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(8));
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
            TEST_ASSERT_EQUAL_UINT64(8u, result.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
            TEST_ASSERT_EQUAL_UINT(1u, memory.reads - reads);
            TEST_ASSERT_EQUAL_UINT(0u, memory.byte_reads);
            TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
            owned_cpu_observation after;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
            TEST_ASSERT_EQUAL_HEX32(0x102u, after.pc);
            TEST_ASSERT_EQUAL_HEX16(quick == 8u ? 0x2704u : 0x2700u, after.sr);
            for (unsigned r = 0u; r < 8u; ++r) {
                TEST_ASSERT_EQUAL_HEX32(r == reg ? expected[quick - 1u] : before.data_registers[r], after.data_registers[r]);
                TEST_ASSERT_EQUAL_HEX32(before.address_registers[r], after.address_registers[r]);
            }
            owned_cpu_destroy(cpu); cpu = NULL;
        }
    }
}

/* Guest-observed encoding (05-02): CLR.W (d8,An,Xn). */
/* Guest-observed encoding (05-02): CLR.L (An)+. */
static void clr_long_postincrement_reads_both_words_then_clears_for_all_address_registers(void) {
    for (unsigned address_register = 0u; address_register < 8u;
         ++address_register) {
        memset(&memory, 0, sizeof(memory));
        create_cpu();
        const uint8_t program[] = {
            0x42u, (uint8_t)(0x98u | address_register)};
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          reset_with_program(program, sizeof(program)));
        owned_cpu_state before;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          owned_cpu_capture_state(cpu, &before));
        before.address_registers[address_register] = UINT32_C(0x1e0);
        before.ssp = before.address_registers[7];
        before.sr = UINT16_C(0x271b); /* X, N, V, C set; Z clear. */
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          owned_cpu_restore_state(cpu, &before));
        memory.rom[0x1e0u] = 0x12u;
        memory.rom[0x1e1u] = 0x34u;
        memory.rom[0x1e2u] = 0x56u;
        memory.rom[0x1e3u] = 0x78u;
        const size_t reads_before = memory.reads;
        const size_t writes_before = memory.write_attempts;
        owned_cpu_run_result result =
            owned_cpu_run(cpu, UINT64_C(20));
        TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
        TEST_ASSERT_EQUAL_UINT64(20u, result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
        TEST_ASSERT_EQUAL_UINT(3u, memory.reads - reads_before);
        TEST_ASSERT_EQUAL_UINT(0u, memory.byte_reads);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x1e0),
            memory.read_addresses[reads_before + 1u]);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x1e2),
            memory.read_addresses[reads_before + 2u]);
        TEST_ASSERT_EQUAL_UINT(writes_before + 2u, memory.write_attempts);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x1e0),
            memory.write_addresses[writes_before]);
        TEST_ASSERT_EQUAL_HEX16(0u, memory.write_values[writes_before]);
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x1e2),
            memory.write_addresses[writes_before + 1u]);
        TEST_ASSERT_EQUAL_HEX16(0u,
            memory.write_values[writes_before + 1u]);
        owned_cpu_observation after;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                          owned_cpu_observe(cpu, &after));
        TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102), after.pc);
        TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2714), after.sr);
        for (unsigned reg = 0u; reg < 8u; ++reg) {
            const uint32_t expected = reg == address_register
                ? UINT32_C(0x1e4) : before.address_registers[reg];
            TEST_ASSERT_EQUAL_HEX32(expected, after.address_registers[reg]);
            TEST_ASSERT_EQUAL_HEX32(before.data_registers[reg],
                                    after.data_registers[reg]);
        }
        if (address_register == 7u)
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x1e4), after.ssp);
        else
            TEST_ASSERT_EQUAL_HEX32(before.ssp, after.ssp);
        owned_cpu_destroy(cpu);
        cpu = NULL;
    }
}

/* Guest-observed (05-02 task 2): CLR.L (An). The MC68000 reads both operand
 * words before writing either; UM Rev. 9.1 Tables 8-6 and 8-1 give
 * 12(1/2)+8(2/0)=20(3/2). */
