static void clr_word_address_index_reads_then_clears_for_register_and_index_sizes(void) {
    static const uint32_t indexes[8] = {
        UINT32_C(0x00000002), UINT32_C(0x0000fffc), UINT32_C(0x00010001),
        UINT32_C(0xffff0003), UINT32_C(0x7fff0000), UINT32_C(0x80000000),
        UINT32_C(0x1234007f), UINT32_C(0xffffff81)};
    static const int8_t displacements[4] = {-128, -1, 0, 127};
    for (unsigned base_reg = 0u; base_reg < 8u; ++base_reg) {
        for (unsigned index_reg = 0u; index_reg < 8u; ++index_reg) {
            for (unsigned index_is_address = 0u; index_is_address < 2u;
                 ++index_is_address) {
                for (unsigned index_is_long = 0u; index_is_long < 2u;
                     ++index_is_long) {
                    if (index_is_address != 0u && index_reg == base_reg) continue;
                    memset(&memory, 0, sizeof(memory));
                    create_cpu();
                    uint8_t program[4];
                    size_t length = 0u;
                    const int8_t displacement = displacements[
                        (base_reg + index_reg + index_is_address + index_is_long) % 4u];
                    emit_word(program, &length, (uint16_t)(
                        UINT16_C(0x4270) | base_reg));
                    emit_word(program, &length, (uint16_t)(
                        (index_is_address != 0u ? UINT16_C(0x8000) : 0u) |
                        (index_reg << 12) |
                        (index_is_long != 0u ? UINT16_C(0x0800) : 0u) |
                        (uint8_t)displacement));
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      reset_with_program(program, length));
                    owned_cpu_state before;
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      owned_cpu_capture_state(cpu, &before));
                    const uint32_t index_value = indexes[index_reg];
                    const uint32_t effective_index = index_is_long != 0u
                        ? index_value
                        : expected_sign_extend_word((uint16_t)index_value);
                    if (index_is_address != 0u)
                        before.address_registers[index_reg] = index_value;
                    else
                        before.data_registers[index_reg] = index_value;
                    const uint32_t target = UINT32_C(0x1e0);
                    before.address_registers[base_reg] = target -
                        (uint32_t)(int32_t)displacement - effective_index;
                    before.ssp = before.address_registers[7];
                    before.sr = (uint16_t)(UINT16_C(0x270b) |
                        (((base_reg + index_reg) & 1u) != 0u
                            ? UINT16_C(0x0010) : 0u));
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      owned_cpu_restore_state(cpu, &before));
                    memory.rom[target] = 0x5au;
                    memory.rom[target + 1u] = 0xa5u;
                    const size_t reads_before = memory.reads;
                    const size_t writes_before = memory.write_attempts;
                    owned_cpu_run_result result =
                        owned_cpu_run(cpu, UINT64_C(18));
                    TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
                    TEST_ASSERT_EQUAL_UINT64(18u, result.elapsed_cycles);
                    TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
                    TEST_ASSERT_EQUAL_UINT(3u, memory.reads - reads_before);
                    TEST_ASSERT_EQUAL_UINT(0u, memory.byte_reads);
                    TEST_ASSERT_EQUAL_HEX32(target,
                        memory.read_addresses[reads_before + 2u]);
                    TEST_ASSERT_EQUAL_UINT(writes_before + 1u,
                                           memory.write_attempts);
                    TEST_ASSERT_EQUAL_HEX32(target,
                        memory.write_addresses[writes_before]);
                    TEST_ASSERT_EQUAL_HEX16(0u,
                        memory.write_values[writes_before]);
                    owned_cpu_observation after;
                    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                                      owned_cpu_observe(cpu, &after));
                    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x104), after.pc);
                    TEST_ASSERT_EQUAL_HEX16(
                        (uint16_t)((before.sr & UINT16_C(0xfff0)) |
                                   UINT16_C(0x0004)), after.sr);
                    for (unsigned reg = 0u; reg < 8u; ++reg) {
                        TEST_ASSERT_EQUAL_HEX32(before.data_registers[reg],
                                                after.data_registers[reg]);
                        TEST_ASSERT_EQUAL_HEX32(before.address_registers[reg],
                                                after.address_registers[reg]);
                    }
                    owned_cpu_destroy(cpu);
                    cpu = NULL;
                }
            }
        }
    }
}

static void clr_word_address_index_aliases_base_register_without_scaling(void) {
    for (unsigned reg = 0u; reg < 8u; ++reg) {
        for (unsigned index_is_long = 0u; index_is_long < 2u; ++index_is_long) {
            memset(&memory, 0, sizeof(memory));
            create_cpu();
            uint8_t program[4];
            size_t length = 0u;
            emit_word(program, &length, (uint16_t)(UINT16_C(0x4270) | reg));
            emit_word(program, &length, (uint16_t)(UINT16_C(0x8000) |
                (reg << 12) | (index_is_long != 0u ? UINT16_C(0x0800) : 0u) |
                UINT16_C(0x00fc)));
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              reset_with_program(program, length));
            owned_cpu_state before;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_capture_state(cpu, &before));
            before.address_registers[reg] = UINT32_C(0x00f2);
            before.ssp = before.address_registers[7];
            before.sr = UINT16_C(0x271b);
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_restore_state(cpu, &before));
            const uint32_t target = UINT32_C(0x1e0);
            memory.rom[target] = 0x12u;
            memory.rom[target + 1u] = 0x34u;
            const size_t reads_before = memory.reads;
            const size_t writes_before = memory.write_attempts;
            owned_cpu_run_result result =
                owned_cpu_run(cpu, UINT64_C(18));
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
            TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
            TEST_ASSERT_EQUAL_UINT(3u, memory.reads - reads_before);
            TEST_ASSERT_EQUAL_HEX32(target,
                memory.read_addresses[reads_before + 2u]);
            TEST_ASSERT_EQUAL_UINT(writes_before + 1u, memory.write_attempts);
            TEST_ASSERT_EQUAL_HEX32(target,
                memory.write_addresses[writes_before]);
            owned_cpu_observation after;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                              owned_cpu_observe(cpu, &after));
            TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2714), after.sr);
            TEST_ASSERT_EQUAL_HEX32(before.address_registers[reg],
                                    after.address_registers[reg]);
            owned_cpu_destroy(cpu);
            cpu = NULL;
        }
    }
}

