/* MC68000 PRM §4 CLR pp. 4-73 to 4-74 clears the selected Dn width, sets Z,
 * clears N/V/C, and preserves X. UM Rev. 9.1 Chapter 8 Table 8-6 p. 8-6
 * gives Dn-direct 4(1/0) for byte/word and 6(1/0) for long. */
static void clr_byte_word_long_data_register_forms_cover_all_registers(void) {
    static const uint32_t initial[8] = {
        UINT32_C(0xffffffff), UINT32_C(0x12345678), UINT32_C(0x80008001),
        UINT32_C(0x7fffffff), UINT32_C(0x00000001), UINT32_C(0x00000000),
        UINT32_C(0xdeadbeef), UINT32_C(0xa5a55a5a)};
    static const unsigned widths[3] = {1u, 2u, 4u};
    static const uint16_t bases[3] = {
        UINT16_C(0x4200), UINT16_C(0x4240), UINT16_C(0x4280)};
    for (unsigned size = 0u; size < 3u; ++size) {
        uint8_t program[16];
        size_t length = 0u;
        for (unsigned reg = 0u; reg < 8u; ++reg)
            emit_word(program, &length, (uint16_t)(bases[size] | reg));
        memset(&memory, 0, sizeof(memory));
        create_cpu();
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, length));
        owned_cpu_state before;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
        memcpy(before.data_registers, initial, sizeof(initial));
        before.sr = UINT16_C(0x271f);
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));
        uint32_t expected_data[8];
        memcpy(expected_data, initial, sizeof(expected_data));
        const size_t reads_start = memory.reads;
        const size_t writes_start = memory.write_attempts;
        for (unsigned reg = 0u; reg < 8u; ++reg) {
            const uint64_t cycles = widths[size] == 4u ? UINT64_C(6)
                                                       : UINT64_C(4);
            const owned_cpu_run_result result = owned_cpu_run(cpu, cycles);
            TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
            TEST_ASSERT_EQUAL_UINT64(cycles, result.elapsed_cycles);
            TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
            TEST_ASSERT_EQUAL_UINT(reads_start + reg + 1u, memory.reads);
            TEST_ASSERT_EQUAL_UINT(writes_start, memory.write_attempts);
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100) + reg * UINT32_C(2),
                                    memory.read_addresses[reads_start + reg]);
            owned_cpu_state after;
            TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &after));
            const uint32_t mask = widths[size] == 1u ? UINT32_C(0xffffff00)
                : widths[size] == 2u ? UINT32_C(0xffff0000) : 0u;
            expected_data[reg] &= mask;
            for (unsigned index = 0u; index < 8u; ++index) {
                TEST_ASSERT_EQUAL_HEX32(expected_data[index],
                                        after.data_registers[index]);
                TEST_ASSERT_EQUAL_HEX32(before.address_registers[index],
                                        after.address_registers[index]);
            }
            TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x102) + reg * UINT32_C(2),
                                    after.pc);
            TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2714), after.sr);
        }
        TEST_ASSERT_EQUAL_UINT(8u, memory.reads - reads_start);
        owned_cpu_destroy(cpu);
        cpu = NULL;
    }
}

static void clr_long_data_register_counter_overflow_is_atomic(void) {
    const uint8_t program[] = {0x42u, 0x83u}; /* CLR.L D3 */
    create_cpu();
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, reset_with_program(program, sizeof(program)));
    owned_cpu_state before;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
    before.data_registers[3] = UINT32_C(0xffffffff);
    before.sr = UINT16_C(0xa71f);
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_test_seed_counters(
        cpu, 0u, 0u, 0u, 0u, UINT64_MAX - UINT64_C(5)));
    const size_t reads_before = memory.reads;
    const owned_cpu_run_result result = owned_cpu_run(cpu, UINT64_C(6));
    TEST_ASSERT_EQUAL(OWNED_CPU_COUNTER_OVERFLOW, result.reason);
    TEST_ASSERT_EQUAL_UINT64(0u, result.elapsed_cycles);
    TEST_ASSERT_EQUAL_UINT64(0u, result.instructions);
    TEST_ASSERT_EQUAL_UINT(reads_before + 1u, memory.reads);
    owned_cpu_observation after;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_observe(cpu, &after));
    TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x100), after.pc);
    TEST_ASSERT_EQUAL_HEX32(before.data_registers[3], after.data_registers[3]);
    TEST_ASSERT_EQUAL_HEX16(before.sr, after.sr);
    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
    tearDown();
}

static void clr_data_registers_preserve_clear_extend_flag_across_widths(void) {
    const uint8_t program[] = {
        0x42u, 0x00u, /* CLR.B D0 */
        0x42u, 0x41u, /* CLR.W D1 */
        0x42u, 0x82u, /* CLR.L D2 */
    };
    memset(&memory, 0, sizeof(memory));
    create_cpu();
    TEST_ASSERT_EQUAL(OWNED_CPU_OK,
                      reset_with_program(program, sizeof(program)));
    owned_cpu_state before;
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &before));
    before.data_registers[0] = UINT32_C(0x12345678);
    before.data_registers[1] = UINT32_C(0xabcdef01);
    before.data_registers[2] = UINT32_C(0xffffffff);
    before.sr = UINT16_C(0x270f); /* all NZVC set, X clear */
    TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_restore_state(cpu, &before));
    const size_t reads_start = memory.reads;
    const uint64_t cycles[3] = {UINT64_C(4), UINT64_C(4), UINT64_C(6)};
    for (unsigned index = 0u; index < 3u; ++index) {
        const owned_cpu_run_result result = owned_cpu_run(cpu, cycles[index]);
        TEST_ASSERT_EQUAL(OWNED_CPU_BUDGET, result.reason);
        TEST_ASSERT_EQUAL_UINT64(cycles[index], result.elapsed_cycles);
        TEST_ASSERT_EQUAL_UINT64(1u, result.instructions);
        owned_cpu_state after;
        TEST_ASSERT_EQUAL(OWNED_CPU_OK, owned_cpu_capture_state(cpu, &after));
        TEST_ASSERT_EQUAL_HEX16(UINT16_C(0x2704), after.sr);
        TEST_ASSERT_EQUAL_HEX32(index == 0u ? UINT32_C(0x12345600)
                                 : index == 1u ? UINT32_C(0xabcd0000)
                                               : UINT32_C(0),
                                after.data_registers[index]);
    }
    TEST_ASSERT_EQUAL_UINT(3u, memory.reads - reads_start);
    TEST_ASSERT_EQUAL_UINT(0u, memory.write_attempts);
    tearDown();
}

